-- Biology part 2 of 2: longer explanations for BIO-1285 onwards (rest of Biology 11, the gap and hard sets and past-paper questions).
-- Longer explanations: each question's "why" now says in two or three sentences why the key is right, and each wrong
-- option gets a sentence or two on the mistake behind it. Facts checked against the source textbook named in each
-- question's source. Stems, options and answer keys are unchanged: every UPDATE also matches on the current key, so a
-- question whose key was edited since is left alone. Safe to run twice.

UPDATE questions SET why = 'Saliva contains thiocyanate ions, which kill microorganisms that enter the mouth with food. This gives the oral cavity a first chemical defence, while other parts of saliva moisten food, buffer the mouth and begin starch digestion.', wrong = '{"1": "Bicarbonate ions in saliva act as a buffer, keeping the pH of the oral cavity steady. They do not kill microbes.", "2": "Mucus, along with water, moistens and lubricates food so it can be chewed and swallowed easily. It is not the antimicrobial part.", "3": "Salivary amylase is an enzyme that partially digests starch and glycogen into maltose. It has no role in killing microorganisms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1285' AND answer = 0;
UPDATE questions SET why = 'Fresh saliva is alkaline, with a pH of about 8, partly because of dissolved carbon dioxide balanced by bicarbonate. Once in the mouth it quickly loses CO₂, and its pH falls to about 6.', wrong = '{"0": "Hydrochloric acid is made by parietal cells of the stomach. It is not added to saliva in the mouth.", "1": "Saliva is not in contact with blood after secretion, so it cannot lose bicarbonate to it. The fall in pH is due to loss of CO₂.", "3": "Bile is made by the liver and enters the duodenum. It never mixes with saliva in the mouth."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1286' AND answer = 2;
UPDATE questions SET why = 'Salivary amylase begins carbohydrate digestion in the mouth. It partially breaks the polysaccharides starch and glycogen into maltose, a disaccharide made of two glucose units. Food stays in the mouth only briefly, so this digestion is incomplete.', wrong = '{"0": "Glucose and fructose are produced when sucrase in intestinal juice digests sucrose, not when amylase acts on starch.", "2": "Amino acids are the end products of protein digestion. Amylase does not act on proteins.", "3": "Glycerol, with fatty acids, is a product of fat digestion by lipase. Amylase does not digest fats."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1287' AND answer = 1;
UPDATE questions SET why = 'In the mouth, food is chewed (mechanical digestion) and mixed with saliva (chemical digestion). The result is a small, moist, rounded mass called a bolus, which is then swallowed into the pharynx.', wrong = '{"0": "Chyme is the semi-liquid acidic mass formed in the stomach about three to four hours after a meal.", "1": "Chyle is the alkaline emulsion formed in the small intestine after intestinal juice has acted on chyme.", "2": "Faeces are the semi-solid wastes formed in the colon after water has been absorbed from undigested material."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1288' AND answer = 3;
UPDATE questions SET why = 'During swallowing, the soft palate is raised against the back wall of the pharynx. This closes the passage between the nasal cavity and pharynx, so food does not go up into the nose.', wrong = '{"0": "The epiglottis is lowered to close the opening of the trachea, not the nasal passage. It stops food entering the airway.", "2": "The cardiac sphincter lies at the junction of the oesophagus and stomach. It controls entry of food into the stomach.", "3": "The tongue moves up and back against the roof of the mouth to push the bolus backwards. It does not seal off the nasal cavity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1289' AND answer = 1;
UPDATE questions SET why = 'Swallowing begins as a voluntary action, when the tongue pushes the bolus to the back of the mouth. Once food reaches the back of the mouth, the rest of swallowing becomes automatic (a reflex).', wrong = '{"0": "The start of swallowing is under conscious control, so it is not completely involuntary.", "1": "Only the first stage is voluntary. Once food reaches the back of the mouth, swallowing continues automatically.", "3": "Gastrin is a stomach hormone that stimulates secretion of gastric juice. It has no role in swallowing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1290' AND answer = 2;
UPDATE questions SET why = 'The pharynx is a cavity behind the mouth. It is a common passageway for both the digestive tract (food going to the oesophagus) and the respiratory tract (air going to the larynx and trachea).', wrong = '{"1": "The pharynx lies above the oesophagus, which in turn leads to the stomach. It is not part of the stomach.", "2": "Accessory glands, such as the salivary glands, liver and pancreas, pour secretions into the gut. The pharynx is a passage, not a gland.", "3": "Fats are absorbed in the jejunum and ileum of the small intestine, into the lacteals of the villi."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1291' AND answer = 0;
UPDATE questions SET why = 'The oesophagus is the muscular tube that connects the pharynx to the stomach. In an adult human it is about 25 cm long, and food moves through it by peristalsis.', wrong = '{"0": "About 6 m is the length of the whole small intestine, not the oesophagus.", "1": "About 2.4 m is the length of the jejunum, the middle part of the small intestine.", "2": "20 to 25 cm is the length of the duodenum, and it is a length, not a width. The oesophagus is a narrow tube about 25 cm long."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1292' AND answer = 3;
UPDATE questions SET why = 'The lower oesophageal (cardiac) sphincter opens in response to the pressure of food, letting it pass from the oesophagus into the stomach. It also prevents backflow of acidic stomach contents into the oesophagus.', wrong = '{"0": "The pyloric sphincter, at the lower end of the stomach, regulates release of chyme into the duodenum.", "2": "The opening of the trachea is closed by the epiglottis during swallowing, not by any sphincter of the gut.", "3": "Defecation is controlled by the internal and external anal sphincters around the anus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1293' AND answer = 1;
UPDATE questions SET why = 'Peristalsis is a rhythmic sequence of waves of contraction in the smooth muscles of the gut wall. Each wave squeezes food forward, moving it along the oesophagus and the rest of the alimentary canal.', wrong = '{"0": "Back-and-forth movement in the same place is segmentation, which mixes food with digestive juices in the intestines.", "1": "Reverse movement of food is antiperistalsis, which pushes contents back towards the stomach and mouth and causes vomiting.", "2": "The walls of the alimentary canal contain smooth muscle, which contracts involuntarily. Peristalsis is not a voluntary skeletal-muscle action."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1294' AND answer = 3;
UPDATE questions SET why = 'Hunger contractions are peristaltic movements of the stomach that are triggered when blood glucose falls. They create the uncomfortable sensation called hunger pangs.', wrong = '{"1": "Antiperistalsis is reversed peristalsis that pushes food back towards the mouth and causes vomiting.", "2": "Bile is secreted by the liver and released from the gallbladder to emulsify fats. It does not cause hunger pangs.", "3": "Gastrin is released when proteins are present in the stomach and stimulates gastric juice secretion. It is not the cause of hunger pangs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1295' AND answer = 0;
UPDATE questions SET why = 'Occasionally peristaltic movements reverse, a process called antiperistalsis. Food is pushed from the intestines back into the stomach and oral cavity, and this results in vomiting.', wrong = '{"0": "Segmentation is a back-and-forth movement in one place that mixes food with secretions. It does not push food backwards.", "1": "Hunger contractions are peristaltic movements triggered by low blood glucose. They cause hunger pangs, not vomiting.", "3": "The defecation reflex is triggered when the rectum fills with faeces. It empties the rectum through the anus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1296' AND answer = 2;
UPDATE questions SET why = 'The stomach is an elastic, muscular bag between the oesophagus and duodenum. It lies on the left side of the abdominal cavity, just below the diaphragm.', wrong = '{"1": "The liver occupies the upper right part of the abdomen. The stomach lies on the left side.", "2": "The thoracic cavity holds the lungs and heart. The stomach lies below the diaphragm, in the abdominal cavity.", "3": "The rectum is at the end of the large intestine in the pelvis. The stomach is high in the abdomen, just under the diaphragm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1297' AND answer = 0;
UPDATE questions SET why = 'The muscularis externa of the stomach has three layers of smooth muscle: outer longitudinal, middle circular and inner oblique. The extra oblique layer lets the stomach contract strongly in several directions and churn food.', wrong = '{"0": "Circular muscle is only the middle layer. Longitudinal and oblique layers are also present.", "1": "The stomach wall contains smooth (involuntary) muscle, not skeletal muscle fibres.", "2": "Connective tissue carrying blood vessels, lymphatics and nerves is the submucosa, a separate layer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1298' AND answer = 3;
UPDATE questions SET why = 'The stomach wall has four layers. The submucosa lies just outside the mucosa and is made of connective tissue that carries blood vessels, lymphatic vessels and nerves.', wrong = '{"0": "The mucosa is the innermost layer. It contains gastric glands that secrete enzymes, HCl and mucus.", "1": "The serosa is the outermost thin layer. It forms part of the peritoneum and protects the stomach.", "3": "The muscularis externa is the muscle layer, with longitudinal, circular and oblique smooth muscles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1299' AND answer = 2;
UPDATE questions SET why = 'The muscular stomach wall contracts vigorously, churning food and mixing it with gastric secretions, which is mechanical digestion. These contractions also generate enough heat to melt solid fats.', wrong = '{"0": "Protein digestion is chemical. It is carried out by the enzyme pepsin, not by muscle contractions.", "2": "Glucose is absorbed in the jejunum and ileum of the small intestine, through the villi.", "3": "Bile is made by the liver, stored in the gallbladder and released into the duodenum, not by the stomach wall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1300' AND answer = 1;
UPDATE questions SET why = 'Parietal (oxyntic) cells of the gastric glands secrete hydrochloric acid. HCl brings the pH of stomach contents to about 2 to 3, softens food, activates pepsinogen and kills microorganisms.', wrong = '{"1": "Pepsinogen, the inactive form of pepsin, is secreted by chief cells, not parietal cells.", "2": "Mucus is secreted by mucous cells. It forms a thick layer that protects the stomach lining from acid.", "3": "Gastrin is a hormone released by endocrine cells of the stomach mucosa when proteins are present."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1301' AND answer = 0;
UPDATE questions SET why = 'Chief cells of the gastric glands secrete pepsinogen, the inactive precursor of pepsin. H⁺ ions from HCl then convert it into active pepsin inside the stomach.', wrong = '{"0": "Parietal (oxyntic) cells secrete hydrochloric acid, not pepsinogen.", "1": "Mucous cells secrete thick mucus that protects the stomach wall from acid and pepsin.", "3": "Goblet cells of the colon secrete mucus into the large intestine. They are not part of gastric glands."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1302' AND answer = 2;
UPDATE questions SET why = 'Hydrochloric acid secreted by parietal cells makes stomach contents strongly acidic, at a pH of about 2 to 3. This acidity activates pepsinogen and kills microorganisms in food.', wrong = '{"0": "pH 6 is the value saliva reaches after losing CO₂ in the mouth.", "2": "pH 8 is the value of fresh saliva and of pancreatic juice, both of which are slightly alkaline.", "3": "pH 7.4 is the normal pH of blood. Stomach contents are far more acidic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1303' AND answer = 1;
UPDATE questions SET why = 'Pepsin is the protein-digesting enzyme of the stomach. It breaks long protein chains into shorter polypeptides and peptides. Breakdown to amino acids is completed later in the small intestine.', wrong = '{"0": "Amino acids are released later by enzymes such as carboxypeptidase and erepsin in the small intestine, not by pepsin alone.", "1": "Glycerol and fatty acids are products of fat digestion by lipase, not of protein digestion.", "2": "Nucleotides are produced when nucleases digest DNA and RNA in the small intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1304' AND answer = 3;
UPDATE questions SET why = 'About three to four hours after a meal, food in the stomach has been mixed with gastric juice into a semi-liquid, acidic mass called chyme. The pyloric sphincter then releases it into the small intestine.', wrong = '{"0": "A bolus is the small moist mass of chewed food formed in the mouth before swallowing.", "2": "Chyle is the alkaline emulsion formed later in the small intestine by the action of intestinal juice.", "3": "Bile is the secretion of the liver that emulsifies fats. It is not stomach contents."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1305' AND answer = 1;
UPDATE questions SET why = 'The pyloric sphincter is a ring of muscle at the lower end of the stomach. It regulates release of chyme into the small intestine in small amounts.', wrong = '{"0": "The cardiac sphincter lies between the oesophagus and stomach. It lets food into the stomach and prevents backflow.", "1": "The internal anal sphincter, made of smooth muscle, surrounds the anus and helps control defecation.", "3": "The epiglottis is a cartilage flap that covers the trachea during swallowing. It is not in the stomach."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1306' AND answer = 2;
UPDATE questions SET why = 'Gastric secretion is partly under nervous control. The smell, sight or thought of food makes the medulla of the brain send messages to the gastric glands, which secrete a small amount of gastric juice even before food arrives.', wrong = '{"1": "The pancreas secretes pancreatic juice into the duodenum. It does not send signals to the gastric glands.", "2": "The duodenal walls release secretin and CCK, which act on the pancreas and gallbladder after chyme arrives.", "3": "The liver produces bile and processes nutrients. It does not send signals that start gastric secretion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1307' AND answer = 0;
UPDATE questions SET why = 'Proteins in food stimulate special endocrine cells in the stomach mucosa to release the hormone gastrin. Gastrin is carried by the blood to the gastric glands and makes them secrete more gastric juice.', wrong = '{"0": "Fats and partly digested proteins in the duodenum stimulate release of cholecystokinin (CCK), not gastrin.", "1": "Acidic chyme in the duodenum stimulates release of secretin, which acts on the pancreas and gallbladder.", "2": "Low blood glucose triggers hunger contractions of the stomach, not release of gastrin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1308' AND answer = 3;
UPDATE questions SET why = 'When food moves from the stomach into the small intestine, the hormone somatostatin is released. It stops the release of hydrochloric acid, so acid secretion falls once the stomach is emptying.', wrong = '{"0": "Gastrin has the opposite effect. It stimulates gastric glands to secrete more gastric juice.", "1": "Secretin is released by the duodenal wall in response to acidic chyme. It stimulates the pancreas and gallbladder.", "3": "Insulin is a pancreatic hormone that lowers blood glucose. It does not control HCl secretion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1309' AND answer = 2;
UPDATE questions SET why = 'The small intestine is the longest part of the alimentary canal. In an adult it is about 6 m long but only about 2 to 3 cm in diameter, which is why it is called small.', wrong = '{"0": "About 1 m long and wider, about 6 cm, describes the large intestine, which occupies the last metre of the tract.", "2": "About 25 cm is the length of the oesophagus. The duodenum alone is 20 to 25 cm.", "3": "About 3.5 m is the length of the ileum only, not the whole small intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1310' AND answer = 1;
UPDATE questions SET why = 'The duodenum is the first part of the small intestine, about 20 to 25 cm long. It receives pancreatic juice and bile and is mainly concerned with digestion of food.', wrong = '{"1": "About 2.4 m is the length of the jejunum, which follows the duodenum.", "2": "About 3.5 m is the length of the ileum, the last three-fifths of the small intestine.", "3": "About 6 m is the length of the entire small intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1311' AND answer = 0;
UPDATE questions SET why = 'Pancreatic juice contains bicarbonate, which makes it slightly alkaline with a pH of about 8. When it enters the duodenum, the bicarbonate neutralizes the acidity of chyme coming from the stomach, so intestinal enzymes can work.', wrong = '{"0": "Bile salts emulsify fats into small droplets. They come from the liver, not the pancreas.", "1": "Pepsin is a protein-digesting enzyme of the stomach. It does not neutralize acid.", "2": "Hydrochloric acid is secreted in the stomach and would make chyme more acidic, not neutralize it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1312' AND answer = 3;
UPDATE questions SET why = 'Trypsinogen is secreted by the pancreas in an inactive form. Enterokinase, an enzyme secreted by the walls of the duodenum, converts it into active trypsin, which digests proteins into polypeptides.', wrong = '{"0": "Hydrochloric acid activates pepsinogen into pepsin in the stomach, not trypsinogen.", "2": "Bile salts emulsify fats into small droplets. They do not activate enzymes.", "3": "Pepsin digests proteins in the acidic stomach. It is not the activator of trypsinogen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1313' AND answer = 1;
UPDATE questions SET why = 'Pancreatic juice contains enzymes for all groups of food. Among them are pancreatic nucleases, which digest the nucleic acids DNA and RNA into their building blocks, nucleotides, in the duodenum.', wrong = '{"0": "Carboxypeptidase digests peptides into amino acids. It acts on proteins, not nucleic acids.", "1": "Lipase digests lipids into glycerol and fatty acids.", "3": "Amylase digests polysaccharides such as starch into maltose and some glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1314' AND answer = 2;
UPDATE questions SET why = 'Fats do not dissolve in water, so lipase cannot reach them easily. Bile salts emulsify fats, breaking them into many tiny droplets that give a large surface area for lipid-digesting enzymes. Bile itself contains no digestive enzymes.', wrong = '{"0": "Hydrolysis of fats into fatty acids and glycerol is done by lipase. Bile salts only break fat into droplets.", "1": "Trypsinogen is activated to trypsin by enterokinase from the duodenal wall, not by bile.", "2": "Bile acts in the duodenum, not the stomach. Acid chyme is neutralized there mainly by bicarbonate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1315' AND answer = 3;
UPDATE questions SET why = 'Intestinal juice finishes protein digestion in two steps. Aminopeptidase breaks polypeptides into dipeptides, and then erepsin breaks dipeptides into amino acids, which can be absorbed.', wrong = '{"1": "Aminopeptidase acts one step earlier. It digests polypeptides into dipeptides, not dipeptides into amino acids.", "2": "Trypsin is a pancreatic enzyme that digests proteins into polypeptides.", "3": "Pepsin works in the stomach and digests proteins into polypeptides and peptides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1316' AND answer = 0;
UPDATE questions SET why = 'Sucrose is a disaccharide made of one glucose and one fructose unit. The intestinal enzyme sucrase splits it into these two monosaccharides, glucose and fructose.', wrong = '{"0": "Glucose and galactose are produced when lactase digests lactose, the sugar of milk.", "2": "Two glucose molecules are produced when maltase digests maltose.", "3": "Maltose is produced from starch by amylase. It is a disaccharide, not a product of sucrose digestion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1317' AND answer = 1;
UPDATE questions SET why = 'In the jejunum and ileum, enzymes of intestinal juice complete digestion of chyme. The result is an alkaline emulsion called chyle, from which digested food is absorbed.', wrong = '{"1": "A bolus is the moist mass of chewed food formed in the mouth.", "2": "Bile is the secretion of the liver that emulsifies fats. It is not digested food.", "3": "Lymph is the fluid carried in lymphatic vessels, such as lacteals. It is not the product of intestinal digestion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1318' AND answer = 0;
UPDATE questions SET why = 'The small intestine has three parts: duodenum, jejunum and ileum. The ileum is the last part and forms about three-fifths of the small intestine, about 3.5 m long. Along with the jejunum, it completes digestion and absorbs food.', wrong = '{"0": "The first 20 to 25 cm of the small intestine is the duodenum, which receives bile and pancreatic juice.", "1": "The 2.4 m section next to the duodenum is the jejunum.", "2": "The last metre of the intestinal tract is the large intestine, not the ileum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1319' AND answer = 3;
UPDATE questions SET why = 'Each villus is richly supplied with blood capillaries and a small lymphatic vessel called a lacteal. Sugars and amino acids enter the capillaries, while fat products, as chylomicrons, enter the lacteal.', wrong = '{"0": "The hepatic portal vein is formed outside the villi when capillaries from the villi join. It is not inside each villus.", "1": "The thoracic duct is a large lymph vessel that receives lymph from the lacteals. It is not inside a villus.", "3": "Microvilli are tiny projections of the epithelial cells on the villus surface. They are not vessels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1320' AND answer = 2;
UPDATE questions SET why = 'Glucose and amino acids enter the blood capillaries of the villi. These capillaries join to form the hepatic portal vein, which carries the absorbed sugars and amino acids directly to the liver.', wrong = '{"0": "Lacteals carry chylomicrons, the absorbed products of fat digestion, into the lymphatic system.", "2": "The hepatic artery brings oxygenated blood from the aorta to the liver. It does not collect from the intestine.", "3": "The thoracic lymphatic duct carries lymph, including chylomicrons, to the blood. Sugars and amino acids travel in blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1321' AND answer = 1;
UPDATE questions SET why = 'Inside the epithelial cells of villi, fatty acids and glycerol recombine into triglycerides. These are coated with protein to form tiny droplets called chylomicrons, which enter the lacteals and travel through the thoracic duct into the blood.', wrong = '{"0": "Fat products do not travel as free fatty acids in the portal vein. They leave as chylomicrons in the lymph.", "1": "Glycogen is the storage form of glucose in the liver, not a form of absorbed fat.", "2": "Bile salts are made in the liver and secreted into bile. They are not formed from absorbed fat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1322' AND answer = 3;
UPDATE questions SET why = 'Fatty acids and glycerol are absorbed into the epithelial cells of villi by passive transport. Being lipid-soluble, they can move through the cell membrane without spending energy.', wrong = '{"1": "Simple sugars and amino acids are absorbed by diffusion or active transport. Fat products are absorbed passively.", "2": "Lacteals receive chylomicrons from the epithelial cells. They do not take up fatty acids by pinocytosis from the gut.", "3": "Osmosis is the movement of water across a membrane, not the uptake of fatty acids and glycerol."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1323' AND answer = 0;
UPDATE questions SET why = 'The large intestine absorbs water and salts from its contents into the blood. It also absorbs vitamin K, which is made by colon bacteria such as E. coli and is needed for blood clotting.', wrong = '{"0": "Amino acids from protein digestion are absorbed in the jejunum and ileum of the small intestine.", "1": "Fatty acids are absorbed in the small intestine and leave the villi as chylomicrons.", "3": "Bile pigments are not absorbed here. They pass out of the body as part of the faeces."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1324' AND answer = 2;
UPDATE questions SET why = 'The large intestine is not convoluted, and its inner surface has no villi. Most absorption of digested food has already happened in the small intestine, so it mainly absorbs water, salts and vitamin K.', wrong = '{"0": "Numerous villi line the jejunum and ileum of the small intestine, not the large intestine.", "2": "Lacteals are found inside villi of the small intestine. The large intestine has no villi.", "3": "Pepsin is secreted as pepsinogen by chief cells of the stomach, not by the large intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1325' AND answer = 1;
UPDATE questions SET why = 'The caecum is the first part of the large intestine and ends blindly. A finger-like process, the vermiform appendix, arises from this blind end. It has no digestive function in humans, so it is called vestigial.', wrong = '{"0": "The colon, including its transverse limb, absorbs water. The appendix does not arise from it.", "1": "The rectum stores faeces temporarily before defecation. The appendix is not attached to it.", "2": "The duodenum is part of the small intestine and receives pancreatic juice and bile. The appendix does not arise there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1326' AND answer = 3;
UPDATE questions SET why = 'Faeces are formed from material that could not be absorbed. Glucose is absorbed into the blood in the small intestine, so absorbed glucose is not part of faeces. This makes it the exception.', wrong = '{"0": "Bacteria, such as E. coli from the colon, make up a large part of faeces.", "1": "Cellulose is an indigestible plant fibre, so it passes out in the faeces.", "3": "Bile pigments are present in faeces and give them their colour."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1327' AND answer = 2;
UPDATE questions SET why = 'Bacteria such as E. coli live and divide in the colon. During their metabolism they produce amino acids and vitamin K. Vitamin K is absorbed into the blood and is needed for blood coagulation.', wrong = '{"1": "Bile salts are made by the liver and stored in the gallbladder, not by colon bacteria.", "2": "Insulin is a hormone secreted by the endocrine part of the pancreas.", "3": "Pepsin is formed from pepsinogen secreted by chief cells of the stomach."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1328' AND answer = 0;
UPDATE questions SET why = 'The anus is surrounded by two sphincters. The internal sphincter is made of smooth (involuntary) muscle, and the external sphincter is made of striated (skeletal) muscle, which allows conscious control of defecation.', wrong = '{"0": "This reverses the two. The internal sphincter is smooth muscle and the external one is striated.", "1": "Only the internal sphincter is smooth muscle. The external sphincter is striated muscle.", "3": "Sphincters are rings of muscle that contract and relax. They are not made of cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1329' AND answer = 2;
UPDATE questions SET why = 'In infants, defecation is an involuntary reflex controlled by the spinal cord: a full rectum triggers relaxation of the internal sphincter. The higher brain centres for voluntary control are not yet developed. As the cerebral cortex matures, control of the external sphincter becomes voluntary.', wrong = '{"0": "The rectum of an infant does store faeces. Its filling is what triggers the defecation reflex.", "2": "Infants have both the internal and external anal sphincters.", "3": "The spinal cord is developed enough to run the reflex. It is the higher brain centres that are immature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1330' AND answer = 1;
UPDATE questions SET why = 'Bile is produced by the liver. The gallbladder stores and concentrates it, and releases it through the bile duct when food enters the small intestine.', wrong = '{"0": "The liver produces bile. The gallbladder only stores and concentrates it.", "1": "Insulin is secreted by the endocrine part of the pancreas.", "2": "Pancreatic juice is made by the exocrine part of the pancreas."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1331' AND answer = 3;
UPDATE questions SET why = 'The pancreas has two parts. Its endocrine (ductless) portion secretes the hormones insulin and glucagon into extracellular fluid, from where they enter capillaries. Its exocrine portion makes pancreatic juice.', wrong = '{"1": "Trypsin and lipase are digestive enzymes of the exocrine (ducted) portion, released into the pancreatic duct.", "2": "Bile is produced by the liver, not by the pancreas.", "3": "Secretin is a hormone released by the duodenal wall in response to acidic chyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1332' AND answer = 0;
UPDATE questions SET why = 'The exocrine pancreas releases pancreatic juice into the pancreatic duct. This duct joins the common bile duct from the liver, and together they open into the duodenum.', wrong = '{"0": "The thoracic duct is a lymphatic vessel that carries lymph and chylomicrons to the blood.", "2": "The cystic duct drains the gallbladder and joins the hepatic duct to form the common bile duct. The pancreatic duct joins the common bile duct.", "3": "The hepatic portal vein is a blood vessel from the intestine to the liver, not a duct carrying secretions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1333' AND answer = 1;
UPDATE questions SET why = 'When acidic chyme enters the duodenum from the stomach, its acidity stimulates the duodenal walls to release the hormone secretin. Secretin stimulates the pancreas to release pancreatic juice and the gallbladder to release bile.', wrong = '{"0": "Fats, along with partly digested proteins, stimulate release of cholecystokinin (CCK), not secretin.", "1": "Proteins in the stomach stimulate release of gastrin from the stomach mucosa.", "2": "The sight of food acts through the medulla of the brain to cause a small secretion of gastric juice."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1334' AND answer = 3;
UPDATE questions SET why = 'Partially digested proteins and fats in chyme stimulate the duodenal wall to secrete cholecystokinin (CCK). Along with secretin, CCK stimulates the pancreas to release pancreatic juice and the gallbladder to release bile.', wrong = '{"0": "Low blood glucose triggers hunger contractions of the stomach, not release of CCK.", "1": "Distension of the oesophagus is not a trigger for CCK. CCK responds to food in the duodenum.", "3": "Acid in the mouth has no role. CCK is released by the duodenum in response to proteins and fats."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1335' AND answer = 2;
UPDATE questions SET why = 'When the liver breaks down excess amino acids, toxic ammonia is produced. The liver removes this ammonia by converting it into urea, which is less toxic and is excreted in urine.', wrong = '{"1": "Uric acid is mainly a product of nucleic acid breakdown in humans. Ammonia from amino acids is turned into urea.", "2": "Glycogen is the form in which the liver stores excess glucose. It is not made from ammonia.", "3": "Bile salts are made from cholesterol and help emulsify fats. They do not remove ammonia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1336' AND answer = 0;
UPDATE questions SET why = 'The liver stores excess nutrients and releases them when needed. These include glucose as glycogen, the vitamins A, D, B12 and K, minerals such as iron and copper, and fats and fat-soluble substances.', wrong = '{"0": "Vitamin C and B1 are water-soluble and are not the vitamins listed as stored in the liver.", "1": "Vitamin C, E and folic acid are not the group listed. The stored vitamins are A, D, B12 and K.", "3": "The liver does store several vitamins, including A, D, B12 and K."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1337' AND answer = 2;
UPDATE questions SET why = 'Sometimes acidic chyme flows back from the stomach into the oesophagus. The acid irritates the oesophageal lining and causes a painful burning feeling in the chest, called heartburn or pyrosis.', wrong = '{"0": "Jaundice is caused by bile pigments building up in the blood, which yellows the skin.", "2": "Appendicitis is inflammation of the vermiform appendix, usually due to infection.", "3": "Hunger pangs are caused by hunger contractions of the stomach when blood glucose is low."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1338' AND answer = 1;
UPDATE questions SET why = 'Bile pigments are normally removed from the body through the digestive tract in faeces. If they are prevented from leaving this way, they accumulate in the blood and cause jaundice, which makes the skin and eyes yellow.', wrong = '{"1": "Acid flowing back into the oesophagus causes heartburn, not jaundice.", "2": "Infection and inflammation of the appendix is appendicitis.", "3": "Poor vitamin K absorption affects blood clotting. It does not cause bile pigments to build up."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1339' AND answer = 0;
UPDATE questions SET why = 'The liver secretes cholesterol into bile. In the gallbladder this cholesterol may precipitate out to form hard gallstones, which can block the bile duct.', wrong = '{"0": "Gallstones form inside the gallbladder from cholesterol. Absorption of bile salts in the colon is not the cause.", "1": "Pancreatic juice is alkaline because of bicarbonate, and it does not form stones in the gallbladder.", "2": "Chylomicrons enter lacteals normally as part of fat absorption. They are not linked to gallstones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1340' AND answer = 3;
UPDATE questions SET why = 'Appendicitis is inflammation of the appendix, often due to infection. The infected appendix must be removed by surgery, called appendicectomy, or it may burst and spread inflammation through the abdominal lining.', wrong = '{"0": "Cholecystectomy is surgical removal of the gallbladder, for example because of gallstones.", "1": "Gastrectomy is surgical removal of all or part of the stomach.", "2": "A colostomy is a surgical opening of the colon onto the abdominal wall, not removal of the appendix."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1341' AND answer = 3;
UPDATE questions SET why = 'External respiration happens at the level of the body system. It is the uptake of oxygen from the environment and the release of carbon dioxide into it, through breathing and gas exchange between the lungs and blood capillaries.', wrong = '{"0": "Breakdown of glucose in mitochondria to release energy is cellular (internal) respiration.", "2": "Movement of oxygen inside cells is part of cellular processes, not exchange with the environment.", "3": "Glycolysis is the first stage of cellular respiration, which produces a little ATP in the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1342' AND answer = 1;
UPDATE questions SET why = 'Gases can only diffuse across a moist respiratory surface. If this surface were on the outside of the body, it would quickly lose water to the air and dry out. Keeping it inside the body prevents this water loss.', wrong = '{"0": "Light has no role in gas exchange in humans, so it is not a reason for an internal location.", "1": "Respiratory surfaces are made thin so gases travel a short distance, not a greater one.", "3": "The surface must stay moist for gases to dissolve and diffuse. Drying out would stop gas exchange."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1343' AND answer = 2;
UPDATE questions SET why = 'Air reaches the internal respiratory surface through a branched system of tubes. As it passes along these airways it becomes saturated with water vapour, so it does not dry out the moist surface of the alveoli.', wrong = '{"1": "Air keeps its oxygen in the airways. Oxygen is taken up only at the respiratory surface.", "2": "Air is warmed as it passes through the airways, not cooled.", "3": "The airways are not there to speed up air. Their role is to condition the air before it reaches the surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1344' AND answer = 0;
UPDATE questions SET why = 'Gas exchange at the respiratory surface happens by diffusion. Oxygen moves from the air in the alveoli, where its concentration is higher, into the blood, while carbon dioxide moves from the blood into the alveolar air. No energy is spent.', wrong = '{"0": "Active transport uses ATP to move substances against a gradient. O₂ and CO₂ simply move down their partial pressure gradients.", "1": "Osmosis is the movement of water across a partially permeable membrane, not the movement of gases.", "2": "There is no bulk flow of air through the alveolar wall. Individual gas molecules diffuse across the thin, moist membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1345' AND answer = 3;
UPDATE questions SET why = 'The respiratory tract has upper and lower divisions. The upper respiratory tract consists of the nasal cavity, pharynx and larynx. These organs move, clean, warm and humidify air, but no gas exchange occurs in them.', wrong = '{"0": "The trachea, bronchi and lungs all belong to the lower respiratory tract.", "1": "The nasal cavity is upper tract, but the trachea and bronchi are part of the lower respiratory tract.", "2": "The larynx is upper tract, but the trachea and alveoli are part of the lower respiratory tract."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1346' AND answer = 3;
UPDATE questions SET why = 'The nasal cavity has many blood vessels lying very close to its surface. As inhaled air flows over them it is warmed and humidified. Nasal hairs and mucus also trap larger particles before air goes deeper.', wrong = '{"0": "Vocal cords are in the larynx and vibrate to produce sound. They do not warm air.", "2": "Surfactant is secreted inside the alveoli to stop them collapsing. It is not found in the nasal cavity.", "3": "Cartilage rings support the trachea and keep it open. They do not warm or humidify air."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1347' AND answer = 1;
UPDATE questions SET why = 'Besides conducting, warming and cleaning air, the nasal cavity contains chemoreceptors needed for the sense of smell. Through smell it also contributes to the sense of taste.', wrong = '{"0": "No gas exchange happens in the nasal cavity. Alveoli are found only in the lungs.", "1": "Taste buds are found mainly on the tongue. The nasal cavity contains smell receptors.", "3": "Vocal cords are found in the larynx, not in the nasal cavity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1348' AND answer = 2;
UPDATE questions SET why = 'The larynx, made of muscles and cartilages, connects the pharynx with the trachea. It is called the voice box because it contains the vocal cords, which vibrate as air flows over them and produce sound.', wrong = '{"1": "The epiglottis is a flap that covers the glottis during swallowing. It does not produce sound.", "2": "C-shaped cartilage rings support the trachea. They are not what makes the larynx a voice box.", "3": "Alveoli are tiny air sacs in the lungs where gas exchange happens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1349' AND answer = 0;
UPDATE questions SET why = 'The opening of the larynx is called the glottis. Above and in front of it is the epiglottis, a cartilage flap that is forced down over the glottis during swallowing so food does not enter the larynx.', wrong = '{"0": "The epiglottis is the flap that covers the opening, not the opening itself.", "2": "The pharynx is the tube-like passage shared by air and food, leading to the larynx and oesophagus.", "3": "A bronchus is a branch of the trachea that enters a lung. It is not the opening of the larynx."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1350' AND answer = 1;
UPDATE questions SET why = 'If swallowed material starts to enter the larynx, it irritates the lining and stimulates a strong cough reflex. The cough usually expels the material out of the larynx and back into the throat.', wrong = '{"1": "Peristalsis is the wave-like contraction that moves food along the gut, not a way of clearing the larynx.", "2": "Sneezing mainly clears the nasal passages. Irritation of the larynx triggers a cough reflex.", "3": "Surfactant lines the alveoli and prevents them collapsing. It does not remove material from the larynx."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1351' AND answer = 0;
UPDATE questions SET why = 'The walls of the trachea contain smooth muscle and C-shaped rings of cartilage. The cartilage gives strength and support so the windpipe stays open and does not collapse during breathing.', wrong = '{"0": "The trachea has no bone, and its cartilage rings are C-shaped, open at the back, not complete rings.", "1": "Cartilage plates replace the C-shaped rings only in the secondary bronchi, not in the trachea.", "2": "Surfactant acts in the alveoli, where it prevents collapse. It does not support the trachea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1352' AND answer = 3;
UPDATE questions SET why = 'The trachea is lined with mucus and cilia. Dust and germs are trapped in the mucus, and the beating cilia push this mucus upwards towards the pharynx, away from the lungs, where it can be swallowed or coughed out.', wrong = '{"0": "Moving mucus towards the alveoli would carry dirt into the lungs. The cilia beat in the opposite direction.", "1": "The cilia move mucus up to the pharynx. They do not deliver it directly into the oesophagus.", "3": "Trapped particles are cleared from the airway, not passed into the blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1353' AND answer = 2;
UPDATE questions SET why = 'The trachea, or windpipe, connects the larynx to the lungs. It is the widest passageway in the respiratory tract, about 1 inch wide and 4 to 6 inches long, and its walls are supported by C-shaped cartilage.', wrong = '{"0": "The trachea is the widest airway. The narrowest are the bronchioles.", "2": "The trachea has C-shaped cartilage rings that keep it open.", "3": "Gas exchange happens only in the alveoli of the lungs, not in the trachea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1354' AND answer = 1;
UPDATE questions SET why = 'Each primary bronchus branches into secondary bronchi, one for each lobe of the lung. The left lung has two lobes, so it has two secondary bronchi, while the right lung, with three lobes, has three.', wrong = '{"1": "Three secondary bronchi are found in the right lung, which has three lobes.", "2": "One is the number of primary bronchi entering each lung, not the number of secondary bronchi.", "3": "Five is the total number of lobes in both lungs together (three plus two), not the number in the left lung."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1355' AND answer = 0;
UPDATE questions SET why = 'In the trachea and primary bronchi, support comes from C-shaped cartilage rings. In the secondary bronchi, these C-shaped cartilages are replaced by cartilage plates. The bronchioles have no cartilage plates at all.', wrong = '{"0": "Complete rings of cartilage are not described in the bronchi. The C-shapes give way to plates.", "1": "There is no bone in any part of the airways.", "2": "Secondary bronchi still have support from cartilage plates. It is the bronchioles that lack cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1356' AND answer = 3;
UPDATE questions SET why = 'The tertiary bronchi branch into very small tubes called bronchioles, and these do not have cartilage plates. Their walls are mainly smooth muscle, which is why they can narrow in conditions such as asthma.', wrong = '{"0": "Primary bronchi are supported by C-shaped cartilage rings.", "1": "Secondary bronchi are supported by cartilage plates, which replace the C-shaped rings.", "3": "Tertiary bronchi are still bronchi and keep cartilage support. Only the bronchioles that arise from them lack plates."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1357' AND answer = 2;
UPDATE questions SET why = 'The trachea divides into two primary bronchi. These branch into secondary and then tertiary bronchi, which divide into bronchioles. Terminal bronchioles end in alveolar ducts, which open into clusters of alveoli.', wrong = '{"0": "Bronchioles come after the bronchi, not before them, and alveolar ducts are skipped.", "1": "Secondary bronchi come before bronchioles, not after them.", "3": "Bronchioles lead into alveolar ducts, so this order is reversed, and the bronchi are missing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1358' AND answer = 2;
UPDATE questions SET why = 'Each lung is covered by the visceral pleura, and the thoracic wall is lined by the parietal pleura. The narrow pleural cavity between them is filled with fluid, which lets the lungs expand and contract freely, without friction, during breathing.', wrong = '{"0": "Gas exchange takes place across the thin walls of the alveoli, not in the pleural fluid.", "1": "Oxygen is stored in muscle by myoglobin. Pleural fluid does not store oxygen.", "2": "Surfactant is secreted by some epithelial cells of the alveoli, not by the pleura."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1359' AND answer = 3;
UPDATE questions SET why = 'The heart lies just left of the centre of the chest. To make room for it, the left lung is smaller and has only two lobes, while the right lung is larger with three lobes.', wrong = '{"1": "The left lung does have a bronchus. The left primary bronchus enters it and divides into two secondary bronchi.", "2": "The amount of blood it receives is not the reason for its smaller size.", "3": "The size difference is explained by the position of the heart, not by the level of the diaphragm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1360' AND answer = 0;
UPDATE questions SET why = 'Some epithelial cells of the alveoli secrete surfactant, a liquid that lines the inside of the alveoli. It lowers surface tension and prevents the alveoli from collapsing and sticking together when air moves out of them.', wrong = '{"0": "Trapped dust is cleared by mucus and cilia in the airways and by white blood cells, not digested by surfactant.", "2": "Oxygen is carried in blood mainly by haemoglobin inside red blood cells.", "3": "Surfactant does not thicken the wall. The alveolar wall stays very thin so gases can diffuse quickly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1361' AND answer = 1;
UPDATE questions SET why = 'An alveolus is made of a moist epithelium only about 0.1 micrometre thick. Such a thin barrier means oxygen and carbon dioxide have a very short distance to diffuse between air and blood.', wrong = '{"0": "1 mm is 10,000 times thicker than the alveolar wall. Gases could not diffuse across it fast enough.", "1": "10 micrometres is 100 times thicker than the alveolar epithelium.", "2": "1 cm is far too thick. It is larger than a whole cluster of alveoli."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1362' AND answer = 3;
UPDATE questions SET why = 'The alveoli are the functional units of the lungs. An adult pair of lungs contains about 480 million alveoli, within a range of about 274 to 790 million, giving a huge total surface area for gas exchange.', wrong = '{"0": "480 thousand is a thousand times too few. The figure is in millions.", "2": "4.8 billion is ten times the actual figure of about 480 million.", "3": "48 million is ten times too few, and below the lowest value of the normal range."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1363' AND answer = 1;
UPDATE questions SET why = 'The lungs do not pull air in or push it out by themselves. Ventilation is produced by two sets of muscles: the dome-shaped diaphragm, which separates the thorax from the abdomen, and the intercostal muscles between the ribs.', wrong = '{"0": "The diaphragm is involved, but the other set named is the intercostal muscles, not the abdominal muscles.", "1": "The vocal cords produce sound and the epiglottis guards the glottis. Neither ventilates the lungs.", "3": "Smooth muscle of the bronchioles changes the width of the airways. It does not pump air in and out."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1364' AND answer = 2;
UPDATE questions SET why = 'During inspiration the intercostal muscles contract, raising the ribs and expanding the rib cage. At the same time the diaphragm contracts and flattens. Thoracic volume increases, lung pressure falls below atmospheric pressure and air flows in.', wrong = '{"1": "Relaxing intercostals lower the ribs. This happens in expiration, not inspiration.", "2": "Relaxed intercostals and a diaphragm rising back to its dome shape describe expiration.", "3": "The intercostal muscles are one of the two muscle sets that ventilate the lungs, so they do take part."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1365' AND answer = 0;
UPDATE questions SET why = 'The visceral pleura on the lungs and the parietal pleura on the thoracic wall adhere to each other through the thin layer of pleural fluid. So when the thorax enlarges, the lungs are pulled outward with it and expand.', wrong = '{"1": "Lung tissue does not actively contract to draw in air. The lungs follow the movement of the thorax.", "2": "The trachea only conducts air. It does not pump air into the lungs.", "3": "Surfactant prevents alveoli from collapsing. It does not pull the lungs outward."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1366' AND answer = 0;
UPDATE questions SET why = 'Air flows into the lungs only when lung pressure falls below atmospheric pressure. At high altitude atmospheric pressure is lower, so the thorax must expand more to make lung pressure low enough. This extra effort makes breathing harder.', wrong = '{"0": "Air at high altitude still contains oxygen. There is simply less air pressure overall.", "1": "Air pressure decreases as altitude increases. It is not higher.", "2": "The diaphragm still contracts normally at high altitude. The problem is the lower outside pressure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1367' AND answer = 3;
UPDATE questions SET why = 'Birds have lungs plus air sacs. Air flows in one direction: from outside to posterior air sacs, then through the lungs to anterior air sacs, and out. This air flows opposite to the blood, which makes gas exchange very efficient, even at high altitudes.', wrong = '{"0": "In birds air does not go in and out of the same sac. It moves one way through the system.", "2": "Birds do have lungs, and they also have air sacs attached to them.", "3": "Birds have several air sacs, both anterior and posterior, not just one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1368' AND answer = 1;
UPDATE questions SET why = 'Each breath starts in the respiratory centre in the medulla oblongata, part of the brain stem. Its neurons send impulses to the diaphragm and intercostal muscles, which contract for inspiration. When the impulses stop, the muscles relax and expiration follows.', wrong = '{"0": "The cerebrum handles thinking and voluntary actions. It is not the site of the respiratory centre.", "1": "The cerebellum coordinates movement and balance. It does not start each breath.", "3": "The spinal cord carries the impulses, but the breathing rhythm begins in the medulla oblongata."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1369' AND answer = 2;
UPDATE questions SET why = 'Inspiration stretches the thorax and lungs, putting them under elastic tension. At rest the diaphragm and intercostals simply relax, the ribs lower and the diaphragm becomes dome-shaped again. The lungs recoil, pressure inside rises above atmospheric, and air moves out.', wrong = '{"0": "Contraction of the diaphragm flattens it and causes inspiration, not expiration.", "2": "Ribs rise during inspiration. In expiration they move down and inwards.", "3": "Alveoli cannot pump air. Air leaves because the stretched lungs recoil and pressure rises."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1370' AND answer = 1;
UPDATE questions SET why = 'Plasma can dissolve only about 3 mL of oxygen per litre, yet whole blood carries almost 200 mL per litre. The difference is that most oxygen is not dissolved but bound to haemoglobin inside red blood cells.', wrong = '{"1": "Plasma has no oxygen pumps. Oxygen enters the blood by diffusion.", "2": "Oxygen dissolves poorly in water, which is exactly why plasma alone carries so little.", "3": "White blood cells defend the body. Oxygen is carried by red blood cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1371' AND answer = 0;
UPDATE questions SET why = 'At sea level, the partial pressure of oxygen in the alveoli is about 105 mm Hg. At this pressure about 97% of the haemoglobin in red blood cells combines with oxygen to form bright red oxyhaemoglobin.', wrong = '{"0": "About 35% saturation is found in venous blood during exercise, when PO₂ falls to about 20 mm Hg.", "1": "50% saturation is not a value linked to alveolar blood. At 105 mm Hg haemoglobin is almost fully loaded.", "2": "About 75% saturation is found in venous blood at rest, when PO₂ is about 40 mm Hg."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1372' AND answer = 3;
UPDATE questions SET why = 'Blood leaving the lungs is 97% saturated, and venous blood at rest is 75% saturated. The amount unloaded in the tissues is the difference: 97% − 75% = 22%. The 75% that stays bound is a reserve for times of extra need.', wrong = '{"1": "62% is the amount unloaded during exercise, worked out as 97% − 35%.", "2": "75% is the saturation that remains in venous blood. It is the reserve, not the amount unloaded.", "3": "97% is the saturation of arterial blood leaving the lungs, before any oxygen is unloaded."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1373' AND answer = 0;
UPDATE questions SET why = 'Arterial blood is still 97% saturated during exercise, but venous saturation falls to 35% as muscles take more oxygen. The oxygen unloaded is 97% − 35% = 62%, nearly three times the 22% unloaded at rest.', wrong = '{"0": "22% is the amount unloaded at rest, worked out as 97% − 75%.", "1": "35% is the saturation still left in venous blood during exercise, not the amount unloaded.", "3": "75% is the venous saturation at rest, not an amount of oxygen unloaded."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1374' AND answer = 2;
UPDATE questions SET why = 'Venous blood still holds a large reserve of oxyhaemoglobin. This reserve ensures the blood contains enough oxygen to maintain life for about four to five minutes if breathing is interrupted or the heart stops.', wrong = '{"0": "One hour is far too long. Without breathing, brain damage begins within minutes.", "1": "Ten seconds is far too short. The reserve lasts for a few minutes.", "3": "One day is impossible. The oxygen reserve lasts only about four to five minutes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1375' AND answer = 2;
UPDATE questions SET why = 'CO₂ produced by tissues lowers the pH of blood. A lower pH reduces haemoglobin''s affinity for oxygen, so oxygen is released more readily where it is most needed. This effect of pH on oxygen affinity is called the Bohr effect.', wrong = '{"0": "The direction is reversed. A fall in pH decreases haemoglobin''s affinity for oxygen.", "1": "Binding of carbon monoxide to haemoglobin causes CO poisoning. It is not the Bohr effect.", "2": "Movement of chloride ions into red cells in exchange for bicarbonate is the chloride shift."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1376' AND answer = 3;
UPDATE questions SET why = 'Active muscles produce more CO₂, which lowers blood pH, and more heat, which raises temperature. Both reduce haemoglobin''s affinity for oxygen, so haemoglobin unloads a higher percentage of its oxygen to the working muscles.', wrong = '{"1": "In active tissue blood pH falls because of extra CO₂. It does not rise.", "2": "Exercising muscles produce heat, so local temperature rises rather than falls.", "3": "Higher affinity would make haemoglobin hold oxygen more tightly. During exercise affinity decreases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1377' AND answer = 0;
UPDATE questions SET why = 'Carbon dioxide moves by diffusion from high to low partial pressure. Tissues produce CO₂, so its partial pressure is higher in tissues than in blood and it diffuses into the blood. In the lungs alveolar PCO₂ is lower, so it diffuses out.', wrong = '{"0": "CO₂ is not actively pumped. It diffuses down its partial pressure gradient.", "1": "This is reversed. PCO₂ is higher in the tissues, which is why CO₂ moves into the blood.", "2": "Haemoglobin carries some CO₂ once it is in the blood, but it does not pull CO₂ out of tissues."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1378' AND answer = 3;
UPDATE questions SET why = 'About 72% of CO₂ travels as bicarbonate. CO₂ enters red blood cells and combines with water to form carbonic acid, CO₂ + H₂O → H₂CO₃, catalysed by the enzyme carbonic anhydrase. Carbonic acid then splits into H⁺ and HCO₃⁻.', wrong = '{"0": "Pepsin is a protein-digesting enzyme of the stomach.", "2": "Rubisco is a plant enzyme that fixes CO₂ in the Calvin cycle of photosynthesis.", "3": "Trypsin is a protein-digesting enzyme from the pancreas, active in the duodenum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1379' AND answer = 1;
UPDATE questions SET why = 'Bicarbonate ions formed inside red blood cells move out into the plasma. A transporter in the membrane exchanges each bicarbonate ion for a chloride ion moving in. This exchange is called the chloride shift, or Hamburger phenomenon.', wrong = '{"0": "The Bohr effect is the fall in haemoglobin''s oxygen affinity when blood pH falls.", "1": "The Z-scheme describes electron flow in the light reactions of photosynthesis.", "3": "Haldane reflex is not the name of this ion exchange. The swap of Cl⁻ for HCO₃⁻ is the chloride shift."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1380' AND answer = 2;
UPDATE questions SET why = 'Blood carries CO₂ in three ways: about 72% as bicarbonate ions, about 20% bound to the globin part of haemoglobin, and about 8% dissolved in plasma. So the share bound to haemoglobin is about 20%.', wrong = '{"0": "About 8% is the share carried dissolved in plasma.", "2": "About 72% is the share carried as bicarbonate ions, the main form.", "3": "97% is the oxygen saturation of haemoglobin in arterial blood, not a CO₂ figure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1381' AND answer = 1;
UPDATE questions SET why = 'Oxygen binds to the iron ion of each haem group, while CO₂ binds to the globin (protein) chains of haemoglobin. Because they use different sites, they do not compete for binding.', wrong = '{"1": "CO₂ does not bind the iron at all. Only oxygen binds the iron of haem.", "2": "About 20% of CO₂ is carried bound to haemoglobin inside red cells, not only in plasma.", "3": "Oxygen binds the iron of the haem group, not the globin chains."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1382' AND answer = 0;
UPDATE questions SET why = 'Carbon monoxide, from incomplete burning of fuel, binds to haemoglobin with a much higher affinity than oxygen. This leaves less haemoglobin free to carry oxygen, so tissues receive too little and suffer hypoxia.', wrong = '{"0": "CO does not destroy red blood cells. It blocks their haemoglobin from carrying oxygen.", "1": "CO is a gas inhaled through open airways. It does not block the trachea.", "3": "CO does not form bicarbonate. Bicarbonate is formed from CO₂, a different gas."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1383' AND answer = 2;
UPDATE questions SET why = 'A haemoglobin molecule has four globin polypeptide chains, two alpha and two beta. Each chain holds one haem group in a pocket, so there are four haem groups, and each can carry one O₂ molecule.', wrong = '{"0": "One polypeptide chain with one haem group describes myoglobin, the oxygen store of muscle.", "1": "Haemoglobin has two alpha and two beta chains, not four alpha chains, and it has four haem groups.", "2": "Haemoglobin has four chains and four haem groups, not two of each."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1384' AND answer = 3;
UPDATE questions SET why = 'Adult haemoglobin has two kinds of globin chain. Each alpha (α) chain contains 141 amino acids and each beta (β) chain contains 146. A quick memory hook: the alpha chain, first in the alphabet, is the shorter one.', wrong = '{"0": "This reverses the two. The alpha chain has 141 amino acids and the beta chain has 146.", "2": "153 amino acids is the length of the single chain of myoglobin, not the alpha chain of haemoglobin.", "3": "The alpha value of 141 is right, but 153 is the length of myoglobin''s chain. The beta chain has 146."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1385' AND answer = 1;
UPDATE questions SET why = 'Each haem group consists of an iron ion held in the centre of a porphyrin ring, a flat ring built from four smaller pyrrole rings. Under high oxygen partial pressure, this iron binds one O₂ molecule.', wrong = '{"1": "Pyrrole units are present, but they are joined into a closed porphyrin ring, not left as an open chain.", "2": "A magnesium complex is found at the centre of chlorophyll. Haem holds iron, not magnesium.", "3": "A long hydrocarbon (phytol) tail is a feature of chlorophyll. The haem group has no such tail."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1386' AND answer = 0;
UPDATE questions SET why = 'Myoglobin, found in skeletal and cardiac muscle, binds oxygen more tightly than haemoglobin. It holds on to oxygen and releases it only when PO₂ falls very low, below about 20 mm Hg, so it acts as an oxygen store for working muscle.', wrong = '{"0": "Myoglobin has only one haem group, so it binds just one O₂ molecule. Haemoglobin carries four.", "1": "Myoglobin is found in skeletal and cardiac muscle cells, not in red blood cells.", "2": "Myoglobin releases oxygen only when PO₂ is low, below about 20 mm Hg, not at high partial pressure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1387' AND answer = 3;
UPDATE questions SET why = 'Myoglobin has a high affinity for oxygen, so it keeps its oxygen until the partial pressure of oxygen in muscle falls below about 20 mm Hg. It then releases it, supplying muscles when they most need it, such as during hard exercise.', wrong = '{"1": "40 mm Hg is the PO₂ of venous blood at rest. Myoglobin still holds its oxygen at this level.", "2": "80 mm Hg is a high PO₂, near arterial levels. Myoglobin stays fully loaded here.", "3": "105 mm Hg is the PO₂ in the alveoli, where pigments load oxygen rather than release it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1388' AND answer = 0;
UPDATE questions SET why = 'Sinusitis is inflammation of the lining of the sinuses. Acute sinusitis lasts about 7 to 10 days, while sinusitis that lasts longer than 12 weeks is called chronic.', wrong = '{"0": "Acute sinusitis is short-lived, lasting about 7 to 10 days, not more than 12 weeks.", "1": "Self-limiting means a condition clears up on its own. It is not the term for long duration.", "3": "Congenital means present from birth. It does not describe how long an infection lasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1389' AND answer = 2;
UPDATE questions SET why = 'Most cases of sinusitis are caused by viral infections, and these usually clear up without antibiotics. Some cases are bacterial, and rare cases involve fungi.', wrong = '{"0": "Bacteria cause only some cases of sinusitis, which are treated with antibiotics. Viruses cause most.", "2": "Fungi cause only rare cases of sinusitis.", "3": "Protozoa are not listed among the causes of sinusitis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1390' AND answer = 1;
UPDATE questions SET why = 'Otitis media is inflammation of the middle ear. Its common cause is fluid building up in the Eustachian tube that cannot drain from the middle ear. The trapped fluid lets bacteria and viruses grow there.', wrong = '{"1": "Inflamed alveoli filled with pus and fluid describe pneumonia, a lower respiratory infection.", "2": "Damage to the vocal cords affects the voice. It has nothing to do with middle-ear infection.", "3": "Mycobacterium tuberculosis in the lungs causes pulmonary tuberculosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1391' AND answer = 0;
UPDATE questions SET why = 'Pneumonia is an acute respiratory infection in which the alveoli of one or both lungs become inflamed and filled with pus and fluid. This makes breathing painful and limits oxygen intake.', wrong = '{"0": "Rupture of alveolar walls into larger air spaces happens in emphysema, not pneumonia.", "2": "Alveoli are not replaced by cartilage in any of these diseases. Cartilage supports only the larger airways.", "3": "Extra surfactant is not a feature of pneumonia. The alveoli fill with pus and fluid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1392' AND answer = 1;
UPDATE questions SET why = 'Pneumonia is caused mainly by bacteria or viruses, and less often by fungi. Among bacteria, Streptococcus pneumoniae is named in particular, while human rhinovirus is an example of a viral cause.', wrong = '{"0": "Mycobacterium tuberculosis causes tuberculosis, mainly pulmonary TB, not typical pneumonia.", "1": "Escherichia coli lives in the colon, where it produces vitamin K. It is not the named cause of pneumonia.", "2": "Vibrio cholerae causes cholera, an intestinal disease with severe diarrhoea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1393' AND answer = 3;
UPDATE questions SET why = 'In pulmonary tuberculosis, Mycobacterium tuberculosis multiplies in the lungs and damages lung tissue, including the alveoli. Small cavities form. In advanced stages the lungs cannot supply enough oxygen, leading to respiratory failure.', wrong = '{"0": "TB destroys alveoli. It does not make new ones.", "1": "A third lung cannot develop. TB damages the existing lung tissue.", "3": "TB damages alveoli. It does not thicken the cartilage rings of the airways."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1394' AND answer = 2;
UPDATE questions SET why = 'Major symptoms of pulmonary tuberculosis include cough, sometimes with blood, intermittent fever usually in the evening, night sweats, weight loss, loss of appetite, weakness and chest pain from inflamed pleura.', wrong = '{"0": "Loss of the sense of smell is a symptom of sinusitis.", "2": "Severe ear pain is a symptom of otitis media, a middle-ear infection.", "3": "Headache that worsens on bending over is a feature of sinusitis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1395' AND answer = 1;
UPDATE questions SET why = 'Most COPD is caused by smoking or long exposure to pollutants. A small number of people develop COPD or emphysema even without smoking because they have an inherited deficiency of the protein alpha-1 antitrypsin.', wrong = '{"1": "Haemoglobin deficiency causes anaemia, which reduces oxygen carriage. It is not a genetic cause of COPD.", "2": "Surfactant deficiency makes alveoli collapse, mainly in premature babies. It is not the cause named for COPD.", "3": "Carbonic anhydrase helps carry CO₂ as bicarbonate. Its deficiency is not linked to emphysema."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1396' AND answer = 0;
UPDATE questions SET why = 'Chronic bronchitis is a type of COPD. It involves inflammation and narrowing of the bronchial tubes, with increased mucus production that further blocks the airways and makes breathing difficult.', wrong = '{"0": "Rupture of alveolar walls into larger spaces describes emphysema, another type of COPD.", "1": "Infection of the middle ear is otitis media, an upper respiratory tract infection.", "3": "Alveoli filled with pus and fluid describe pneumonia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1397' AND answer = 2;
UPDATE questions SET why = 'In emphysema the walls of the alveoli are damaged and rupture, leaving fewer, larger air spaces with less surface for gas exchange. Smoking is the primary cause. Air pollution, dust, chemical fumes and alpha-1 antitrypsin deficiency can also cause it.', wrong = '{"0": "Viral infection is a common cause of sinusitis and pneumonia, not the primary cause of emphysema.", "1": "Undrained fluid in the Eustachian tube causes otitis media, a middle-ear infection.", "2": "Low altitude does not damage alveoli. It is not a cause of emphysema."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1398' AND answer = 3;
UPDATE questions SET why = 'Continued smoking speeds up the damage to alveoli in emphysema, so quitting smoking is the most important step in managing it. Bronchodilators, inhaled steroids, oxygen therapy and pulmonary rehabilitation are also used.', wrong = '{"0": "A long course of several antibiotics, about nine months, is the treatment for tuberculosis.", "1": "Nasal surgery is used for chronic or recurring sinusitis, not emphysema.", "3": "Removing the appendix treats appendicitis and has no link to lung disease."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1399' AND answer = 2;
UPDATE questions SET why = 'The heart lies in the middle of the chest, between the lungs. It is usually felt on the left because its left side, especially the left ventricle, is larger and stronger, since it pumps blood to all parts of the body.', wrong = '{"0": "The heart is not entirely in the left thorax. It sits in the middle of the chest, between the two lungs.", "1": "The right lung does not push the heart. The left lung is actually smaller, with a cardiac notch to make room for the heart.", "3": "The position of the aorta is not the reason. The heart is felt on the left because its left side is bigger and stronger."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1400' AND answer = 2;
UPDATE questions SET why = 'The pericardium has an outer fibrous layer made of strong connective tissue. This fibrous pericardium protects the heart against outside pressure and shocks, and prevents the heart from dilating excessively.', wrong = '{"0": "The inner lining of the heart chambers is the endocardium, a single layer of epithelial cells.", "2": "Pericardial fluid lies in the pericardial cavity between the parietal and visceral layers of the serous pericardium.", "3": "Impulses are conducted to the ventricles by the AV bundle and Purkinje fibres, not the pericardium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1401' AND answer = 1;
UPDATE questions SET why = 'The serous pericardium has two sub-layers. The inner visceral pericardium is closely attached to the heart and forms the outer lining of the heart wall, so it is also called the epicardium.', wrong = '{"1": "The endocardium is the innermost layer, lining the heart chambers.", "2": "The myocardium is the thick middle layer of cardiac muscle.", "3": "The fibrous pericardium is the tough outermost layer of the sac, not the layer attached to the heart."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1402' AND answer = 0;
UPDATE questions SET why = 'The pericardial cavity is the space between the parietal and visceral layers of the serous pericardium. It holds up to 50 mL of pericardial fluid, which lubricates the beating heart and helps protect it from infection.', wrong = '{"0": "The parietal pericardium lies directly beneath the fibrous pericardium, with no fluid cavity between them.", "1": "The myocardium and endocardium are layers of the heart wall, joined together without a cavity.", "2": "The space between the two atria is filled by the interatrial septum, not the pericardial cavity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1403' AND answer = 3;
UPDATE questions SET why = 'The heart wall has three layers: epicardium outside, myocardium in the middle and endocardium inside. The myocardium, made of cardiac muscle, is the thickest layer because it does the work of pumping.', wrong = '{"0": "The epicardium is the thin outer lining of the heart wall, formed by the visceral pericardium.", "1": "The endocardium is only a single layer of epithelial cells lining the chambers.", "2": "The pericardium is the sac around the heart, not a layer of the heart wall itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1404' AND answer = 3;
UPDATE questions SET why = 'The interatrial septum separates the two thin-walled atria, and the interventricular septum separates the two thick-walled ventricles. The interventricular septum is much thicker, matching the stronger walls of the ventricles.', wrong = '{"1": "The interatrial septum is the thinner one, like the thin walls of the atria.", "2": "The two septa are not equal. The interventricular septum is much thicker.", "3": "The heart does have septa: interatrial, interventricular and atrioventricular."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1405' AND answer = 0;
UPDATE questions SET why = 'The tricuspid valve, made of three cusps, lies between the right atrium and right ventricle. When the ventricle contracts it closes and stops blood flowing back into the atrium.', wrong = '{"0": "The valve between the left atrium and left ventricle is the bicuspid (mitral) valve, with two cusps.", "2": "Between the right ventricle and pulmonary trunk lies the pulmonary semilunar valve.", "3": "Between the left ventricle and aorta lies the aortic semilunar valve."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1406' AND answer = 1;
UPDATE questions SET why = 'The pulmonary and aortic valves are semilunar (half-moon shaped) valves at the exits of the ventricles. When the ventricles relax, pressure in them falls, and these valves close to prevent blood flowing back from the arteries.', wrong = '{"0": "When the ventricles contract, the semilunar valves open to let blood out into the arteries.", "1": "Atrial contraction pushes blood through the open AV valves. The semilunar valves are not closing because of it.", "3": "Firing of the SA node starts the heartbeat. The semilunar valves close because the ventricles relax."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1407' AND answer = 2;
UPDATE questions SET why = 'The right ventricle pumps blood only to the nearby lungs. The left ventricle has to push blood to all parts of the body against higher resistance, so its muscular wall is about three times thicker.', wrong = '{"0": "Receiving blood from the lungs is the job of the left atrium, through the pulmonary veins.", "1": "Both ventricles hold and pump about the same volume of blood. The thicker wall is about pressure, not volume.", "2": "Pumping blood to the lungs is the job of the right ventricle, which has the thinner wall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1408' AND answer = 3;
UPDATE questions SET why = 'The right atrium receives deoxygenated blood from the body through two large veins: the superior vena cava from the upper body and the inferior vena cava from the lower body.', wrong = '{"0": "The pulmonary veins carry oxygenated blood from the lungs into the left atrium.", "1": "The aorta carries oxygenated blood out of the left ventricle to the body.", "3": "The coronary arteries supply oxygenated blood to the heart muscle itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1409' AND answer = 2;
UPDATE questions SET why = 'When the right ventricle contracts, blood passes through the pulmonary semilunar valve into the pulmonary trunk. This divides into the right and left pulmonary arteries, which carry it to the lungs. Oxygenated blood returns by the pulmonary veins to the left atrium.', wrong = '{"0": "The aortic valve and aorta belong to the left ventricle and carry blood to the body, not to the lungs.", "2": "This has the vessels reversed. Pulmonary arteries carry blood to the lungs and pulmonary veins bring it back.", "3": "This order runs backwards. Blood reaches the lungs through the pulmonary trunk and leaves through the pulmonary veins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1410' AND answer = 1;
UPDATE questions SET why = 'One heartbeat lasts about 0.8 s. Diastole, when all chambers relax and fill, lasts about 0.4 s, atrial systole about 0.1 s and ventricular systole about 0.3 s. Check: 0.4 + 0.1 + 0.3 = 0.8 s.', wrong = '{"1": "This swaps diastole and ventricular systole timings wrongly. Diastole is the longest phase, about 0.4 s, not 0.1 s.", "2": "This swaps diastole and ventricular systole. Diastole is 0.4 s and ventricular systole is 0.3 s.", "3": "This swaps the two systoles. Atrial systole is the shortest phase at 0.1 s, and ventricular systole is 0.3 s."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1411' AND answer = 0;
UPDATE questions SET why = 'When the ventricles contract, pressure inside them rises. This closes the tricuspid and bicuspid (AV) valves, stopping backflow into the atria, and pushes open the pulmonary and aortic (semilunar) valves so blood leaves the heart.', wrong = '{"0": "Open AV valves with closed semilunar valves is the pattern when the ventricles are filling, not when they contract.", "1": "If all valves were open, blood would flow back into the atria. The AV valves must be closed.", "3": "The semilunar valves open during ventricular systole to let blood out into the arteries."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1412' AND answer = 2;
UPDATE questions SET why = 'The heart beats continuously, about 70 times a minute in an adult, throughout life. Over an average lifetime this adds up to about 2.5 billion beats without stopping.', wrong = '{"1": "2.5 million is a thousand times too few. At about 70 beats a minute this is reached in less than a month.", "2": "250 million is ten times too few. It would be reached in well under ten years.", "3": "25 billion is ten times too many. It would need a lifespan of several hundred years."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1413' AND answer = 0;
UPDATE questions SET why = 'The heartbeat has two sounds. ''Lubb'' comes when the ventricles contract and the AV valves close. ''Dubb'' comes when ventricular systole ends, the ventricles relax and the pulmonary and aortic semilunar valves close.', wrong = '{"0": "Closure of the tricuspid and bicuspid valves at the start of ventricular systole makes the ''lubb'' sound.", "1": "Contraction of the atria is not the source of either main heart sound.", "2": "Heart sounds come from valves closing, not opening."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1414' AND answer = 3;
UPDATE questions SET why = 'If heart valves do not close fully, or open only narrowly, blood flow becomes turbulent inside the heart. This turbulence can be heard through a stethoscope as a hissing sound called a heart murmur.', wrong = '{"0": "Lubb-dubb is the normal pair of heart sounds made by valves closing properly.", "2": "A problem with the SA node affects the rhythm of the heartbeat, not the sound of blood through valves.", "3": "Rupture of a blood vessel causes bleeding (haemorrhage), not a heart murmur."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1415' AND answer = 1;
UPDATE questions SET why = 'The SA node, or pacemaker, is a small cluster of specialised cardiac muscle cells embedded in the upper wall of the right atrium. It sends out the impulses that start each heartbeat.', wrong = '{"0": "The lower part of the interatrial septum is where the AV node lies.", "1": "The interventricular septum contains the AV bundle (bundle of His).", "2": "The walls of the ventricles contain the Purkinje fibres, not the SA node."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1416' AND answer = 3;
UPDATE questions SET why = 'The AV node, like the SA node, is a small cluster of cardiac muscle cells. It lies in the lower portion of the interatrial septum and passes impulses from the atria on to the ventricles.', wrong = '{"0": "The upper wall of the right atrium is the location of the SA node, the pacemaker.", "1": "The apex of the ventricle is reached by Purkinje fibres, not the AV node.", "3": "The aortic arch contains baroreceptors that sense blood pressure. No part of the conduction system lies there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1417' AND answer = 2;
UPDATE questions SET why = 'The SA node fires first and the atria contract. The impulse then reaches the AV node, passes into the AV bundle (bundle of His) in the interventricular septum, and its branches end in the Purkinje fibres, which make the ventricles contract.', wrong = '{"0": "The heartbeat starts at the SA node, not the AV node, and Purkinje fibres come after the bundle of His.", "2": "Purkinje fibres are the last part of the pathway. The AV node and bundle of His come before them.", "3": "The bundle of His cannot come first. The SA node starts each beat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1418' AND answer = 1;
UPDATE questions SET why = 'Impulses take about 0.15 s to pass from the SA node to the AV node. This delay lets atrial systole be completed, so the ventricles fill fully before ventricular systole begins.', wrong = '{"1": "The atria contract before the ventricles. The delay ensures this order rather than reversing it.", "2": "The semilunar valves open when ventricular pressure rises during ventricular systole, not because of this delay.", "3": "The delay is only about 0.15 s. The heart never rests for a whole minute."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1419' AND answer = 0;
UPDATE questions SET why = 'If the SA node is weak or impulses are blocked, the heartbeat may become irregular or stop. Such patients receive an artificial pacemaker, a battery-operated device implanted near the AV node that emits electrical signals to trigger normal beats.', wrong = '{"0": "A leaky mitral valve is a valve problem. Damaged valves are corrected by replacing them, not by a pacemaker.", "1": "High cholesterol is managed with diet, exercise and medicine. It is not an indication for a pacemaker.", "2": "A blocked coronary artery is treated by angioplasty or bypass surgery, not by a pacemaker."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1420' AND answer = 3;
UPDATE questions SET why = 'The SA node and AV node set the normal heart rate, but the brain can change it. During fever or exercise, a control centre in the brain sends nerve signals to both nodes to speed up the heart. At rest or during sleep it slows them down.', wrong = '{"0": "The heart keeps receiving blood. The faster rate is caused by nerve signals from the brain.", "1": "The SA node is not removed. It is stimulated by the brain to fire faster.", "3": "Slower Purkinje fibres would not speed up the heart. The rate rises because the nodes are stimulated."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1421' AND answer = 2;
UPDATE questions SET why = 'The heart of an average adult at rest beats about 70 times per minute. At this rate it pumps the whole blood volume, about 5 litres, every minute.', wrong = '{"0": "40 beats per minute is much slower than an average adult resting rate.", "2": "120 beats per minute is a fast rate, seen during exercise or fever, not the average resting rate.", "3": "200 beats per minute is far above the normal resting rate of an adult."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1422' AND answer = 1;
UPDATE questions SET why = 'An ECG records electrical activity of the heart. The P wave shows the beginning of atrial depolarization, started by the SA node, which leads to atrial contraction. Irregular or absent P waves may indicate arrhythmia.', wrong = '{"1": "Depolarization of the ventricles is shown by the QRS complex.", "2": "Repolarization of the ventricles is shown by the T wave.", "3": "An ECG records electrical events, not the mechanical closing of valves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1423' AND answer = 0;
UPDATE questions SET why = 'The time from the start of atrial depolarization to the start of ventricular depolarization is normally about 0.12 to 0.20 s. If it is prolonged, the impulse is being delayed between the atria and ventricles, which indicates a first-degree heart block.', wrong = '{"0": "Myocardial infarction is shown by an elevated ST segment and hyper-acute T waves, not a long PR.", "2": "Electrolyte disturbance is suggested by T wave abnormalities.", "3": "Ventricular tachycardia shows up as abnormalities of the QRS complex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1424' AND answer = 1;
UPDATE questions SET why = 'The ST segment shows completion of ventricular depolarization. When heart muscle receives too little blood and oxygen, a condition called ischemia, the ST segment can be depressed. In myocardial infarction it is elevated instead.', wrong = '{"0": "First-degree heart block shows up as a prolonged PR interval, not a depressed ST segment.", "1": "In a normal resting heart the ST segment is flat, neither depressed nor elevated.", "3": "Absent or irregular P waves point to arrhythmia. They do not describe ST depression."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1425' AND answer = 2;
UPDATE questions SET why = 'On an ECG, the T wave follows the QRS complex and represents the beginning of ventricular repolarization, when the ventricles recover electrically after contracting. T wave abnormalities may indicate electrolyte disturbance.', wrong = '{"1": "Atrial depolarization, started by the SA node, is shown by the P wave.", "2": "Atrial repolarization happens during the QRS complex and is hidden by it.", "3": "Ventricular depolarization is shown by the QRS complex, not the T wave."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1426' AND answer = 0;
UPDATE questions SET why = 'Blue babies have cyanosis, a bluish skin, because oxygenated and deoxygenated blood mix. This happens if the interatrial foramen between the atria fails to close, or the ductus arteriosus between the pulmonary artery and aorta fails to constrict, during development.', wrong = '{"0": "Problems with the SA node affect heart rhythm. They are not the cause of blue babies.", "1": "Blue babies have normal lungs with alveoli. The problem is mixing of blood in the heart and great vessels.", "2": "Blue babies have a four-chambered heart. The problem is an opening that failed to close."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1427' AND answer = 3;
UPDATE questions SET why = 'Artery walls have three layers. The middle layer, the tunica media, is made of thick muscular tissue with elastic fibres, so it can withstand the high blood pressure produced during ventricular systole.', wrong = '{"0": "The tunica intima is only a thin layer of endothelial cells lining the lumen. It gives little strength.", "2": "The tunica externa is an outer covering of connective and elastic tissue. It is not the main pressure-bearing layer.", "3": "The lumen is the hollow space through which blood flows, not a layer of the wall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1428' AND answer = 1;
UPDATE questions SET why = 'Arteries carry blood away from the heart, and nearly all carry oxygenated blood. The exception is the pulmonary arteries, which carry deoxygenated blood from the right ventricle to the lungs to be oxygenated.', wrong = '{"0": "The aorta carries oxygenated blood from the left ventricle to the body.", "1": "Coronary arteries arise from the aorta and carry oxygenated blood to the heart muscle.", "2": "Renal arteries carry oxygenated blood to the kidneys."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1429' AND answer = 3;
UPDATE questions SET why = 'The internal diameter of a capillary is only about 8 micrometres, about the size of a red blood cell. This is why red blood cells pass through capillaries in single file.', wrong = '{"0": "8 mm is a thousand times too wide. That is closer to the size of a large artery.", "1": "0.1 micrometre is the thickness of the alveolar epithelium. A red cell could never pass through such a gap.", "3": "100 micrometres is the greatest distance of any body cell from a capillary, not a capillary''s width."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1430' AND answer = 2;
UPDATE questions SET why = 'The wall of a capillary is just a single layer of endothelial cells. This very thin wall lets water, gases, nutrients and wastes pass easily between blood and tissues by diffusion or active transport.', wrong = '{"0": "Three-layered walls are found in arteries and veins, not capillaries.", "2": "Smooth muscle and elastic fibres make up the tunica media of arteries and veins. Capillaries lack this layer.", "3": "Blood vessels do not contain cartilage. Cartilage supports airways such as the trachea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1431' AND answer = 1;
UPDATE questions SET why = 'Pressure in capillaries pushes fluid out into the tissues. This interstitial fluid carries water, nutrients, hormones, gases, wastes and small proteins. Large proteins, red blood cells and platelets are too big and stay inside the capillaries.', wrong = '{"1": "Water leaks out of capillaries continuously and forms most of the interstitial fluid.", "2": "Dissolved gases such as oxygen and carbon dioxide pass freely through capillary walls.", "3": "Small nutrients such as glucose leave capillaries to reach the body cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1432' AND answer = 0;
UPDATE questions SET why = 'Veins carry blood at low pressure, so their middle layer, the tunica media, is thin, only slightly muscular and has few elastic fibres. Without this support an empty vein collapses like an empty balloon, while a thick-walled artery stays open.', wrong = '{"0": "Veins do have an endothelium, the tunica intima, just like arteries.", "1": "Veins usually have a wider lumen than arteries. Lumen size is not why they collapse.", "2": "Valves in veins stop backflow of blood. They do not make the vein collapse."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1433' AND answer = 3;
UPDATE questions SET why = 'Blood pressure in veins is low. Semilunar valves inside veins stop blood flowing backwards, and contraction of the skeletal muscles around veins presses on them, pushing blood towards the heart.', wrong = '{"1": "Most of the pressure from the left ventricle is used up by the time blood reaches the veins.", "2": "Precapillary sphincters control how much blood enters capillary loops. They do not return blood to the heart.", "3": "The SA node starts each heartbeat. It does not act on veins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1434' AND answer = 0;
UPDATE questions SET why = 'Some capillaries are connected to arterioles and venules through loops of other capillaries. The entry of each loop is guarded by a ring of muscle called a precapillary sphincter, which controls how much blood flows into it.', wrong = '{"0": "Semilunar valves are found at the exits of the ventricles and inside veins, where they stop backflow.", "2": "The AV node passes electrical impulses in the heart. It does not control capillary flow.", "3": "Lymph nodes filter lymph and contain lymphocytes. They do not control blood flow into capillaries."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1435' AND answer = 1;
UPDATE questions SET why = 'The amount of blood in capillaries is controlled by constricting or dilating them. Nervous stimulation can constrict capillaries, while certain chemicals, such as histamine, dilate them.', wrong = '{"0": "Antidiuretic hormone constricts arterioles and makes the kidneys retain water. It does not dilate capillaries.", "1": "Calcium is not the chemical named for dilating capillaries.", "3": "Fibrin is the protein that forms the mesh of a blood clot. It does not dilate vessels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1436' AND answer = 2;
UPDATE questions SET why = 'When a tissue becomes more active, oxygen falls and carbon dioxide rises in its interstitial fluid. In response, the circular muscles of its arterioles relax (vasodilation), increasing blood flow to bring more oxygen and remove more CO₂.', wrong = '{"0": "Constriction of arterioles happens when metabolic activity decreases, not when it rises.", "2": "Closing arterioles would stop the supply just when the tissue needs more oxygen.", "3": "Arterioles respond to metabolic activity. This is a key way blood is directed to active tissues."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1437' AND answer = 1;
UPDATE questions SET why = 'Blood flows fastest in the aorta, about 450 to 500 mm/s, and slows along the arteries and arterioles. It is slowest in the capillaries, which gives time for exchange with tissues, and then speeds up again in venules and veins, about 250 to 300 mm/s in the venae cavae.', wrong = '{"0": "The aorta has the highest velocity, about 450 to 500 mm/s.", "1": "Velocity rises again in the venae cavae to about 250 to 300 mm/s.", "3": "Arterioles carry blood faster than capillaries, since velocity keeps falling until the capillaries."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1438' AND answer = 2;
UPDATE questions SET why = 'Blood velocity depends on the total cross-sectional area of the vessels. Capillaries are each tiny, but there are so many that their combined area is huge, so blood slows down there. In the few large veins the total area is smaller, so blood speeds up again.', wrong = '{"1": "The colour of blood depends on oxygen content. It has no effect on how fast blood flows.", "2": "The number of red cells is similar throughout the circulation, so it cannot explain the changes in speed.", "3": "Endothelium thickness is not what changes velocity. The key factor is total cross-sectional area."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1439' AND answer = 0;
UPDATE questions SET why = 'After supplying the heart muscle, coronary capillaries unite into venules and coronary veins. Most coronary veins join to form the coronary sinus, which opens into the right atrium. A few small veins drain directly into the right atrium.', wrong = '{"0": "Pulmonary veins carry oxygenated blood from the lungs into the left atrium.", "1": "The superior vena cava drains the upper body. Coronary veins mainly drain through the coronary sinus.", "2": "The hepatic portal vein carries blood from the gut and spleen to the liver."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1440' AND answer = 3;
UPDATE questions SET why = 'The heart muscle gets its own blood supply through the coronary circulation. The right and left coronary arteries arise from the aorta near its origin, so they receive fully oxygenated blood just as it leaves the left ventricle.', wrong = '{"0": "The pulmonary trunk carries deoxygenated blood to the lungs. It cannot supply the heart muscle.", "1": "The right atrium is a chamber that receives deoxygenated blood. Coronary arteries do not arise from it.", "3": "The inferior vena cava is a vein carrying deoxygenated blood towards the heart. Arteries do not arise from veins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1441' AND answer = 2;
UPDATE questions SET why = 'A portal system is a circulation in which veins end in capillaries instead of going straight to the heart. In the hepatic portal system, the hepatic portal vein carries blood from the gut and spleen and breaks into capillaries in the liver.', wrong = '{"0": "Arteries opening directly into veins would skip capillaries. In a portal system a vein ends in capillaries.", "1": "Blood flow to and from the lungs is the pulmonary circulation.", "2": "A portal system depends on capillaries, at both its start and its end."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1442' AND answer = 3;
UPDATE questions SET why = 'The hepatic portal vein collects blood from the spleen and the alimentary canal and carries it to the liver. The liver removes harmful substances and stores nutrients before the blood goes on to the heart through the hepatic veins.', wrong = '{"1": "The kidneys drain through the renal veins into the inferior vena cava.", "2": "The lungs drain through the pulmonary veins into the left atrium.", "3": "Blood from the brain returns through veins to the superior vena cava, not to the hepatic portal vein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1443' AND answer = 0;
UPDATE questions SET why = 'In each kidney, afferent arterioles form the glomerular capillaries, which unite into an efferent arteriole. The efferent arteriole divides into two sets of capillaries: peritubular capillaries around tubules in the cortex, and vasa recta around tubules in the medulla.', wrong = '{"0": "Glomerular capillaries come from the afferent arteriole, before the efferent arteriole.", "2": "The renal vein forms later, when venules and small veins from these capillaries unite.", "3": "Afferent arterioles come before the glomerulus. The efferent arteriole does not divide into them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1444' AND answer = 1;
UPDATE questions SET why = 'In a normal young adult, the highest arterial pressure during ventricular systole (systolic) is about 120 mm Hg, and the lowest pressure before the next contraction (diastolic) is about 80 mm Hg. This is written as 120/80.', wrong = '{"0": "40 mm Hg is far below a normal diastolic pressure.", "2": "120 mm Hg is the normal systolic pressure, not the diastolic.", "3": "140 mm Hg is the systolic level above which pressure is counted as hypertension."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1445' AND answer = 1;
UPDATE questions SET why = 'A sphygmomanometer is used to measure blood pressure manually. The rise and fall of its mercury column gives the systolic and diastolic readings.', wrong = '{"1": "An electrocardiograph records the electrical activity of the heart as an ECG.", "2": "A stethoscope lets a doctor hear sounds such as lubb-dubb. On its own it does not measure pressure.", "3": "Angiography is an X-ray examination of blood vessels using a contrast dye."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1446' AND answer = 0;
UPDATE questions SET why = 'Pressure receptors called baroreceptors are found in the carotid arteries, which supply the head and brain, and in the aortic arch. When blood pressure falls, they send information to the brain.', wrong = '{"0": "The right atrium contains endocrine cells that secrete ANH when stretched, not the baroreceptors.", "2": "The kidneys adjust blood volume in response to hormones like ADH. They are not where baroreceptors are found.", "3": "The pulmonary veins return blood from the lungs. Baroreceptors are not located there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1447' AND answer = 1;
UPDATE questions SET why = 'When blood pressure falls, baroreceptors send signals to the brain''s control centre. It responds by increasing the rate and force of heart contraction and by constricting arterioles (vasoconstriction). Both changes raise blood pressure back to normal.', wrong = '{"0": "Slowing the heart would lower blood pressure further, the opposite of what is needed.", "1": "Dilating arterioles lowers blood pressure. The response to low pressure is vasoconstriction.", "3": "ANH increases salt and water loss and lowers pressure. It is released when blood volume is high."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1448' AND answer = 2;
UPDATE questions SET why = 'Endocrine cells in the wall of the right atrium secrete atrial natriuretic hormone (ANH) when the atrium is stretched by increased blood volume. ANH speeds up loss of salts and water in urine, lowering blood volume and pressure.', wrong = '{"0": "A fall in blood volume triggers thirst and ADH release, which raise volume. ANH is released when volume is high.", "1": "Thirst goes with low blood volume, while ANH is released when volume is high.", "2": "A weak SA node affects heart rhythm. It is not the trigger for ANH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1449' AND answer = 3;
UPDATE questions SET why = 'When blood volume and pressure fall, the posterior pituitary releases antidiuretic hormone (ADH). ADH makes the kidneys retain more water, restoring blood volume, and it also constricts arterioles. Both effects raise blood pressure.', wrong = '{"0": "Increasing salt excretion is the action of ANH, which lowers blood pressure.", "2": "ADH constricts arterioles. Dilating them would lower pressure.", "3": "ADH does not slow the heart. Its effects are on the kidneys and arterioles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1450' AND answer = 1;
UPDATE questions SET why = 'Atherosclerosis is the build-up of materials inside arteries, such as fats, cholesterol, fibrin, smooth muscle cells and cell debris. Of these, accumulation of cholesterol is thought to be the prime contributor.', wrong = '{"0": "Calcium deposits harden arterial walls in arteriosclerosis, which often follows severe atherosclerosis.", "1": "Glucose is not listed as a material that builds up in arteries in atherosclerosis.", "2": "Haemoglobin stays inside red blood cells. It is not deposited in artery walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1451' AND answer = 3;
UPDATE questions SET why = 'Arteriosclerosis means hardening of the arterial walls. It happens when calcium is deposited in them, so arteries cannot expand normally and the heart must work harder. Severe atherosclerosis usually leads to arteriosclerosis.', wrong = '{"0": "Cholesterol build-up is the prime contributor to atherosclerosis, not the cause of hardening.", "1": "Fibrin forms the mesh of blood clots. It is one material in atherosclerotic deposits, but hardening is due to calcium.", "3": "Lymph is fluid in lymph vessels. It is not deposited in artery walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1452' AND answer = 2;
UPDATE questions SET why = 'In coronary angiography, a catheter is guided through large arteries to the opening of the coronary arteries. A contrast medium (dye) that shows up on X-rays is then injected, giving pictures called angiograms. Narrowing from clots can be seen.', wrong = '{"1": "Inflating a balloon inside a narrowed artery is angioplasty, a treatment, not the imaging step.", "2": "Placing electrodes on the chest is how an ECG records the heart''s electrical activity.", "3": "Listening with a stethoscope lets a doctor hear heart sounds, not see the coronary arteries."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1453' AND answer = 0;
UPDATE questions SET why = 'A thrombus is a clot that forms inside a blood vessel. If it breaks loose and is carried by the blood to another place in the circulation, it is called an embolus.', wrong = '{"0": "An aneurysm is a bulge in a weakened artery wall. It is not a moving clot.", "2": "Angina pectoris is chest pain during exertion because the heart muscle gets too little oxygen.", "3": "An infarct is an area of dead tissue caused by lack of blood supply."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1454' AND answer = 1;
UPDATE questions SET why = 'A thrombus can form because of irritation or infection of the vessel lining, slow blood flow during long periods of inactivity, or diseases such as pneumonia, tuberculosis and emphysema.', wrong = '{"0": "Histamine dilates capillaries. High histamine is not listed as a cause of thrombus.", "1": "A strong SA node gives a normal heartbeat. It does not cause clots.", "2": "Swollen lymph nodes reflect infection or immune activity. They are not a cause of thrombosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1455' AND answer = 3;
UPDATE questions SET why = 'When coronary arteries are narrowed, usually by cholesterol build-up, the heart muscle may get too little blood. During stress or exertion this causes chest pain called angina pectoris. It shows the heart''s oxygen demand is greater than supply and warns that a heart attack may follow.', wrong = '{"1": "Death of heart muscle from lack of blood supply is myocardial infarction, a heart attack.", "2": "Rupture of a blood vessel in the brain is brain haemorrhage.", "3": "A hissing heart sound is a heart murmur, caused by faulty valves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1456' AND answer = 0;
UPDATE questions SET why = 'In coronary bypass surgery, a healthy blood vessel is taken from the patient''s leg, arm, chest or abdomen. Its ends are attached above and below the blocked part of the coronary artery, so blood flows around the blockage.', wrong = '{"0": "Using a balloon to widen the blocked artery is angioplasty.", "1": "Inserting an expandable mesh tube to keep the artery open is stenting.", "3": "Bypass surgery reroutes blood around a blockage. The heart is not replaced."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1457' AND answer = 2;
UPDATE questions SET why = 'A stent is an expandable stainless steel mesh tube mounted on a balloon catheter. Inflating the balloon in a narrowed artery expands the stent. The balloon is removed, but the stent stays to support the artery wall and keep it open.', wrong = '{"0": "A dye visible on X-rays is the contrast medium used in angiography.", "2": "A vessel taken from the leg is used as a graft in coronary bypass surgery.", "3": "A battery-operated device placed near the AV node is an artificial pacemaker."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1458' AND answer = 1;
UPDATE questions SET why = 'Hypertension is a chronic, long-lasting rise in blood pressure. It is diagnosed when blood pressure consistently stays above 140/90 mm Hg. Stress, obesity, high salt intake, smoking and heredity can contribute.', wrong = '{"0": "120/80 mm Hg is the normal blood pressure of a young adult.", "1": "100/60 mm Hg is lower than normal. It does not define hypertension.", "2": "90/60 mm Hg is low blood pressure, closer to hypotension than hypertension."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1459' AND answer = 3;
UPDATE questions SET why = 'Prolonged hypertension weakens cardiac muscle. The heart can no longer pump effectively enough to meet the tissues'' needs, and blood is retained in the heart and lungs. This is called congestive heart failure.', wrong = '{"1": "Sudden blockage of a coronary artery by a clot causes a heart attack (myocardial infarction).", "2": "Rupture of a blood vessel in the brain is brain haemorrhage, another possible effect of hypertension.", "3": "The SA node stopping is a conduction problem treated with a pacemaker, not congestive heart failure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1460' AND answer = 0;
UPDATE questions SET why = 'Fluid that leaks from blood capillaries into the tissues is called interstitial fluid. Its pressure forces some of it into blind-ended lymph capillaries, and once it is inside them it is called lymph.', wrong = '{"0": "Fluid that has just left the blood capillaries is interstitial fluid. It becomes lymph only after entering lymph capillaries.", "1": "Lymph returns to the blood at the subclavian veins, before reaching the heart. Entering the atrium does not create lymph.", "3": "Kidney filtration produces filtrate that becomes urine, not lymph."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1461' AND answer = 2;
UPDATE questions SET why = 'Lymph capillaries begin with blind endings in the interstitial fluid. They are more permeable than blood capillaries, so larger molecules, such as proteins, can enter them along with the fluid.', wrong = '{"0": "This is reversed. Lymph capillaries are more permeable than blood capillaries.", "1": "Lymph capillaries are not connected to arteries. They start as blind-ended tubes in the tissues.", "3": "Lymph capillaries have no cartilage. Their walls are thin and leaky."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1462' AND answer = 2;
UPDATE questions SET why = 'Lymph vessels join into two main ducts. The right lymphatic duct empties into the right subclavian vein, and the thoracic duct, the larger one, empties into the left subclavian vein, returning lymph to the blood.', wrong = '{"0": "The right subclavian vein receives the right lymphatic duct, not the thoracic duct.", "2": "The thoracic duct does not open into the inferior vena cava. It opens into the left subclavian vein.", "3": "Lymph does not enter the right atrium directly. It joins the blood at the subclavian veins first."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1463' AND answer = 1;
UPDATE questions SET why = 'Lymph has no pump of its own in humans. Its flow from the tissues towards the thoracic duct is kept up by contraction of skeletal muscles, movement of the viscera and breathing movements. Valves in lymph vessels prevent backflow.', wrong = '{"1": "Humans do not have a lymph heart. Lymph is moved by surrounding body movements.", "2": "The SA node controls the heartbeat. It does not move lymph.", "3": "Lymph vessels are not arteries and carry fluid at low pressure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1464' AND answer = 0;
UPDATE questions SET why = 'Every day more fluid leaks out of blood capillaries into the tissues than returns to them, about three litres extra in an average person. Lymph capillaries absorb this excess and return it to the bloodstream before the blood reaches the heart.', wrong = '{"0": "Up to 50 mL is the volume of pericardial fluid around the heart, not the daily lymph return.", "1": "About 8,000 litres is the volume of blood moving through the blood vessels each day.", "2": "About 5 litres per minute is the amount of blood the heart pumps (the whole blood volume each minute)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1465' AND answer = 3;
UPDATE questions SET why = 'The spleen is a large lymphoid organ. Its macrophages and lymphocytes filter blood, destroying foreign particles and aged red blood cells. The spleen also stores red blood cells.', wrong = '{"1": "Bile is produced by the liver and stored in the gallbladder.", "2": "ADH is secreted by the posterior pituitary gland.", "3": "The spleen does not pump lymph. Lymph flow depends on muscle activity, visceral movements and breathing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1466' AND answer = 0;
UPDATE questions SET why = 'A lymph node is a mass of connective tissue containing lymphocytes. Several afferent lymph vessels bring lymph into the node, and it is drained by a single efferent vessel. Inside, the lymph is filtered.', wrong = '{"0": "This is reversed. Several afferent vessels enter a node and only one efferent vessel leaves it.", "1": "Lymph nodes receive lymph through lymph vessels, not through arteries and veins.", "3": "The thoracic duct is a main collecting duct further along. Lymph reaches nodes through afferent lymph vessels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1467' AND answer = 2;
UPDATE questions SET why = 'Besides lymph nodes, the body has lymphoid masses, for example in the lining of the gut. The larger lymphoid masses are the spleen, thymus, tonsils and adenoids, and they produce lymphocytes.', wrong = '{"0": "The pancreas is a digestive and endocrine gland that makes pancreatic juice, insulin and glucagon.", "2": "The liver is a large gland that makes bile and processes nutrients. It is not a lymphoid mass.", "3": "The thyroid is an endocrine gland in the neck. It is not a lymphoid mass."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1468' AND answer = 1;
UPDATE questions SET why = 'The outer surface of a bone is covered by a tough membrane called the periosteum. Collagen fibres anchor it to the bone tissue underneath. Cartilage has a different covering, the perichondrium.', wrong = '{"0": "The perichondrium is the connective tissue layer that surrounds cartilage, not bone.", "1": "The sarcolemma is the plasma membrane of a muscle fibre.", "3": "The synovial membrane lines the fibrous capsule of a synovial joint and secretes synovial fluid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1469' AND answer = 2;
UPDATE questions SET why = 'A long bone has a long middle shaft called the diaphysis and two expanded ends called the epiphyses. The shaft is filled with yellow bone marrow.', wrong = '{"1": "The epiphyses are the two ends of a long bone, not the shaft.", "2": "The acetabulum is the bony socket in the hip bone where the head of the femur fits.", "3": "Lacunae are tiny spaces in bone or cartilage that hold osteocytes or chondrocytes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1470' AND answer = 0;
UPDATE questions SET why = 'Compact bone is built from repeating units called Haversian systems. Each has concentric lamellae of matrix around a central Haversian canal, with osteocytes in lacunae between the lamellae, linked by canaliculi.', wrong = '{"0": "Sarcomeres are the contractile units of muscle myofibrils, between two Z-lines.", "1": "Spongy bone has a lattice of bony spikes. Trabeculae of cartilage are not the units of compact bone.", "2": "Myofibrils are the threadlike bundles of actin and myosin inside muscle fibres."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1471' AND answer = 3;
UPDATE questions SET why = 'Bone matrix contains needle-shaped crystals of calcium phosphate and collagen fibres. The crystals are brittle but rigid, giving strength, while collagen is flexible but weak. Together they make bone both strong and flexible.', wrong = '{"0": "Collagen alone is flexible but weak. Bone needs mineral crystals for strength.", "2": "The mineral crystals in bone are calcium phosphate, and collagen is also needed for flexibility.", "3": "A matrix of collagen, elastin and proteoglycans describes cartilage, which has no mineral crystals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1472' AND answer = 1;
UPDATE questions SET why = 'Osteocytes sit in small spaces called lacunae between the lamellae of compact bone. They are linked to each other and to the central Haversian canal by tiny channels called canaliculi, through which materials pass.', wrong = '{"0": "T-tubules are infoldings of the sarcolemma in muscle fibres.", "1": "Lacteals are lymph vessels inside the villi of the small intestine.", "2": "Plasmodesmata are channels connecting neighbouring plant cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1473' AND answer = 3;
UPDATE questions SET why = 'Each Haversian system has a central Haversian canal surrounded by lamellae. This canal carries blood vessels, nerves and lymphatic vessels that serve the living bone cells.', wrong = '{"1": "Bone marrow fills spaces in spongy bone and the shafts of long bones, not Haversian canals.", "2": "Synovial fluid is found in synovial joints, secreted by the synovial membrane.", "3": "Chondrocytes are cartilage cells. Bone cells in compact bone are osteocytes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1474' AND answer = 0;
UPDATE questions SET why = 'Red bone marrow produces red blood cells, white blood cells and platelets. It is found in spongy bone, the ends of long bones, ribs, vertebrae, the sternum and the pelvis.', wrong = '{"0": "The shafts of long bones are filled with yellow marrow, which is mostly fat.", "1": "Cartilage has no marrow. Its matrix does not even contain blood vessels.", "3": "Haversian canals carry blood vessels, nerves and lymphatics, not marrow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1475' AND answer = 2;
UPDATE questions SET why = 'Yellow bone marrow fills the shafts of long bones. It consists mostly of fat cells and serves as an energy reserve. After severe blood loss it can be converted to red marrow to make blood cells.', wrong = '{"0": "Red blood cell precursors are found in red marrow, which produces blood cells.", "2": "Osteoclasts are bone-resorbing cells found on bone surfaces, not the main part of yellow marrow.", "3": "Chondrocytes are cartilage cells, found in lacunae within cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1476' AND answer = 1;
UPDATE questions SET why = 'Despite their number and size, bones make up less than 20% of body mass. Bone is not dry, dead material. It is moist, living tissue, and its lattice-like spongy parts keep it light.', wrong = '{"0": "About 50% would make bones half the body''s weight, far more than they are.", "1": "About 35% is still too high. Bones make up less than 20% of body mass.", "3": "More than 60% is far too high. Muscles and other tissues make up most of the body''s mass."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1477' AND answer = 2;
UPDATE questions SET why = 'Osteoblasts are bone-forming cells that secrete the unmineralized ground substance of bone. As they work, they become trapped and surrounded by the matrix they have made, and they then become osteocytes, mature bone cells.', wrong = '{"0": "Fusion with macrophages is not how osteocytes form. Osteoclasts are the cells that develop from macrophages.", "2": "Osteocytes keep their nuclei. They are living cells that maintain bone tissue.", "3": "Osteoblasts become osteocytes within bone. Moving into cartilage is not part of the process."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1478' AND answer = 1;
UPDATE questions SET why = 'Osteoclasts develop from macrophages and carry out bone resorption. They break down bone and release calcium and phosphate into the blood, which is important for bone growth, repair and remodelling.', wrong = '{"0": "Osteoblasts do the opposite job. They build bone by secreting new matrix.", "1": "Osteocytes are mature bone cells that maintain bone tissue. They do not break it down on a large scale.", "2": "Chondrocytes are cartilage cells that make and maintain cartilage matrix."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1479' AND answer = 3;
UPDATE questions SET why = 'Osteocytes are mature bone cells sitting in lacunae. They maintain healthy bone tissue by secreting enzymes and controlling its mineral content, and they regulate the release of calcium from bone into the blood.', wrong = '{"1": "Osteoblasts are bone-forming cells that secrete new matrix. Once trapped in it they become osteocytes.", "2": "Chondrocytes are the cells of cartilage, not bone.", "3": "Myofibres are muscle cells, which contract. They do not maintain bone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1480' AND answer = 0;
UPDATE questions SET why = 'In forming long bones, the centre of the cartilage model calcifies and blood vessels bring in osteoblasts. The step in which cartilage is replaced by bone through the deposition of minerals is called ossification.', wrong = '{"0": "Osteoporosis is loss of bone density, which makes bones weak and porous. It is not bone formation.", "2": "Remodelling is the ongoing breakdown and rebuilding of bone after it has formed, not the replacement of cartilage.", "3": "Chondrification would mean forming cartilage, the opposite of replacing cartilage with bone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1481' AND answer = 1;
UPDATE questions SET why = 'Most bones, such as the femur and humerus, first form as cartilage that is later replaced by bone. A few bones, such as some bones of the skull, develop directly into flat plates of bone in embryonic connective tissue, without a cartilage stage.', wrong = '{"0": "The femur is a long bone that forms from a cartilage model, which is later ossified.", "1": "The humerus is also a long bone that develops from cartilage before becoming bone.", "3": "Vertebrae are not the example of bones that skip the cartilage stage. The flat skull bones are."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1482' AND answer = 2;
UPDATE questions SET why = 'Cartilage is surrounded by the perichondrium, which carries blood vessels, but the cartilage matrix itself has no blood vessels. Its cells are supplied only by diffusion, so cartilage heals very slowly after injury.', wrong = '{"1": "Osteoclasts are bone cells. Cartilage contains chondrocytes, not osteoclasts.", "2": "Cartilage is covered by perichondrium. Periosteum covers bone.", "3": "Cartilage matrix has no calcium crystals. It contains collagen, elastin and proteoglycans."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1483' AND answer = 0;
UPDATE questions SET why = 'Fibrocartilage is found where the body faces high stress and tension. Examples are the intervertebral discs between vertebrae and the pubic symphysis, which joins the two pubic bones.', wrong = '{"0": "Hyaline cartilage is found in the nose, trachea and on the articulating surfaces of bones.", "1": "Elastic cartilage is found in the external ear and the epiglottis.", "2": "Intervertebral discs and the pubic symphysis are cartilage, not compact bone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1484' AND answer = 3;
UPDATE questions SET why = 'Elastic cartilage is flexible and springs back to shape after bending. It is found in the external ear and in the epiglottis.', wrong = '{"0": "Hyaline cartilage is found in the nose, trachea and joint surfaces of bones.", "1": "Fibrocartilage is found in high-stress areas such as intervertebral discs and the pubic symphysis.", "2": "The external ear and epiglottis are flexible. They contain cartilage, not spongy bone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1485' AND answer = 3;
UPDATE questions SET why = 'Hyaline cartilage is the most common type of cartilage. It covers the articulating surfaces of bones in joints, where it is called articular cartilage, and is also found in the nose and trachea.', wrong = '{"0": "Elastic cartilage is found only in a few places, such as the external ear and epiglottis.", "2": "Fibrocartilage is found in high-stress areas like intervertebral discs, not on joint surfaces.", "3": "Calcified cartilage is a stage in bone formation, not one of the three types of cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1486' AND answer = 1;
UPDATE questions SET why = 'The adult human skeleton consists of 206 bones. They are arranged in two divisions: the axial skeleton (skull, vertebral column, ribs and sternum) and the appendicular skeleton (girdles and limbs).', wrong = '{"1": "208 is not the count. The adult skeleton has 206 bones.", "2": "33 is the number of vertebrae in the vertebral column, not the whole skeleton.", "3": "About 300 bones are present at birth, but many fuse during growth to leave 206 in the adult."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1487' AND answer = 0;
UPDATE questions SET why = 'The skull has 22 bones. Eight of them form the cranium, the brain box: paired parietal and temporal bones and unpaired frontal, occipital, ethmoid and sphenoid. The other 14 are facial bones.', wrong = '{"0": "Fourteen is the number of facial bones attached to the cranium.", "1": "Twenty-two is the total for the whole skull: 8 cranial plus 14 facial bones.", "3": "Six is the number of middle-ear ossicles (three in each ear), not cranial bones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1488' AND answer = 2;
UPDATE questions SET why = 'The hyoid is a small, single bone lying at the base of the skull just below the tongue. It is unusual because it does not articulate with any other bone of the head.', wrong = '{"0": "The hyoid is a neck bone, not one of the eight cranial bones.", "1": "The wrist is formed by the eight carpal bones, not the hyoid.", "2": "The hyoid is not a vertebra. Fused vertebrae form the sacrum and coccyx."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1489' AND answer = 3;
UPDATE questions SET why = 'There are seven cervical (neck) vertebrae. The first is called the atlas, which supports the skull, and the second is called the axis. The joint between them is a pivot joint that lets the head turn.', wrong = '{"0": "The sacrum and coccyx are fused vertebrae at the lower end of the vertebral column.", "2": "The malleus and incus are ossicles of the middle ear.", "3": "The ilium and ischium are parts of the hip bone in the pelvic girdle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1490' AND answer = 1;
UPDATE questions SET why = 'The vertebral column has 33 vertebrae in five groups: 7 cervical, 12 thoracic, 5 lumbar, 5 sacral and 4 coccygeal. Check: 7 + 12 + 5 + 5 + 4 = 33. In adults the sacral and coccygeal vertebrae are fused.', wrong = '{"0": "12 is only the number of thoracic (rib-carrying) vertebrae.", "1": "24 is the number of ribs (12 pairs), not vertebrae.", "2": "26 is the count of separate bones in an adult spine, when the sacrum and coccyx are each counted as one fused bone. The vertebrae themselves number 33."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1491' AND answer = 3;
UPDATE questions SET why = 'The first 7 pairs of ribs attach to the sternum by separate costal cartilages and are called true ribs. Pairs 8, 9 and 10 attach through a common costal cartilage and are called false ribs. Pairs 11 and 12 are floating ribs.', wrong = '{"1": "True ribs are the first 7 pairs, which attach directly to the sternum by their own separate cartilages.", "2": "Floating ribs are pairs 11 and 12, which do not attach to the sternum at all.", "3": "Cervical ribs are not one of the rib groups described. The groups are true, false and floating."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1492' AND answer = 0;
UPDATE questions SET why = 'The pectoral girdle consists of a pair of clavicles (collar bones) and a pair of scapulae (shoulder bones). Each clavicle joins the sternum at one end and the scapula at the other.', wrong = '{"0": "Two hip bones make up the pelvic girdle, not the pectoral girdle.", "1": "The sternum and ribs are part of the axial skeleton, forming the rib cage.", "3": "The humerus and radius are bones of the forelimb, not the girdle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1493' AND answer = 2;
UPDATE questions SET why = 'The pelvic girdle is made of two hip bones. Each hip bone is formed by the fusion of three bones, the ilium, ischium and pubis, which meet at a socket called the acetabulum, where the femur fits.', wrong = '{"0": "The femur, tibia and fibula are bones of the hindlimb, not parts of the hip bone.", "1": "The sacrum and coccyx are fused vertebrae that form the back of the pelvis, not the hip bone.", "2": "The clavicle and scapula form the pectoral girdle at the shoulder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1494' AND answer = 3;
UPDATE questions SET why = 'The patella, or kneecap, is a small bone embedded in a long tendon that runs over the front of the knee joint. It protects the joint and helps the thigh muscles straighten the leg.', wrong = '{"0": "The shin bone is the tibia, the large bone of the lower leg.", "1": "The wrist is made of the eight carpal bones.", "3": "The pelvic girdle is made of the two hip bones. The patella is part of the hindlimb."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1495' AND answer = 2;
UPDATE questions SET why = 'In fibrous joints, bones are joined directly by fibrous connective tissue made mainly of collagen, and they permit no movement. Sutures between the skull bones are an example.', wrong = '{"1": "Cartilaginous joints connect bones by cartilage and allow a little movement, as at the pubic symphysis.", "2": "Synovial joints allow free movement, as at the shoulder and knee. Sutures do not move.", "3": "Hinge joints are a type of synovial joint that moves in one plane, like the elbow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1496' AND answer = 0;
UPDATE questions SET why = 'Cartilaginous joints join bones with cartilage and allow little movement. In some of them the cartilage is hyaline, as in the joint between the first rib and the sternum. Others use fibrocartilage, such as intervertebral discs.', wrong = '{"0": "Fibrous joints join bones by collagen fibres, as in skull sutures. The first rib joins the sternum by cartilage.", "2": "A synovial hinge joint, like the elbow, moves freely in one plane. The rib-sternum joint has no joint cavity.", "3": "Ball-and-socket joints, like the shoulder and hip, move in all directions. This joint barely moves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1497' AND answer = 1;
UPDATE questions SET why = 'A synovial joint is enclosed by a fibrous capsule. Its outer layer is made of ligaments, and its inner lining is the synovial membrane, which secretes synovial fluid to lubricate the joint.', wrong = '{"0": "Articular cartilage covers the ends of bones and gives a smooth, low-friction surface. It does not secrete the fluid.", "1": "Ligaments are strong bands that hold bones together. They form the outer capsule but do not secrete fluid.", "2": "The periosteum is the tough membrane covering the outside of bone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1498' AND answer = 3;
UPDATE questions SET why = 'A pivot joint allows rotation around a single axis. The joint between the first and second cervical vertebrae, the atlas and axis, is a pivot joint and lets the head turn from side to side.', wrong = '{"0": "Hinge joints move in one plane like a door, as in the elbow and knee. They do not rotate.", "2": "A saddle joint, such as the thumb joint, moves in two planes using concave and convex surfaces.", "3": "Ball-and-socket joints, such as the shoulder and hip, allow movement in all directions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1499' AND answer = 1;
UPDATE questions SET why = 'In a saddle joint one bone has a concave surface and the other a convex surface, which allows movement in two planes. The thumb joint is a saddle joint, which lets the thumb move across the palm.', wrong = '{"0": "A pivot joint allows rotation around one axis, as between the atlas and axis.", "1": "Gliding joints allow sliding movements, as between vertebrae and between wrist and ankle bones.", "3": "A hinge joint moves in only one plane, as in the elbow and knee."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1500' AND answer = 2;
UPDATE questions SET why = 'An ellipsoidal joint allows movement in two planes, up and down and side to side, but not rotation. The joint of the wrist with the radius is an ellipsoidal joint.', wrong = '{"1": "A ball-and-socket joint, like the shoulder, moves in all directions, including rotation.", "2": "A pivot joint allows only rotation around one axis, which is the movement this joint lacks.", "3": "A fibrous joint permits no movement, but the wrist moves in two planes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1501' AND answer = 0;
UPDATE questions SET why = 'Several skeletal features support upright walking on two legs. The vertebral column has an S-shaped curve that spreads weight evenly and keeps balance. The pelvis is short and broad, and the femur angles inward towards the knee.', wrong = '{"0": "The human pelvis is short and broad, not long and narrow, which helps support weight on two legs.", "2": "The human femur angles inward towards the knee, keeping the centre of mass over the feet.", "3": "Human toes are short and less able to grasp, so the foot works as a firm lever for walking."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1502' AND answer = 1;
UPDATE questions SET why = 'Osteoarthritis is the most common type of arthritis. It occurs when the articular cartilage at the ends of bones gradually softens and breaks down. It mostly affects the knees, hips and joints of the spine.', wrong = '{"1": "Uric acid crystals forming in joints cause gouty arthritis (gout), often in the big toe.", "2": "An immune attack that inflames the synovial membrane is rheumatoid arthritis.", "3": "Loss of bone calcium after menopause leads to osteoporosis, which weakens bone but is not arthritis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1503' AND answer = 0;
UPDATE questions SET why = 'Rheumatoid arthritis is an autoimmune disorder: the body''s immune system attacks its own joints, and the synovial membrane becomes inflamed. The wrists and hands are most commonly affected.', wrong = '{"0": "Uric acid crystals in joints cause gouty arthritis, not rheumatoid arthritis.", "1": "Gradual wearing away of articular cartilage is osteoarthritis.", "2": "Rheumatoid arthritis is not caused by bacteria. It results from the immune system attacking the joints."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1504' AND answer = 3;
UPDATE questions SET why = 'Gouty arthritis, or gout, happens when uric acid builds up in the blood and forms crystals in the joints, causing painful inflammation. The joint most commonly affected is that of the big toe, though knees, wrists and fingers can also be involved.', wrong = '{"0": "The shoulder is not the usual site of gout. Gout most commonly affects the big toe joint.", "1": "The hip is a common site of osteoarthritis, not gout.", "3": "The jaw joint is not a typical site of gout. The big toe is affected most often."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1505' AND answer = 2;
UPDATE questions SET why = 'Intervertebral discs act as shock absorbers between vertebrae. In a slipped (herniated) disc, the outer layer of the disc tears, and its inner gel-like core leaks out and presses on nearby nerves or the spinal cord, causing pain, numbness and weakness.', wrong = '{"0": "A fracture is a break in the bone itself. A slipped disc involves the cartilage disc between vertebrae.", "2": "The sciatic nerve is not cut in any of these conditions. Pressure on it is called sciatica.", "3": "Loss of bone density is osteoporosis, which makes bones fragile."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1506' AND answer = 1;
UPDATE questions SET why = 'Spondylosis is degeneration of the vertebrae, discs, ligaments or cartilage of the vertebral column, often with narrowing of discs and bony outgrowths. It is most common in the lower back (lumbar region) and the neck (cervical region).', wrong = '{"0": "The thoracic and sacral regions are less often affected. Spondylosis is most common in the neck and lower back.", "1": "The skull is not part of the vertebral column, so spondylosis does not affect it.", "2": "The pelvic girdle is made of hip bones, not vertebrae, so it is not the site of spondylosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1507' AND answer = 3;
UPDATE questions SET why = 'Sciatica is compression or irritation of the sciatic nerve, which runs from the lower back through the buttocks into each leg. It is often caused by a herniated or bulging disc pressing on the nerve. Trauma, infection, inflammation and spondylosis can also cause it.', wrong = '{"0": "Too much uric acid in the blood causes gout, in which crystals form in joints.", "1": "Low blood calcium is the most common cause of tetany, not sciatica.", "3": "A sprained ankle is an injury to ligaments at the ankle. It does not press on the sciatic nerve."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1508' AND answer = 2;
UPDATE questions SET why = 'Oestrogen helps maintain bone mass. After menopause, oestrogen levels in women drop, and this speeds up bone loss, so osteoporosis develops faster. Ageing, low calcium and vitamin D, and lack of exercise also contribute.', wrong = '{"1": "A rise in uric acid leads to gout, not to bone loss.", "2": "Vitamin D helps the body absorb calcium. Lack of it, not excess, contributes to osteoporosis.", "3": "Weight-bearing exercise strengthens bones. It is lack of such exercise that weakens them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1509' AND answer = 0;
UPDATE questions SET why = 'Ligaments are strong bands of connective tissue joining bones at a joint. A sprain happens when a joint is forced beyond its normal range of motion, so these ligaments stretch or tear. Ankle, knee and wrist ligaments are most often injured.', wrong = '{"0": "Tendons join muscle to bone. A sprain is defined as an injury to ligaments.", "2": "Breakdown of articular cartilage is a feature of osteoarthritis, not a sprain.", "3": "Damage to the bone shaft is a fracture, not a sprain."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1510' AND answer = 1;
UPDATE questions SET why = 'First aid for a dislocation is to keep the area still with a sling or splint and not try to push the joint back. Then apply ice to reduce swelling, raise the limb if possible, and get medical help, for example by calling 1122.', wrong = '{"1": "Trying to force the joint back can tear muscles, ligaments and nerves further. It must be left to a professional.", "2": "An ice pack or cold compress is used to reduce swelling and pain, not heat.", "3": "The limb should be raised, if possible, to reduce swelling, not lowered."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1511' AND answer = 0;
UPDATE questions SET why = 'Smooth muscle, found in the walls of the gut, blood vessels and other internal organs, has spindle-shaped fibres. Each fibre has a single nucleus and no striations. It is involuntary muscle.', wrong = '{"0": "Long cylindrical, multinucleate, striated fibres describe skeletal muscle.", "1": "Branched fibres joined by intercalated discs describe cardiac muscle.", "3": "Muscle found only in the heart wall is cardiac muscle. Smooth muscle is in many internal organs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1512' AND answer = 2;
UPDATE questions SET why = 'Cardiac muscle is found only in the walls of the heart. Its fibres branch extensively and are striated like skeletal muscle, but each cell usually has one nucleus near the centre. It is involuntary.', wrong = '{"0": "Unstriated, spindle-shaped fibres describe smooth muscle.", "1": "Multinucleated fibres under voluntary control describe skeletal muscle.", "2": "The stomach wall contains smooth muscle. Cardiac muscle is found only in the heart."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1513' AND answer = 3;
UPDATE questions SET why = 'Each skeletal muscle fibre is enclosed by its own plasma membrane, called the sarcolemma. Its cytoplasm is the sarcoplasm, which contains the sarcoplasmic reticulum.', wrong = '{"1": "The sarcoplasm is the cytoplasm of the muscle fibre, inside the membrane.", "2": "The sarcoplasmic reticulum is an internal membrane network that stores and releases calcium ions.", "3": "The perichondrium is the connective tissue layer around cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1514' AND answer = 0;
UPDATE questions SET why = 'The sarcolemma dips deep into the muscle fibre to form hollow tubes called transverse tubules (T-tubules), which reach the sarcoplasmic reticulum. They carry the impulse inside the fibre so the SR releases calcium.', wrong = '{"0": "Actin forms the thin filaments of myofibrils. These are proteins, not membrane tubes.", "2": "Myosin forms the thick filaments, which make the dark A-bands.", "3": "Connective tissue around muscles forms bundles and tendons. It is outside the fibre, not tubules within it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1515' AND answer = 1;
UPDATE questions SET why = 'Myofibrils contain thick filaments of myosin and thin filaments of actin. The thick myosin filaments make the dark A-bands, and regions with only thin actin filaments make the light I-bands. This alternation gives skeletal muscle its striped look.', wrong = '{"0": "Regions with only thin actin filaments form the light I-bands, not the dark A-bands.", "1": "Z-lines are protein discs that mark the ends of each sarcomere. They are not the A-bands.", "2": "T-tubules are infoldings of the sarcolemma. They do not form bands."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1516' AND answer = 3;
UPDATE questions SET why = 'The A-band covers the whole length of the thick filaments. In its centre is a lighter region, the H-band, where thin filaments do not reach, so there is no overlap between thin and thick filaments. During contraction the H-band narrows and disappears.', wrong = '{"0": "Actin filaments are attached at the Z-lines, which lie at the ends of the sarcomere.", "1": "A region with only thin filaments is the I-band. The H-band contains only thick filaments.", "3": "Calcium ions are stored in the sarcoplasmic reticulum, not in a band of the sarcomere."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1517' AND answer = 2;
UPDATE questions SET why = 'In the centre of the H-band there may be a dark line called the M-line. It helps hold the thick myosin filaments in place, keeping them stable and evenly arranged.', wrong = '{"1": "Z-lines are found at the two ends of a sarcomere, where thin filaments are attached.", "2": "The A-band is the whole dark band of thick filaments, which contains the H-band and M-line.", "3": "I-bands are the light bands of thin filaments on either side of each Z-line."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1518' AND answer = 0;
UPDATE questions SET why = 'Thick myofilaments, made of many myosin molecules, are about 16 nm in diameter. Thin myofilaments, made of actin with tropomyosin and troponin, are about 7 to 8 nm, roughly half as wide.', wrong = '{"0": "This reverses the two. The thick filament is about 16 nm and the thin filament about 7 to 8 nm.", "1": "1 µm and 0.5 µm are about a hundred times too large. These are sizes nearer to whole myofibrils.", "2": "8 µm and 16 µm are a thousand times too large, close to the size of whole cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1519' AND answer = 3;
UPDATE questions SET why = 'In a relaxed muscle fibre, two strands of tropomyosin wrap around the actin core and cover the myosin-binding sites. Myosin heads cannot attach until calcium binds to troponin and moves tropomyosin aside.', wrong = '{"0": "Troponin''s calcium-binding subunit binds Ca²⁺. Troponin holds tropomyosin in place but does not itself cover the sites.", "1": "ATP binds to myosin heads and lets them detach from actin. It does not block sites on actin.", "3": "The Z-line anchors the ends of thin filaments. It does not cover binding sites."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1520' AND answer = 2;
UPDATE questions SET why = 'Troponin is made of three polypeptides. One is inhibitory and binds to actin, the second binds to tropomyosin and holds it in place, and the third binds calcium ions, which starts contraction.', wrong = '{"0": "Troponin does not bind myosin or ATP. Its partners are actin, tropomyosin and calcium.", "2": "Calcium is right, but ATP and myosin are not binding partners of troponin.", "3": "Troponin lies along the thin filament. It does not bind the Z-line or M-line."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1521' AND answer = 1;
UPDATE questions SET why = 'When a nerve impulse reaches the end of a motor neuron, the neuron releases the neurotransmitter acetylcholine at the synapse with the muscle fibre. This makes the sarcolemma produce its own impulse, which leads to contraction.', wrong = '{"0": "Adrenaline is a hormone of the adrenal medulla. It is not the transmitter at the nerve-muscle junction.", "1": "Dopamine is a neurotransmitter in parts of the brain, not at the junction with skeletal muscle.", "3": "Histamine dilates capillaries during inflammation. It does not carry signals to muscle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1522' AND answer = 2;
UPDATE questions SET why = 'An impulse travels along the sarcolemma and T-tubules to the sarcoplasmic reticulum, which releases Ca²⁺ into the cytosol. Calcium binds to troponin, which shifts tropomyosin away from the myosin-binding sites on actin, so cross-bridges can form.', wrong = '{"1": "Calcium does not bind myosin heads directly. Myosin binds actin only after troponin moves tropomyosin.", "2": "Calcium does not bind ATP here. ATP is used by myosin heads to detach and re-cock.", "3": "Calcium is released from the sarcoplasmic reticulum into the cytosol. It does not bind the sarcolemma to start contraction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1523' AND answer = 0;
UPDATE questions SET why = 'Once myosin heads attach to actin to form cross-bridges, they release ADP and Pi and change shape. They bend towards the centre of the sarcomere, pulling the actin filaments with them. This pull is the power stroke.', wrong = '{"0": "Binding a new ATP and detaching from actin happens after the power stroke, ending one cycle.", "1": "Calcium is not hydrolysed. Myosin heads hydrolyse ATP, and calcium simply binds troponin.", "2": "Myosin heads pull actin towards the centre of the sarcomere, not away from it. Muscles pull, they never push."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1524' AND answer = 3;
UPDATE questions SET why = 'In contraction, thin filaments slide past thick filaments. Z-lines move closer, the H-zone disappears and the sarcomere shortens. The thick filaments themselves do not change length, so the A-bands stay the same length but move closer together.', wrong = '{"0": "A-bands do not shorten, because the thick myosin filaments that form them keep their length.", "2": "It is the H-zone that disappears. The A-bands remain.", "3": "Nothing in the sarcomere lengthens during contraction. The A-band length stays the same."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1525' AND answer = 1;
UPDATE questions SET why = 'To detach from actin, each myosin head needs a new ATP molecule. After death, cells can no longer produce ATP, so the cross-bridges cannot break and muscles stay locked in a stiff state called rigor mortis.', wrong = '{"1": "Lack of calcium reaching troponin would keep muscles relaxed, not stiff.", "2": "If tropomyosin blocked all sites, no cross-bridges could form and muscles would be relaxed.", "3": "Actin filaments do not dissolve to cause stiffness. The cross-bridges simply cannot detach."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1526' AND answer = 0;
UPDATE questions SET why = 'A skeletal muscle is usually attached by tendons to two different bones. The end on the bone that stays still is the origin, the end on the bone that moves is the insertion, and the thick middle part is the belly.', wrong = '{"0": "The origin is the end attached to the stationary bone.", "1": "The belly is the fleshy middle part of the muscle, not an attachment point.", "2": "A tendon sheath surrounds a tendon. It is not the name of a muscle''s moving attachment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1527' AND answer = 3;
UPDATE questions SET why = 'The hamstrings are a group of three muscles at the back of the thigh. They arise from the pelvic girdle and top of the femur and insert on the upper fibula and tibia. When they contract, the lower leg bends (flexion) at the knee.', wrong = '{"0": "The quadriceps, at the front of the thigh, straighten (extend) the lower leg.", "1": "The biceps flexes the forearm at the elbow joint, not the leg at the knee.", "3": "The triceps extends the forearm at the elbow joint."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1528' AND answer = 2;
UPDATE questions SET why = 'The quadriceps are four muscles at the front of the thigh. They arise from the ilium (part of the pelvic girdle) and the femur, and are inserted on the patella and tibia. Their contraction straightens the lower leg.', wrong = '{"0": "The upper fibula and tibia are the insertions of the hamstrings, not the quadriceps.", "2": "The femur is one of the origins of the quadriceps, not its insertion.", "3": "The ilium of the pelvic girdle is an origin of the quadriceps, not the insertion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1529' AND answer = 1;
UPDATE questions SET why = 'The skeleton works like a set of rods and levers. Bones act as rods, joints act as fulcrums (pivot points), muscles supply the effort, and the weight being moved is the load. At the elbow, for example, the joint is the fulcrum and the biceps gives the effort.', wrong = '{"0": "The load is the weight or resistance being moved, not the joint.", "1": "The effort is supplied by the contracting muscles.", "3": "The rods of the lever system are the bones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1530' AND answer = 2;
UPDATE questions SET why = 'As muscles work hard, they produce metabolic wastes such as lactate, hydrogen ions and reactive oxygen, and these contribute to fatigue. Running out of ATP, poor handling of calcium and small fibre damage also reduce performance.', wrong = '{"0": "Fatigue is linked to depletion of ATP, not excess. Without ATP the muscle cannot keep contracting.", "1": "High blood calcium is not a cause listed. The problem is poor handling of calcium inside overworked fibres.", "2": "More mitochondria would improve ATP supply, so they would delay fatigue rather than cause it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1531' AND answer = 3;
UPDATE questions SET why = 'Tetany is involuntary muscle contraction caused by overexcited nerves and increased muscle tone. Its most common cause is hypocalcaemia, a low level of calcium in the blood, which may result from vitamin D deficiency, kidney failure or thyroid disorders.', wrong = '{"0": "Infection by Clostridium tetani causes tetanus, a different and more serious disease.", "2": "Excess uric acid causes gout, with crystals forming in joints.", "3": "Dehydration is a common cause of muscle cramps, not the main cause of tetany."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1532' AND answer = 1;
UPDATE questions SET why = 'Tetanus is a severe bacterial infection caused by Clostridium tetani. The bacterium makes a toxin that acts on the nervous system and causes stiffness and spasms, mainly of the jaw and neck muscles. It is more serious than tetany.', wrong = '{"1": "Low blood calcium causes tetany, not tetanus.", "2": "Tetanus is serious and can be life-threatening, more so than tetany.", "3": "Tetanus affects nerves and muscles, not cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1533' AND answer = 0;
UPDATE questions SET why = 'A muscle cramp is a sudden, involuntary, painful contraction, often in the legs or feet. It can be relieved by gently stretching and massaging the affected muscle. Applying heat or cold and taking pain relievers can also help.', wrong = '{"1": "Cramps last only seconds to minutes, so weeks of immobilization are not needed.", "2": "Calcium or magnesium supplements are used for tetany caused by salt imbalance, not as the main relief for cramps.", "3": "Removing a tendon would be harmful surgery and is never a treatment for cramps."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1534' AND answer = 0;
UPDATE questions SET why = 'Osmoregulators keep the water and solute concentrations of their body fluids constant even when the surroundings change, using methods such as active transport of salts and water conservation. Most vertebrates, in both aquatic and terrestrial habitats, are osmoregulators.', wrong = '{"0": "Staying isotonic to the surroundings is the feature of osmoconformers, not of most vertebrates.", "1": "Osmoconformers include all marine invertebrates but only a few vertebrates, such as hagfishes, sharks and rays.", "3": "Ammonotelic describes animals that excrete mainly ammonia. It is about waste type, not osmotic regulation, and most land vertebrates are not ammonotelic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5001' AND answer = 2;
UPDATE questions SET why = 'Osmoconformers let the osmotic concentration of their body fluids match their surroundings. Examples are all marine invertebrates, some freshwater invertebrates and a few marine vertebrates: hagfishes, sharks and rays. So the shark is the osmoconformer here.', wrong = '{"0": "Freshwater bony fishes are osmoregulators. They make large volumes of dilute urine and actively take up salts.", "1": "The kangaroo rat is a desert osmoregulator that conserves water and can live on metabolic water.", "2": "Birds such as the sparrow are osmoregulators that save water by excreting uric acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5002' AND answer = 3;
UPDATE questions SET why = 'Freshwater fishes are hypertonic to their surroundings, so salts such as Na⁺ and Cl⁻ diffuse out of their bodies. To make up for this loss, they actively transport salts back into their bodies, using energy, for example across the gills.', wrong = '{"0": "Rectal glands remove excess salt. They are found in some marine fishes, which have too much salt, not too little.", "2": "Freshwater fishes rarely drink. Water already floods in by osmosis, and drinking would add to the excess.", "3": "Freshwater fishes make large volumes of dilute urine to remove excess water, not small amounts of concentrated urine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5003' AND answer = 1;
UPDATE questions SET why = 'Marine bony fishes are hypotonic to sea water, so they constantly lose water by osmosis through their gills and skin. They drink sea water and conserve water by producing very small amounts of highly concentrated urine.', wrong = '{"1": "Large volumes of dilute urine are made by freshwater fishes, which need to get rid of excess water.", "2": "Marine fishes still produce some urine, and their kidneys help remove excess salts.", "3": "Their urine is concentrated to save water. Urine as dilute as fresh water would waste water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5004' AND answer = 0;
UPDATE questions SET why = 'Desert animals face strong evaporation in the daytime heat. Many reduce water loss by staying underground during the hottest part of the day and coming out at night, when the air is cooler and more humid.', wrong = '{"1": "Basking in the midday sun would increase heat gain and evaporation, the opposite of what desert animals need.", "2": "Large volumes of dilute urine waste water. Desert animals conserve water instead.", "3": "Ammonia needs the most water to excrete, about 500 mL per gram, so it is unsuitable for desert animals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5005' AND answer = 0;
UPDATE questions SET why = 'The osmotic pressure of a solution measures its tendency to take in water by osmosis. The more concentrated the solution, the higher its osmotic pressure and the more strongly it draws water in from a more dilute solution.', wrong = '{"0": "Active transport moves solutes using energy. It is not what osmotic pressure measures.", "1": "Osmotic pressure is a property of a solution, not a diffusion ability. Water itself moves from the hypotonic side to the hypertonic side.", "2": "The temperature at which water evaporates is unrelated to osmosis or osmotic pressure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5006' AND answer = 3;
UPDATE questions SET why = 'When amino acids and nucleic acids are broken down, their amino groups (-NH₂) are removed. In the liver, these amino groups combine with H⁺ to form ammonia (NH₃), which is highly toxic.', wrong = '{"0": "Glucose contains no nitrogen, so oxidising it, with or without oxygen, cannot produce ammonia.", "1": "Urea is made from ammonia, not broken down with CO₂ to form it.", "3": "Uric acid is a product of purine breakdown. The kidneys excrete it rather than turning it into ammonia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5007' AND answer = 2;
UPDATE questions SET why = 'Urea is less toxic than ammonia, so it needs less water to dilute it to a safe level. One gram of urea needs about 50 mL of water, compared with 500 mL for ammonia and only about 1 mL for uric acid.', wrong = '{"0": "500 mL per gram is the figure for ammonia, the most toxic nitrogenous waste.", "2": "About 1 mL per gram is the figure for uric acid, the least toxic and least soluble waste.", "3": "5 litres per gram is far more than any of the three wastes needs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5008' AND answer = 1;
UPDATE questions SET why = 'Land animals cannot spare the large amount of water needed to excrete ammonia. Mammals convert ammonia to the less toxic urea in the liver and excrete it through the kidneys. Animals whose main nitrogenous waste is urea are called ureotelic.', wrong = '{"1": "Osmoconformers are animals whose body fluids match the osmotic concentration of their surroundings. The term is not about waste type.", "2": "Uricotelic animals, such as birds and insects, excrete mainly uric acid.", "3": "Ammonotelic animals, such as most fishes, excrete mainly ammonia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5009' AND answer = 0;
UPDATE questions SET why = 'Uric acid is poorly soluble in water and forms precipitates, so it can be excreted as a near-solid paste. About 1 mL of water is enough for one gram, which suits birds, insects and desert animals.', wrong = '{"0": "Uric acid is the least toxic of the three wastes, less toxic than both urea and ammonia.", "2": "Converting ammonia into uric acid uses a lot of energy.", "3": "If uric acid dissolved easily, it would need more water to carry it away, not less."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5010' AND answer = 1;
UPDATE questions SET why = 'Cell membranes are built from a lipid bilayer whose properties depend on temperature. Very low temperatures make the membrane rigid and brittle, while high temperatures can make it lose its selective permeability.', wrong = '{"0": "Permanent denaturation describes enzymes at high temperatures, not membranes in the cold.", "1": "Cold does not make membranes better at controlling what passes. It makes them stiff and brittle.", "3": "Losing selective permeability is the effect of high temperatures, not low ones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5011' AND answer = 2;
UPDATE questions SET why = 'A snake is an ectotherm that uses behaviour to control its temperature. When it basks in direct sunlight, it absorbs heat from the sun''s rays, which is heat gain by radiation.', wrong = '{"0": "Conduction is heat gained by direct contact, for example when a reptile lies on a warm rock.", "1": "Burning brown adipose tissue is a heat-producing method of endotherms, not snakes.", "2": "Shivering produces heat inside the body and is a response of endotherms such as mammals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5012' AND answer = 3;
UPDATE questions SET why = 'Ectotherms have a low metabolic rate and cannot make enough heat to stay warm. In very cold climates, many of them become dormant during the coldest months, slowing their body activity until warmer weather returns.', wrong = '{"0": "Insulation such as fur, feathers or fat is a feature of endotherms (mammals and birds).", "1": "Shivering is an endotherm response that makes heat by muscle contraction.", "2": "Ectotherms keep a low metabolic rate and depend on outside heat. They do not raise their rate to stay warm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5013' AND answer = 3;
UPDATE questions SET why = 'Poikilotherms cannot keep their body temperature within narrow limits, so it varies with their surroundings. All invertebrates are poikilotherms, and so are fishes, amphibians and reptiles among the vertebrates.', wrong = '{"0": "Birds, like mammals, are homeotherms that keep a fairly constant body temperature.", "1": "The body temperature of poikilotherms varies considerably. A near-constant temperature describes homeotherms.", "3": "Poikilotherms need much less food, because they do not burn fuel to keep a constant temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5014' AND answer = 2;
UPDATE questions SET why = 'When body temperature falls below 37 °C, the body tries to save and make heat: skin vessels constrict, muscles shiver and metabolic rate rises. Vasodilation of skin capillaries increases heat loss, so it is a response to overheating, not cooling.', wrong = '{"1": "Shivering is a response to cold. Rapid contractions of skeletal muscles produce heat.", "2": "A higher metabolic rate is a response to cold, because it produces more body heat.", "3": "Vasoconstriction is a response to cold. It reduces blood flow to the skin, so less heat is lost."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5015' AND answer = 0;
UPDATE questions SET why = 'Positive feedback boosts the original change instead of reversing it. It is used where rapid, large changes are needed, such as blood clotting and labour and childbirth.', wrong = '{"0": "Body temperature is kept near 37 °C by negative feedback, which reverses any change.", "2": "Blood glucose is regulated by negative feedback, which returns it to its set point.", "3": "Most hormone secretion is controlled by negative feedback, which stops secretion once the effect is reached."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5016' AND answer = 1;
UPDATE questions SET why = 'Homeostasis works through receptors, a control centre and effectors. Skin thermoreceptors detect the cold and signal the hypothalamus, the control centre. The hypothalamus then signals the skeletal muscles, the effectors, which shiver to produce heat. This is negative feedback.', wrong = '{"0": "Skeletal muscles are the effectors at the end of the pathway, so they cannot come first.", "1": "Sweat glands cool the body. Shivering is done by skeletal muscles, controlled by the hypothalamus.", "3": "The order is reversed, since receptors come before the control centre, and sweat glands cause cooling, not warming."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5017' AND answer = 2;
UPDATE questions SET why = 'The kidneys lie high in the abdominal cavity, one on each side of the vertebral column, between the 12th thoracic and 3rd lumbar vertebrae. At this level, the 11th and 12th ribs partly cover and protect the upper parts of both kidneys.', wrong = '{"0": "The sternum and clavicles are in the chest and shoulder region, far above the kidneys.", "1": "The pelvic girdle surrounds the pelvic cavity, where the urinary bladder lies, not the kidneys.", "2": "The kidneys do lie beside these vertebrae, but the protection of their upper parts comes from the 11th and 12th ribs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5018' AND answer = 3;
UPDATE questions SET why = 'The urinary bladder is a hollow, distensible (stretchable) muscular organ that acts as a reservoir for urine. It lies in the pelvic cavity, and urine reaches it from the kidneys through the two ureters.', wrong = '{"0": "High in the abdominal cavity beside the vertebral column is where the kidneys lie, not the bladder.", "2": "The renal pelvis is a funnel inside the kidney that collects urine and passes it to the ureter. It does not store urine.", "3": "The thoracic cavity contains the heart and lungs, above the diaphragm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5019' AND answer = 1;
UPDATE questions SET why = 'Each kidney has an adrenal gland sitting on its top. The kidney and its adrenal gland are enclosed together in a fibrous renal capsule. The adrenal cortex makes aldosterone, which acts on the kidney.', wrong = '{"1": "The thyroid gland lies in the neck, far from the kidneys.", "2": "The urinary bladder lies in the pelvic cavity and receives urine through the ureters.", "3": "The pancreas lies in the abdomen near the stomach and duodenum, not on top of the kidney."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5020' AND answer = 0;
UPDATE questions SET why = 'Nephrons are of two types. Cortical nephrons lie mainly in the renal cortex, have relatively short loops of Henle and make up the majority, about 85%. Juxtamedullary nephrons, near the medulla, have long loops reaching deep into it.', wrong = '{"0": "Not all nephrons are cortical. Juxtamedullary nephrons make up the remainder.", "1": "Cortical nephrons are a clear majority, about 85%, not half.", "3": "About 15% is roughly the share of juxtamedullary nephrons, found by 100% − 85%."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5021' AND answer = 2;
UPDATE questions SET why = 'Most reabsorption happens in the proximal convoluted tubule. Here about 75% of the water in the filtrate returns to the peritubular capillaries by osmosis, while glucose, amino acids and salts are returned by active transport.', wrong = '{"0": "Not all water is taken back here. More is reabsorbed in the loop of Henle, distal tubule and collecting duct.", "2": "About 20% is the fraction of the blood''s fluid that filters into Bowman''s capsule, not the water reabsorbed.", "3": "5% is far too small. The proximal tubule is the main site of reabsorption."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5022' AND answer = 1;
UPDATE questions SET why = 'Water is reabsorbed at several points along the nephron, and the collecting duct is the final site. ADH acts on its walls, making them more or less permeable to water, so this is where the final concentration of urine is set.', wrong = '{"1": "The proximal convoluted tubule is the main site of reabsorption, but it comes first, not last.", "2": "Bowman''s capsule is where glomerular filtration takes place, not reabsorption.", "3": "The ascending limb of the loop of Henle is impermeable to water. It pumps salts out instead."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5023' AND answer = 0;
UPDATE questions SET why = 'Tubular secretion is the reverse of reabsorption. The epithelial cells of the distal convoluted tubule take materials such as H⁺, ammonium, K⁺ and drug residues like penicillin from the blood and secrete them into the filtrate.', wrong = '{"0": "The glomerulus is a capillary network where filtration happens, not secretion by tubule cells.", "1": "The renal pelvis only collects urine and passes it to the ureter.", "2": "The descending limb of the loop of Henle is where water is reabsorbed into the salty surrounding fluid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5024' AND answer = 3;
UPDATE questions SET why = 'On a hot day, much water is lost as sweat. To keep body water balanced, more ADH is released, the collecting ducts reabsorb more water, and the kidneys produce a smaller volume of concentrated urine.', wrong = '{"0": "Urine output does change. The kidneys respond to water lost in sweat by saving water.", "1": "Glucose is normally fully reabsorbed in the proximal tubule. Sweating does not make it appear in urine.", "2": "A large volume of dilute urine is made when there is excess water in the body, not after heavy sweating."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5025' AND answer = 3;
UPDATE questions SET why = 'The loop of Henle keeps the fluid around it in the medulla very salty. As urine passes down the collecting duct through this salty fluid, water leaves by osmosis and enters the blood through the vasa recta, the long straight capillaries running beside the loops.', wrong = '{"0": "Glomerular capillaries lie inside Bowman''s capsule and are for filtration, not taking water back.", "2": "The afferent arteriole brings blood into the glomerulus. It does not collect reabsorbed water.", "3": "The renal pelvis collects urine from the collecting ducts. It does not return water to the blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5026' AND answer = 1;
UPDATE questions SET why = 'The ascending limb of the loop of Henle is impermeable to water but actively transports sodium ions out of the filtrate. Chloride ions follow the sodium ions, so the surrounding fluid stays rich in NaCl.', wrong = '{"1": "Potassium ions are mainly secreted into the filtrate, for example under the influence of aldosterone.", "2": "Calcium is reabsorbed mainly in the proximal tubule. It is not the ion described as following sodium here.", "3": "Hydrogen ions are secreted into the filtrate by the distal tubule to control blood pH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5027' AND answer = 0;
UPDATE questions SET why = 'ADH makes the collecting ducts more permeable, so more water returns to the blood and blood volume and pressure rise. ADH also causes blood vessels to constrict, which raises blood pressure further.', wrong = '{"0": "Increasing sodium excretion would lower blood volume and pressure. This is the action of ANH, not ADH.", "1": "Dilating blood vessels would lower blood pressure. ADH constricts them.", "3": "ADH makes the collecting ducts more permeable to water, not less."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5028' AND answer = 2;
UPDATE questions SET why = 'Aldosterone controls the sodium and potassium levels of urine. It is produced by the adrenal cortex, the outer layer of the adrenal gland on top of the kidney. It increases Na⁺ reabsorption and K⁺ excretion.', wrong = '{"1": "The posterior pituitary releases ADH, which controls water reabsorption.", "2": "The hypothalamus produces ADH and detects blood salt concentration. It does not make aldosterone.", "3": "The adrenal medulla, the inner part of the gland, secretes adrenaline and noradrenaline."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5029' AND answer = 0;
UPDATE questions SET why = 'The type of kidney stone depends partly on the pH of urine. When urine is alkaline, stones are usually of calcium phosphate. Acidic urine is linked with calcium oxalate stones, and persistently acidic urine with uric acid stones.', wrong = '{"0": "Cellulose is the material of the semipermeable membrane in a dialyzer. It does not form kidney stones.", "1": "Calcium oxalate stones are linked with acidic urine and with high calcium and oxalate in urine.", "2": "Uric acid stones form when urine is persistently acidic, not alkaline."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5030' AND answer = 3;
UPDATE questions SET why = 'About 70% of kidney stone patients have calcium oxalate stones. These form because of hypercalciuria, too much calcium in urine, and hyperoxaluria, too much oxalate in urine. Continued dehydration makes stones more likely.', wrong = '{"0": "Hyperkalaemia is high blood potassium, which can cause dangerous heart rhythms. It does not form stones.", "2": "Low ADH secretion causes diabetes insipidus, with large volumes of dilute urine.", "3": "Hyperuricemia, high uric acid in blood, causes uric acid stones, about 10% of cases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5031' AND answer = 1;
UPDATE questions SET why = 'Larger stones are treated by percutaneous nephrolithotripsy (PNL). A tube is inserted from the patient''s back into the kidney, a small camera called a nephroscope shows the stone, and ultrasound breaks it so the pieces can be pulled out.', wrong = '{"0": "Breaking stones from outside the body with shockwaves, with no incision, is extracorporeal shockwave lithotripsy.", "1": "Urinary tract infections are treated with antibiotics, not lithotripsy.", "3": "Small stones are usually broken by shockwaves from outside, or pass in urine on their own."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5032' AND answer = 2;
UPDATE questions SET why = 'Chronic kidney failure develops slowly and cannot be reversed. It is often caused by long-standing conditions such as diabetes, high blood pressure, or chronic kidney disease like long-term infection or inflammation of the glomeruli.', wrong = '{"0": "Medicines such as NSAIDs are listed as a cause of acute kidney failure, which comes on suddenly.", "2": "Blood clots in renal arteries or arterioles are listed as a cause of acute kidney failure.", "3": "Sudden blockage of the urinary tract, for example by a stone, causes acute, not chronic, kidney failure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5033' AND answer = 1;
UPDATE questions SET why = 'In haemodialysis, blood leaves the body through a catheter inserted in an artery, usually in the arm. It passes through the dialyzer, where wastes, water and salts move into the dialysate. The cleaned blood returns through a second catheter inserted in a vein.', wrong = '{"1": "The catheter in the artery takes blood out. Clean blood comes back through a second catheter in a vein.", "2": "The ureter carries urine from the kidney to the bladder, not blood.", "3": "The peritoneal membrane is used in peritoneal dialysis, where blood is not circulated outside the body."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5034' AND answer = 0;
UPDATE questions SET why = 'Dialysis removes wastes, water and salts from the blood. The resulting changes in salt levels can cause muscle cramps during treatment. Other problems include infections, low blood pressure and anaemia.', wrong = '{"0": "The 11th and 12th ribs partly protect the kidneys. They are not affected by dialysis.", "1": "Rejection by the immune system is a problem of kidney transplants, not of a dialyzer machine.", "3": "Cramps during dialysis are linked to changes in salt levels, not to glucose in the dialysate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5035' AND answer = 2;
UPDATE questions SET why = 'A kidney donor who is not genetically related to the recipient, such as a spouse, friend or co-worker, is called an unrelated donor. This is less common but can succeed if blood group and tissue type match.', wrong = '{"0": "A deceased donor is someone who registered to donate organs after death.", "1": "A related donor is a genetic relative such as a parent, sibling or child.", "2": "Universal donor is a blood-group term, used for group O blood. It is not a kidney donor category."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5036' AND answer = 3;
UPDATE questions SET why = 'The Pakistan Kidney and Liver Institute and Research Center (PKLI&RC) is a tertiary-care hospital in Lahore, established in 2017 to tackle the large burden of kidney and liver disease through care, transplantation and research.', wrong = '{"0": "Islamabad is not where PKLI&RC was set up. The institute is located in Lahore.", "1": "Peshawar is not where PKLI&RC was set up. The institute is located in Lahore.", "2": "Karachi is home to SIUT, Pakistan''s first kidney transplant centre (1985). PKLI&RC is in Lahore."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5037' AND answer = 3;
UPDATE questions SET why = 'After a transplant, immunosuppressant medicines are given to stop the immune system rejecting the new kidney. Their side effects include high blood pressure, weight gain, and a higher risk of infections and cancers.', wrong = '{"0": "High, not low, blood pressure is listed as a side effect of these medicines.", "2": "Weight gain, not weight loss, is listed as a side effect.", "3": "These medicines are given to reduce rejection, not to make it stronger."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5038' AND answer = 1;
UPDATE questions SET why = 'Humans have two types of coordination. Nervous coordination is controlled by the nervous system using electrical signals. Chemical coordination is controlled by the endocrine system, which releases hormones into the blood.', wrong = '{"1": "The nervous system controls nervous coordination, using electrical impulses rather than hormones.", "2": "The immune system defends the body against pathogens. It is not one of the two coordination systems.", "3": "The urinary system removes wastes and regulates water and salts. It does not coordinate body activities."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5039' AND answer = 0;
UPDATE questions SET why = 'Myelin sheaths are made by glial cells that wrap around axons. In the peripheral nervous system, Schwann cells make the myelin sheath, while in the central nervous system it is made by oligodendrocytes.', wrong = '{"0": "Nissl''s granules are groups of ribosomes and rough ER in the neuron''s cell body. They are not cells.", "1": "Nodes of Ranvier are the gaps between sections of myelin, not cells that make it.", "3": "Oligodendrocytes make myelin in the central nervous system, not the peripheral nervous system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5040' AND answer = 2;
UPDATE questions SET why = 'In the central nervous system, myelinated axons look white because of their fatty myelin and form white matter. Non-myelinated dendrites and cell bodies of neurons form grey matter.', wrong = '{"0": "Schwann cells are found in the peripheral nervous system. They do not make up grey matter.", "1": "Myelinated axons make up white matter, not grey matter.", "2": "Cerebrospinal fluid fills the ventricles and central canal. It is a fluid, not a tissue like grey matter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5041' AND answer = 3;
UPDATE questions SET why = 'Sensory neurons carry impulses from receptors to the CNS, and their cell bodies lie in ganglia outside the CNS. They are described as unipolar: they have only one long dendrite, whose end branches into smaller branches connected to receptors, with an axon on the other side of the cell body.', wrong = '{"1": "The cell bodies of sensory neurons lie outside the CNS, in ganglia such as the dorsal root ganglia.", "2": "Many highly branched dendrites describe multipolar motor neurons.", "3": "Sensory neurons do have an axon, which carries impulses on into the CNS."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5042' AND answer = 0;
UPDATE questions SET why = 'A nerve impulse is a wave of electrochemical changes that travels along the length of a neuron. It is produced by ions such as Na⁺ and K⁺ moving across the membrane, which changes the charge on each side in turn.', wrong = '{"0": "An impulse is not a flow of electrons as in a wire. It is a wave of ion movements across the membrane.", "2": "Release of hormones into the blood is chemical coordination by the endocrine system.", "3": "Movement of neurotransmitter across the synaptic cleft is synaptic transmission between neurons, not the impulse along the neuron."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5043' AND answer = 1;
UPDATE questions SET why = 'During depolarization, Na⁺ gates open and Na⁺ ions rush in. The membrane potential changes from the resting −70 mV towards zero and then reverses to about +50 mV. This action potential lasts about one millisecond in each region.', wrong = '{"0": "A value more negative than −70 mV happens during hyperpolarization, after repolarization, not at the peak of depolarization.", "1": "The potential passes through zero and becomes positive. It does not stop at 0 mV.", "3": "120 is the top speed in metres per second of myelinated neurons, not a membrane voltage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5044' AND answer = 2;
UPDATE questions SET why = 'The resting membrane potential of −70 mV is set by three factors: fixed anions such as proteins trapped inside, the sodium-potassium pump moving 3 Na⁺ out for every 2 K⁺ in, and leakage of K⁺ out through K⁺ gates. Rapid entry of Na⁺ through open gates is what causes depolarization, so it is the exception.', wrong = '{"0": "Fixed anions, such as proteins and nucleic acids, cannot leave the cell and keep the inside negative. This is one of the factors.", "1": "The sodium-potassium pump removes more positive ions than it brings in, making the inside negative. This is one of the factors.", "2": "Leakage of K⁺ out of the cell removes positive charge from the inside. This is one of the factors."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5045' AND answer = 3;
UPDATE questions SET why = 'After the refractory period, the sodium-potassium pump uses ATP to move Na⁺ back out and K⁺ back in. This restores the original ion distribution, and the membrane returns to its resting potential of −70 mV, ready for the next impulse.', wrong = '{"0": "Neurotransmitters act at synapses on the next cell. They do not reset the ion balance along the axon.", "2": "Calcium entering the synaptic knob triggers release of neurotransmitter. It does not restore the resting potential.", "3": "Opening Na⁺ gates lets Na⁺ rush in and causes depolarization, the opposite of restoring rest."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5046' AND answer = 1;
UPDATE questions SET why = 'In myelinated axons, action potentials are produced only at the nodes of Ranvier and jump from node to node. This saltatory conduction is up to 50 times faster than in the fastest non-myelinated axons. Myelinated neurons reach up to 120 m/s, compared with 1 to 3 m/s.', wrong = '{"1": "1000 times is a large overstatement. The figure is up to about 50 times.", "2": "Twice as fast greatly understates the difference made by myelin.", "3": "Ten times is too low. Saltatory conduction can be up to about 50 times faster."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5047' AND answer = 0;
UPDATE questions SET why = 'Biogenic amines, such as norepinephrine, epinephrine, dopamine and serotonin, are excitatory neurotransmitters that increase membrane permeability to Na⁺. They also function as hormones in the body.', wrong = '{"0": "GABA and glycine are inhibitory neurotransmitters. They make neurons less likely to fire.", "1": "Fixed anions are large negative molecules, such as proteins, trapped inside neurons. They are not neurotransmitters.", "3": "Endorphins are inhibitory neurotransmitters released in the brain that block pain signals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5048' AND answer = 2;
UPDATE questions SET why = 'Norepinephrine is a biogenic amine made in the central nervous system and in sympathetic nerves. It regulates sleep patterns, focus and alertness.', wrong = '{"1": "The intestine''s neurons make about 90% of the body''s serotonin, not norepinephrine.", "2": "The pineal gland produces melatonin, which controls sleep patterns.", "3": "The posterior pituitary releases ADH and oxytocin, not norepinephrine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5049' AND answer = 0;
UPDATE questions SET why = 'Dopamine is a neurotransmitter in the brain that controls body movements, the pleasure linked to motivation and emotional stimulation. Degeneration of dopamine-releasing neurons causes the muscle tremors of Parkinson''s disease.', wrong = '{"0": "Glycine is an inhibitory neurotransmitter acting mainly in the spinal cord, brainstem and retina.", "1": "GABA is the chief inhibitory neurotransmitter of the CNS. It reduces anxiety and promotes relaxation and sleep.", "2": "Acetylcholine acts mainly between motor neurons and skeletal muscle fibres and between many neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5050' AND answer = 3;
UPDATE questions SET why = 'Glycine is an inhibitory neurotransmitter. It acts especially in the spinal cord, brainstem and retina, making postsynaptic neurons less likely to fire.', wrong = '{"0": "At the neuromuscular junctions of skeletal muscle, the transmitter is acetylcholine, which is excitatory.", "2": "Neurons in the intestine produce about 90% of the body''s serotonin.", "3": "The adrenal glands release epinephrine, a biogenic amine, not glycine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5051' AND answer = 1;
UPDATE questions SET why = 'GABA is the chief inhibitory neurotransmitter of the CNS. It reduces anxiety and promotes relaxation and sleep. Many sedative drugs enhance the binding of GABA to its receptors, making it more effective at the synapse.', wrong = '{"0": "Blocking adenosine receptors, as caffeine does, increases alertness. It does not promote sleep.", "1": "More Na⁺ entering postsynaptic neurons would excite them, the opposite of sedation.", "3": "Blocking the breakdown of acetylcholine is how nerve gases work, keeping muscles contracted."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5052' AND answer = 2;
UPDATE questions SET why = 'Endorphins are inhibitory neurotransmitters released by neurons in the brain. They reduce the release of the excitatory neurotransmitters that carry pain messages, so pain signals are blocked from reaching the brain. Morphine and heroin act on the same receptors.', wrong = '{"0": "Glutamate is an excitatory neurotransmitter. More glutamate would help carry signals, not block them.", "1": "Endorphins act on neurons in the brain. They do not destroy pain receptors in the skin.", "2": "Opening Na⁺ gates would start impulses in postsynaptic neurons, not block them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5053' AND answer = 3;
UPDATE questions SET why = 'The brain and spinal cord are covered by three meninges. The innermost, the pia mater, is a very delicate membrane that adheres to their surfaces and carries blood capillaries that nourish the brain and spinal cord.', wrong = '{"0": "The corpus callosum is a band of axons joining the two cerebral hemispheres. It is not a meningeal layer.", "1": "The arachnoid is the thin middle layer. It separates the cerebrospinal fluid below it from the blood in the dura mater.", "3": "The dura mater is the thick outermost layer, just below the skull, and it contains the larger blood vessels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5054' AND answer = 2;
UPDATE questions SET why = 'The parietal lobes process sensory information. They give awareness of the position of the body and its surroundings, control attention, and help plan and carry out movements.', wrong = '{"0": "The temporal lobes deal with visual memory, language comprehension and emotions, and contain the auditory cortex.", "2": "The frontal lobes handle executive functions such as self-control, planning, reasoning and abstract thought.", "3": "The occipital lobes, at the back of the cerebrum, control vision and contain the visual cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5055' AND answer = 1;
UPDATE questions SET why = 'The visual cortex, which processes information from the eyes, lies in the occipital lobe at the back of the cerebrum. The auditory cortex, which deals with sound, lies in the temporal lobe.', wrong = '{"1": "The temporal lobe contains the auditory cortex, which deals with sound frequencies.", "2": "The frontal lobe deals with executive functions like planning and reasoning.", "3": "The cerebellum coordinates muscle actions and posture. It is not part of the cerebral cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5056' AND answer = 0;
UPDATE questions SET why = 'The surface of each cerebral hemisphere is folded into ridges called gyri, separated by grooves. A shallow groove is called a sulcus, and a deep groove is called a fissure.', wrong = '{"0": "A fissure is a deep groove, such as the one dividing the two cerebral hemispheres.", "1": "A ventricle is a fluid-filled cavity inside the brain, not a groove on its surface.", "2": "A gyrus is a ridge on the surface, not a groove."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5057' AND answer = 3;
UPDATE questions SET why = 'The brainstem has three parts: midbrain, pons and medulla oblongata. The midbrain relays visual and auditory information and contains the reticular formation, which connects the hindbrain with the forebrain.', wrong = '{"0": "The thalamus is part of the diencephalon, not the brainstem. It relays sensory information to the cerebrum.", "1": "The medulla oblongata is a relay and control centre for heart rate, breathing and other homeostatic activities.", "3": "The pons transmits impulses between the cerebral hemispheres and the cerebellum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5058' AND answer = 2;
UPDATE questions SET why = 'The brain has four fluid-filled ventricles. The two large lateral ventricles are in the cerebrum. The third ventricle lies in the diencephalon between the right and left thalamus, and the fourth lies between the cerebellum and brainstem.', wrong = '{"0": "A pair of large cavities in the cerebrum describes the two lateral ventricles.", "2": "The fluid-filled channel in the centre of the spinal cord is the central canal, continuous with the fourth ventricle.", "3": "The space between the cerebellum and brainstem is the fourth ventricle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5059' AND answer = 1;
UPDATE questions SET why = 'The spinal cord is wider in the cervical and lumbar regions because these regions handle much more traffic. The cervical region deals with sensory input and motor output for the arms and trunk, and the lumbar region does the same for the legs.', wrong = '{"1": "All regions of the spinal cord have outer white matter of myelinated axons.", "2": "Cranial nerves arise from the brain, not from the spinal cord.", "3": "The medulla oblongata is part of the brainstem, above the spinal cord."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5060' AND answer = 0;
UPDATE questions SET why = 'There are 12 pairs of cranial nerves. The first two pairs, the olfactory nerve for smell and the optic nerve for vision, arise from the cerebrum. The remaining 10 pairs arise from the brainstem.', wrong = '{"1": "Nerves arising from the spinal cord are spinal nerves (31 pairs), not cranial nerves.", "2": "The cerebellum is not given as the origin of any cranial nerve.", "3": "The brainstem is the origin of the other 10 pairs, not the first two."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5061' AND answer = 0;
UPDATE questions SET why = 'Cranial nerve V is a mixed nerve, containing both sensory and motor axons. It carries sensation from the face and controls the muscles used in chewing.', wrong = '{"0": "Cranial nerve VII is mixed but serves facial expressions and taste in the front of the tongue.", "2": "Cranial nerve XII is a motor nerve that controls the muscles of the tongue.", "3": "Cranial nerve III is a motor nerve that moves the eye."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5062' AND answer = 1;
UPDATE questions SET why = 'Cranial nerve IX is a mixed nerve. Its sensory part carries taste from the back of the tongue, and its motor part moves the muscles used in swallowing.', wrong = '{"0": "Cranial nerve XI is a motor nerve controlling the neck and shoulder muscles.", "1": "Cranial nerve VII carries taste from the front of the tongue, not the back.", "3": "Cranial nerve I is the olfactory nerve, which carries the sense of smell."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5063' AND answer = 2;
UPDATE questions SET why = 'All 31 pairs of spinal nerves are mixed, carrying both sensory and motor information. The cell bodies of sensory neurons sit in the dorsal root ganglia outside the cord, while the cell bodies of somatic motor neurons lie inside the spinal cord, not in ganglia.', wrong = '{"0": "No spinal nerve is purely sensory. All spinal nerves are mixed, unlike some cranial nerves such as nerve I.", "1": "The dorsal and ventral roots join just before the spinal nerve leaves the vertebral column.", "2": "The dorsal root ganglia hold the cell bodies of sensory neurons, not motor neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5064' AND answer = 3;
UPDATE questions SET why = 'The autonomic system has two divisions with different origins. Parasympathetic motor neurons arise from the brain and the sacral region of the spinal cord, many of them in the vagus nerve. Sympathetic motor neurons arise from the thoracic and lumbar regions.', wrong = '{"1": "The cerebellum coordinates movement. It is not the origin of parasympathetic motor neurons.", "2": "The thoracic and lumbar regions are the origin of sympathetic motor neurons.", "3": "Dorsal root ganglia contain the cell bodies of sensory neurons, not autonomic motor neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5065' AND answer = 0;
UPDATE questions SET why = 'The two autonomic divisions usually have opposite effects. Sympathetic stimulation relaxes the urinary bladder, while parasympathetic stimulation makes it contract, which helps empty it.', wrong = '{"0": "The two divisions do not both cause contraction. Their effects on the bladder are opposite.", "2": "This reverses the effects. Sympathetic relaxes the bladder and parasympathetic contracts it.", "3": "The bladder does respond to both divisions, in opposite ways."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5066' AND answer = 1;
UPDATE questions SET why = 'The parasympathetic system restores the body to normal after stress and favours rest and digestion. It increases the motility of the digestive tract and stimulates digestive secretions, while the sympathetic system decreases them.', wrong = '{"0": "Stimulation of glucose release by the liver is a sympathetic effect. The parasympathetic system inhibits it.", "1": "Decreased salivary secretion is a sympathetic effect. The parasympathetic system increases it.", "3": "Dilation of the pupil is a sympathetic effect. The parasympathetic system constricts the pupil."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5067' AND answer = 2;
UPDATE questions SET why = 'Taste is sensed by chemoreceptors called taste buds. Humans have about 10,000 taste buds, most of them between the papillae of the tongue, with some in the throat and on the roof of the mouth.', wrong = '{"0": "100 is far too few. Humans have about 10,000 taste buds.", "1": "About one million is the number of nephrons in each kidney, not taste buds.", "2": "About 100 billion is the number of inter-neurons in the brain."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5068' AND answer = 3;
UPDATE questions SET why = 'Olfactory neurons lie in the nasal epithelium, packed between two other cell types. Supporting cells give protection, and basal cells act as stem cells that replace old olfactory neurons.', wrong = '{"0": "Supporting cells provide protection to the olfactory neurons. They do not replace them.", "2": "Merkel cells are touch receptors in the deepest layer of the epidermis.", "3": "Schwann cells make myelin sheaths around axons in the peripheral nervous system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5069' AND answer = 1;
UPDATE questions SET why = 'Air-borne chemicals dissolve in nasal mucus and bind to receptors on the cilia of olfactory neurons. The resulting impulses travel along the olfactory nerves, cranial nerve I, to the olfactory bulb, which produces the perception of smell.', wrong = '{"0": "Dorsal roots of spinal nerves carry sensory input from the body, not smell.", "1": "Cranial nerves VII, IX and X carry taste impulses to the brainstem.", "2": "Cranial nerve II is the optic nerve, which carries vision."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5070' AND answer = 3;
UPDATE questions SET why = 'Merkel cells are oval-shaped touch receptors found in the deepest layer of the epidermis. They detect light touch and are present in highly touch-sensitive areas such as the fingertips.', wrong = '{"0": "Nociceptors are free nerve endings that detect pain.", "1": "Ruffini endings are capsule-enclosed endings in the dermis that detect sustained pressure and stretching.", "3": "Hair follicle receptors are nerve endings around the base of hair follicles that detect hair movement."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5071' AND answer = 2;
UPDATE questions SET why = 'Skin thermoreceptors sense the temperature of the body surface and the surroundings. Thermoreceptors in the hypothalamus instead sense the temperature of the blood flowing through the brain, so they monitor core body temperature. The hypothalamus then acts as the control centre for temperature regulation.', wrong = '{"1": "Pain is detected by nociceptors, which respond to damaging stimuli. Thermoreceptors respond to temperature, not only to pain.", "2": "Capsules in the dermis describe skin mechanoreceptors such as Pacinian corpuscles. Hypothalamic thermoreceptors lie in the brain, not in the skin.", "3": "Light touch and vibration are sensed by touch receptors such as Meissner''s and Pacinian corpuscles, not by thermoreceptors."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5072' AND answer = 0;
UPDATE questions SET why = 'A narcotic is an opioid drug used for pain relief that carries a high risk of addiction and abuse. Morphine, codeine and oxycodone are all opioids, so codeine and oxycodone is the only pair made up entirely of narcotics. All narcotics are psychoactive, but not all psychoactive drugs are narcotics.', wrong = '{"0": "Caffeine and nicotine are psychoactive stimulants that alter mood and alertness. They are not opioids, so they are not narcotics.", "1": "Nail polish remover and glue give off vapours that are abused as inhalants. They are not opioid pain relievers.", "2": "Alcohol and cannabis are psychoactive drugs that change mood and perception, but neither is an opioid, so the pair is not narcotic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5073' AND answer = 3;
UPDATE questions SET why = 'Dependence is the state in which a person relies on a drug, physically or emotionally, just to function normally. It usually develops after repeated abuse of psychoactive drugs and often leads to addiction, which is uncontrollable craving and use despite harm.', wrong = '{"0": "Euphoria is a feeling of intense happiness or excitement that some drugs produce. It is a drug effect, not a state of reliance.", "1": "Tolerance means the body becomes less sensitive to a drug, so higher doses are needed for the same effect. It is not reliance on the drug.", "3": "Withdrawal is the set of unpleasant symptoms, such as irritability and cravings, that appear when a drug is stopped suddenly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5074' AND answer = 2;
UPDATE questions SET why = 'Nicotine, the addictive stimulant in tobacco, binds to nicotine receptors in the brain. These receptors trigger the release of dopamine and other neurotransmitters, which produce pleasurable feelings. Regular use leads to tolerance, so higher doses are needed for the same pleasure.', wrong = '{"1": "Inhibiting acetylcholinesterase is how nerve gases act. Acetylcholine then builds up at synapses, which is not how nicotine causes pleasure.", "2": "Blocking adenosine receptors is how caffeine keeps a person alert. Nicotine acts on nicotine receptors instead.", "3": "Resembling endorphins and binding their receptors describes opium derivatives such as morphine and heroin, not nicotine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5075' AND answer = 0;
UPDATE questions SET why = 'Heroin is a highly addictive opioid drug made from the opium poppy plant. It can be injected, smoked or snorted, and produces a false sense of euphoria. In high doses it can slow breathing dangerously, called respiratory depression.', wrong = '{"0": "The tobacco plant is the source of nicotine, a stimulant, not of heroin.", "2": "Cannabis sativa, the Indian hemp plant, is the source of marijuana and hashish, not of opioids such as heroin.", "3": "The coffee plant is a source of caffeine, a mild stimulant. It has no link to heroin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5076' AND answer = 1;
UPDATE questions SET why = 'Aphasia is the inability to express oneself through words. It is a common symptom of stroke when the damaged area of the brain controls language. Other stroke symptoms include sudden trouble seeing or walking, dizziness, loss of balance and severe headache.', wrong = '{"0": "In stroke, paralysis occurs on the side of the body opposite the damaged brain area, not the same side. Paralysis is also not aphasia.", "1": "Stiffness of the neck, along with headache and fever, is a typical symptom of meningitis, not the meaning of aphasia.", "3": "Loss of the sense of smell is called anosmia. Aphasia refers to loss of the ability to express in words."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5077' AND answer = 2;
UPDATE questions SET why = 'A transient ischaemic attack, or ministroke, happens when the blood supply to part of the brain falls for a short time. The symptoms may last as little as five minutes and then clear. It is often a warning sign of a full stroke later.', wrong = '{"1": "Rupture of a brain artery causes a haemorrhagic stroke, which is a bleed, not a short temporary drop in blood supply.", "2": "Immune damage to the myelin sheath is the cause of multiple sclerosis, a degenerative disorder, not of a ministroke.", "3": "Bacterial infection of the meninges causes bacterial meningitis, an infectious disorder, not a ministroke."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5078' AND answer = 0;
UPDATE questions SET why = 'Fungal meningitis is rare and is usually seen in people whose immune systems are weak, since a healthy immune system normally keeps fungi in check. It needs long-term treatment with antifungal medicines. Bacterial meningitis, in contrast, is the most severe form.', wrong = '{"0": "Stroke is a vascular disorder caused by blocked or burst blood vessels. Having a stroke is not the usual risk factor for a fungal infection.", "2": "Fungal meningitis is rare, so it does not occur in all healthy children. It mainly affects people with weakened immunity.", "3": "Alzheimer''s disease is a degenerative disorder. Fungal meningitis is linked to weak immunity, not limited to Alzheimer''s patients."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5079' AND answer = 1;
UPDATE questions SET why = 'Structural disorders of the nervous system are caused by abnormalities or damage to the physical structure of the brain, spinal cord or nerves. A brain tumour and a spinal cord injury both physically damage nervous tissue, so they are structural disorders.', wrong = '{"0": "Functional disorders, such as headache, disturb how the nervous system works without an obvious structural cause.", "1": "Vascular disorders, such as stroke, arise from problems in the blood vessels that supply the brain, not from tumours or injury.", "2": "Degenerative disorders, such as Alzheimer''s and Parkinson''s diseases, involve slow, progressive loss of nerve cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5080' AND answer = 3;
UPDATE questions SET why = 'Headaches are grouped as primary or secondary. A primary headache is a disorder in itself and is not caused by another condition. Migraine and tension headache are primary headaches, so migraine is classed as a primary headache under functional disorders.', wrong = '{"0": "Degenerative disorders involve progressive death of nerve cells, as in Alzheimer''s disease. Migraine does not destroy neurons.", "2": "Vascular disorders such as stroke come from damaged blood vessels. Headache, including migraine, is placed under functional disorders.", "3": "Secondary headaches are symptoms of another problem, such as a tumour or bleeding in the brain. Migraine is not caused by another disease."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5081' AND answer = 1;
UPDATE questions SET why = 'An electroencephalogram (EEG) records the brain''s electrical activity as waves of different frequencies. Beta waves appear when a person is awake, alert and actively thinking. Alpha waves go with relaxation, theta and delta waves with sleep, and gamma waves with high-level processing.', wrong = '{"0": "Delta waves are the slowest waves and are seen in the deepest stage of sleep, not in an alert, thinking state.", "1": "Alpha waves appear when a person is awake but physically and mentally relaxed, for example resting with eyes closed.", "3": "Theta waves are slow waves associated with sleep and reduced consciousness, not active thinking."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5082' AND answer = 2;
UPDATE questions SET why = 'In computed tomography (CT), the patient lies on a table that slides into a doughnut-shaped machine called the gantry. Inside the gantry an X-ray tube rotates around the patient, and detectors on the opposite side measure how much X-ray is absorbed to build cross-sectional images.', wrong = '{"1": "A lithotripter produces shockwaves to break kidney stones into small pieces. It is not part of a CT scanner.", "2": "Electrodes are small metal discs placed on the scalp in EEG to record electrical activity, not a rotating X-ray unit.", "3": "A dialyzer is the artificial kidney filter used in haemodialysis to clean blood, unrelated to CT scanning."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5083' AND answer = 0;
UPDATE questions SET why = 'Tri-iodothyronine (T3) and thyroxine (T4) are the thyroid''s iodine-containing hormones. T4 is listed as controlling the speed of metabolism, while T3, the more active form, is listed as regulating body temperature and heart rate. So the thyroid hormone in question is T3.', wrong = '{"0": "Norepinephrine is made by the adrenal medulla. It raises blood pressure and alertness but is not a thyroid hormone.", "1": "Cortisol is a steroid hormone from the adrenal cortex that helps regulate glucose. It is not made by the thyroid.", "2": "Calcitonin is made by the thyroid, but its job is to lower blood calcium by moving calcium into bones, not to regulate temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5084' AND answer = 3;
UPDATE questions SET why = 'Hormone receptors can be found on the cell membrane, in the cytoplasm or in the nucleus, depending on the hormone. Water-soluble hormones such as peptides cannot cross the membrane and bind surface receptors, while lipid-soluble steroids pass through and bind receptors inside the cell.', wrong = '{"1": "Mitochondria are sites of cellular respiration. They are not the general location of hormone receptors.", "2": "Only water-soluble hormones use membrane receptors. Steroid hormones cross the membrane and bind receptors in the cytoplasm or nucleus.", "3": "Peptide hormones cannot enter the cell, so they bind receptors on the membrane. Receptors are not found only in the nucleus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5085' AND answer = 0;
UPDATE questions SET why = 'The hypothalamus controls the anterior pituitary with releasing and inhibiting hormones. Thyrotropin releasing hormone (TRH) causes the anterior pituitary to secrete thyroid stimulating hormone (TSH). TSH then stimulates the thyroid gland to make thyroxine.', wrong = '{"0": "Thyroxine is made by the thyroid gland in response to TSH. The anterior pituitary does not secrete thyroxine itself.", "2": "Growth hormone release is stimulated by growth hormone releasing hormone and inhibited by somatostatin, not by TRH.", "3": "ACTH release is triggered by adrenocorticotropin releasing hormone, not by TRH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5086' AND answer = 1;
UPDATE questions SET why = 'Prolactin is an anterior pituitary hormone that stimulates the mammary glands to produce milk. It is produced in both males and females, but it has a function only in females. Its release is held back by dopamine from the hypothalamus.', wrong = '{"0": "Milk ejection by contraction of smooth muscle in the mammary glands is caused by oxytocin, not prolactin.", "1": "Dopamine acts as the prolactin inhibiting factor, so it decreases prolactin secretion rather than increasing it.", "3": "Prolactin is made and released by the anterior pituitary. The posterior pituitary stores and releases only ADH and oxytocin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5087' AND answer = 2;
UPDATE questions SET why = 'During embryonic development the posterior pituitary forms as an outgrowth of neural tissue from the brain. For this reason it stays connected to the hypothalamus by a tract of axons. Hormones made in the hypothalamus travel down these axons to be stored and released by the posterior pituitary.', wrong = '{"0": "The posterior pituitary does not make any hormones. It only stores and releases ADH and oxytocin made by the hypothalamus.", "1": "Developing from the lining of the mouth describes the anterior pituitary. The posterior pituitary has a neural origin.", "2": "Linking through blood vessels describes the hypothalamus and anterior pituitary. The posterior pituitary is linked by axons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5088' AND answer = 3;
UPDATE questions SET why = 'Melanocyte stimulating hormone (MSH) is produced by the intermediate pituitary, a thin layer between the anterior and posterior lobes. It stimulates melanocytes in the skin and hair to produce and release melanin, the dark pigment.', wrong = '{"1": "Stimulating the mammary glands to produce milk is the job of prolactin from the anterior pituitary.", "2": "Red blood cell production in bone marrow is stimulated by erythropoietin, a hormone made mainly by the kidneys.", "3": "Stimulating the thyroid to make thyroxine is the role of thyroid stimulating hormone (TSH)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5089' AND answer = 0;
UPDATE questions SET why = 'Growth hormone stimulates the growth of bones and muscles. In a growing child the long bones can still lengthen, so too much GH causes gigantism: height well above average with large hands, feet and facial features. In adults the same excess causes acromegaly instead.', wrong = '{"0": "Acromegaly is excess GH in adult life, when bones can no longer lengthen but grow thicker, enlarging hands, feet and jaw.", "2": "Dwarfism results from a deficiency of GH, giving short but proportionate stature, the opposite of over-secretion.", "3": "Cretinism is caused by lack of thyroid hormones in foetal life and childhood, not by growth hormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5090' AND answer = 1;
UPDATE questions SET why = 'Oxytocin stimulates the uterus to contract during childbirth. If it is over-secreted, the contractions become too strong and can rupture the uterine wall. Under-secretion has the opposite effect and holds back the normal labour process.', wrong = '{"0": "Failure of normal labour results from too little oxytocin, because the uterus does not contract strongly enough.", "1": "Gigantism is caused by excess growth hormone in childhood, not by oxytocin.", "2": "Diabetes insipidus is caused by under-secretion of ADH, giving large volumes of dilute urine and thirst."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5091' AND answer = 3;
UPDATE questions SET why = 'Growth hormone therapy improves growth in children who are short because they lack growth hormone. However, not every person of short stature has GH deficiency, so the treatment will not help everyone. Doctors also do not support using GH to build muscle or slow ageing.', wrong = '{"0": "GH treatment is in fact given to children with GH deficiency to improve their growth rate.", "1": "Excess GH in children causes gigantism, not acromegaly, and therapy is given to correct a deficiency, not to create an excess.", "3": "GH acts on muscles, bones and many other tissues. It does not act only on the thyroid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5092' AND answer = 2;
UPDATE questions SET why = 'The thyroid is a butterfly-shaped gland made of two connected lobes. It lies at the front of the neck, with one lobe on each side of the trachea (windpipe). It secretes T4, T3 and calcitonin.', wrong = '{"1": "The glands that sit just above each kidney are the adrenal glands, not the thyroid.", "2": "The gland beneath the sternum between the lungs is the thymus, which helps T lymphocytes mature.", "3": "It is the other way round: the four parathyroid glands are attached to the posterior surface of the thyroid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5093' AND answer = 0;
UPDATE questions SET why = 'T4 and T3 control the body''s metabolism. They raise heart rate and breathing rate, stimulate cellular respiration and set the basal metabolic rate. They also enhance the breakdown of glucose and the synthesis of cholesterol in the liver, and in children they promote skeleton and brain development.', wrong = '{"0": "Lowering blood calcium by depositing it in bone is the action of calcitonin, another thyroid hormone, not T4 and T3.", "2": "T4 and T3 increase heart rate and breathing rate. Lowering them is a sign of hypothyroidism, not the hormones'' effect.", "3": "Milk production is stimulated by prolactin from the anterior pituitary, not by thyroid hormones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5094' AND answer = 1;
UPDATE questions SET why = 'Lack of thyroid hormones (hypothyroidism) slows down metabolism. Typical signs are lethargy, weight gain, constipation, high cholesterol, low heart rate and low body temperature. This patient shows that pattern, so hypothyroidism is the most likely cause.', wrong = '{"0": "Hyperthyroidism speeds up metabolism, causing weight loss, fast heart rate, high blood pressure and high body temperature.", "1": "Hypoglycaemia (low blood sugar) causes lethargy, dizziness and nervousness, but not weight gain, constipation and slow heart rate together.", "2": "Cushing disease is excess cortisol, causing high blood sugar, thin bones and muscle loss, not this slowed-metabolism picture."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5095' AND answer = 3;
UPDATE questions SET why = 'When blood calcium falls, parathormone raises it in three ways. It makes osteoclasts dissolve bone to release calcium, makes the kidneys reabsorb calcium from urine, and activates vitamin D. Active vitamin D is needed for the intestine to absorb calcium from food.', wrong = '{"0": "Parathormone stimulates osteoclasts, which break down bone. Osteoblasts that lay down bone would lower blood calcium instead.", "1": "Calcitonin lowers blood calcium and opposes parathormone, so stimulating it would not raise calcium.", "3": "Parathormone makes the kidneys reabsorb calcium, which reduces calcium loss in urine rather than increasing it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5096' AND answer = 2;
UPDATE questions SET why = 'Too much parathormone makes osteoclasts dissolve far more bone than normal. The bones become soft and deformed, and the extra calcium in the blood (hypercalcaemia) depresses the nervous system and weakens the muscles.', wrong = '{"0": "Goitre is swelling of the thyroid gland, usually caused by iodine deficiency. It is not linked to parathormone.", "1": "Tetany comes from hypocalcaemia, which is caused by too little parathormone, not too much.", "3": "Increased excitability of neurons is a result of low blood calcium, which follows under-secretion of parathormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5097' AND answer = 2;
UPDATE questions SET why = 'The islets of Langerhans are patches of endocrine cells in the pancreas. They contain two main cell types: alpha (α) cells secrete glucagon, which raises blood glucose, and the more numerous beta (β) cells secrete insulin, which lowers it.', wrong = '{"1": "Beta cells are the larger group in the islets and they secrete insulin, not glucagon.", "2": "Interstitial (Leydig) cells lie between the seminiferous tubules of the testes and secrete testosterone.", "3": "The exocrine cells of the pancreas make pancreatic juice, which flows into the pancreatic duct. They do not release hormones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5098' AND answer = 0;
UPDATE questions SET why = 'Insulin lowers blood glucose. It increases glucose uptake by cells, promotes glycogen formation in the liver, increases the use of glucose in respiration and turns extra glucose into fat. It inhibits gluconeogenesis, the making of new glucose, so stimulating it is NOT an action of insulin.', wrong = '{"0": "This is a true action of insulin. It increases glucose uptake by skeletal muscle and fat cells, which lowers blood glucose.", "2": "This is a true action of insulin. It promotes the conversion of excess glucose into fat for storage.", "3": "This is a true action of insulin. It increases the use of glucose as fuel in cellular respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5099' AND answer = 1;
UPDATE questions SET why = 'In Type II diabetes the blood has normal levels of insulin, but the body''s cells respond to it less well (reduced sensitivity). Because insulin is not lacking, these patients usually do not need insulin injections and control their sugar with other medicines, diet and exercise.', wrong = '{"0": "A kidney transplant treats end-stage kidney failure. It is not the usual way to control Type II diabetes.", "1": "Removing the islets would remove the body''s only source of insulin and make diabetes much worse.", "2": "Daily insulin injections are the standard treatment for Type I diabetes, where the beta cells are missing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5100' AND answer = 3;
UPDATE questions SET why = 'The adrenal medulla secretes epinephrine and norepinephrine, which prepare the body for fight or flight by raising heart rate and blood pressure. If they are over-secreted, a person may have hypertension (high blood pressure) and aggressive behaviour in daily life. Under-secretion leaves the body unable to cope with emergencies.', wrong = '{"0": "Diabetes insipidus is caused by too little ADH, a hormone released by the posterior pituitary, not by the adrenal medulla.", "1": "Cushing disease is caused by excess cortisol from the adrenal cortex, not by medulla hormones.", "2": "Addison''s disease is caused by too little cortisol from the adrenal cortex, the outer layer, not the medulla."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5101' AND answer = 3;
UPDATE questions SET why = 'Cushing disease is caused by too much cortisol, often because the pituitary releases excess ACTH. Cortisol drives heavy protein breakdown and glucose production, which gives high blood sugar, high blood pressure, thin bones, muscle loss, thin fragile skin and depression.', wrong = '{"1": "Weight loss with protruding eyeballs points to hyperthyroidism such as Graves'' disease, not to excess cortisol.", "2": "Excessive dilute urine and constant thirst are the signs of diabetes insipidus, caused by lack of ADH.", "3": "Muscle weakness and salt loss that develop slowly describe Addison''s disease, the result of too little cortisol."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5102' AND answer = 0;
UPDATE questions SET why = 'The adrenal cortex makes corticosteroids of two main kinds. Aldosterone is a mineralocorticoid: it regulates mineral balance by making the kidneys reabsorb sodium and excrete excess potassium. Cortisol is a glucocorticoid that maintains glucose homeostasis.', wrong = '{"0": "Aldosterone is a steroid made from cholesterol, not a glycoprotein. Glycoprotein hormones include FSH, LH and TSH.", "2": "Glucocorticoids such as cortisol regulate glucose. Aldosterone regulates minerals, so it is not a glucocorticoid.", "3": "Biogenic amines such as epinephrine and norepinephrine come from the adrenal medulla, not the cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5103' AND answer = 1;
UPDATE questions SET why = 'During the menstrual cycle, progesterone is made by the corpus luteum under the influence of LH. During pregnancy the placenta also produces and releases progesterone. This keeps the uterine wall thick and well supplied with blood, which is needed to maintain the pregnancy.', wrong = '{"0": "The interstitial (Leydig) cells of the testes secrete testosterone, a male hormone, not progesterone.", "1": "The anterior pituitary secretes FSH and LH, which control the ovaries, but it does not make progesterone.", "3": "The Graafian follicle secretes estrogen in response to FSH. Progesterone comes from the corpus luteum that forms after ovulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5104' AND answer = 2;
UPDATE questions SET why = 'Estrogen, secreted by the Graafian follicle, has many roles. It develops female secondary sexual characteristics, regulates the menstrual cycle, repairs the uterine lining after menstruation, maintains bone density and lowers LDL (bad) cholesterol.', wrong = '{"0": "Suppressing ovulation is an effect of progesterone, which inhibits FSH. Estrogen is involved in bringing about ovulation.", "1": "Milk ejection is caused by oxytocin, which contracts the smooth muscle around the milk glands.", "3": "Estrogen lowers LDL cholesterol, not raises it. This is one reason it helps protect the heart and blood vessels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5105' AND answer = 2;
UPDATE questions SET why = 'Too much estrogen keeps stimulating the tissues of the uterus and ovaries. Its over-secretion may lead to fibroids, which are abnormal growths in the uterus, and to polycystic ovaries. Deficiency, in contrast, prevents sexual maturity in young females and causes sterility in adults.', wrong = '{"0": "Sterility in adult females is linked with estrogen deficiency, not with excess estrogen.", "2": "Feminine characteristics in males result from under-secretion of testosterone, not from excess estrogen.", "3": "Miscarriage is linked with too little progesterone during pregnancy, since progesterone maintains the uterine lining."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5106' AND answer = 1;
UPDATE questions SET why = 'Testosterone, made by the interstitial cells of the testes, matures the male reproductive organs, produces male secondary sexual characteristics and is needed for normal sperm production. When it is under-secreted, feminine characteristics develop and the male becomes sterile.', wrong = '{"0": "Acromegaly is caused by excess growth hormone in adult life, not by low testosterone.", "1": "Hypercalcaemia is high blood calcium caused by over-secretion of parathormone.", "2": "Early menstruation is a female condition linked with low progesterone during the menstrual cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5107' AND answer = 3;
UPDATE questions SET why = 'Anabolic steroids are synthetic versions of testosterone that athletes misuse to build muscle and strength. Long-term use can damage the liver, leading to hepatitis and liver tumours. They also raise the risk of heart disease, stroke and blood clots, and can cause infertility and mental health problems.', wrong = '{"1": "Anabolic steroids increase the risk of stroke and blood clots. They do not lower it.", "2": "Steroid misuse can cause mood problems such as depression and aggression. It does not prevent depression.", "3": "Anabolic steroids can cause infertility and impotence, so they do not permanently raise fertility."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5108' AND answer = 0;
UPDATE questions SET why = 'The thymus lies in the chest, beneath the sternum (breastbone) and between the lungs. It secretes thymosin, which stimulates T lymphocytes to mature so they can defend the body against pathogens.', wrong = '{"0": "The gland attached to the hypothalamus by a stalk, the infundibulum, is the pituitary gland.", "1": "The glands on top of each kidney are the adrenal glands, which secrete epinephrine, cortisol and aldosterone.", "3": "The gland at the front of the neck on both sides of the trachea is the thyroid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5109' AND answer = 2;
UPDATE questions SET why = 'Some digestive organs have endocrine cells in their walls. When food enters the stomach, cells in the stomach wall secrete gastrin, which stimulates the gastric glands to release gastric juice. Secretin and cholecystokinin come instead from the wall of the small intestine.', wrong = '{"1": "Secretin is released by the small intestine wall and stimulates the pancreas to release pancreatic juice. Cholecystokinin stimulates the gallbladder.", "2": "Insulin is secreted by beta cells of the pancreatic islets, not by the stomach wall.", "3": "Renin is produced by the kidneys and controls aldosterone production. It is not made in the stomach."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5110' AND answer = 0;
UPDATE questions SET why = 'The kidneys produce renin, which controls the production of aldosterone by the adrenal glands. Aldosterone then makes the kidneys reabsorb sodium and water, keeping blood volume and pressure normal. The kidneys also make erythropoietin and calcitriol.', wrong = '{"0": "Erythropoietin is a kidney hormone, but it stimulates bone marrow to produce red blood cells, not aldosterone.", "2": "ADH is made by the hypothalamus and released from the posterior pituitary. It controls water reabsorption, not aldosterone.", "3": "Calcitriol is a kidney hormone that raises blood calcium by increasing calcium absorption in the intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5111' AND answer = 1;
UPDATE questions SET why = 'Calcitriol is the active form of vitamin D, made in the kidneys. It raises blood calcium mainly by increasing the absorption of calcium from food in the intestines. This links to parathormone, which activates vitamin D when calcium is low.', wrong = '{"0": "Depositing calcium into bones lowers blood calcium. That is the action of calcitonin from the thyroid.", "1": "Increasing calcium loss in urine would lower blood calcium, the opposite of what calcitriol does.", "2": "Stimulating red blood cell production is the role of erythropoietin, a different kidney hormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5112' AND answer = 3;
UPDATE questions SET why = 'Glucagon is controlled by negative feedback. Alpha cells release glucagon when blood glucose falls, and glucagon raises glucose by breaking down liver glycogen. Once glucose returns to normal, this change itself switches off further glucagon release.', wrong = '{"1": "A fall in blood glucose below normal is the signal that starts glucagon release, not the one that stops it.", "2": "Stronger uterine contractions are part of the positive feedback loop of oxytocin during childbirth.", "3": "Oxytocin is involved in labour and milk ejection. It does not control glucagon release."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5113' AND answer = 0;
UPDATE questions SET why = 'Each testis is an oval organ about 3 to 5 cm long and 2 to 3 cm wide. It is packed with highly coiled seminiferous tubules where sperm are made. The ovary is described with a similar length of about 3 to 5 cm.', wrong = '{"0": "1 to 2 mm is far too small. A testis is several centimetres long, enough to hold many coiled seminiferous tubules.", "2": "8 to 10 cm is about the length of the vagina, not of a testis.", "3": "About 25 cm is the length of a ureter, the tube from kidney to bladder, far longer than a testis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5114' AND answer = 1;
UPDATE questions SET why = 'The testes develop inside the abdominal cavity. Shortly before birth they descend through an opening into the scrotum. There they are kept at about 34 °C, slightly below core body temperature, which sperm development needs.', wrong = '{"0": "The testes do not form in the scrotum. They form in the abdomen and only later move down into it.", "1": "The inguinal canal is the passage through which the vas deferens enters the abdomen. Testes only pass through this region during descent.", "2": "Testes that stayed in the pelvis would be too warm for sperm production. Normally they descend into the scrotum outside the abdomen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5115' AND answer = 3;
UPDATE questions SET why = 'The vas deferens from each testis joins the duct of a seminal vesicle to form an ejaculatory duct. The two ejaculatory ducts then pass through the prostate gland, and inside it they open into the urethra coming from the urinary bladder.', wrong = '{"0": "The bulbourethral glands are two small glands that release lubricating fluid into the urethra. The ejaculatory ducts do not pass through them.", "1": "The seminal vesicle''s duct joins the vas deferens to form the ejaculatory duct. The duct does not then pass through the vesicle.", "3": "The epididymis comes earlier in the pathway, before the vas deferens, so the ejaculatory ducts do not pass through it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5116' AND answer = 2;
UPDATE questions SET why = 'The penis is the male copulatory organ. Besides the urethra, which carries urine and semen, it contains erectile tissue and blood vessels, described as an artery and two veins. Filling of the erectile tissue with blood causes erection.', wrong = '{"1": "The prostate gland lies just below the urinary bladder, inside the pelvis, not within the penis.", "2": "The ejaculatory ducts open into the urethra inside the prostate gland, so they are not contents of the penis.", "3": "Seminiferous tubules are the coiled tubules inside the testes where sperms are produced."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5117' AND answer = 0;
UPDATE questions SET why = 'Germline cells (2n) in the wall of the seminiferous tubules divide by mitosis. Some of the daughter cells become spermatogonia, which go on to make sperm. The rest remain as germline cells, keeping a reserve for future sperm production.', wrong = '{"0": "Secondary spermatocytes (1n) form later, when primary spermatocytes divide by meiosis I. They do not come straight from germline cells.", "2": "The other cells do not die. They are kept as germline cells so that sperm production can continue.", "3": "Sertoli cells are a separate cell type in the tubule wall that nourishes developing sperms. Germline cells do not turn into them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5118' AND answer = 1;
UPDATE questions SET why = 'A sperm has a head, a midpiece and a tail. The midpiece contains mitochondria and a centriole. The tail is made of microtubules, called the axial filament, which arise from this centriole and beat to move the sperm.', wrong = '{"0": "The mitochondria in the midpiece supply ATP for swimming, but they do not form the microtubules of the tail.", "1": "The nucleus in the head carries the genetic material. It is not the origin of the tail''s microtubules.", "3": "The acrosome is a cap on the head containing enzymes for fertilisation. It does not give rise to the tail."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5119' AND answer = 2;
UPDATE questions SET why = 'The acrosome is a thick cap that covers about two-thirds of the sperm head. It forms mainly from the Golgi body and contains enzymes that help the sperm penetrate and fertilise the ovum.', wrong = '{"0": "The acrosome is on the head, not the tail. The tail is made of microtubules from the centriole.", "1": "The acrosome covers only about two-thirds of the head, not the whole of it.", "2": "One-tenth is far too small. The acrosome covers about two-thirds of the head."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5120' AND answer = 3;
UPDATE questions SET why = 'Spermatozoa in the lumen of the seminiferous tubules cannot yet swim. They are carried into the epididymis by fluid secreted by Sertoli cells. They stay in the epididymis for at least 18 hours, where they gain the ability to move.', wrong = '{"0": "The vas deferens comes after the epididymis, so it cannot carry sperm into the epididymis.", "2": "The urinary bladder stores urine and has no role in moving sperm out of the testis.", "3": "Sperms cannot beat their tails at this stage. They become motile only after time in the epididymis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5121' AND answer = 1;
UPDATE questions SET why = 'LH stimulates the Leydig cells between the seminiferous tubules to secrete testosterone. Testosterone stimulates the development of the germinal epithelium, where sperm are made, and maintains male secondary sexual characteristics. It also feeds back to reduce LH and GnRH release.', wrong = '{"1": "Inhibin is released by Sertoli cells when they are stimulated by FSH, not by testosterone. Inhibin then reduces further FSH secretion.", "2": "The seminal vesicles secrete a fructose-rich fluid for semen. Testosterone comes from the Leydig (interstitial) cells of the testes.", "3": "Testosterone works by negative feedback, so it inhibits the release of GnRH and LH rather than increasing it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5122' AND answer = 0;
UPDATE questions SET why = 'The female reproductive system is made of the gonads (ovaries) plus the oviducts, uterus and vagina. The ovaries produce eggs and hormones, so they are the primary organs. The oviducts, uterus and vagina support them and are called the accessory organs.', wrong = '{"0": "This list includes the ovaries, which are the gonads (primary organs), not accessory organs.", "1": "The ovaries alone are the gonads. They are the primary reproductive organs, not accessory organs.", "3": "Seminal vesicles and the prostate are accessory glands of the male reproductive system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5123' AND answer = 2;
UPDATE questions SET why = 'Fertilisation normally takes place in the oviduct. The zygote then begins dividing by mitosis while still in the oviduct, forming a small ball of cells. This early embryo continues moving toward the uterus, where it implants.', wrong = '{"0": "A zygote is diploid and grows by mitosis. Meiosis to form haploid cells happens only when gametes are made.", "1": "The zygote moves toward the uterus with help from cilia. It never returns to the ovary.", "2": "The corpus luteum forms from the ruptured follicle left in the ovary after ovulation, not from the zygote."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5124' AND answer = 3;
UPDATE questions SET why = 'The uterine wall has three layers. The perimetrium is the outermost thin covering, the myometrium is the thick middle layer of smooth muscle, and the endometrium is the inner spongy lining that thickens and is shed during the cycle.', wrong = '{"1": "The cervix is the lower narrow part of the uterus that opens into the vagina. It is a region, not a layer of the wall.", "2": "The myometrium is the thick middle layer of smooth muscle that contracts during childbirth, not the outer layer.", "3": "The endometrium is the innermost spongy lining, with a basal layer and a functional layer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5125' AND answer = 0;
UPDATE questions SET why = 'The functional layer of the endometrium thickens further in pregnancy so that the embryo can implant. Its vascular (blood) spaces then fuse and become interconnected, forming the placenta. The placenta supplies oxygen and nutrients to the embryo and foetus.', wrong = '{"0": "The basal layer holds stem cells that regenerate the functional layer. It is not shed, and shedding would not form a placenta.", "1": "The corpus luteum stays in the ovary and secretes hormones. It never moves to the uterus.", "2": "The myometrium is the smooth muscle layer used in contractions. It does not turn into glandular tissue or form the placenta."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5126' AND answer = 3;
UPDATE questions SET why = 'Oogenesis starts while the female is still an embryo. Oogonia (2n) inside the follicles divide by mitosis to produce primary oocytes, which are also 2n. These primary oocytes then begin meiosis I but stop in prophase I and remain there through childhood.', wrong = '{"0": "Meiosis I begins in the primary oocytes after they have formed. It is not the division that makes them from oogonia.", "2": "Meiosis II is completed by the secondary oocyte only when a sperm fuses with it, much later in life.", "3": "Binary fission is the simple division of prokaryotes such as bacteria. Human cells do not divide this way."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5127' AND answer = 1;
UPDATE questions SET why = 'At puberty a primary oocyte finishes meiosis I, producing a large secondary oocyte (1n) and a small first polar body. The secondary oocyte starts meiosis II but stops at metaphase II, and it is released in this state at ovulation. It completes meiosis II only if a sperm fuses with it.', wrong = '{"0": "Interphase comes before division begins. The ovulated cell is already partway through meiosis II.", "1": "Prophase I is where primary oocytes are arrested throughout childhood, before meiosis I is completed.", "3": "Telophase II is near the end of meiosis II, which is reached only after a sperm enters the oocyte."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5128' AND answer = 2;
UPDATE questions SET why = 'The ovulated secondary oocyte is arrested in metaphase II and can finish meiosis only if a sperm fuses with it. If no fertilisation happens, it cannot complete its development and simply dies.', wrong = '{"0": "Meiosis II is completed, forming an ovum and a second polar body, only after a sperm fuses with the oocyte.", "1": "Meiosis cannot go backwards. The oocyte has already passed prophase I and cannot return to it.", "2": "The corpus luteum develops from the ruptured follicle left in the ovary, not from the released oocyte."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5129' AND answer = 3;
UPDATE questions SET why = 'In males, each primary spermatocyte divides by meiosis I and II into four spermatids, which mature into four sperms. In females, each primary oocyte gives only one ovum, because the other products are small polar bodies. So 10 spermatocytes give 10 × 4 = 40 sperms, and 10 oocytes give 10 ova.', wrong = '{"0": "10 sperms assumes each primary spermatocyte gives one sperm. Meiosis actually gives four sperms per spermatocyte.", "1": "40 ova would mean each oocyte gives four ova. In fact three of the four products are polar bodies, so only one ovum forms.", "3": "20 counts only the two cells made in meiosis I. Meiosis II doubles sperm to 40, and oocytes still give only one ovum each."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5130' AND answer = 2;
UPDATE questions SET why = 'The menstrual phase covers days 1 to 5 of the cycle. The functional layer of the endometrium breaks down and leaves the body with blood, which is menstruation. It lasts about 3 to 5 days and happens because estrogen and progesterone levels are low.', wrong = '{"0": "Day 14 is the time of ovulation, around the middle of the cycle. Menstruation does not last 14 days.", "2": "One day is too short. Menstruation normally lasts about 3 to 5 days.", "3": "28 days is the average length of the whole menstrual cycle, not of menstruation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5131' AND answer = 1;
UPDATE questions SET why = 'During the proliferative phase, FSH makes the Graafian follicle grow and secrete estrogen. At the end of this phase, around day 14, the anterior pituitary suddenly releases a large amount of LH. This LH surge causes the Graafian follicle to release its oocyte, which is ovulation.', wrong = '{"1": "Day 1 is the start of menstruation, when estrogen and progesterone are low and new follicles are only beginning to grow.", "2": "Around day 28, if there is no pregnancy, the corpus luteum degenerates and menstruation follows, not ovulation.", "3": "Around day 21 is the secretory phase, after ovulation, when the corpus luteum secretes progesterone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5132' AND answer = 0;
UPDATE questions SET why = 'Human chorionic gonadotropin (hCG) is made by the embryo''s chorion. It keeps the corpus luteum alive, so it continues secreting estrogen and progesterone. These hormones keep the endometrium thick, so menstruation does not occur. hCG is also the hormone detected in pregnancy tests.', wrong = '{"0": "More FSH would start new follicles growing, which is not what happens in pregnancy. hCG acts on the corpus luteum.", "1": "Destruction of the corpus luteum causes a fall in estrogen and progesterone, which triggers menstruation.", "3": "Ovulation is suppressed during pregnancy by high progesterone. hCG does not stimulate a new follicle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5133' AND answer = 2;
UPDATE questions SET why = 'In modern terms, a gene is a sequence of nucleotides, a part of a DNA molecule, that codes for the formation of a polypeptide. The polypeptide then helps produce a trait. Mendel called these units factors before DNA was known.', wrong = '{"0": "The particular location of a gene on a chromosome is called its locus, not the gene itself.", "2": "The observable trait of an organism, such as seed colour, is its phenotype.", "3": "The combination of alleles an individual carries, such as Rr, is its genotype."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5134' AND answer = 1;
UPDATE questions SET why = 'A testcross mates an individual of unknown genotype with a homozygous recessive (rr). A heterozygous Rr plant makes R and r gametes in equal numbers, while rr makes only r. The offspring are Rr (round) and rr (wrinkled) in a 1:1 ratio.', wrong = '{"1": "All wrinkled offspring would need both parents to be rr. Half the offspring get R from the Rr parent and are round.", "2": "A 3:1 ratio comes from crossing two heterozygotes (Rr × Rr), not from a testcross.", "3": "All round offspring would show that the round parent was homozygous RR, not Rr."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5135' AND answer = 0;
UPDATE questions SET why = 'Crossing RRYY with rryy gives F1 plants that all have the genotype RrYy. Each plant is heterozygous for two different genes, seed shape and seed colour. An individual heterozygous for two genes is called a dihybrid.', wrong = '{"0": "Homozygous dominant for both genes would be RRYY, like one parent. The F1 received one recessive allele of each gene from the other parent.", "1": "Pure-breeding plants are homozygous. The F1 RrYy plants are heterozygous, so they do not breed true.", "2": "Both parents are pea plants of the same species. Dihybrid refers to two genes, not two species."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5136' AND answer = 3;
UPDATE questions SET why = 'Each gene can be treated separately. From Rr × Rr, the chance of round is 3/4, and from Yy × Yy the chance of yellow is 3/4. The product rule multiplies independent probabilities: 3/4 × 3/4 = 9/16 round, yellow offspring.', wrong = '{"0": "1/16 is the chance of the double recessive, wrinkled green: 1/4 × 1/4.", "1": "3/16 is the chance of round green (3/4 × 1/4) or of wrinkled yellow (1/4 × 3/4), with only one dominant trait.", "3": "3/4 is the chance of only one trait, such as round, without also requiring yellow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5137' AND answer = 2;
UPDATE questions SET why = 'In Aa × Aa, the offspring genotypes AA, Aa, aA and aa each have a probability of 1/4. The dominant phenotype appears with AA, Aa or aA. These outcomes are mutually exclusive, so the sum rule adds them: 1/4 + 1/4 + 1/4 = 3/4.', wrong = '{"0": "1/2 × 1/2 equals 1/4, not 3/4. That product gives the chance of one particular genotype, such as aa.", "2": "A heterozygous Aa parent passes on A with a probability of 1/2, not 3/4.", "3": "Each Aa parent passes on the recessive allele a half of the time, which is why 1/4 of the offspring are aa."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5138' AND answer = 1;
UPDATE questions SET why = 'In complete dominance, the dominant allele is fully expressed in the heterozygote and the recessive allele has no visible effect. A Yy pea plant therefore has yellow seeds exactly like YY, with no intermediate colour.', wrong = '{"1": "In incomplete dominance the heterozygote shows an intermediate phenotype, such as pink four o''clock flowers from red and white.", "2": "Epistasis is when a gene at one locus masks or changes the effect of a different gene. Here only one gene is involved.", "3": "In codominance both alleles are fully expressed together in the heterozygote, as in blood group AB."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5139' AND answer = 0;
UPDATE questions SET why = 'The MN blood group system was discovered in 1927 by Karl Landsteiner and Philip Levine. The ''L'' in the allele symbols Lᴹ and Lᴺ stands for their names. Lᴹ and Lᴺ are codominant, so LᴹLᴺ people have both M and N antigens.', wrong = '{"0": "Bayliss and Starling discovered secretin, the first hormone to be identified, not a blood group system.", "1": "Landsteiner alone discovered the ABO system in 1901. The MN system came later, in 1927, with Levine.", "2": "Morgan studied linkage and sex linkage in Drosophila, and Sutton proposed the chromosomal theory of inheritance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5140' AND answer = 3;
UPDATE questions SET why = 'ABO and Rh antigens can trigger strong antibody reactions, so they must be matched before a transfusion. Other major systems, such as MNS, Lutheran, Kell, Lewis and Duffy, usually do not cause matching problems. Duffy is therefore the system that usually causes no difficulty.', wrong = '{"0": "Rh must be matched, because an Rh-negative person can make anti-Rh antibodies against Rh-positive blood.", "1": "Both ABO and Rh must be matched for a safe transfusion, so neither is free of matching problems.", "3": "ABO must be matched, since the plasma naturally contains anti-A or anti-B antibodies that clump mismatched cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5141' AND answer = 2;
UPDATE questions SET why = 'Antigens A and B are normally on red cells, but some people also secrete them into body fluids such as saliva and tears. These people, called secretors, carry a dominant secretor gene, Se, on chromosome 19. This is separate from the ABO gene on chromosome 9.', wrong = '{"1": "The hh genotype blocks formation of H substance, so A and B antigens cannot be made at all. This gives the Bombay phenotype.", "2": "The I gene on chromosome 9 decides which ABO antigens are made, not whether they are secreted into body fluids.", "3": "The d allele means no Rh antigen is made. It has nothing to do with secreting A and B antigens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5142' AND answer = 0;
UPDATE questions SET why = 'A group O child has genotype ii, so each parent must carry an i allele. The group A father is therefore Iᴬi and the group B mother Iᴮi. Iᴬi × Iᴮi gives group AB children (IᴬIᴮ), group A (Iᴬi), group B (Iᴮi) and group O (ii), so all four blood groups can appear.', wrong = '{"0": "IᴬIᴬ × IᴮIᴮ can only give IᴬIᴮ, so every child would be group AB.", "2": "With IᴮIᴮ the mother always passes on Iᴮ, so children could be only AB or B, never A or O.", "3": "With IᴬIᴬ the father always passes on Iᴬ, so children could be only A or AB, never B or O."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5143' AND answer = 1;
UPDATE questions SET why = 'Group O people have the genotype ii, so their red cells carry neither antigen A nor antigen B. Landsteiner''s rule says plasma contains antibodies against whichever antigens are absent from the person''s own cells. So group O plasma contains both anti-A and anti-B.', wrong = '{"0": "Anti-Rh antibodies are not present from birth. An Rh-negative person makes them only after exposure to Rh-positive blood.", "1": "Having neither anti-A nor anti-B describes group AB, whose cells carry both antigens.", "2": "Anti-B only describes group A, whose cells carry antigen A."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5144' AND answer = 3;
UPDATE questions SET why = 'The ABO system is controlled by the gene I, located on chromosome 9. The letter I stands for iso-haem-agglutinogen, the antigen on red cells that can cause clumping. The gene has three alleles: Iᴬ, Iᴮ and i.', wrong = '{"1": "Insulin is a pancreatic hormone that lowers blood glucose. It has no link to the naming of the ABO gene.", "2": "I in the ABO gene does not stand for inhibitor. It stands for iso-haem-agglutinogen.", "3": "Antibodies are immunoglobulins, but the I gene codes for antigens on red cells, and its letter stands for iso-haem-agglutinogen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5145' AND answer = 0;
UPDATE questions SET why = 'Group B blood has antigen B on its red cells and anti-A antibodies in its plasma. Donated AB red cells carry both A and B antigens. The recipient''s anti-A antibodies bind the A antigens on the donor cells and make them clump (agglutinate).', wrong = '{"0": "AB is the universal recipient, not the universal donor. Group O is the universal donor because its cells carry no A or B antigen.", "1": "Group AB plasma contains neither anti-A nor anti-B antibodies, so the donor plasma does not attack the recipient.", "2": "Sharing antigen B is not enough. The donor cells also carry antigen A, which the recipient''s anti-A antibodies attack."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5146' AND answer = 3;
UPDATE questions SET why = 'In erythroblastosis foetalis, the mother''s anti-Rh antibodies cross the placenta and destroy the Rh-positive red cells of the foetus. To make up for this loss, the liver and spleen work harder to produce new red blood cells, so they become enlarged.', wrong = '{"0": "The antibodies destroy red cells in the circulation. The liver and spleen enlarge because of extra red cell production, not from storing antibodies.", "1": "The disease is caused by the mother''s anti-Rh antibodies, not anti-A antibodies.", "3": "Bilirubin from broken-down red cells builds up and causes jaundice. The organs do not absorb it and stop jaundice."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5147' AND answer = 2;
UPDATE questions SET why = 'The baby''s red cells are Rh-positive and are being destroyed by anti-Rh antibodies from the mother. Replacing the baby''s blood with Rh-negative blood that has no anti-Rh antibodies removes the harmful antibodies, and the new red cells cannot be attacked by any that remain.', wrong = '{"0": "Rh-positive blood carrying anti-Rh antibodies would add more antibodies and more target cells, so the destruction would continue.", "2": "Removing the liver and spleen is not a treatment. These organs are enlarged because they are trying to replace lost red cells.", "3": "Giving anti-Rh antibodies to the baby would attack its Rh-positive red cells even more."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5148' AND answer = 1;
UPDATE questions SET why = 'Polygenic traits are controlled by many gene pairs, each adding a small effect. They show continuous variation, a smooth range of values in a population. Height, skin colour, weight and intelligence are human examples, and grain colour in wheat is a plant example.', wrong = '{"0": "Haemophilia and colour blindness are X-linked recessive traits, each controlled by a single gene.", "1": "ABO and MN blood groups are each controlled by a single gene with multiple or codominant alleles, giving distinct classes.", "3": "Hypertrichosis of the pinna and webbed toes are given as Y-linked traits, passed from father to son."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5149' AND answer = 2;
UPDATE questions SET why = 'Self-crossing the F1 (AaBbCc) gives 64 combinations in the ratio 1:6:15:20:15:6:1. Only one plant is darkest red (AABBCC) and only one is white (aabbcc). The remaining 64 − 2 = 62 plants show shades from moderate red to very light red.', wrong = '{"1": "20 is the size of the largest single class, the middle shade. It is not the total of all intermediate shades.", "2": "32 does not match the distribution. Adding the classes between the two extremes gives 6 + 15 + 20 + 15 + 6 = 62.", "3": "Only one plant shows the darkest red and one shows white. These are the two extremes, not the intermediate shades."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5150' AND answer = 0;
UPDATE questions SET why = 'Epistasis is when an allele of one gene masks or changes the effect of alleles of a different gene. In humans, the allele for baldness is epistatic to the alleles for black and blonde hair: if there is no hair, hair colour cannot be seen.', wrong = '{"0": "Lᴹ and Lᴺ are codominant alleles of the same MN gene. Epistasis involves alleles of different genes.", "1": "Iᴬ and Iᴮ are codominant alleles of the same ABO gene, so they show codominance, not epistasis.", "2": "D and d are alleles of the same Rh gene. D is simply dominant over d, which is not epistasis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5151' AND answer = 3;
UPDATE questions SET why = 'Labrador coat colour depends on two genes. Gene B sets the pigment colour: B gives black and bb gives brown. Gene E controls whether pigment is deposited: E allows it, while ee blocks it and gives yellow. A bbEe dog deposits pigment, and bb makes it brown.', wrong = '{"0": "Labradors in this example are black, brown or yellow. No genotype produces a white coat.", "2": "A black coat needs at least one dominant B allele (BB or Bb). This dog is bb.", "3": "Yellow appears only with ee, which blocks pigment deposition. This dog has one E allele, so pigment is deposited."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5152' AND answer = 1;
UPDATE questions SET why = 'The Bombay phenotype occurs in people with genotype hh, who cannot make H substance, the precursor of A and B antigens. They type as group O even if they carry Iᴬ or Iᴮ. It was discovered in Bombay in 1952 and is found mostly in India, Bangladesh, Pakistan and Iran.', wrong = '{"0": "Rhesus monkeys are linked with the discovery of the Rh antigen, not the Bombay phenotype.", "1": "The Bombay phenotype is mainly found in South Asia and Iran, not only in Northern Europe.", "3": "Drosophila is the fruit fly Morgan used for linkage and sex-linkage studies. The Bombay phenotype is a human blood type."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5153' AND answer = 2;
UPDATE questions SET why = 'Foxglove flower colour depends on two genes. Gene D makes the pigment: D gives dark red and dd gives light red. Gene W controls where it goes: W limits pigment to small spots so the petals look white, while ww lets it spread evenly. A ddww plant spreads light red pigment evenly, so its flowers are light red.', wrong = '{"0": "White flowers need at least one W allele, which restricts pigment to small spots. This plant is ww.", "2": "Dark red needs at least one D allele along with ww. This plant is dd, which makes only light red pigment.", "3": "Pink is the intermediate colour of heterozygous four o''clock plants. Foxglove colours are dark red, light red and white."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5154' AND answer = 1;
UPDATE questions SET why = 'In 1900 the German geneticist Karl Correns rediscovered Mendel''s work and suggested that chromosomes play a role in heredity. Two years later, in 1902, Walter Sutton proposed the chromosomal theory of inheritance.', wrong = '{"0": "Karl Landsteiner is known for discovering the ABO blood groups and, with others, the MN and Rh systems.", "1": "Thomas Hunt Morgan studied linkage and sex linkage using Drosophila, after Mendel''s work had been rediscovered.", "2": "Walter Sutton, an American, proposed the chromosomal theory of inheritance in 1902. He did not rediscover Mendel''s work."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5155' AND answer = 3;
UPDATE questions SET why = 'Each chromosome carries many genes, so the number of genes is far larger than the number of chromosomes. Humans have about 20,000 genes on 23 chromosomes, and the fruit fly Drosophila has about 13,000 genes on 4 chromosomes. In both, each chromosome is present in two sets.', wrong = '{"1": "Drosophila has 4 pairs of chromosomes (8 in total), not 8 pairs. Its genes are spread over 4 chromosomes per set.", "2": "About 20,000 genes on 23 chromosomes is the human figure, not the figure for Drosophila.", "3": "About 60 genes is the number thought to control human skin colour. It has nothing to do with the Drosophila genome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5156' AND answer = 0;
UPDATE questions SET why = 'In a testcross, genes on different chromosomes assort independently, so the four kinds of gamete form in equal numbers. This gives parental and new combinations in a 1:1:1:1 ratio. Linked genes instead give more parental types (incomplete linkage) or only parental types (complete linkage).', wrong = '{"0": "Incomplete linkage gives more parental combinations than new ones, because crossing over happens only sometimes.", "2": "A 1:1:1:1 ratio shows independent assortment. It gives no evidence that the genes are on the Y chromosome.", "3": "Complete linkage gives only parental combinations, with no new combinations at all."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5157' AND answer = 1;
UPDATE questions SET why = 'During crossing over, non-sister chromatids of homologous chromosomes break at matching points and exchange segments. Each recombinant chromatid still carries the same genes in the same order, but now has a new mix of maternal and paternal alleles.', wrong = '{"0": "Normal crossing over swaps matching segments, so the order of genes along the chromatid is not changed.", "1": "Crossing over mixes maternal and paternal alleles on one chromatid. A recombinant chromatid is not purely maternal.", "2": "Equal segments are exchanged, so the chromatid keeps the full set of genes rather than losing half."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5158' AND answer = 3;
UPDATE questions SET why = 'In the XX–XY system the sex chromosomes are a non-matching pair. The X chromosome is rod-shaped and larger, while the Y chromosome is smaller and hook-shaped. Females are XX and males are XY.', wrong = '{"0": "X and Y are not identical. Their difference in shape and genes is what makes them a sex chromosome pair.", "1": "Neither X nor Y is ring-shaped. X is rod-shaped and Y is hook-shaped.", "3": "This reverses the shapes. The X is rod-shaped and the Y is hook-shaped."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5159' AND answer = 2;
UPDATE questions SET why = 'In grasshoppers, females are XX and males are XO, with only one X. When a male forms sperm, half receive the X and half receive no sex chromosome. A gamete without any sex chromosome is called a nullo gamete, and if it fertilises an egg the offspring is an XO male.', wrong = '{"1": "A polar body is a small cell produced during oogenesis in females, not a sperm.", "2": "Homogametic describes the sex that makes only one kind of gamete, here the XX female. The male XO is heterogametic.", "3": "Grasshopper males have no Y chromosome, so they cannot make Y sperm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5160' AND answer = 0;
UPDATE questions SET why = 'The F1 female was red-eyed but carried the white allele. Crossing her with a white-eyed male gave red and white eyes in both males and females in a 1:1:1:1 ratio. The appearance of white-eyed females proved that females could have white eyes, supporting an X-linked gene.', wrong = '{"0": "Morgan concluded that the eye colour gene is on the X chromosome. A Y-linked gene could never appear in females.", "1": "Morgan''s crosses showed that eye colour follows the X chromosome, so the gene is not autosomal.", "2": "Morgan''s F1 flies were all red-eyed, which showed that red is dominant over white."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5161' AND answer = 3;
UPDATE questions SET why = 'In amniocentesis, a needle is guided by ultrasound into the uterus to draw out amniotic fluid. The fluid contains foetal cells, which are grown in a culture medium and then checked for an abnormal number of chromosomes, as in Down syndrome.', wrong = '{"0": "The cells are not injected back into the mother. They are cultured in the laboratory for analysis.", "1": "Ultrasound is used only to guide the needle. The cells themselves are cultured and their chromosomes examined.", "3": "Rh-antiserum is serum that contains anti-Rh antibodies. It is not made from foetal cells in amniocentesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5162' AND answer = 2;
UPDATE questions SET why = 'An X-linked dominant trait shows up when a person has just one copy of the dominant allele on an X chromosome. Rett syndrome, which causes loss of speech and repetitive hand movements, is an example, as are vitamin D-resistant rickets and Aicardi syndrome.', wrong = '{"1": "X-linked recessive examples are muscular dystrophy, colour blindness and haemophilia A and B.", "2": "Autosomal recessive traits are carried on non-sex chromosomes. Haemophilia C is an example of this type.", "3": "Y-linked traits pass only from father to son, such as hypertrichosis of the pinna and webbed toes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5163' AND answer = 0;
UPDATE questions SET why = 'Some genes lie on the part of the Y chromosome that has no matching region on the X. They have no alleles on the X, so they occur only in males and pass from father to son. They are called holandric genes and include those for hypertrichosis of the pinna.', wrong = '{"0": "Pseudo-autosomal genes lie on the matching regions of X and Y, so they do have alleles on both chromosomes.", "2": "Polygenes are several genes that add their small effects together, as in human skin colour.", "3": "Hypostatic genes are those whose effect is masked by an epistatic allele of another gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5164' AND answer = 1;
UPDATE questions SET why = 'SRY stands for sex-determining region Y, a gene on the Y chromosome. It produces a protein that switches on the development of testes in the embryo and prevents female reproductive structures from forming. An embryo with SRY therefore develops as a male.', wrong = '{"1": "The red and green opsin genes for colour vision are on the X chromosome, not the Y.", "2": "SRY is on the Y chromosome, so it is normally present only in males, not in females.", "3": "Haemophilia A is caused by a faulty X-linked gene for clotting factor VIII, not by SRY."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5165' AND answer = 0;
UPDATE questions SET why = 'When a blood vessel is injured, the first step is that platelets stick to the injured site and form a platelet plug. Activated platelets and damaged tissue then release clotting factors. These set off a cascade that converts fibrinogen into fibrin, which forms a mesh to seal the wound.', wrong = '{"0": "Fibrinogen is converted to fibrin later, after the platelets and damaged tissue release clotting factors.", "2": "The fibrin mesh that traps blood cells forms only after fibrinogen has been converted, near the end of clotting.", "3": "Cross-linking of fibrin strands is the final step that strengthens the clot, not the first."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5166' AND answer = 1;
UPDATE questions SET why = 'Colour vision depends on three types of cone, each with its own opsin protein. The genes for the red and green opsins lie on the X chromosome, which is why red-green colour blindness is X-linked. The gene for the blue opsin lies on autosome 7.', wrong = '{"0": "The Y chromosome carries few genes and none for opsins.", "1": "Chromosome 9 carries the I gene for the ABO blood groups, not an opsin gene.", "2": "The X chromosome carries the red and green opsin genes, not the blue one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5167' AND answer = 3;
UPDATE questions SET why = 'Duchenne muscular dystrophy is an X-linked recessive disorder. About two-thirds of cases are inherited from a carrier mother, while about one-third come from a new mutation in the gene for dystrophin, a protein muscles need.', wrong = '{"0": "Two-thirds is the share of cases inherited from the mother, not the share caused by new mutations.", "1": "New mutations do cause some cases, about one-third of the total.", "3": "Not all cases are new mutations. About two-thirds are inherited from the mother."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5168' AND answer = 2;
UPDATE questions SET why = 'Duchenne muscular dystrophy becomes evident around age 4, when the child starts walking. Muscles weaken over time, so braces may be needed by about age 10. By about age 12, most patients cannot walk and need a wheelchair.', wrong = '{"0": "Around age 4 is when the disease first becomes noticeable as the child begins walking.", "1": "45 is the upper end of the typical lifespan of 15 to 45 years, not the age a wheelchair is needed.", "3": "By about age 10 the child may need braces. Wheelchair use usually follows by about 12."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5169' AND answer = 2;
UPDATE questions SET why = 'A sex-limited trait is controlled by genes present in both sexes but expressed in only one sex. The genes for beard growth are carried by both males and females, but they are expressed only in males, so beard growth is sex-limited.', wrong = '{"0": "Sex-influenced traits, such as baldness, appear in both sexes, but the allele is dominant in one sex and recessive in the other.", "1": "Beard genes are present in both sexes, so they are not limited to the Y chromosome.", "2": "Beard growth is not an X-linked recessive trait. Its genes are expressed according to sex, not carried on the X."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5170' AND answer = 3;
UPDATE questions SET why = 'Walther Flemming first observed chromosomes in 1882 while studying cell division in salamander larvae. In 1888 the German anatomist Waldeyer-Hartz proposed the name chromosome, meaning coloured bodies, because these structures take up stain strongly.', wrong = '{"1": "Flemming discovered chromosomes in 1882, but the name was proposed later by Waldeyer-Hartz.", "2": "Walter Sutton proposed the chromosomal theory of inheritance in 1902, not the name chromosome.", "3": "Wilhelm Johannsen introduced the term gene in 1909, not the term chromosome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5171' AND answer = 0;
UPDATE questions SET why = 'The centromere is the constricted region that holds sister chromatids together. It is described as a specific DNA sequence of about 220 nucleotides. A disc-shaped protein structure, the kinetochore, attaches to it and connects the chromosome to the spindle during cell division.', wrong = '{"0": "About 140 million nucleotides is the DNA content of a whole average human chromosome, not of the centromere.", "2": "About 146 nucleotides is the length of DNA wrapped around each histone octamer in a nucleosome.", "3": "About 80 nucleotides is the length of the linker DNA that joins one nucleosome to the next."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5172' AND answer = 1;
UPDATE questions SET why = 'Some chromosomes have a second narrow region, the secondary constriction or nucleolar organiser region, which makes nucleoli. The knob-like end of the chromosome beyond it is called the satellite. It contains highly repetitive DNA sequences, often called junk DNA.', wrong = '{"0": "The kinetochore is a disc-shaped protein structure on the centromere where spindle fibres attach.", "2": "Telomeres are the tips of every chromosome. They stop chromosomes from sticking to each other end to end.", "3": "A chromatid is one of the two identical strands of a duplicated chromosome, not a knob at its end."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5173' AND answer = 1;
UPDATE questions SET why = 'Chromosomes are named by where the centromere lies. In metacentric chromosomes it is at the centre, in sub-metacentric slightly off centre, in acrocentric near one end, and in telocentric exactly at one end. So a centromere right at the end means telocentric.', wrong = '{"1": "Acrocentric chromosomes have the centromere near one end, leaving a very short arm, but not exactly at the end.", "2": "Metacentric chromosomes have the centromere in the middle, giving two arms of equal length.", "3": "Sub-metacentric chromosomes have the centromere slightly away from the centre, giving one arm a little longer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5174' AND answer = 0;
UPDATE questions SET why = 'Each chromosome holds one very long DNA molecule packed tightly with histone proteins. In an average human chromosome this DNA is about 5 cm long and contains about 140 million nucleotides. Packing by histones lets it fit into a nucleus only a few micrometres wide.', wrong = '{"0": "2 nm is the width of the DNA double helix, and 146 nucleotides is the DNA wrapped around one nucleosome.", "1": "700 nm is the thickness of a fully condensed chromatid, not the length of its DNA.", "3": "About 20,000 is the number of human genes in total, not the nucleotides in one chromosome, and 1 m is not its length."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5175' AND answer = 2;
UPDATE questions SET why = 'DNA is negatively charged because of its phosphate groups. Histone proteins carry many basic amino acids, such as arginine and lysine, whose side chains are positively charged. Opposite charges attract, so DNA binds tightly to histones.', wrong = '{"0": "Deoxyribose is the sugar in DNA. Histones are proteins and do not contain it.", "1": "Phosphate groups belong to DNA and give it a negative charge, not a positive one.", "2": "Acidic amino acids such as glutamic acid carry a negative charge, which would repel DNA rather than bind it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5176' AND answer = 3;
UPDATE questions SET why = 'A nucleosome is the basic unit of DNA packing. About 146 nucleotides of DNA wrap twice around a histone octamer, which has two copies each of H2A, H2B, H3 and H4. Neighbouring nucleosomes are joined by about 80 nucleotides of linker DNA, giving a beads-on-a-string look.', wrong = '{"0": "About 80 nucleotides is the linker DNA between nucleosomes, and the DNA wraps around the core twice, not once.", "1": "About 220 nucleotides is the length given for the centromere sequence. DNA wraps around each octamer twice.", "3": "About 1000 nucleotides wrapped ten times is far more than one nucleosome holds. The real figure is about 146 nucleotides, wrapped twice."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5177' AND answer = 2;
UPDATE questions SET why = 'Histone H1 is the fifth type of histone, called the linker histone. It sits at the base of the nucleosome, near where DNA enters and leaves the core, and helps wind the chain of nucleosomes into a tighter coil.', wrong = '{"1": "The histone octamer core has two copies each of H2A, H2B, H3 and H4 only. H1 is outside the core.", "2": "Okazaki fragments are joined by the enzyme DNA ligase during replication, not by a histone.", "3": "Hydrogen bonds between DNA strands are broken by the enzyme helicase during replication."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5178' AND answer = 0;
UPDATE questions SET why = 'Chromatin has two kinds of region. Euchromatin is the active part, where genes can be read. Heterochromatin is more tightly packed, mostly inactive and forms dark bands when stained.', wrong = '{"0": "Heterochromatin is the inactive, tightly packed chromatin that produces dark bands.", "1": "Nucleosomes are units of DNA wrapped around histones. They occur in both active and inactive chromatin.", "2": "Satellites are knob-like ends found on some chromosomes, beyond the secondary constriction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5179' AND answer = 3;
UPDATE questions SET why = 'Homologous chromosomes carry genes for the same traits in the same order. The alternative forms of a gene, called alleles, therefore sit at the same locus on each homologue. So the matching chromosome also carries an allele for eye colour at that locus, which may be the same or a different allele.', wrong = '{"0": "Alleles of a gene occupy the same locus on homologous chromosomes, not different loci.", "2": "Homologous chromosomes have genes for the same traits at matching loci, so that locus also controls eye colour.", "3": "Each homologue has the gene at the same locus. A homologue does not have an empty place there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5180' AND answer = 1;
UPDATE questions SET why = '³⁵S labels the protein coat of the phage, because sulphur is found in proteins but not in DNA. During infection only the phage DNA enters the bacterium, and the protein coat stays outside. After centrifugation, the radioactivity was therefore found in the medium and not in the bacterial cells.', wrong = '{"0": "The two locations gave clearly different results. All the ³⁵S stayed with the protein coats in the medium.", "1": "³⁵S labels protein, not DNA. Since the protein never entered the cells, it could not appear in new phage DNA.", "2": "Radioactivity inside the bacterial cells was the result with ³²P-labelled DNA, the other setup."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5181' AND answer = 3;
UPDATE questions SET why = 'Three models of DNA replication were proposed. In the dispersive model, the parent DNA is broken into pieces that mix with new nucleotides. After replication, every strand of both daughter DNAs is a mixture of old and new nucleotides.', wrong = '{"0": "One all-old and one all-new daughter molecule is what the conservative model predicts.", "2": "Every model of replication produces new DNA. They differ only in how old and new strands are shared.", "3": "One parental and one new strand in each daughter is the semi-conservative model, which Meselson and Stahl proved correct."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5182' AND answer = 1;
UPDATE questions SET why = 'In conservative replication, the original heavy (¹⁵N) double helix would stay intact and a completely new light (¹⁴N) helix would be made. After one round in ¹⁴N medium there would be two bands, one heavy and one light. Meselson and Stahl saw a single intermediate band instead, which ruled this model out.', wrong = '{"1": "A single heavy band was seen only before any replication, when all the DNA still contained ¹⁵N.", "2": "A single intermediate band is what was actually observed. It fits semi-conservative (and dispersive) replication, not conservative.", "3": "Intermediate and light bands appeared after the second replication, as the semi-conservative model predicts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5183' AND answer = 0;
UPDATE questions SET why = 'A pulse-chase experiment has two stages. In the pulse stage, the organism is exposed to a radioisotope for a short time and builds it into its DNA. In the chase stage, the labelled DNA is followed over time by measuring its radioactivity.', wrong = '{"0": "A testcross is a genetic cross with a homozygous recessive to find out whether a dominant individual is homozygous or heterozygous.", "1": "Transformation is the uptake of genetic material that changes the receiving cell, as in Griffith''s bacteria experiment.", "3": "Ultracentrifugation is a technique that separates molecules by density. It is a tool, not the name of the labelling experiment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5184' AND answer = 2;
UPDATE questions SET why = 'Prokaryotes have three DNA polymerases. DNA polymerase III is the main enzyme that builds new strands, and DNA polymerase I removes RNA primers and fills the gaps with DNA. DNA polymerase II is involved in repairing DNA damage during the life of the cell.', wrong = '{"0": "RNA primers are laid down by the enzyme primase, not by a DNA polymerase.", "1": "Replacing RNA primers with DNA is the job of DNA polymerase I at the end of replication.", "3": "Building most of the new strand is done by DNA polymerase III, the main replicating enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5185' AND answer = 2;
UPDATE questions SET why = 'New strands are built from deoxyribonucleoside triphosphates (dATP, dCTP, dGTP, dTTP), each carrying three phosphate groups. As DNA polymerase III adds one to the chain, it breaks off two of the phosphates. This releases the energy that drives the building of the strand.', wrong = '{"0": "Helicase breaks hydrogen bonds to open the helix, but that energy is not what joins each new nucleotide.", "1": "The deoxyribose sugar becomes part of the new backbone. It is not broken down to release energy.", "2": "RNA primers are removed only at the end by DNA polymerase I. They do not power the addition of each nucleotide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5186' AND answer = 3;
UPDATE questions SET why = 'DNA polymerase III can add nucleotides only to an existing 3′ end. The leading strand is built continuously toward the fork, so one primer is enough. The lagging strand is made in short Okazaki fragments away from the fork, and each fragment needs its own new primer.', wrong = '{"1": "The lagging strand needs primers too, in fact one for every Okazaki fragment, so many more than the leading strand.", "2": "Both strands need primers because DNA polymerase cannot start a new chain on its own.", "3": "The leading strand is extended continuously from a single primer. It does not need one per nucleotide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5187' AND answer = 0;
UPDATE questions SET why = 'The lagging strand is built in short pieces called Okazaki fragments. In prokaryotes these fragments are longer, about 1000 to 2000 nucleotides each. In eukaryotes they are much shorter, about 100 to 200 nucleotides.', wrong = '{"0": "5 to 10 nucleotides is the length of an RNA primer laid down by primase, not of an Okazaki fragment.", "2": "100 to 200 nucleotides is the length of Okazaki fragments in eukaryotes, not in prokaryotes.", "3": "About 250 nucleotides is the length of the poly-A tail added to eukaryotic mRNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5188' AND answer = 1;
UPDATE questions SET why = 'The 1968 Nobel Prize in Physiology or Medicine was shared by three scientists. Nirenberg was honoured for his work on the genetic code, Khorana for synthesis of nucleic acids, and Robert Holley for discovering the chemical structure of transfer RNA (tRNA).', wrong = '{"0": "Making poly-U mRNA, which showed that UUU codes for phenylalanine, was the work of Nirenberg.", "1": "The term central dogma was introduced by Francis Crick, not Holley.", "3": "Decoding the remaining 17 codons was done by Har Gobind Khorana."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5189' AND answer = 2;
UPDATE questions SET why = 'After Nirenberg showed that UUU codes for phenylalanine, he and Philip Leder tested triplet codons and worked out the amino acids for 47 codons. Har Gobind Khorana then decoded the remaining 17, which together make 47 + 17 = 64 codons.', wrong = '{"1": "3 is the number of stop codons (UAA, UAG and UGA), which code for no amino acid.", "2": "64 is the total number of codons. Nirenberg and Leder decoded only part of them.", "3": "17 is the number of codons decoded by Khorana after Nirenberg and Leder''s work."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5190' AND answer = 0;
UPDATE questions SET why = 'AUG is the start codon, found at the beginning of the coding sequence of genes. It signals where translation should begin and specifies the amino acid methionine, so new polypeptides start with methionine.', wrong = '{"0": "Phenylalanine is coded by UUU, as Nirenberg showed with poly-U mRNA. It is not coded by AUG.", "2": "Glycine is coded by codons beginning with GG, such as GGU and GGC, not by AUG.", "3": "Arginine is coded by codons such as AGA, not by the start codon AUG."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5191' AND answer = 1;
UPDATE questions SET why = 'The genetic code is nearly universal, but there are a few exceptions. The code used by mitochondrial DNA differs slightly from the code of chromosomal DNA. This difference reflects the independent evolutionary history of mitochondria, which are thought to have come from free-living bacteria.', wrong = '{"0": "Mitochondria do contain their own DNA, which is why they can have a slightly different code at all.", "1": "UV-induced mutations are random damage. The mitochondrial code is a regular, shared feature, not a result of damage.", "2": "RNA primers are used in all DNA replication, so they cannot explain a difference in the mitochondrial code."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5192' AND answer = 3;
UPDATE questions SET why = 'The genetic code has no punctuation. The three nucleotides of a codon are read one after another without any gaps or markers between them. This is different from the triplet nature of the code, which only states that a codon has three nucleotides.', wrong = '{"0": "Universality means that the same code is used by almost all organisms, for example AGA codes arginine in bacteria and humans.", "1": "Being a triplet code means each codon has three nucleotides. It does not say whether they are read with or without gaps.", "3": "Degeneracy means that more than one codon can specify the same amino acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5193' AND answer = 2;
UPDATE questions SET why = 'In transcription only one DNA strand, the template strand, is copied into RNA. It is also called the antisense (–) strand, because the mRNA is complementary to it. The other strand, the coding or sense (+) strand, has the same sequence as the mRNA, with T in place of U.', wrong = '{"1": "The lagging strand is the daughter strand made in Okazaki fragments during DNA replication, not a transcription term.", "2": "The sense (+) strand is the coding strand, which is not transcribed. It matches the mRNA sequence.", "3": "The leading strand is the continuously made daughter strand in DNA replication, not a transcription term."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5194' AND answer = 0;
UPDATE questions SET why = 'Promoters are DNA sequences where RNA polymerase binds before transcription. In prokaryotes, TTGACA lies 35 nucleotides before the start point, so it is called the –35 sequence. A second promoter, TATAAT, lies 10 nucleotides before the start and is the –10 sequence.', wrong = '{"0": "The TATA box (TATAAA) is a eukaryotic promoter about 25 nucleotides before the start, the –25 sequence.", "1": "The CAAT box (GGCCAATCT) is a eukaryotic promoter about 70 nucleotides before the start, the –70 sequence.", "2": "The –10 sequence in prokaryotes is TATAAT, not TTGACA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5195' AND answer = 3;
UPDATE questions SET why = 'Prokaryotic RNA polymerase has five subunits, each with its own job. The two α subunits bind regulatory proteins, the β′ subunit binds the template DNA, the β subunit binds RNA nucleotides and the σ subunit recognises the promoter.', wrong = '{"0": "The β subunit binds the incoming RNA nucleotides, not the template DNA.", "2": "The two α subunits bind regulatory proteins that control transcription.", "3": "The σ subunit recognises the promoter and starts transcription, then it is released from the enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5196' AND answer = 1;
UPDATE questions SET why = 'Eukaryotes have three RNA polymerases, each making a different RNA. RNA polymerase I works in the nucleolus and makes ribosomal RNA (rRNA). RNA polymerase II makes mRNA, and RNA polymerase III makes tRNA. Prokaryotes have only one RNA polymerase for all three.', wrong = '{"0": "RNA polymerase II makes messenger RNA (mRNA), not rRNA.", "1": "DNA polymerase III builds new DNA strands during replication in prokaryotes. It does not make RNA.", "3": "RNA polymerase III makes transfer RNA (tRNA), not ribosomal RNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5197' AND answer = 2;
UPDATE questions SET why = 'As RNA polymerase moves along the DNA, the first 12 bases of the new mRNA pair with the template strand and form a temporary RNA–DNA helix. This holds the growing 3′ end steady at the enzyme''s catalytic site, so new ribonucleotides can keep being added.', wrong = '{"0": "The σ subunit is released once RNA polymerase has bound the promoter and started, so it does not hold the 3′ end.", "1": "The 5′ cap is added to eukaryotic mRNA during processing to protect it. It is at the other end and does not anchor the RNA to DNA.", "2": "Transcription needs no primer. RNA polymerase can start a new RNA chain on its own."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5198' AND answer = 3;
UPDATE questions SET why = 'Eukaryotic mRNA is processed before it leaves the nucleus. At its 3′ end, a chain of about 250 adenine nucleotides is added, called the poly-A tail. This tail protects the mRNA from being broken down by nuclease enzymes.', wrong = '{"0": "5 to 10 nucleotides is the length of an RNA primer used in DNA replication, not the poly-A tail.", "2": "2000 nucleotides is the upper length of prokaryotic Okazaki fragments, far longer than a poly-A tail.", "3": "12 is the number of bases in the temporary RNA–DNA helix during transcription."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5199' AND answer = 1;
UPDATE questions SET why = 'Aminoacyl-tRNA synthetase attaches each amino acid to its correct tRNA before translation. There are 20 kinds of this enzyme, one for each of the 20 amino acids. Each enzyme also recognises every tRNA whose anticodon matches its amino acid.', wrong = '{"1": "3 is the number of stop codons, which code for no amino acid and need no synthetase.", "2": "61 is the number of codons that specify amino acids. Synthetases match amino acids, so there is one per amino acid, not per codon.", "3": "64 is the total number of codons, including the three stop codons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5200' AND answer = 0;
UPDATE questions SET why = 'During elongation, the P site holds the tRNA with the growing chain and the A site holds the incoming aminoacyl-tRNA. The enzyme peptidyl transferase detaches the amino acid or chain from the P-site tRNA and joins it to the amino acid at the A site with a peptide bond.', wrong = '{"0": "A release factor binds at a stop codon and ends translation. It does not form peptide bonds.", "1": "RNA polymerase makes RNA from a DNA template during transcription, not peptide bonds.", "2": "Aminoacyl-tRNA synthetase loads amino acids onto their tRNAs before translation. It does not link amino acids together."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5201' AND answer = 3;
UPDATE questions SET why = 'Prokaryotic ribosomes are smaller, 70S, while eukaryotic ribosomes are larger, 80S. Other differences are that prokaryotic genes lack introns and start with N-formyl methionine, while eukaryotic mRNA is processed first and translated in the cytoplasm and on rough ER.', wrong = '{"0": "It is prokaryotes that start with N-formyl methionine. Eukaryotes start with ordinary methionine.", "1": "Prokaryotic genes lack introns. Most eukaryotic genes contain introns.", "3": "Prokaryotes have no endoplasmic reticulum, so they translate in the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5202' AND answer = 2;
UPDATE questions SET why = 'In positive gene regulation, regulatory proteins called activators (or inducers) bind to operator regions of DNA. They help RNA polymerase attach to the promoter, which starts transcription or increases its rate. This is the opposite of repressors, which block transcription.', wrong = '{"0": "Removing introns from mRNA is splicing, a post-transcriptional step, not the job of activators.", "2": "Adding a 5′ cap is part of mRNA processing after transcription, not a regulatory protein''s role.", "3": "Blocking RNA polymerase to stop transcription is what repressors do in negative gene regulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5203' AND answer = 1;
UPDATE questions SET why = 'Gene expression can be regulated at several levels. Post-translational regulation happens after the protein has been made. It controls modification of the protein, such as its folding and its stability, which decide whether it works and how long it lasts.', wrong = '{"1": "Controlling the rate of transcription is regulation at the transcriptional level, before any mRNA exists.", "2": "Controlling the rate of translation is regulation at the translational level, while the protein is being made.", "3": "Modifying mRNA, such as splicing and capping, is regulation at the post-transcriptional level."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5204' AND answer = 0;
UPDATE questions SET why = 'A mutation is a change in the DNA. The organism or cell in which a mutation has happened is called a mutant. The agent that causes the change, such as UV light or certain chemicals, is called a mutagen.', wrong = '{"0": "A transposon is a piece of DNA that can move from one place to another in the genome.", "1": "A mutagen is the agent that causes a mutation, such as radiation or chemicals, not the changed organism.", "3": "A carrier is a heterozygous individual who has one recessive allele but does not show the trait."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5205' AND answer = 2;
UPDATE questions SET why = 'DNA strongly absorbs ultraviolet light. When two neighbouring pyrimidine nucleotides (C or T) on the same strand absorb UV, covalent bonds form between them, joining them into a dimer. This distorts the DNA and can completely block replication at that point.', wrong = '{"0": "Transposons move through the genome by themselves. UV radiation does not insert them into genes.", "2": "Forming free radicals that break phosphodiester bonds is how ionising radiation such as X-rays and gamma rays acts.", "3": "Removing amino groups from adenine or cytosine is how some mutagenic chemicals act, not UV radiation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5206' AND answer = 1;
UPDATE questions SET why = 'Mutagenic chemicals cause point mutations in several ways. Some remove the amino group from adenine or cytosine, so the changed base pairs with the wrong partner during replication. Others resemble nucleotides and get built into DNA, or add hydrocarbon groups to bases.', wrong = '{"0": "Bonding adjacent pyrimidines together is the effect of ultraviolet radiation, not of chemical mutagens.", "1": "Non-disjunction of chromosome 21 changes chromosome number and causes Down syndrome. It is not a chemical point mutation.", "2": "Breaking the centromere is not how chemical mutagens cause point mutations, which change single bases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5207' AND answer = 3;
UPDATE questions SET why = 'A single nucleotide polymorphism (SNP) is a change in just one nucleotide. SNPs are very common and are often harmless or have subtle effects. One example is a single base change in a gene that leaves a person unable to digest milk sugar (lactose).', wrong = '{"1": "Trisomy 21 is an extra whole chromosome, a chromosomal mutation, not a single nucleotide change.", "2": "Deleting three nucleotides in cystic fibrosis is an example of a deletion, which removes more than one nucleotide.", "3": "A premature stop codon is a nonsense mutation, a different category of point mutation from the SNP example."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5208' AND answer = 0;
UPDATE questions SET why = 'Sickle cell anaemia comes from a single point mutation in the β-globin gene. The DNA base T is replaced by A, so the codon CTC, which codes glutamic acid, becomes CAC, which codes valine. Changing one amino acid this way makes it a missense mutation.', wrong = '{"1": "GGC → GGU still codes glycine, so it is a silent mutation and does not change the protein.", "2": "Transposon insertion into the factor IX gene is an example of insertional inactivation causing haemophilia.", "3": "Deletion of three nucleotides is the common cause of cystic fibrosis, not sickle cell anaemia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5209' AND answer = 0;
UPDATE questions SET why = 'Phenylketonuria (PKU) is caused by a faulty enzyme that cannot break down phenylalanine, so it builds up and damages the brain. Untreated PKU causes intellectual disability, seizures, behavioural problems, a small head (microcephaly) and a musty odour of the breath, skin and urine.', wrong = '{"0": "Small testicles and breast growth in males are features of Klinefelter syndrome (XXY).", "2": "Pain, jaundice and sickle-shaped red cells are features of sickle cell anaemia.", "3": "Webbed neck, short stature and infertility in females are features of Turner syndrome (XO)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5210' AND answer = 1;
UPDATE questions SET why = 'Pharmacogenomics studies how a person''s genes affect their response to drugs. By analysing an individual''s DNA, doctors can choose the drug and dose most likely to work for that person and avoid harmful side effects.', wrong = '{"0": "Cell therapy replaces cells that do not work, for example beta cells in type 1 diabetes.", "1": "Genetic counselling gives families information about genetic disorders, testing and family planning.", "2": "Gene therapy corrects or replaces a faulty gene itself, rather than choosing drugs to suit the genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5211' AND answer = 3;
UPDATE questions SET why = 'In an inversion, a segment of a chromosome breaks out, turns around and reinserts, so its orientation is reversed. The genes are still present, but their order in that region is reversed.', wrong = '{"0": "Non-disjunction is the failure of chromosomes to separate during meiosis, which changes chromosome number.", "1": "In a translocation, a segment breaks off one chromosome and becomes part of another chromosome.", "3": "In a duplication, a segment of a chromosome is repeated, so some genes are present in extra copies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5212' AND answer = 2;
UPDATE questions SET why = 'Insertional inactivation happens when a mobile piece of DNA, a transposon, inserts into a gene and stops it working. A human transposon inserted into the clotting factor IX gene on the X chromosome puts a stop codon in the middle of the gene, causing X-linked haemophilia.', wrong = '{"0": "Down syndrome is caused by an extra chromosome 21, usually from non-disjunction, not by a transposon.", "1": "Phenylketonuria is caused by point mutations in the gene for the enzyme that breaks down phenylalanine.", "3": "Sickle cell anaemia is caused by a single base substitution, T replaced by A, in the β-globin gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5213' AND answer = 2;
UPDATE questions SET why = 'Down syndrome, usually caused by an extra chromosome 21 (trisomy 21), is the most common chromosomal disorder in live births. It occurs in about 1 in every 750 children, and its risk rises with the mother''s age. It was first described by J. Langdon Down in 1866.', wrong = '{"1": "About 1 in 5000 is the figure for Turner syndrome among female births, not Down syndrome.", "2": "1/64 is a probability from genetics problems, such as one genotype class in a trihybrid cross.", "3": "1 in 4 is the chance of an affected child from two carriers of a recessive allele, not the frequency of Down syndrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5214' AND answer = 0;
UPDATE questions SET why = 'Klinefelter syndrome (XXY) produces sterile males with low testosterone and some female features, such as breast growth. Testosterone is given from the onset of puberty to make up for the deficiency. Surgical breast removal and behavioural therapy may also be used.', wrong = '{"0": "A bone marrow transplant can cure sickle cell anaemia. It does not treat a sex chromosome disorder.", "2": "Estrogen replacement therapy is used in Turner syndrome to develop female secondary sexual characteristics.", "3": "A low-phenylalanine diet is the treatment for phenylketonuria (PKU)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5215' AND answer = 1;
UPDATE questions SET why = 'Turner syndrome (XO) causes short stature and immature sex organs. If growth hormone treatment is started early in childhood, it improves growth and the girl can reach adult height. Estrogen replacement therapy is given separately to develop secondary sexual characteristics.', wrong = '{"0": "Insulin injections treat type 1 diabetes. They do not improve height in Turner syndrome.", "1": "Rh-antiserum is given to Rh-negative mothers to prevent Rh sensitisation. It has no effect on growth.", "2": "Testosterone at puberty is a treatment for Klinefelter syndrome in males, not Turner syndrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5216' AND answer = 3;
UPDATE questions SET why = 'Genetic engineering relies on two basic technologies. Recombinant DNA technology cuts DNA and joins pieces from different sources, a cut and paste of genes. The polymerase chain reaction (PCR) makes many copies of a chosen DNA segment rapidly.', wrong = '{"0": "Vaccination and antibiotics are medical treatments. They are not the technologies genetic engineering is built on.", "1": "Electrophoresis and microscopy are useful laboratory methods, but they are not the two core technologies of genetic engineering.", "3": "Fermentation and selective breeding are traditional biotechnology methods that do not directly change DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5217' AND answer = 2;
UPDATE questions SET why = 'Restriction endonucleases cut DNA at specific recognition sequences called restriction sites. These sites are palindromic, meaning both strands read the same in the 5′ to 3′ direction, and are usually four to eight nucleotides long, for example GAATTC for EcoRI.', wrong = '{"1": "20 to 30 nucleotides is about the length of a PCR primer, not a restriction site.", "2": "About 220 nucleotides is the length given for a centromere sequence, far longer than a restriction site.", "3": "A single nucleotide cannot form a palindrome across two strands and would occur too often to be a useful cutting site."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5218' AND answer = 0;
UPDATE questions SET why = 'Vectors are carriers that take a gene of interest into a host cell. Bacterial plasmids are the most common, but for monkey and human cells animal viruses, such as the human cold virus, are used as vectors because they naturally infect those cells.', wrong = '{"0": "Bacteriophage lambda infects bacteria, so it is used to carry genes into bacterial cells, not human cells.", "2": "Bacterial plasmids are mainly used with bacterial host cells such as E. coli.", "3": "Cosmids are plasmids carrying a phage cos sequence. They are used with bacterial hosts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5219' AND answer = 1;
UPDATE questions SET why = 'A vector is a DNA molecule that carries a gene of interest into a host cell. Plasmids, bacteriophages such as lambda and P1, cosmids, BACs, YACs and P1 artificial chromosomes are all vectors. A restriction endonuclease is an enzyme that cuts DNA, so it is NOT a vector.', wrong = '{"0": "Bacterial artificial chromosomes (BACs) are vectors that can carry large pieces of DNA into bacteria.", "1": "Bacteriophage P1 is a virus of bacteria used as a vector to carry genes into bacterial cells.", "2": "Yeast artificial chromosomes (YACs) are vectors that carry very large DNA fragments into yeast cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5220' AND answer = 3;
UPDATE questions SET why = 'After the recombinant vector is made, it is put into bacteria. Each bacterium that takes it up divides again and again, forming a colony of identical cells called a bacterial clone. Every cell in the clone carries identical copies of the gene of interest.', wrong = '{"0": "Transgenic plants are grown from plant cells that receive a gene. They do not form from multiplying bacteria.", "1": "Okazaki fragments are short DNA pieces made on the lagging strand during replication.", "2": "Sticky ends are short single-stranded overhangs made by restriction enzymes before the vector and gene are joined."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5221' AND answer = 3;
UPDATE questions SET why = 'A radioactive probe is a DNA strand complementary to the gene of interest, so it sticks only to colonies carrying that gene. Photographic film is then laid over the sample. The radioactivity darkens the film at those spots (autoradiography), showing which colonies on the master plate to pick.', wrong = '{"1": "Gel electrophoresis separates DNA fragments by size. It does not show where a probe has bound on a plate of colonies.", "2": "Growing on ampicillin selects bacteria that have taken up a plasmid. It does not show which carry the gene of interest.", "3": "Blue–white screening shows whether a plasmid is recombinant by colour. It does not detect where a radioactive probe has bound."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5222' AND answer = 0;
UPDATE questions SET why = 'Kary Mullis developed the polymerase chain reaction (PCR) in 1983. PCR copies a chosen DNA segment again and again to make millions of copies. For this invention he won the Nobel Prize in Chemistry in 1993, ten years later.', wrong = '{"0": "Mullis''s Nobel Prize was in Chemistry, not Physics, though the year 1993 is correct.", "1": "1983 is the year PCR was developed. The Nobel Prize came ten years later, in 1993.", "3": "The 1968 Nobel Prize in Physiology or Medicine went to Nirenberg, Khorana and Holley for work on the genetic code."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5223' AND answer = 2;
UPDATE questions SET why = 'Each PCR cycle heats the mixture to about 98 °C to separate the DNA strands, which would destroy most enzymes. Taq polymerase comes from Thermus aquaticus, a bacterium of hot springs, and stays stable at these temperatures. So the same enzyme keeps working through every cycle.', wrong = '{"0": "Primers are short DNA sequences that mark where copying starts. They cannot make enzymes.", "2": "Every cycle needs a polymerase to extend the primers. The original Taq enzyme simply survives and keeps working.", "3": "DNA ligase is not used in PCR. Extension in every cycle is done by Taq polymerase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5224' AND answer = 1;
UPDATE questions SET why = 'A genomic library is a collection of the total DNA of a single organism, stored as many cloned fragments. PCR can help build one by making many copies of DNA pieces. Genomic libraries are often used for DNA sequencing.', wrong = '{"1": "A clone library of plasmids only is not the term for an organism''s total DNA. That collection is called a genomic library.", "2": "A restriction site is a short palindromic sequence where a restriction enzyme cuts DNA.", "3": "A karyotype is the complete set of an organism''s chromosomes as seen under a microscope, not a collection of cloned DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5225' AND answer = 0;
UPDATE questions SET why = 'PCR can make millions of copies from a tiny amount of DNA. This lets scientists examine the DNA of extinct species, as long as even a small amount remains. Other uses include diagnosing infections, detecting mutations, DNA fingerprinting and testing early embryos.', wrong = '{"0": "Kidney stones are broken by shockwaves in lithotripsy, not by copying DNA.", "2": "Antibodies are made by plasma cells of the immune system. PCR copies DNA, not proteins.", "3": "Joining the two insulin chains by disulphide bonds is a chemical step after the chains are extracted, not PCR."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5226' AND answer = 1;
UPDATE questions SET why = 'Transgenic organisms carry DNA from a different, unrelated species. Genetically modified crops are now very common: approximately 90% of the canola, cotton, corn, soybean and sugar beet grown in the world are transgenic.', wrong = '{"0": "10% is far too low. About 90% of these crops are transgenic.", "1": "Not every plant of these crops is transgenic, so 100% overstates it. The figure is about 90%.", "3": "50% is too low. Approximately 90% of these crops worldwide are transgenic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5227' AND answer = 2;
UPDATE questions SET why = 'To make a whole multicellular GMO, every cell must carry the new gene. So the gene is put into a gamete or into gamete-producing tissue. When such gametes fuse, the zygote and every cell that grows from it contains the gene of interest.', wrong = '{"0": "A gene added to adult skin cells stays in those cells only. It is not passed to a new whole organism.", "1": "Mature red blood cells have no nucleus and do not divide, so they cannot be used to make a GMO.", "2": "A bacterial plasmid is a vector used to carry genes. It is not the target cell for building a multicellular organism."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5228' AND answer = 3;
UPDATE questions SET why = 'In microinjection, a very fine glass needle is used to inject the gene of interest directly into the nucleus of the target cell, often a fertilised egg. It is a precise, physical method of gene transfer that works one cell at a time.', wrong = '{"0": "Biolistic transformation fires tiny metal particles coated with DNA into cells using a gene gun.", "2": "Protoplast-mediated transfer removes the cell wall and mixes the bare protoplast with the gene.", "3": "Electroporation uses a pulse of electric current to make temporary pores in the membrane so DNA can enter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5229' AND answer = 1;
UPDATE questions SET why = 'Viruses naturally insert their genetic material into host cells, so they can be used to carry genes. In virus-mediated gene transfer, adenovirus, adeno-associated virus, HIV, lentivirus and other retroviruses are modified to deliver a gene of interest into target cells.', wrong = '{"1": "Blue–white screening uses the lacZ′ gene of a plasmid to tell recombinant from non-recombinant colonies.", "2": "Taq polymerase is obtained from the hot-spring bacterium Thermus aquaticus, not from these viruses.", "3": "Cutting DNA at palindromic sites is done by restriction endonucleases, enzymes from bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5230' AND answer = 0;
UPDATE questions SET why = 'Transgenic bacteria carry human genes and make useful human proteins. Erythropoietin, the hormone that stimulates red blood cell production, is made this way to treat anaemia. Others include interferon for some cancers and tissue plasminogen activator to dissolve blood clots.', wrong = '{"0": "Chymosin made by transgenic bacteria clots milk protein in cheese making. It does not treat anaemia.", "1": "Alpha-amylase made by transgenic bacteria turns starch into simple sugars for industry.", "3": "Interferon made by transgenic bacteria is used to treat some cancers, not anaemia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5231' AND answer = 2;
UPDATE questions SET why = 'Transgenic bacteria are also used to make enzymes for the food industry. Pectin-esterase acts on pectin, which makes fruit juice cloudy, and so improves the clarity of fruit juice.', wrong = '{"0": "Dissolving blood clots is the job of tissue plasminogen activator, another product of transgenic bacteria.", "1": "Clotting milk protein for cheese making is done by chymosin.", "2": "Converting starch into simple sugars is done by alpha-amylase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5232' AND answer = 3;
UPDATE questions SET why = 'Some transgenic goats carry the human gene for lysozyme, an enzyme that digests bacterial cell walls. They produce human lysozyme in their milk, which can help fight the bacteria that cause diarrhoea in people who drink it.', wrong = '{"0": "Spider-silk proteins are made by a different group of transgenic goats, not those making lysozyme.", "1": "Reducing the development of Plasmodium is the aim of transgenic malaria-resistant mosquitoes.", "2": "Making milk closer to human breast milk is the goal of transgenic dairy cows."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5233' AND answer = 3;
UPDATE questions SET why = 'Transgenic goats can secrete human proteins in their milk. The first human biological drug made in a transgenic goat was an anticoagulant, a substance that reduces blood clotting. It is used to lower the risk of clots during surgery or childbirth.', wrong = '{"0": "Lysozyme goats, which help fight diarrhoea-causing bacteria, are a separate example, not the first drug.", "2": "Hepatitis B vaccine is produced by genetically modified microbes, not given as the first transgenic goat drug.", "3": "Human insulin is produced by transgenic bacteria such as E. coli, not by goats."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5234' AND answer = 1;
UPDATE questions SET why = 'Since the mid-1980s, transgenic mice have been a key model for studying human diseases. Their genome has been completely sequenced and is very similar to the human genome. Genes can be added or knocked out in mice to see how a disease develops.', wrong = '{"0": "Mice do get diseases. They are useful exactly because diseases can be produced and studied in them.", "1": "Having four chromosomes per set describes the fruit fly Drosophila, not mice.", "3": "Totipotency, the ability of one cell to form a whole organism, is a feature of many plant cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5235' AND answer = 2;
UPDATE questions SET why = 'Glyphosate is a herbicide, a chemical that kills weeds. Many crops have been genetically modified to resist glyphosate, so farmers can spray fields to kill weeds without harming the crop.', wrong = '{"1": "The antibiotic used to select bacteria with plasmids is ampicillin, not glyphosate.", "2": "Beta-carotene is the precursor of vitamin A added to golden rice.", "3": "Insect toxins come from genes of Bacillus thuringiensis (Bt), used for insect resistance, not glyphosate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5236' AND answer = 0;
UPDATE questions SET why = 'Rice was genetically modified to fight nutrient deficiencies. To raise its iron content, genes were taken from beans, the fungus Aspergillus and wild rice. Separately, genes for making beta-carotene, a precursor of vitamin A, were taken from daffodil.', wrong = '{"0": "Daffodil supplied the genes for beta-carotene (vitamin A precursor), not the iron genes.", "2": "Bacillus thuringiensis supplies Bt toxin genes that give crops resistance to insects.", "3": "Thermus aquaticus is a hot-spring bacterium, the source of Taq polymerase used in PCR."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5237' AND answer = 1;
UPDATE questions SET why = 'Genetically modified plants and plant cells can be used as factories for medicines. They produce biopharmaceuticals such as cytokines, hormones, antibodies, enzymes and vaccines. Growing these in plants can be cheaper than other methods.', wrong = '{"0": "Taq polymerase is obtained from the bacterium Thermus aquaticus, not from GMO plants.", "1": "Restriction endonucleases are bacterial enzymes used as tools. They are not the biopharmaceuticals made in plants.", "3": "Crops are modified to resist glyphosate. They do not produce the herbicide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5238' AND answer = 2;
UPDATE questions SET why = 'The first major triumph of genetic engineering was producing human insulin in bacteria. The human insulin gene was inserted into bacteria, which then made the hormone in large amounts for people with diabetes. Before this, insulin came mostly from animals.', wrong = '{"0": "Spider-silk goats are a later example of transgenic animals, not the first major triumph.", "1": "Golden rice, enriched with beta-carotene, is a later example of a transgenic plant.", "2": "Malaria-resistant mosquitoes are a more recent laboratory development, not the first triumph."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5239' AND answer = 3;
UPDATE questions SET why = 'Skin is the largest organ of the vertebrate body. In an adult human it makes up about 15% of the total body weight. It forms part of the first line of defence by acting as a physical barrier to microbes.', wrong = '{"1": "2% is far too small for the body''s largest organ. Skin makes up about 15% of body weight.", "2": "50% is far too large. Skin makes up only about 15% of total body weight.", "3": "20% is too high. About 20% by weight is the share of plasma protein made up of antibodies, not the skin''s share of body weight."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5240' AND answer = 0;
UPDATE questions SET why = 'The stratum corneum is the outer layer of the epidermis, and its cells are constantly damaged and shed. New cells form in the deep epidermis and move upward to replace them. These cells make keratin, a tough protein that keeps microbes out.', wrong = '{"0": "New skin cells form in the deep epidermis, not in the dermis from fat cells.", "2": "Sweat glands secrete sweat, which contains lysozyme. They do not produce new epidermal cells.", "3": "Bone marrow makes blood cells. Skin cells are produced locally in the deep epidermis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5241' AND answer = 1;
UPDATE questions SET why = 'Many bacteria are swallowed with food. Saliva kills many of them with lysozyme, the strong acid in the stomach kills more, and the protein-digesting enzymes in the intestine also kill bacteria. These are part of the first line of defence.', wrong = '{"0": "Histamine is released by damaged tissue to start inflammation. It is not an intestinal secretion that kills bacteria.", "1": "Bile pigments are waste products from broken-down haemoglobin. They are not named as antibacterial defences.", "2": "Insulin is a hormone that lowers blood glucose. It does not kill bacteria in the gut."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5242' AND answer = 3;
UPDATE questions SET why = 'Macrophages develop from monocytes and engulf microbes. Some are fixed in organs such as the lungs, liver, spleen and brain. Most, however, patrol through the blood, lymph and interstitial fluid, searching for invaders to destroy.', wrong = '{"0": "The skin surface is defended by the stratum corneum and its acid secretions, not by macrophages living there.", "1": "Macrophages are large separate cells that develop from monocytes. They are not stored inside red blood cells.", "3": "The thymus is where T lymphocytes mature. Macrophages do not stay permanently there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5243' AND answer = 2;
UPDATE questions SET why = 'The complement system is made of more than a dozen different proteins produced in the liver. They circulate in the blood in an inactive state. When they meet a microbe they become active in sequence, the first activating the second and so on, and the last five form a membrane-attack complex that bursts the microbe.', wrong = '{"1": "Complement proteins circulate in an inactive state and switch on only when they meet a microbe.", "2": "Complement proteins are made in the liver. Antibodies made by plasma cells are a separate group of proteins.", "3": "Proteins released by virus-infected cells are interferons, not complement proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5244' AND answer = 0;
UPDATE questions SET why = 'Interferons are protective proteins released by virus-infected cells. They warn nearby cells to strengthen their antiviral defences. As members of the cytokine family, they also activate other immune cells such as natural killer cells and macrophages.', wrong = '{"0": "The membrane-attack complex is formed by the final proteins of the complement system, not by interferons.", "2": "Digesting bacterial cell walls is the action of the enzyme lysozyme, found in sweat, saliva and tears.", "3": "Antibodies are made by plasma cells formed from B lymphocytes, not by interferons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5245' AND answer = 1;
UPDATE questions SET why = 'During infection, pyrogens make the hypothalamus raise body temperature above the normal 37 °C (98.6 °F), causing fever. A mild fever helps fight microbes, but temperatures above about 39.4 °C (103 °F) are generally considered dangerous, and those above 40.5 °C (105 °F) are often fatal.', wrong = '{"1": "34 °C is below normal body temperature. It is about the temperature at which the scrotum keeps the testes.", "2": "37 °C (98.6 °F) is normal core body temperature, not a dangerous one.", "3": "Above 40.5 °C (105 °F) temperatures are often fatal. The danger level begins lower, at about 39.4 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5246' AND answer = 0;
UPDATE questions SET why = 'Fever is a defence because it slows the reproduction of bacteria and viruses. Some microbes are temperature-sensitive and are killed outright at high fever. Streptococcus pneumoniae and the influenza virus are examples, so a fever can directly help clear them.', wrong = '{"0": "Thermus aquaticus lives in hot springs and tolerates very high temperatures. It is the source of heat-stable Taq polymerase.", "1": "Escherichia coli and Bacillus thuringiensis are bacteria used in biotechnology. They are not named as killed by fever.", "3": "Plasmodium, the malaria parasite, is mentioned in connection with malaria-resistant mosquitoes, not as the fever-sensitive example."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5247' AND answer = 2;
UPDATE questions SET why = 'The first and second lines of defence are non-specific: they act against any invader in the same way. Because this defence is present from birth, it is called inborn or innate immunity. The specific defence of the immune system develops during life and is called acquired immunity.', wrong = '{"0": "Artificial active immunity is gained later in life through vaccination, so it is not present at birth.", "1": "Acquired immunity is the specific defence that develops during growth, the opposite of non-specific defence.", "2": "Passive immunity is a type of acquired immunity in which ready-made antibodies are given. It is short-lived."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5248' AND answer = 3;
UPDATE questions SET why = 'In natural active immunity, the body makes its own antibodies and memory cells after natural exposure to an antigen, for example during an infection. Because the body itself responds fully and keeps memory cells, this is described as the most effective form of immunity.', wrong = '{"0": "Passive immunity uses antibodies given from outside. It is quick but short-lived because no memory cells form.", "2": "Inborn immunity is non-specific and present at birth. It does not target particular microbes or keep a memory.", "3": "Artificial active immunity from vaccines is effective, but natural active immunity is described as the most effective form."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5249' AND answer = 1;
UPDATE questions SET why = 'Both B cells and T cells develop from stem cells in the bone marrow. T cells move to the thymus to mature. B cells, however, stay and complete their maturation in the bone marrow before entering the blood and lymphoid organs.', wrong = '{"1": "The spleen is a lymphoid organ where mature lymphocytes gather. B cells complete maturation in the bone marrow.", "2": "The thymus is where T cells, not B cells, complete their maturation.", "3": "The liver makes complement proteins. It is not where B cells mature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5250' AND answer = 0;
UPDATE questions SET why = 'T cells are of several kinds with different jobs. Helper T cells start the immune response, cytotoxic T cells kill infected cells, and inducer T cells oversee T cell development in the thymus. Suppressor T cells end the immune response once the infection is under control.', wrong = '{"0": "Helper T cells start, or initiate, the immune response by activating other cells. They do not end it.", "1": "Cytotoxic T cells destroy infected and abnormal cells. They carry out the attack rather than stopping it.", "3": "Inducer T cells supervise the development of T cells in the thymus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5251' AND answer = 2;
UPDATE questions SET why = 'Each T cell carries receptors for just one particular antigen. The body makes tens of millions of different T cells, each with its own receptor. With so many types, any antigen an invader carries will be recognised by at least a few T cells.', wrong = '{"0": "T cells do not make antibodies. Antibodies are made by plasma cells, which come from B cells.", "1": "T cells circulate throughout the body. Recognition depends on their huge variety, not on where they are found.", "2": "A single T cell recognises only one particular antigen, not every antigen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5252' AND answer = 3;
UPDATE questions SET why = 'Cell-mediated immunity is carried out by T cells, which attack whole cells rather than free molecules. Cytotoxic T cells kill body cells that are infected by viruses or have become cancerous. This mainly protects the body against virus infections and cancer.', wrong = '{"0": "Bacteria on the skin surface are kept out by the first line of defence, such as the stratum corneum and acid secretions.", "1": "Toxins dissolved in plasma are neutralised by antibodies in antibody-mediated (humoral) immunity, not by T cells.", "2": "Allergic responses to pollen involve E-antibodies binding to mast cells, which release histamine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5253' AND answer = 3;
UPDATE questions SET why = 'After a macrophage engulfs a microbe, it produces special proteins linked to that microbe and displays them. Helper T cells with matching receptors recognise these proteins and become activated. The activated helper T cells then stimulate other T cells and B cells.', wrong = '{"1": "Histamine is released by mast cells and injured cells during inflammation, not as a signal to helper T cells.", "2": "Macrophages develop from monocytes and never become T cells. T cells come from bone marrow stem cells.", "3": "Macrophages do not release antibodies. Antibodies are made by plasma cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5254' AND answer = 0;
UPDATE questions SET why = 'During a cell-mediated response, suppressor T cells multiply more slowly than cytotoxic T cells. After about 1 to 2 weeks their numbers become large enough to block the cytotoxic T cells and shut the response down. Some helper and cytotoxic T cells remain as memory cells.', wrong = '{"0": "1 to 2 days is too early. Suppressor T cells multiply slowly, so it takes about 1 to 2 weeks.", "1": "A few minutes is far too short. Suppressor T cells start in low numbers and grow slowly.", "3": "The response is shut down after weeks, not years. It is the memory cells that persist for years."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5255' AND answer = 2;
UPDATE questions SET why = 'Antibody-mediated immunity uses B cells, which turn into plasma cells that release antibodies into body fluids. Because antibodies act in the blood and lymph, which were once called humours, this is also called humoral immunity.', wrong = '{"0": "Cell-mediated immunity is the other branch, carried out directly by T cells rather than by antibodies.", "2": "The inflammatory response is part of the non-specific second line of defence.", "3": "Innate immunity is the non-specific defence present at birth, not the antibody-based specific defence."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5256' AND answer = 1;
UPDATE questions SET why = 'Killer cells are similar to natural killer cells, which kill cells by puncturing their membranes. The difference is that killer cells have receptors that recognise antigens already coated with antibodies. When a killer cell meets an antibody-coated cell, it binds and kills it.', wrong = '{"0": "Neither killer cells nor natural killer cells make antibodies. Plasma cells make them.", "1": "The membrane-attack complex is formed by the final proteins of the complement system.", "2": "Pyrogens that trigger fever are released by macrophages, not by killer cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5257' AND answer = 3;
UPDATE questions SET why = 'A vaccine contains killed or weakened pathogens, or their parts, that cannot cause the disease. The immune system responds by making antibodies and forming memory cells. If the real pathogen enters later, the memory cells give a fast, strong response. This is artificial active immunity.', wrong = '{"0": "Giving ready-made antibodies is passive immunity, as with antiserum. It gives no memory cells.", "1": "Histamine release from mast cells is part of an allergic or inflammatory response, not how vaccines protect.", "3": "A vaccine trains the immune system against foreign antigens. Attacking self-proteins would be autoimmunity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5258' AND answer = 2;
UPDATE questions SET why = 'An antibody is made of four polypeptide chains joined by disulphide bridges. Each chain has a constant region, which is similar in all antibodies of the same class, and a variable region, which differs between antibodies. The variable regions form the antigen-binding sites.', wrong = '{"1": "The four chains are held together by disulphide bridges. The constant region is defined by its similar sequence, not by joining chains.", "2": "Differing in every antibody describes the variable region, not the constant region.", "3": "The antigen-binding site is formed by the variable regions at the tips of the chains."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5259' AND answer = 0;
UPDATE questions SET why = 'An antigen surface has many different sites, called determinants. When many different antibodies attach to different portions of the same antigen, they are called polyclonal antibodies, since they come from many B cell clones. Antibodies from one clone that bind only one determinant are monoclonal.', wrong = '{"0": "E-antibodies are those made in allergies. They bind to mast cells and cause histamine release.", "2": "G-antibodies are produced during desensitisation treatment for allergies. They destroy the allergen before E-antibodies can act.", "3": "Monoclonal antibodies come from a single clone and attach to only one determinant of the antigen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5260' AND answer = 1;
UPDATE questions SET why = 'Cesar Milstein and George Kohler fused antibody-producing plasma cells with myeloma (cancer) cells to make hybridoma cells. These divide endlessly and release one kind of antibody, a monoclonal antibody. For learning how to produce monoclonal antibodies they shared the 1984 Nobel Prize.', wrong = '{"1": "Interferons were discovered by other scientists. Milstein and Kohler''s prize was for monoclonal antibodies.", "2": "PCR was developed by Kary Mullis, who won the Nobel Prize in Chemistry in 1993.", "3": "The ABO blood groups were discovered by Karl Landsteiner in 1901."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5261' AND answer = 0;
UPDATE questions SET why = 'A monoclonal antibody binds only one specific determinant. Because of this precision, it can pull one particular molecule out of a complex mixture. Interferon, an antiviral protective protein, was purified in this way.', wrong = '{"0": "Keratin is a tough structural protein of the skin. It is not the example of a protein purified by monoclonal antibodies.", "1": "Histamine is a small chemical released by mast cells in inflammation, not a protective protein purified this way.", "3": "Human insulin is produced in transgenic bacteria. It is not the example given for monoclonal antibody purification."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5262' AND answer = 2;
UPDATE questions SET why = 'In an allergy, the body makes E-antibodies against a weak antigen such as pollen. These antibodies attach to mast cells, which usually lie in the connective tissue around blood vessels. When the allergen returns, the mast cells release histamines, which cause the allergic symptoms.', wrong = '{"0": "Mast cells are separate tissue cells. They are never found inside red blood cells.", "2": "The thymus is the organ where T cells mature. Mast cells are not found only there.", "3": "The stratum corneum is the outer layer of dead skin cells, not where mast cells are usually found."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5263' AND answer = 1;
UPDATE questions SET why = 'Allergy symptoms such as sneezing, runny nose and itching are caused by histamines released from mast cells. Antihistamine drugs block the action of histamines, so the symptoms ease. The relief is temporary because the underlying allergy remains.', wrong = '{"0": "E-antibodies cause the allergic reaction by binding mast cells, so stimulating them would make the allergy worse.", "1": "Activated mast cells release histamines, so activating them would increase symptoms.", "2": "More histamine would worsen sneezing, itching and swelling, not relieve them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5264' AND answer = 3;
UPDATE questions SET why = 'In autoimmune diseases, the immune system cannot tell self from foreign and attacks body tissues. In systemic lupus erythematosus (SLE), the patient forms antibodies against their own connective tissues and major organs, so many parts of the body are affected.', wrong = '{"0": "In type I diabetes, antibodies destroy only the insulin-producing cells of the pancreas.", "1": "In myasthenia gravis, antibodies attack acetylcholine receptors on skeletal muscle, causing muscle weakness.", "3": "In rheumatoid arthritis, antibodies attack mainly the cartilage of the joints."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5265' AND answer = 2;
UPDATE questions SET why = 'Rheumatoid arthritis is an autoimmune disease. The patient''s immune system forms antibodies against the cartilaginous tissue of the joints. These antibodies damage the cartilage, causing painful, swollen and stiff joints.', wrong = '{"0": "Antibodies against insulin-producing cells in the pancreas cause type I diabetes.", "2": "Antibodies against acetylcholine receptors on skeletal muscle cause myasthenia gravis.", "3": "Antibodies against red cells of an Rh-positive foetus cause erythroblastosis foetalis, which is not autoimmune."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5266' AND answer = 1;
UPDATE questions SET why = 'Transplant success depends on matching the self-proteins on cells, the molecular fingerprints recognised by T and B cells. Identical twins match 100%, and the best matches are within a family. The chance that an unrelated donor matches is only about 1 in 100,000 to 200,000.', wrong = '{"1": "1 in 4 is a typical Mendelian probability, such as the chance of a recessive child from two carriers, not a donor match figure.", "2": "A 100% match occurs only between identical twins, not with an unrelated donor.", "3": "About 1 in 750 is the frequency of Down syndrome among children."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5267' AND answer = 0;
UPDATE questions SET why = 'There are two approaches to preventing transplant rejection. One uses monoclonal antibodies to target the T cells that attack the new organ. The other uses stem cells to build a new immune system that recognises the transplanted organ as self, so it does not attack it.', wrong = '{"0": "Strengthening the recipient''s immune system would make it attack the foreign organ more strongly.", "1": "Antihistamines block histamine to relieve allergies. They do not stop T cells attacking a transplant.", "2": "Rh-antiserum is given to Rh-negative mothers to prevent Rh sensitisation. It has no role in transplants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5268' AND answer = 3;
UPDATE questions SET why = 'Data can be collected in two ways. Secondary data collection uses data that already exist, such as published research, medical records, government reports and databases. Primary data are collected directly by the researcher.', wrong = '{"0": "Primary data are gathered directly by the researcher through experiments, surveys, interviews, observations or clinical trials.", "1": "Inferential statistics is a type of analysis for drawing conclusions about populations. It is not a way of collecting data.", "2": "Data cleaning is part of data management, done after collection to remove errors."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5269' AND answer = 3;
UPDATE questions SET why = 'Inferential statistics use data from a sample to draw conclusions about the whole population. Methods include hypothesis testing, regression analysis and modelling. Descriptive statistics, in contrast, only summarise the data already collected.', wrong = '{"0": "Study design is the planning stage: choosing the question, sampling method, variables, randomisation and sample size.", "2": "Data collection is gathering data, which comes before any analysis such as regression.", "3": "Descriptive statistics, such as mean, median, mode and standard deviation, summarise data without generalising to a population."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5270' AND answer = 1;
UPDATE questions SET why = 'Interpretation of results turns statistical findings into biological or health conclusions. At this stage it is important to consider the context, limitations and assumptions of the analysis, so that conclusions are not overstated.', wrong = '{"1": "Data collection is about gathering accurate and relevant primary or secondary data.", "2": "Data management covers cleaning, coding and storing data while keeping it confidential.", "3": "Presentation and communication covers charts, graphs and clear reporting for different audiences."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5271' AND answer = 0;
UPDATE questions SET why = 'The presentation and communication stage shares results through charts, graphs and clear language suited to the audience. Reporting the methods and findings openly (transparency) lets other researchers repeat the work and check it. This is essential for reproducibility and for trust in the results.', wrong = '{"0": "Confounding factors are controlled when the study is designed, not by how openly the results are reported.", "1": "Sample size is decided during study design. Transparent reporting does not change it.", "3": "How results are reported has no effect on whether the data follow a normal distribution."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5272' AND answer = 2;
UPDATE questions SET why = 'Bioinformatics deals with huge biological datasets from genomics (all of an organism''s genes) and proteomics (all its proteins). Biostatistics supports this field by developing algorithms and models to interpret the data, which helps in drug discovery, diagnosis and personalised therapy.', wrong = '{"1": "Demography studies population trends such as births, deaths and other vital statistics, not genomic datasets.", "2": "Environmental health studies how pollution and toxins affect human health.", "3": "Healthcare quality control monitors diagnostic test accuracy, patient outcomes and consistency of medical procedures."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5273' AND answer = 0;
UPDATE questions SET why = 'Healthcare quality control uses biostatistics to monitor and improve health services. Providers apply statistical tools to evaluate how accurate diagnostic tests are, track patient outcomes and make sure medical procedures are carried out consistently.', wrong = '{"0": "Epidemiology studies how diseases are distributed in populations and what causes them to spread.", "1": "Bioinformatics analyses very large genomic and proteomic datasets using algorithms and models.", "3": "Environmental health studies the effects of pollution and toxins on human health."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5274' AND answer = 2;
UPDATE questions SET why = 'Biostatistics is used to evaluate how well health programs and population-wide interventions work. Examples include measuring the impact of immunisation campaigns, health education and training for health workers. The results help officials decide where to spend resources.', wrong = '{"0": "Tailoring treatment to a person''s genes is personalised medicine, an application in genetics and genomics.", "1": "Analysing genomic data belongs to genetics, genomics and bioinformatics.", "2": "Assessing pollution exposure is an application in environmental health."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5275' AND answer = 3;
UPDATE questions SET why = 'The mean is the sum of all values divided by the number of values. Here the sum is 1.8 + 2.2 + 2.0 + 2.4 = 8.4 kg, and there are 4 rabbits. Mean = 8.4 ÷ 4 = 2.1 kg.', wrong = '{"0": "8.4 kg is only the sum of the four weights. It still has to be divided by 4.", "2": "2.0 kg is one of the individual weights, not the average of all four.", "3": "2.2 kg is another single weight. The average of the four is 8.4 ÷ 4 = 2.1 kg."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5276' AND answer = 1;
UPDATE questions SET why = 'For grouped data, use each class midpoint (x) and multiply by its frequency (f). Midpoints are 10, 30 and 50 cm, so Σfx = 3 × 10 + 5 × 30 + 2 × 50 = 30 + 150 + 100 = 280. Total frequency Σf = 3 + 5 + 2 = 10. Mean = 280 ÷ 10 = 28 cm.', wrong = '{"1": "93.3 cm comes from dividing 280 by 3, the number of classes. The divisor must be the total frequency, 10.", "2": "30 cm is the midpoint of the most frequent class. The mean must weight every class by its frequency.", "3": "56 cm comes from dividing 280 by 5, the largest frequency, instead of by the total frequency, 10."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5277' AND answer = 0;
UPDATE questions SET why = 'To find the median, first arrange the data in order: 4, 6, 7, 9, 10, 12, 15. There are 7 values, an odd number, so the median is the value at position (n + 1)/2 = (7 + 1)/2 = 4. The 4th value is 9 cm.', wrong = '{"0": "15 cm is the largest value, the maximum. The median is the middle value once the data are ordered.", "1": "7 cm is the 3rd value in the ordered list, one place before the middle. It is also the 4th value in the unordered list, a common slip.", "3": "10 cm is the 5th ordered value, one place past the middle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5278' AND answer = 2;
UPDATE questions SET why = 'In the grouped mode formula, fm is the frequency of the modal class, f1 the frequency of the class before it, and f2 the frequency of the class after it. The modal class has the highest frequency, 30–40 (f = 18). The class after it is 40–50, so f2 = 10.', wrong = '{"0": "3 is the frequency of the last class, 50–60. It is not next to the modal class.", "2": "18 is fm, the frequency of the modal class itself.", "3": "12 is f1, the frequency of the class just before the modal class."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5279' AND answer = 1;
UPDATE questions SET why = 'The modal class is 10–15, with the highest frequency. So l = 10, fm = 15, f1 = 9, f2 = 6 and h = 5. Mode = 10 + [(15 − 9)/((15 − 9) + (15 − 6))] × 5 = 10 + (6/15) × 5 = 10 + 2 = 12.0.', wrong = '{"0": "12.5 is the midpoint of the modal class. The formula moves the mode toward the bigger neighbouring class, giving 12.0.", "1": "13.0 comes from using 9/15 instead of 6/15: 10 + (9/15) × 5 = 13. The numerator must be fm − f1 = 6.", "2": "10.0 is only the lower boundary l, before the correction term of 2 is added."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5280' AND answer = 3;
UPDATE questions SET why = 'Standard deviation measures how spread out data are around the mean. A tall, narrow bell curve means most values lie close to the mean, so the standard deviation is low. A flatter, wider curve means values are more spread out, giving a higher standard deviation.', wrong = '{"0": "Every bell-shaped curve has a mean, which lies at the centre of its peak.", "1": "A higher standard deviation produces a wider, flatter curve, not a tall, narrow one.", "3": "A narrow curve means values lie close together, so the spread, including the range, is smaller."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5281' AND answer = 2;
UPDATE questions SET why = 'The variance is the mean of the squared deviations: Σ(x − µ)²/N = 80 ÷ 5 = 16 cm². The standard deviation is the square root of the variance: √16 = 4 cm.', wrong = '{"0": "2 cm is √4. The variance here is 16 cm², so the standard deviation is √16 = 4 cm.", "2": "16 is the variance, in cm². The standard deviation is its square root, 4 cm.", "3": "About 8.9 cm is √80. The sum of squares must first be divided by N = 5 before taking the root."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5282' AND answer = 1;
UPDATE questions SET why = 'Standard deviation measures spread around the mean, so the mean is needed first. The steps are: find the mean, subtract it from each value, square these deviations, average the squares to get the variance, and finally take the square root.', wrong = '{"1": "Arranging the data and picking the middle value finds the median, not the standard deviation.", "2": "A square root is taken only at the very end, of the variance, not of each original value.", "3": "The largest and smallest values give the range, a different and simpler measure of spread."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5283' AND answer = 0;
UPDATE questions SET why = 'The range is the difference between the largest and smallest values, so it shows how spread out the data are. Group P has a range of only 4 g, while group Q has 15 g. So the weights in group P are more closely clustered together.', wrong = '{"0": "The range measures spread, not the average. It gives no information about which group has the higher mean.", "1": "The range depends only on the two extreme values, not on how many mice are in the group.", "2": "Group Q''s wider range points to greater spread, which usually means a larger standard deviation, not a smaller one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5284' AND answer = 3;
UPDATE questions SET why = 'Rank R = (P/100)(n + 1) = (60/100) × 11 = 6.6. The 6th value is 172 cm and the 7th is 175 cm. Interpolating 0.6 of the way between them: 172 + 0.6 × (175 − 172) = 172 + 1.8 = 173.8 cm.', wrong = '{"0": "170 cm is the 5th value, which is below the rank of 6.6.", "1": "175 cm is the 7th value. The rank 6.6 lies between the 6th and 7th values, not at the 7th.", "3": "172 cm is only the 6th value. The fractional part, 0.6, still has to be added by interpolation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5285' AND answer = 2;
UPDATE questions SET why = 'A bar chart shows categorical data, such as species or groups, using bars of equal width. The length of each bar is proportional to its value. The bars can be drawn either vertically or horizontally.', wrong = '{"1": "A total of 360° describes a pie chart, where each sector''s angle shows its share of the whole.", "2": "Bars in a bar chart have equal widths. It is their length or height that shows the value.", "3": "A bar chart is used for categorical data. Continuous data such as time are better shown with a line graph."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5286' AND answer = 0;
UPDATE questions SET why = 'The y-axis should start at 0 and go slightly above the largest value so that every bar fits. Increments such as 10 or 20 make the scale easy to read. With a maximum of 120 ants, a scale from 0 to 140 in steps of 20 fits the data and stays readable.', wrong = '{"0": "A scale must show values accurately. Choosing it to make a bar look smaller would distort the data.", "2": "The species are the categories and go on the x-axis. The y-axis shows the counts.", "3": "Angles that add up to 360° belong to pie charts, not to the y-axis of a bar chart."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5287' AND answer = 1;
UPDATE questions SET why = 'In a pie chart, each sector angle = (category value ÷ total) × 360°. For blood group AB: (25 ÷ 200) × 360° = 0.125 × 360° = 45°.', wrong = '{"0": "12.5 is the percentage of patients with group AB (12.5%), not the angle in degrees.", "1": "25 is the number of AB patients. It must be converted into a share of 360°.", "2": "90° is a quarter of the circle, which would mean 50 of the 200 patients, not 25."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5288' AND answer = 3;
UPDATE questions SET why = 'In an x-axis data figure the independent variable, temperature, is on the x-axis and the measured activity is on the y-axis. The highest activity, 7 µmol/min, was recorded at 20 °C. Activity rose up to this peak and then fell at higher temperatures.', wrong = '{"0": "At 5 °C the activity was only 2 µmol/min, the lowest of all readings.", "2": "At 40 °C the activity had fallen to 3 µmol/min.", "3": "At 30 °C the activity was 5 µmol/min, lower than the 7 µmol/min at 20 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5289' AND answer = 1;
UPDATE questions SET why = 'The x-axis always runs horizontally. It usually starts at the origin (0, 0) and extends in the positive direction, but it can include negative values when the data need it. It most often shows the independent variable.', wrong = '{"0": "The x-axis usually shows the independent variable. The dependent variable is normally on the y-axis.", "1": "The vertical axis is the y-axis. The x-axis is horizontal.", "2": "The x-axis often starts at zero, at the origin (0, 0)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5290' AND answer = 3;
UPDATE questions SET why = 'Error bars show the spread of data around each bar, using either the range or the standard deviation. When drawing a vertical error bar, a short horizontal cap is added at each end so the limits of the bar are clear.', wrong = '{"1": "A legend explains the colours or patterns used in a chart. It is not part of drawing an error bar.", "2": "Error bars are drawn on the bars of the same chart. A separate pie chart is not needed.", "3": "Joining points with a line is done in x-axis data figures to show a trend, not for error bars."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5291' AND answer = 0;
UPDATE questions SET why = 'The range bar runs from the smallest to the largest value, 14 to 16 cm. The mean is (14 + 15 + 16) ÷ 3 = 15 cm, and the standard deviation is just under 1 cm, so the ±1 SD bar also runs from about 14 to 16 cm. In this small data set the two bars nearly coincide.', wrong = '{"0": "A range bar runs from the minimum to the maximum value, not from 0. An SD bar extends both above and below the mean.", "1": "12 to 18 cm would be ±3 cm. The values differ from the mean by only 1 cm, so the SD is about 1 cm, not 3.", "3": "A range bar must start at the minimum, 14 cm, and 13 to 17 cm would be ±2 cm, which is too wide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5292' AND answer = 2;
UPDATE questions SET why = 'To make a fair test, the mice are first selected so that they are matched by age, strain and sex. These are control variables. The mice are then randomly assigned to the diet groups, so that diet is the only difference between groups.', wrong = '{"0": "Diet is the independent variable. It is assigned at random after the mice have been matched and selected.", "1": "Weight gain is the dependent variable, measured at the end. It cannot be used to select the mice.", "2": "Weekly food preference is not used to match the mice. They are matched by age, strain and sex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5293' AND answer = 3;
UPDATE questions SET why = 'In experimental design, after researching the topic, the scientist forms a hypothesis. A hypothesis is a statement of what is expected to happen, based on existing knowledge. The experiment then tests it, and the results either support or reject it.', wrong = '{"0": "The factor measured in an experiment is the dependent variable, such as weight gain.", "1": "The group that receives no treatment is the control group, used for comparison.", "3": "The final conclusion comes at the end, when the hypothesis is accepted or rejected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5294' AND answer = 2;
UPDATE questions SET why = 'Control variables are all the factors kept the same for every group, such as cage, light, temperature and humidity. Keeping them constant means only the diet differs. Any difference in weight gain can then be put down to diet, which makes the test fair.', wrong = '{"1": "The dependent variable is weight gain, which is measured. Housing conditions are kept constant, not measured.", "2": "Identical housing applies to all groups, so it does not create an extra experimental group.", "3": "The independent variable is the type of diet. Housing is kept the same on purpose, not changed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5295' AND answer = 0;
UPDATE questions SET why = 'Drugs are chemical substances used to diagnose, prevent or treat diseases. They can come from natural sources, such as plants or microbes, or be made in laboratories. Pharmacology is the science of how drugs act in the body.', wrong = '{"0": "Killing bacteria describes antibiotics, which are only one group of drugs among many.", "2": "Producing energy in cells is the job of cellular respiration, not of drugs.", "3": "Replacing missing vitamins is one narrow use. Drugs are used much more widely to diagnose, prevent and treat disease."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5296' AND answer = 1;
UPDATE questions SET why = 'Drugs can come from natural sources, namely plants, animals and microorganisms, or they can be synthesised in laboratories. For example, penicillin comes from a fungus, while sulfonamides and fluoroquinolones are synthetic. Medicines made from plants are called herbal medicines.', wrong = '{"1": "Not all drugs are made in laboratories. Many are natural, such as penicillin from Penicillium fungi.", "2": "Microorganisms are only one source. Plants, animals and laboratory synthesis also supply drugs.", "3": "Plants are only one source. Animals, microorganisms and laboratory synthesis also supply drugs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5297' AND answer = 0;
UPDATE questions SET why = 'Drug discovery begins with target identification. Scientists look for a specific molecule, such as a protein or enzyme, that is involved in causing the disease and can be affected by a drug. Later stages then validate this target and find compounds that act on it.', wrong = '{"0": "Healthy volunteers take part in Phase 1 clinical trials, which come much later during drug development.", "2": "Watching for rare side effects after the drug is on sale is post-marketing surveillance, the final stage.", "3": "Screening thousands of compounds that bind the target is lead compound identification, a later step."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5298' AND answer = 1;
UPDATE questions SET why = 'After clinical trials, all the trial data are sent to regulatory agencies, such as the FDA in the USA or the EMA in Europe. These agencies examine the evidence on safety and effectiveness and decide whether to approve or reject the drug before it can be marketed.', wrong = '{"0": "The scientists who found the lead compound cannot approve their own drug. Approval is a regulatory decision.", "1": "Patients in trials provide data, but they do not decide whether a drug is approved.", "3": "Bacteria may be the target of a drug, but they obviously cannot review data or approve medicines."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5299' AND answer = 2;
UPDATE questions SET why = 'A new drug is first tested on cells and animals in preclinical research. It then goes through clinical trials in humans. Regulators review the trial data, after which the drug is manufactured and marketed. Post-marketing surveillance then watches for problems once it is in wide use.', wrong = '{"0": "Preclinical testing on cells and animals must come before any human clinical trials, not after them.", "1": "Regulators review the data produced by clinical trials, so the trials must come before the review.", "2": "Surveillance happens after the drug is released, so it cannot come before review and marketing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5300' AND answer = 3;
UPDATE questions SET why = 'Penicillin is a group of bactericidal antibiotics obtained from Penicillium fungi. Alexander Fleming discovered it in 1928. It kills bacteria by stopping them from building their cell walls.', wrong = '{"0": "Sulfanilamide is the parent compound of the synthetic sulfonamide drugs, not of penicillin.", "2": "Streptomyces, a soil bacterium, is the source of tetracycline, not penicillin.", "3": "Cinchona bark is the source of quinine, which is linked to chloroquine and the fluoroquinolones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5301' AND answer = 1;
UPDATE questions SET why = 'Penicillin is usually well tolerated. Its common side effects are nausea, vomiting, diarrhoea, abdominal pain and skin rashes. Rashes can also be a sign of penicillin allergy.', wrong = '{"1": "Peripheral neuropathy is listed among the rare but serious adverse effects of fluoroquinolones.", "2": "Tendon rupture is a rare adverse effect of fluoroquinolones, not penicillin.", "3": "Kidney damage is listed as a side effect of sulfonamides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5302' AND answer = 0;
UPDATE questions SET why = 'Tetracycline should not be taken with dairy products or iron supplements. The calcium in dairy and the iron in supplements bind to the drug in the gut and reduce how much is absorbed, so the antibiotic works less well.', wrong = '{"0": "No restriction is given for bread. It does not contain the calcium or iron that binds tetracycline.", "1": "No restriction is given for fruit when taking tetracycline.", "3": "Tetracycline is an oral antibiotic that is normally swallowed with water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5303' AND answer = 2;
UPDATE questions SET why = 'Tetracycline comes from Streptomyces bacteria and is a bacteriostatic oral antibiotic, meaning it stops bacteria from multiplying. It blocks bacterial protein synthesis at the 30S ribosomal subunit. It is used for bacterial infections such as chlamydia and syphilis.', wrong = '{"0": "HIV is a retrovirus and is treated with antiretroviral drugs. Antibiotics do not act on viruses.", "1": "Influenza and herpes are viral infections, treated with antiviral drugs rather than antibiotics.", "2": "Tetracycline is an antibacterial drug. Fungal skin infections need antifungal drugs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5304' AND answer = 3;
UPDATE questions SET why = 'Fluoroquinolones are synthetic antibacterial drugs. They arose as a by-product of the synthesis of chloroquine, which is itself made by modifying quinine, a natural compound from the bark of the Cinchona tree. George Lesher discovered them in 1962.', wrong = '{"0": "Sulfanilamide is the parent compound of the sulfonamides, a different class of synthetic drugs.", "1": "Penicillin is a natural antibiotic from Penicillium fungi, not the parent of fluoroquinolones.", "3": "Tetracycline comes from Streptomyces soil bacteria and is not linked to fluoroquinolone synthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5305' AND answer = 2;
UPDATE questions SET why = 'Fluoroquinolones block bacterial type II topoisomerases, enzymes needed for DNA replication. In Gram-positive bacteria their main target is topoisomerase IV, and blocking it stops the replicated DNA molecules from separating. In Gram-negative bacteria the main target is DNA gyrase.', wrong = '{"0": "DNA gyrase, which uncoils DNA during replication, is the main target in Gram-negative bacteria.", "1": "Blocking the enzyme that makes folate is how sulfonamides work.", "2": "Binding the 30S ribosomal subunit is how tetracycline stops protein synthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5306' AND answer = 3;
UPDATE questions SET why = 'Fluoroquinolones were discovered by George Lesher in 1962, as a by-product of making chloroquine. They are bactericidal and kill bacteria by interfering with DNA replication.', wrong = '{"0": "Gerhard Domagk discovered the antibacterial sulfonamides, based on sulfanilamide, in 1932.", "2": "Alexander Fleming discovered penicillin in 1928.", "3": "Louis Pasteur is known for germ theory and vaccines, such as rabies in 1885, not for fluoroquinolones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5307' AND answer = 1;
UPDATE questions SET why = 'Bacteria must make their own folate (folic acid), using para-aminobenzoic acid (PABA). Sulfonamides resemble PABA and bind the enzyme that makes folate, so they act as competitive inhibitors. Without folate the bacteria cannot make DNA and stop growing.', wrong = '{"1": "Trapping type II topoisomerases to cause DNA breaks is how fluoroquinolones act.", "2": "Blocking the 30S ribosomal subunit is how tetracycline stops protein synthesis.", "3": "Enzymes that break the beta-lactam ring are beta-lactamases, which bacteria use to resist penicillin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5308' AND answer = 0;
UPDATE questions SET why = 'A bacteriostatic drug stops bacteria from growing and multiplying, but does not kill them directly. Sulfonamides work this way by starving bacteria of folate. With the bacteria held in check, the body''s immune system can then destroy them.', wrong = '{"0": "Beta-lactamases are bacterial enzymes that destroy penicillin. They do not remove bacteria.", "2": "Double-strand DNA breaks are caused by fluoroquinolones, which are bactericidal.", "3": "Lysing bacteria by damaging the cell wall is how penicillin kills. Sulfonamides do not lyse cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5309' AND answer = 1;
UPDATE questions SET why = 'Sulfonamides are synthetic antibacterial drugs that block folate synthesis. They are used mainly for urinary tract infections and skin infections, and also for acne and respiratory infections. They are often combined with trimethoprim for a stronger effect.', wrong = '{"1": "HIV is a retrovirus, treated with antiretroviral drugs, not antibacterial sulfonamides.", "2": "Cancer is treated with other approaches, such as monoclonal antibodies, not sulfonamides.", "3": "Viral hepatitis is caused by viruses, so it needs antiviral drugs rather than antibacterials."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5310' AND answer = 0;
UPDATE questions SET why = 'Antiviral drugs treat viral infections by preventing viruses from growing and multiplying inside the body. They can combat a wide range of viruses, including the hepatitis, influenza and herpes viruses. Antiretrovirals are a subgroup used against retroviruses such as HIV.', wrong = '{"0": "Gram-positive bacteria are treated with antibiotics such as penicillin, not antivirals.", "1": "HIV is treated by antiretrovirals, a subgroup of antivirals. Antivirals as a whole act on many viruses.", "2": "Penicillium is the fungus that produces penicillin. It is not a disease that antivirals treat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5311' AND answer = 3;
UPDATE questions SET why = 'Monoclonal antibodies are made to bind one specific antigen. This precision lets them target particular cells or molecules, so they are effective in treating cancer, autoimmune disorders and infectious diseases.', wrong = '{"0": "Chromosomal disorders, such as Down syndrome, are not treated with monoclonal antibodies.", "1": "Vitamin deficiencies are treated by supplying the missing vitamin, not by antibodies.", "3": "Monoclonal antibodies bind specific antigens. They do not act on bacterial cell walls the way penicillin does."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5312' AND answer = 2;
UPDATE questions SET why = 'Monoclonal antibodies bind one specific target, so they act precisely. Their listed advantages include lower toxicity, fewer side effects, high specificity, targeted cancer therapy, easy preparation for research and a reduced risk of drug interactions.', wrong = '{"0": "Monoclonal antibodies have fewer side effects than conventional chemotherapy, not more.", "1": "Avoiding dairy is advice for tetracycline. It has nothing to do with monoclonal antibodies.", "2": "Monoclonal antibodies are highly specific and bind a single target, not every antigen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5313' AND answer = 3;
UPDATE questions SET why = 'Personalised medicine means choosing treatment to fit each patient. Because monoclonal antibodies can be made against a specific antigen found in a particular patient''s disease, they allow treatment to be tailored to that individual''s profile.', wrong = '{"0": "Tailoring treatment depends on first diagnosing the patient, so monoclonal antibodies do not replace diagnosis.", "2": "Their value lies in specificity. They are chosen to suit the patient and disease, not used the same way for everyone.", "3": "Monoclonal antibodies are produced in the laboratory from hybridoma cells, not made by the patient after vaccination."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5314' AND answer = 1;
UPDATE questions SET why = 'Early people believed that living creatures could arise directly from non-living matter, for example maggots from rotting meat. This idea was called spontaneous generation. Later experiments disproved it, though they could not rule out creationism.', wrong = '{"0": "Creationism is the belief that each kind of organism was created in its present form.", "1": "Endosymbiosis explains how mitochondria and chloroplasts arose from engulfed prokaryotes.", "3": "Natural selection is Darwin''s mechanism, in which organisms with helpful inherited traits survive and reproduce more."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5315' AND answer = 2;
UPDATE questions SET why = 'The earliest ideas of evolution held that the universe and organisms did not always exist in their present form and were not created all at once. Today''s organisms were seen as the result of innumerable changes from lower to higher forms.', wrong = '{"1": "Inheritance of acquired characters was Lamarck''s later explanation of how evolution works, not one of the basic early speculations.", "2": "Mitochondria arising from engulfed bacteria is the endosymbiotic theory, proposed much later.", "3": "Creation of all organisms at once in their present form is the creationist view that early evolutionary ideas rejected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5316' AND answer = 0;
UPDATE questions SET why = 'On the voyage of the Beagle, Darwin found rocks containing fossils of gigantic extinct mammals. These showed that organisms living in the past looked very different from those living now. This suggested to him that living things change over time.', wrong = '{"1": "Fossils of extinct mammals say nothing about species being created on the Galápagos.", "2": "The fossils were of extinct mammals, which shows that species do become extinct.", "3": "Inheritance of acquired characters was Lamarck''s idea. Darwin did not draw it from these fossils."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5317' AND answer = 0;
UPDATE questions SET why = 'Darwin visited the Galápagos Islands, described as a group of 16 small islands in the Pacific Ocean off South America. He noticed that plants and animals differed from island to island, such as tortoise shell shapes and finch beaks, and that they resembled South American species.', wrong = '{"0": "The Galápagos are a group of islands. Darwin compared tortoises and finches between different islands.", "1": "The Galápagos are small oceanic islands, not continents.", "2": "The islands lie in the Pacific near South America, not near Australia, and are described as 16 islands, not 90."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5318' AND answer = 3;
UPDATE questions SET why = 'Darwin linked the origin of new species with adaptation. When a population is separated from its original habitat, it gradually accumulates adaptations to its new environment. Over many generations the two populations become so different that they are separate species, as with the Galápagos finches.', wrong = '{"0": "Stretching organs during life and passing the change on is Lamarck''s idea of use and disuse.", "1": "Creation in a new habitat in present form is creationism, not Darwin''s explanation.", "3": "Darwin described populations dividing and diverging into new species, not two species merging into one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5319' AND answer = 2;
UPDATE questions SET why = 'Alfred Russel Wallace had independently reached a theory of natural selection very similar to Darwin''s. When their ideas were presented together to the Linnaean Society in 1858, Wallace agreed to give credit for the theory to Darwin and urged him to publish On the Origin of Species, which appeared in 1859.', wrong = '{"0": "Inheritance of acquired characters was proposed by Lamarck in 1809, not by Wallace.", "2": "Wallace did not reject evolution. He had proposed natural selection himself.", "3": "Wallace did not claim sole credit. He agreed that the theory should be attributed to Darwin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5320' AND answer = 1;
UPDATE questions SET why = 'In Darwin''s theory, variation among individuals is the raw material for natural selection. Variations that arise by random mutation can be advantageous, harmful or neutral. A neutral variation neither helps nor harms the organism''s survival or reproduction.', wrong = '{"0": "Vestigial describes structures that have lost most or all of their original function, such as the human appendix.", "2": "Adaptive traits help an organism survive and reproduce, so they are helpful, not neutral.", "3": "Acquired characters are changes gained during life through use or disuse, as in Lamarck''s idea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5321' AND answer = 1;
UPDATE questions SET why = 'Darwin noted that organisms produce far more offspring than the available food, space and other resources can support. Because resources are limited, individuals must compete, or struggle, to survive. Those with helpful variations are more likely to survive and reproduce.', wrong = '{"1": "Mutations do occur and are the source of new variation. Their absence is not why individuals struggle.", "2": "The idea that use or disuse changes organs belongs to Lamarck, and it does not say organs weaken with use. It is not the cause of the struggle.", "3": "Darwin stressed that no two individuals are exactly alike. This variation is what natural selection acts on."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5322' AND answer = 0;
UPDATE questions SET why = 'Genotype frequency is the proportion of individuals in a population that have a particular genotype. Here, 40 of the 100 plants are RR, so the genotype frequency of RR = 40 ÷ 100 = 0.4, or 40%.', wrong = '{"0": "0.8 comes from counting the two R alleles in each RR plant (80) and dividing by 100 plants. Genotype frequency counts individuals, not alleles.", "1": "0.16 is 0.4 squared. Squaring is used to find a genotype frequency from an allele frequency, not here.", "2": "0.6 is the proportion of plants that are not RR (60 out of 100)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5323' AND answer = 3;
UPDATE questions SET why = 'The Hardy-Weinberg theorem says allele and genotype frequencies stay constant if no evolutionary forces act. Its conditions are a large population, random mating, no migration, no mutation (or mutational equilibrium) and an equal chance of survival and reproduction for all genotypes.', wrong = '{"0": "Mating must be random. Choosing mates with similar traits is non-random mating, which changes genotype frequencies.", "1": "The population must be large. In small populations chance events cause genetic drift.", "3": "There must be no migration. Movement in or out causes gene flow, which changes allele frequencies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5324' AND answer = 2;
UPDATE questions SET why = 'Mutation pressure is a measure of the tendency for gene frequencies in a population to change because of mutation. It is the opposite of mutational equilibrium, in which forward and back mutations balance and frequencies stay the same.', wrong = '{"0": "Gene flow is the change in gene frequencies caused by individuals migrating into or out of a population.", "1": "Mutational equilibrium is when mutations in both directions balance, so frequencies do not change at all.", "3": "Genetic drift is a change in gene frequencies by chance events, most obvious in small populations."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5325' AND answer = 2;
UPDATE questions SET why = 'Mutations are random changes in DNA, so most of them disrupt a working gene and are deleterious (harmful). A few are neutral, and some may be harmful in one environment but helpful in another. Mutations are still important as the source of all new genes.', wrong = '{"0": "Some mutations are neutral, but most are deleterious, so they are not always neutral.", "1": "Use and disuse of organs is Lamarck''s idea. It does not cause mutations in DNA.", "2": "Only a few mutations are helpful, and usually only in a particular environment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5326' AND answer = 3;
UPDATE questions SET why = 'Genetic drift is a change in gene frequencies caused by chance events rather than fitness. In a small population, the loss of just a few individuals by chance can change gene frequencies a lot. So drift is most obvious in small populations, for example after a fire reduces 100 rabbits to 10.', wrong = '{"0": "Heavy immigration causes gene flow, which is a different factor from genetic drift.", "2": "Drift can happen in any population. It depends on population size, not on whether the organisms are prokaryotes.", "3": "Very large, randomly mating populations are least affected by chance and tend to stay near Hardy-Weinberg equilibrium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5327' AND answer = 1;
UPDATE questions SET why = 'Biogeography studies how living things are distributed across the world. Australia and Tasmania have been cut off by ocean barriers for a very long time. Their animals, such as kangaroos, evolved separately and so are very different from animals elsewhere, even in similar environments.', wrong = '{"1": "Separate creation of species on each continent is creationism, not a biogeographic explanation.", "2": "Inheritance of characters acquired by use is Lamarck''s idea, which has been disproved.", "3": "Convergent evolution makes unrelated organisms look similar. Here the animals are very different, which separation explains."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5328' AND answer = 0;
UPDATE questions SET why = 'The forelimbs of bats, whales, horses and lizards have the same basic arrangement of bones but are used for flying, swimming, running and climbing. Structures that are similar in structure but differ in function are homologous. They show divergent evolution from a common ancestor.', wrong = '{"0": "Analogous organs have a similar function but different structure, like bird and insect wings. These limbs share structure, not function.", "2": "Genetic drift is a chance change in gene frequencies, not a shared pattern of bones.", "3": "Vestigial organs have lost their use. These forelimbs are fully working organs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5329' AND answer = 1;
UPDATE questions SET why = 'Bird and insect wings are analogous: both are used for flight, but they have different structures and come from different ancestors. Their similarity simply reflects that any flying animal needs a broad, flat surface to glide on the air. This is an example of convergent evolution.', wrong = '{"0": "Insect wings contain no bones at all, so the two kinds of wing do not share bones.", "1": "Birds did not evolve from insects. Their wings are analogous, coming from different ancestors.", "3": "Both kinds of wing are fully working flight organs, not vestigial structures."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5330' AND answer = 2;
UPDATE questions SET why = 'Vestigial structures are body parts that have lost most or all of their original use. The human body is said to contain about 90 of them. Examples include the appendix, the coccyx (tailbone), wisdom teeth and the ear muscles.', wrong = '{"1": "Humans clearly have vestigial structures, such as the coccyx and wisdom teeth.", "2": "About 9 is far too few. The figure given for the human body is about 90.", "3": "About 500 is far too many. The figure given is about 90."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5331' AND answer = 0;
UPDATE questions SET why = 'The coccyx, or tailbone, is the small remnant of a tail that our ancestors had. Other human vestigial structures are the appendix, a vestige of the caecum, the wisdom teeth, which are vestigial third molars, and the small ear muscles.', wrong = '{"0": "The appendix is a vestige of the caecum. Remnants of hindlimbs are found in snakes such as boas and pythons.", "1": "The vestige of the caecum is the appendix. Ear muscles are small, poorly developed muscles that once moved the ears.", "2": "Wisdom teeth are vestigial third molars once used for grinding plant food. The tail remnant is the coccyx."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5332' AND answer = 3;
UPDATE questions SET why = 'Proteins are built according to the code in DNA. Related animals inherited similar DNA from a common ancestor, so their DNA codes for similar proteins. Comparing protein and DNA sequences is therefore molecular evidence of how closely species are related.', wrong = '{"0": "Sharing a habitat can lead to analogous features, but it does not make protein sequences similar.", "1": "Protein structure is coded by genes. Changes from use and disuse are not inherited.", "3": "Diet supplies amino acids, but the order of amino acids in a protein is set by DNA, not by food."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5333' AND answer = 2;
UPDATE questions SET why = 'The endosymbiotic theory says a large cell engulfed smaller prokaryotes that then lived inside it. Some of these small cells could use sunlight to make food and shared it with the host. Over time they became chloroplasts. Engulfed aerobic prokaryotes became mitochondria.', wrong = '{"0": "Prokaryotes resembling spirochetes are suggested as the origin of eukaryotic flagella, not chloroplasts.", "1": "Prokaryotes that carried out aerobic respiration became mitochondria, not chloroplasts.", "2": "Infolding of the cell membrane is a different idea, used to explain the nucleus and endoplasmic reticulum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5334' AND answer = 3;
UPDATE questions SET why = 'The endosymbiotic theory proposes that organelles began as prokaryotes engulfed by a larger cell. Besides mitochondria and chloroplasts, eukaryotic flagella may have come from engulfed prokaryotes similar to spirochetes, which are spiral, actively moving bacteria.', wrong = '{"0": "Viruses are not cells and cannot move by themselves, so they are not proposed as the origin of flagella.", "2": "Aerobic prokaryotes are thought to have become mitochondria.", "3": "Photosynthetic prokaryotes are thought to have become chloroplasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5335' AND answer = 1;
UPDATE questions SET why = 'Several features of mitochondria point to a bacterial origin. They are about the size of prokaryotes, have their own circular DNA, divide by binary fission, and have membranes more similar in composition to prokaryotic membranes than to eukaryotic ones. Chloroplasts share these features.', wrong = '{"1": "Mitochondria divide by binary fission, like prokaryotes. Eukaryotic cells, not mitochondria, divide by mitosis.", "2": "Mitochondria do have their own DNA, arranged in a circular chromosome like that of a prokaryote.", "3": "Mitochondria are about the same size as prokaryotic cells, which supports the theory."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5336' AND answer = 0;
UPDATE questions SET why = 'Eukaryotic cells formed by endosymbiosis gained mitochondria, and plants also gained chloroplasts. This made them powerful and efficient. That efficiency allowed them to evolve new features such as multicellularity, cell specialisation and large size, leading to the diversity of animals, plants and fungi.', wrong = '{"0": "Eukaryotic cells became larger, not smaller. Large size is one of the new features listed.", "1": "Eukaryotic cells reproduce by mitosis. Binary fission is the method of prokaryotes and of the organelles themselves.", "2": "Endosymbiosis gave eukaryotes organelles. It did not let them live without any."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5337' AND answer = 3;
UPDATE questions SET why = 'Jean-Baptiste Lamarck (1744–1829) was a French naturalist and one of the first to propose that organisms change over time. He explained this by use and disuse of organs and the inheritance of acquired characters, an idea later disproved.', wrong = '{"0": "The German physician is Wilhelm Weinberg, co-author of the Hardy-Weinberg theorem.", "2": "The English mathematician is Godfrey Hardy, the other author of the Hardy-Weinberg theorem.", "3": "The British naturalist who sailed on HMS Beagle was Charles Darwin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5338' AND answer = 1;
UPDATE questions SET why = 'Lamarck said organs change through use or disuse and that these acquired changes are inherited. Once inheritance was understood, this was rejected for two reasons. Acquired characters have no genetic basis, so they cannot be passed on, and organs are not modified by an organism''s wish or needs.', wrong = '{"0": "Fossils show that organisms have changed over time, so they support evolution rather than disprove change.", "1": "Mutations do occur and are the source of new variation. This was not a reason given against Lamarck.", "3": "Lamarck did believe organisms change. Rejection was about his mechanism, not about whether change happens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5339' AND answer = 2;
UPDATE questions SET why = 'Ecology is the study of how organisms relate to other organisms and to their environment. It covers levels from individual organisms up to populations, communities, ecosystems, biomes and the whole biosphere.', wrong = '{"1": "Studying the statistical characteristics of populations, such as birth and death rates, is demography, only one part of ecology.", "2": "The structure of cells and their organelles is the subject of cell biology.", "3": "The inheritance of traits from parents to offspring is the subject of genetics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5340' AND answer = 0;
UPDATE questions SET why = 'A species is a group of organisms that share characteristics and can interbreed to produce fertile offspring. Indus dolphins breed among themselves but cannot produce fertile young with other types of dolphin, so they form a separate species.', wrong = '{"0": "Organisms of one species living in the same area at the same time form a population. Location alone does not define a species.", "2": "Interacting with fish and birds makes the dolphins part of a community. It does not make them a species.", "3": "Living in fresh water is a habitat feature. Many different species share the same habitat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5341' AND answer = 1;
UPDATE questions SET why = 'A community is made of all the populations of different species living and interacting in the same area. In a mangrove forest near Karachi, the mangrove trees, mudskippers, crabs and shorebirds share space and interact, for example birds feed on fish. Together they form a community.', wrong = '{"1": "A population contains individuals of only one species, such as just the mudskippers.", "2": "A species is one kind of interbreeding organism. Several different species are listed here.", "3": "The biosphere is the global sum of all biomes, every place on Earth where life exists."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5342' AND answer = 0;
UPDATE questions SET why = 'A biome is a large region with its own climate, soil and adapted plants and animals. In Pakistan, the Thal and Thar regions are examples of the desert biome. They have very low rainfall and drought-adapted succulent plants that store water.', wrong = '{"0": "The coniferous forest biome is found in high, cold areas such as Murree and Swat, with pine trees.", "1": "The Indus River system is the example given of a freshwater biome.", "2": "Mangrove forests grow in salty coastal water, such as near Karachi, not in dry inland deserts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5343' AND answer = 3;
UPDATE questions SET why = 'The biosphere is the highest level of ecological organisation, the sum of all biomes. It is a thin envelope around the Earth where land, water and air interact to support life. For this reason it is often called the Global Ecosystem.', wrong = '{"0": "A primary reservoir is the large part of the biosphere where an element such as carbon or nitrogen is stored.", "1": "Carrying capacity is the largest population an environment can support for a long time.", "3": "A trophic level is a feeding level in a food chain, such as producers or primary consumers."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5344' AND answer = 2;
UPDATE questions SET why = 'Biogeochemical cycles are grouped by their primary reservoir, the main store of an element. In gaseous cycles, such as those of nitrogen, oxygen, carbon and water, the reservoir is the air or the oceans. In sedimentary cycles, such as phosphorus, the reservoir is the Earth''s crust.', wrong = '{"0": "Producers hold elements only for a short time before passing them on. They are not the main long-term store.", "1": "Root nodules of legumes house nitrogen-fixing bacteria. They are not a reservoir of a cycle.", "2": "The Earth''s crust is the reservoir of sedimentary cycles, such as the phosphorus cycle, not gaseous ones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5345' AND answer = 3;
UPDATE questions SET why = 'In the water cycle, water vapour rises and cools as it goes higher. During condensation it turns into tiny droplets or ice crystals. These cling to dust particles in the air and gather together to form clouds.', wrong = '{"1": "Absorbing heat from the sun drives evaporation, turning water into vapour, not condensation.", "2": "Falling to the ground under gravity is precipitation, which comes after clouds have formed.", "3": "Seeping into the soil is infiltration, which happens after rain reaches the ground."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5346' AND answer = 0;
UPDATE questions SET why = 'Precipitation is water falling from clouds when the droplets become too heavy. Depending on the temperature it falls as rain, snow or sleet. Sleet is rain mixed with snow or hail.', wrong = '{"0": "Water flowing over the land into streams and rivers is surface runoff.", "2": "Water released as vapour from the stomata of leaves is transpiration.", "3": "Water vapour rising from oceans and other surfaces is the result of evaporation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5347' AND answer = 1;
UPDATE questions SET why = 'When rain reaches the land, it either soaks into the soil (infiltration) or flows over the surface. Surface runoff is the unconfined flow of water over land, and it happens when the soil can no longer take in more water. The runoff flows into streams, rivers and finally the oceans.', wrong = '{"0": "Decomposition of dead bodies returns some water to the soil or air, but it is not runoff.", "1": "Water vapour cooling in the atmosphere leads to condensation and cloud formation.", "3": "Absorption of water by root hairs is how water enters the biotic part of the cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5348' AND answer = 2;
UPDATE questions SET why = 'Water leaves living organisms by transpiration, by breathing out metabolic water from respiration, through urine and faeces, by sweating and through decomposition after death. Absorption through root hairs takes water into plants, so it is NOT a route by which water leaves the biotic component.', wrong = '{"0": "Transpiration is a true exit route. In fact it is the major way water leaves plants, through leaf stomata.", "1": "Perspiration is a true exit route. Sweat released through skin pores evaporates into the atmosphere.", "2": "Excretion is a true exit route. Water in urine returns to the soil or water bodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5349' AND answer = 3;
UPDATE questions SET why = 'Nitrogen-fixing microorganisms convert N₂ gas into ammonia. Some live freely in soil or water and are called free-living or non-symbiotic fixers, such as cyanobacteria, Azotobacter and Clostridium. Others, such as Rhizobium, live symbiotically in the root nodules of legumes.', wrong = '{"1": "Pseudomonas is a denitrifying bacterium. It turns nitrates back into nitrogen gas rather than fixing nitrogen.", "2": "Rhizobium fixes nitrogen, but it is symbiotic, living in the root nodules of legumes such as chickpea and mung bean.", "3": "Nitrobacter carries out nitrification, converting nitrite into nitrate. It does not fix nitrogen gas."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5350' AND answer = 0;
UPDATE questions SET why = 'Lightning supplies the energy to combine atmospheric nitrogen with oxygen, forming nitrogen oxides and then nitrates. This atmospheric fixation produces only a small share, about 5 to 10%, of fixed nitrogen. More than 90% is fixed biologically by soil microorganisms.', wrong = '{"0": "78% is the proportion of nitrogen gas in the atmosphere, not the share fixed by lightning.", "2": "About 50% is far too high. Lightning fixes only about 5 to 10%.", "3": "More than 90% is the share fixed biologically by microorganisms, not by lightning."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5351' AND answer = 1;
UPDATE questions SET why = 'Industrial nitrogen fixation is the factory synthesis of nitrogen fertilisers. In this process, nitrogen from the atmosphere is combined with hydrogen to produce ammonia (N₂ + 3H₂ → 2NH₃), which is then used to make fertilisers.', wrong = '{"0": "Carbon dioxide contains no hydrogen and is not used to make ammonia.", "1": "Combining nitrogen with oxygen happens in atmospheric fixation by lightning, giving nitrogen oxides, not ammonia.", "3": "Nitrate is a product of nitrification in soil. It is not a raw material for making ammonia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5352' AND answer = 2;
UPDATE questions SET why = 'Nitrogen fixation produces ammonia, but ammonia is often toxic or hard for plants to use in large amounts. In nitrification, soil bacteria convert ammonia first into nitrite and then into nitrate. Plants can absorb nitrate easily through their roots.', wrong = '{"0": "Ammonia is in fact made by organisms during nitrogen fixation and ammonification.", "1": "The gas that makes up 78% of air is nitrogen (N₂), not ammonia.", "2": "Animals do not use ammonia directly to build proteins. They get nitrogen by eating plants and other animals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5353' AND answer = 3;
UPDATE questions SET why = 'Plants take in nitrates from the soil and use the nitrogen to make proteins and nucleic acids. Animals cannot use nitrates or nitrogen gas directly. They obtain nitrogen by eating plants and other animals, then use it to build their own proteins.', wrong = '{"0": "Animals do not absorb nitrates through their skin. Plants and microbes absorb nitrates from the soil.", "1": "No animal can fix atmospheric nitrogen. Only certain microorganisms can do this.", "3": "Converting nitrite to nitrate is nitrification, carried out by bacteria such as Nitrobacter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5354' AND answer = 2;
UPDATE questions SET why = 'Trophic level 3 contains secondary consumers, which feed on herbivores. These include carnivores such as frogs and snakes, and also the parasites of animals that feed on herbivores, since they too take energy from herbivores.', wrong = '{"0": "Wolves and hawks eat other carnivores, so they are tertiary consumers in trophic level 4.", "2": "Rabbits and insects feed directly on plants, so they are herbivores in trophic level 2.", "3": "Green plants and algae are producers in trophic level 1."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5355' AND answer = 1;
UPDATE questions SET why = 'Only about 10% of the energy at one trophic level passes on to the next, since much is used for life processes and lost as heat. So little energy remains after a few steps that ecosystems generally have only three or four trophic levels.', wrong = '{"1": "Most ecosystems have more than producers and herbivores. Carnivores usually form at least one further level.", "2": "Ten or more levels is impossible because so much energy is lost at each transfer.", "3": "An ecosystem needs at least producers and consumers, so one level is too few."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5356' AND answer = 0;
UPDATE questions SET why = 'A survivorship curve shows how many individuals survive at each age. In Type II (diagonal) populations, the chance of dying stays about the same throughout life, so numbers fall steadily. Birds, lizards and rodents show this pattern.', wrong = '{"0": "Type III (concave) curves show very high death among the young, as in fish and many invertebrates.", "2": "Exponential describes a type of population growth, not a survivorship curve.", "3": "Type I (convex) curves show most individuals living to old age, as in humans and many large mammals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5357' AND answer = 1;
UPDATE questions SET why = 'Dispersion is how individuals are spread out in an area. In random spacing, individuals do not strongly attract or repel each other. It occurs in some plants whose wind-dispersed seeds germinate wherever they happen to land in a suitable spot. Random spacing is not common in nature.', wrong = '{"0": "Clumped spacing occurs when seeds fall close to the parent or when animals live in groups.", "1": "Logistic growth is a model of population growth that levels off, not a spacing pattern.", "3": "Uniform spacing results when individuals inhibit neighbours or defend territories, keeping even distances."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5358' AND answer = 2;
UPDATE questions SET why = 'Carrying capacity is the largest population an environment can support. As a dense population nears it, competition for food, space and other resources becomes severe. The birth rate falls, the risk of death rises and pollution can build up.', wrong = '{"1": "At high density the birth rate falls rather than rises, because resources are scarce.", "2": "Growth slows down near carrying capacity, as in the logistic model. Exponential growth happens when resources are plentiful.", "3": "Population density does not force the dispersion pattern to become random."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5359' AND answer = 0;
UPDATE questions SET why = 'If all life on Earth were weighed, humans would make up only about 0.01% of the total biomass. Plants make up about 82% and bacteria about 13%. Even so, the human population places severe strains on the global environment.', wrong = '{"0": "16% is far too high for humans. It does not match the human share of biomass, which is about 0.01%.", "1": "About 13% of Earth''s biomass is made up of bacteria, not humans.", "2": "About 82% of Earth''s biomass is made up of plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5360' AND answer = 3;
UPDATE questions SET why = 'From the early 1700s, changes in technology gave humans more control over their food supply, better weapons against predators and remedies for diseases. Humans also became less vulnerable to climate. Together these allowed them to expand the carrying capacity of their habitats.', wrong = '{"0": "A change in global temperature is not given as the reason. The expansion came from technology.", "2": "Humans developed weapons to protect themselves from predators. A rise in predators would lower carrying capacity.", "3": "Births did not fall. The human population grew rapidly during this period."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5361' AND answer = 1;
UPDATE questions SET why = 'Carbon dioxide is the most significant greenhouse gas. It is released mainly by burning coal, oil and gas and by deforestation, and contributes about 80% of global warming. Methane contributes about 11%, nitrous oxide about 6% and fluorinated gases about 3%.', wrong = '{"0": "About 11% is the contribution of methane, from cattle, coal and gas production and agriculture.", "1": "About 3% is the contribution of fluorinated gases, such as those from old refrigerators.", "3": "About 6% is the contribution of nitrous oxide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5362' AND answer = 2;
UPDATE questions SET why = 'Nitrous oxide (N₂O) is a greenhouse gas released during agricultural activities, such as the use of nitrogen fertilisers, during industrial processes, and when fossil fuels are burned. It contributes about 6% of global warming.', wrong = '{"0": "Photosynthesis takes in carbon dioxide and releases oxygen. It does not produce nitrous oxide.", "1": "Enteric fermentation in cattle is a major source of methane, not nitrous oxide.", "2": "Old refrigerators and air conditioners release fluorinated gases (CFCs), not mainly nitrous oxide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5363' AND answer = 3;
UPDATE questions SET why = 'Before industrialisation, the concentration of carbon dioxide in the atmosphere was about 280 parts per million (ppm). Burning fossil fuels and cutting forests have since raised it to above 420 ppm, and it is still rising.', wrong = '{"1": "1000 ppm is far higher than both the pre-industrial level and today''s level of just over 420 ppm.", "2": "78 is the percentage of nitrogen in the air. It is unrelated to the CO₂ level in ppm.", "3": "50 ppm is far too low. The pre-industrial CO₂ level was about 280 ppm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5364' AND answer = 0;
UPDATE questions SET why = 'The body keeps cool mainly by sweating, but this works only while the surroundings can take up the heat. When air temperature crosses about 50 °C, as in Jacobabad and Sibi, the body can no longer keep its normal temperature. Body temperature then rises out of control, causing fatal heatstroke.', wrong = '{"0": "Sweat glands do not disappear in heat. The problem is that the body cannot lose enough heat.", "2": "High temperature does not use up the oxygen in the air.", "3": "Heat does not change the proportion of nitrogen in the air."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5365' AND answer = 1;
UPDATE questions SET why = 'A cloudburst is a sudden, extremely heavy rainfall that falls over a small area in a short time. It can cause flash floods and landslides, as has happened in Gilgit-Baltistan and Chitral.', wrong = '{"0": "Seawater moving into coastal farmland is seawater intrusion, caused by rising sea levels.", "1": "Slow seepage of rainwater into the soil is infiltration.", "2": "A sudden release of water from a glacial lake is a glacial lake outburst flood (GLOF)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5366' AND answer = 3;
UPDATE questions SET why = 'Warm air can hold more water vapour than cool air. As greenhouse gases warm the atmosphere, it holds more moisture, so when it rains the rainfall is heavier and more erratic. This strengthens monsoons and causes floods.', wrong = '{"1": "Warming is linked to more carbon dioxide in the air, not less.", "2": "Warming melts glaciers, making them shrink rather than grow.", "3": "Higher temperatures increase evaporation from the oceans rather than stopping it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5367' AND answer = 0;
UPDATE questions SET why = 'Flowering is the stage when grains are formed in wheat and rice. High temperatures at this sensitive stage can damage flowers and greatly reduce grain yield. This loss of yield adds to food insecurity.', wrong = '{"0": "Ploughing is a farming activity done before sowing, not a growth stage of the crop.", "1": "Winter dormancy of seeds is not the stage where heat is said to cause the main yield loss.", "3": "Seed storage after harvest is not a growth stage. Yield loss from heat is linked to flowering."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5368' AND answer = 2;
UPDATE questions SET why = 'Temperate deciduous forests grow in the moist northern mountains of Pakistan, such as Shogran, Neelam Valley, Murree and parts of Kaghan. These areas get about 750 to 1500 mm of rain a year and have grey-brown soil rich in humus.', wrong = '{"1": "Tropical thorn forests are on the hot Indus plains, with only about 200 to 750 mm of rain.", "2": "Mangrove forests grow on the coasts of Sindh and Balochistan, in salty tidal water.", "3": "Alpine meadows are on high mountain tops with heavy snow, above the tree line."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5369' AND answer = 0;
UPDATE questions SET why = 'The tropical thorn forest grows on hot, arid plains. Its plants are xerophytes, meaning adapted to drought. Thorns protect them from grazing animals and, being reduced leaves or small surfaces, also help cut down water loss.', wrong = '{"0": "Trapping insects for nitrogen is a feature of insect-eating plants, not of thorn forest plants.", "1": "Breathing roots for waterlogged soil are a feature of mangroves, not thorn forests.", "2": "Thorn forests are on hot plains where it does not snow, so thorns are not for catching snow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5370' AND answer = 3;
UPDATE questions SET why = 'The tropical thorn forest of the Indus plains has drought-resistant trees and shrubs. Its key flora include Jhand (Prosopis cineraria), Peelu (Salvadora oleoides), Karir (Capparis aphylla) and Kikar, all suited to the hot, dry conditions.', wrong = '{"0": "The temperate deciduous forest has trees such as yew, blue pine and Himalayan cedar (deodar).", "2": "The mangrove forest is dominated by Avicennia marina (Timmar).", "3": "The alpine meadow has stunted junipers, birch, willow and alpine grasses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5371' AND answer = 1;
UPDATE questions SET why = 'Alpine and sub-alpine meadows are high-altitude cold grasslands, such as the Deosai Plains and mountain tops of Gilgit-Baltistan and Chitral, where it is too harsh for large trees. Their key fauna are cold-adapted animals: the snow leopard, Himalayan ibex, musk deer, marmots and Himalayan brown bear.', wrong = '{"0": "The tropical thorn forest of the hot plains has fauna such as camels, chinkara and houbara bustard.", "1": "The mangrove forest of the coast has fauna such as mudskippers, crabs, shrimps and crocodiles.", "3": "The temperate deciduous forest has fauna such as rhesus monkeys, black bears and leopard cats."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5372' AND answer = 2;
UPDATE questions SET why = 'Mangroves grow on coastal mudflats flooded by brackish water. This mud is anaerobic, meaning it contains very little oxygen. To get oxygen to their roots, mangrove trees have breathing roots that grow up out of the mud into the air.', wrong = '{"0": "Dry, sandy desert soil is well aerated. It is the habitat of desert and thorn-forest plants, not mangroves.", "1": "Humus-rich forest soil is found in temperate deciduous forests, not on coastal mudflats.", "2": "Frozen soil under heavy snow is found in alpine meadows, not in coastal mangroves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5373' AND answer = 3;
UPDATE questions SET why = 'Mangroves need a mix of fresh river water and seawater. In Pakistan they are threatened mainly by the reduced flow of fresh water from the Indus into its delta and by pollution from Karachi. Recent restoration projects have helped protect them.', wrong = '{"0": "The lumber industry puts pressure on the temperate deciduous forests of the north, not on coastal mangroves.", "1": "Mangroves grow on warm coasts where it does not snow.", "3": "Clearing for canal irrigation in Punjab has mainly degraded the tropical thorn forest."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-5374' AND answer = 2;
UPDATE questions SET why = 'Gonorrhoea is a sexually transmitted disease caused by the bacterium Neisseria gonorrhoeae. Under the microscope it appears as Gram-negative diplococci, meaning pairs of round bacteria. Being bacterial, it can be treated with antibiotics.', wrong = '{"0": "Treponema pallidum is a spiral bacterium that causes syphilis, not gonorrhoea.", "2": "Herpes simplex virus causes genital herpes, a viral infection with painful blisters.", "3": "Chlamydia trachomatis causes chlamydia, another common bacterial STD."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6001' AND answer = 1;
UPDATE questions SET why = 'Syphilis is a sexually transmitted disease caused by Treponema pallidum. This is a spirochaete, a thin, spiral-shaped bacterium. As a bacterial infection it can be cured with antibiotics such as penicillin.', wrong = '{"1": "Syphilis is caused by a bacterium. Viral STDs include genital herpes and AIDS.", "2": "The protozoan STD is trichomoniasis, caused by Trichomonas vaginalis, not syphilis.", "3": "Syphilis is not caused by a fungus. Its cause is the bacterium Treponema pallidum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6002' AND answer = 0;
UPDATE questions SET why = 'Syphilis develops in stages. The primary stage begins with a firm, painless sore called a chancre at the site where the bacteria entered. A skin rash follows in the secondary stage, and if untreated, the tertiary stage can damage the heart, brain and other organs years later.', wrong = '{"0": "Painful blisters that keep returning are typical of genital herpes, a viral infection.", "1": "A pus-like discharge with burning urination is typical of gonorrhoea.", "2": "Damage to the heart and brain occurs in late (tertiary) syphilis, years after infection, not as the first sign."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6003' AND answer = 3;
UPDATE questions SET why = 'Antibiotics work against bacteria, not viruses. Genital herpes is caused by the herpes simplex virus, mostly HSV-2, so antibiotics cannot cure it. Antiviral drugs can only reduce and control outbreaks, and the virus remains in the body.', wrong = '{"0": "Gonorrhoea is caused by the bacterium Neisseria gonorrhoeae and can be treated with antibiotics.", "1": "Syphilis is caused by the bacterium Treponema pallidum and can be cured with penicillin.", "3": "Chlamydia is caused by the bacterium Chlamydia trachomatis and can be cured with antibiotics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6004' AND answer = 2;
UPDATE questions SET why = 'After the first infection, herpes simplex virus travels along nerves and stays dormant (latent) in sensory nerve cells, in the ganglia. The immune system cannot remove it from there. Stress or illness can reactivate the virus, which travels back to the skin and causes new blisters.', wrong = '{"0": "The virus is not killed. Outbreaks recur from the same hidden virus, without a new infection.", "2": "The virus hides inside sensory nerve ganglia, not freely in the blood.", "3": "Viruses do not form spores. Spores are made by some bacteria, fungi and plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6005' AND answer = 1;
UPDATE questions SET why = 'Burning pain on urination with a thick, yellowish (pus-like) discharge is the classic picture of gonorrhoea in men. Gram-negative diplococci in the smear identify the cause as Neisseria gonorrhoeae. In women it is often symptomless and, if untreated, can cause infertility.', wrong = '{"1": "Syphilis starts with a painless sore, the chancre, and is caused by a spiral bacterium, not diplococci.", "2": "Genital herpes causes painful blisters and is caused by a virus, which would not appear as bacteria in a smear.", "3": "AIDS weakens the immune system over years and does not produce this local discharge."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6006' AND answer = 0;
UPDATE questions SET why = 'HIV spreads only through certain body fluids: semen, vaginal fluid, blood and breast milk. It is not spread by casual contact such as shaking hands, sharing food or utensils, or by mosquito and other insect bites, so shaking hands or mosquito bites is the route that does NOT spread it.', wrong = '{"0": "Unprotected sexual contact is a true route, in fact the main way HIV is spread.", "1": "Sharing used needles is a true route, because it passes infected blood directly into the bloodstream.", "2": "An infected mother can pass HIV to her baby across the placenta, during birth or through breast milk."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6007' AND answer = 3;
UPDATE questions SET why = 'Chlamydia, caused by the bacterium Chlamydia trachomatis, often produces no symptoms, especially in women, so it can go unnoticed. If untreated it can spread to cause pelvic inflammatory disease, which can scar and block the oviducts and lead to infertility. It is curable with antibiotics.', wrong = '{"0": "Chlamydia is caused by a bacterium, Chlamydia trachomatis, not by a virus.", "1": "Chlamydia can be cured with antibiotics, such as tetracyclines.", "3": "Chlamydia spreads by sexual contact, not through the air."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6008' AND answer = 2;
UPDATE questions SET why = 'Animal cells contain a pair of centrioles in the centrosome, which help organise the spindle during cell division. Cells of flowering (higher) plants lack centrioles and form their spindle without them. Mitochondria, Golgi apparatus and ribosomes are found in both.', wrong = '{"0": "Mitochondria carry out aerobic respiration in both plant and animal cells.", "2": "The Golgi apparatus, which packages and modifies proteins, is present in both plant and animal cells.", "3": "Ribosomes make proteins and are present in all cells, plant, animal and even bacterial."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6009' AND answer = 1;
UPDATE questions SET why = 'Plant cells have three features that animal cells lack. A rigid cellulose cell wall gives support, chloroplasts carry out photosynthesis, and a large central vacuole stores cell sap and keeps the cell turgid.', wrong = '{"1": "A cell membrane and nucleus are present in all eukaryotic cells, both plant and animal.", "2": "Mitochondria and ribosomes are found in both plant and animal cells.", "3": "Centrioles are typical of animal cells, not plant cells, and lysosomes are mainly an animal cell feature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6010' AND answer = 0;
UPDATE questions SET why = 'Both plants and animals store glucose as a polysaccharide, but a different one. Plants store it as starch, mainly in plastids, while animals store it as glycogen, mainly in the liver and muscles. So the correct order is starch, then glycogen.', wrong = '{"0": "This is the right pair in the wrong order. Glycogen is the animal store and starch the plant store.", "1": "Cellulose is a structural polysaccharide in plant cell walls, not a store, and animals do not store starch.", "2": "Cellulose is structural, not a storage carbohydrate, and animals do not make cellulose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6011' AND answer = 3;
UPDATE questions SET why = 'Plant cells have a rigid cellulose cell wall outside the cell membrane. The wall holds the cell in a fixed, regular shape and stops it bursting when it takes in water. Animal cells have only a flexible membrane, so they are often rounded or irregular and can change shape.', wrong = '{"0": "Both plant and animal cells have a nucleus, so the nucleus cannot explain the difference in shape.", "1": "Mitochondria produce ATP. Their number does not set the shape of the cell.", "3": "Plant cells do have a cytoskeleton. The fixed shape comes mainly from the cell wall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6012' AND answer = 2;
UPDATE questions SET why = 'The fluid mosaic model, proposed by Singer and Nicolson in 1972, describes the membrane as a phospholipid bilayer with proteins scattered through it. Fluid means the lipids and many proteins can move sideways within the bilayer, like a two-dimensional liquid. Mosaic refers to the pattern of proteins.', wrong = '{"0": "The membrane is made of lipids and proteins, not of water.", "2": "Membrane thickness is fairly constant, about 7 to 10 nm. Fluid refers to movement of molecules, not changing thickness.", "3": "Membrane proteins are embedded in or attached to the bilayer, not dissolved in the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6013' AND answer = 1;
UPDATE questions SET why = 'In animal cell membranes, cholesterol molecules sit between the phospholipids. At body temperature they stop the membrane from becoming too fluid, and at low temperatures they stop it becoming too rigid. In this way cholesterol regulates fluidity and adds stability.', wrong = '{"1": "Glucose is carried across the membrane by carrier proteins, not by cholesterol.", "2": "Hormone receptors on the membrane are usually proteins or glycoproteins, not cholesterol.", "3": "Energy is stored as fats and glycogen. Membrane cholesterol plays a structural role, not a storage one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6014' AND answer = 0;
UPDATE questions SET why = 'Glycoproteins and glycolipids carry short carbohydrate chains on the outer surface of the membrane, forming the glycocalyx. These chains act as identification markers, such as blood group antigens, and as receptor sites for hormones and other signals. So they mainly work in cell recognition and signal binding.', wrong = '{"0": "Photosynthesis takes place in chloroplasts, not on the outer surface of the cell membrane.", "1": "DNA replication takes place in the nucleus.", "2": "ATP is made mainly in mitochondria, by cellular respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6015' AND answer = 3;
UPDATE questions SET why = 'Oparin and Haldane proposed that life arose by chemical evolution. Energy from lightning and UV light acted on gases in the early reducing atmosphere to form simple organic molecules. These collected in the oceans as a primordial soup and, over a long time, gave rise to the first cells.', wrong = '{"0": "Special creation is a religious belief, not the Oparin–Haldane hypothesis of chemical origin.", "1": "Life arriving on spores from other planets is the panspermia idea.", "3": "Spontaneous generation from rotting meat was disproved by Redi and Pasteur, and is not this hypothesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6016' AND answer = 2;
UPDATE questions SET why = 'In 1953 Stanley Miller and Harold Urey tested the Oparin–Haldane idea. They passed electric sparks, imitating lightning, through methane, ammonia, hydrogen and water vapour. After some days the mixture contained amino acids and other simple organic compounds, showing these can form from inorganic gases.', wrong = '{"0": "No living cells formed in the experiment, only simple organic molecules.", "2": "DNA is a large, complex polymer and was not produced. Only small molecules such as amino acids formed.", "3": "The mixture had no free oxygen, and the experiment did not produce oxygen gas."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6017' AND answer = 1;
UPDATE questions SET why = 'The early Earth''s atmosphere is thought to have been reducing, with gases such as methane, ammonia, hydrogen and water vapour but no free oxygen (O₂). Oxygen would have broken down newly formed organic molecules. O₂ built up only later, from photosynthesis.', wrong = '{"1": "Water vapour was present, released from volcanoes and the cooling Earth.", "2": "Methane is thought to have been present in the early atmosphere.", "3": "Ammonia is thought to have been present in the early atmosphere."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6018' AND answer = 0;
UPDATE questions SET why = 'Coacervates are tiny droplets that form on their own when organic polymers such as proteins and carbohydrates gather together in water. Each droplet has a boundary that separates its inside from the surrounding water, so it can keep a different internal environment, take in substances and grow. This makes them a model for how the first cells may have arisen.', wrong = '{"0": "Coacervates have no genetic material and no true cell division. Mitosis is a process of real eukaryotic cells, which appeared much later.", "1": "Coacervates are droplets made in laboratory experiments and imagined in the early oceans. They are not fossils of bacteria.", "2": "Coacervates have no chlorophyll or photosynthetic machinery, so they cannot make food from light."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6019' AND answer = 3;
UPDATE questions SET why = 'The RNA world idea says early life used RNA for two jobs. RNA can carry genetic information in its base sequence, like DNA, and some RNA molecules called ribozymes can also catalyse reactions, like enzymes. One molecule doing both jobs could have started life before DNA and proteins evolved.', wrong = '{"0": "RNA is usually single stranded and less stable than DNA. This is one reason DNA later took over long-term storage of genetic information.", "1": "RNA contains uracil in place of thymine. Thymine is found in DNA.", "3": "The first genetic molecules existed long before cells with a nucleus evolved, and even today RNA is also made in mitochondria and chloroplasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6020' AND answer = 2;
UPDATE questions SET why = 'The hepatitis B vaccine is a recombinant subunit vaccine. The gene for the virus''s surface antigen (HBsAg) is inserted into yeast cells, which then make large amounts of this protein. The purified protein is used in the vaccine, so it triggers immunity without any whole virus being present.', wrong = '{"0": "Heat-killed whole virus is the method for some older vaccines. The modern hepatitis B vaccine contains only the surface protein, not whole virus.", "2": "Growing virus in hens'' eggs is used for some influenza vaccines, not for the hepatitis B vaccine.", "3": "Antibodies taken from infected people give short-lived passive immunity. A vaccine instead makes the body produce its own antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6021' AND answer = 1;
UPDATE questions SET why = 'A recombinant subunit vaccine contains only one purified, harmless part of the pathogen, such as a surface protein. It has no genes that can copy themselves, so it cannot multiply in the body or turn back into a harmful form. This is why it cannot cause the disease, although booster doses may still be needed.', wrong = '{"1": "Most subunit vaccines, such as the hepatitis B vaccine, are given by injection.", "2": "Subunit vaccines often need two or more doses and later boosters to give lasting protection.", "3": "Each vaccine is specific to the antigen of one pathogen, so it protects only against that disease."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6022' AND answer = 0;
UPDATE questions SET why = 'An mRNA vaccine carries mRNA, wrapped in tiny lipid particles, into the body''s cells. Ribosomes translate this mRNA into a viral protein such as the coronavirus spike protein. The immune system recognises this protein as foreign and makes antibodies and memory cells. The mRNA is soon broken down.', wrong = '{"0": "An mRNA vaccine contains no virus at all, live or killed. It contains only the instructions for one viral protein.", "1": "The mRNA stays in the cytoplasm and is broken down within days. It does not enter the nucleus or join the person''s DNA.", "2": "Ready-made antibodies give passive immunity. A vaccine gives active immunity, where the body makes its own antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6023' AND answer = 3;
UPDATE questions SET why = 'Ivanovsky passed sap from diseased tobacco plants through a porcelain filter whose pores were too small for bacteria. The filtered sap still caused mosaic disease in healthy plants. So the infectious agent must be smaller than bacteria. This agent was later named tobacco mosaic virus.', wrong = '{"0": "Fungi are larger than bacteria, so they would also have been held back by the filter.", "1": "The filtered sap still infected healthy plants, which shows the disease was infectious.", "3": "The filter was designed to stop bacteria, and it did. That is why the result pointed to a smaller agent."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6024' AND answer = 2;
UPDATE questions SET why = 'Martinus Beijerinck repeated the filtration experiments on tobacco mosaic disease in 1898. He found that the agent multiplied only in living plant cells and could not be grown alone. He called it a contagium vivum fluidum, a contagious living fluid, and used the word virus for it.', wrong = '{"0": "Louis Pasteur is known for germ theory and for the rabies vaccine. He did not describe the tobacco mosaic agent this way.", "2": "W. M. Stanley crystallised tobacco mosaic virus in 1935, decades after Beijerinck''s work.", "3": "Antonie van Leeuwenhoek was the first to see bacteria and other microbes with his simple microscopes in the 1670s."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6025' AND answer = 1;
UPDATE questions SET why = 'In 1935 W. M. Stanley purified tobacco mosaic virus and obtained it as crystals. When the crystals were dissolved and rubbed on tobacco leaves, they still caused disease. This showed that viruses behave like non-living chemicals outside cells but like living things inside cells. Stanley later shared the 1946 Nobel Prize.', wrong = '{"1": "Viruses multiply only inside living host cells. They cannot be grown on non-living media such as nutrient agar.", "2": "Tobacco mosaic virus is far too small to be seen with a light microscope. It can only be seen with an electron microscope.", "3": "Antibiotics act on bacterial structures such as cell walls and ribosomes. Viruses lack these, so antibiotics do not kill them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6026' AND answer = 0;
UPDATE questions SET why = 'By the law of limiting factors, the rate of a process is controlled by the factor in shortest supply. On the rising part of the curve, light is limiting. Once the curve levels off, more light gives no extra rate, so another factor in short supply, usually CO₂ concentration or temperature, now controls the rate.', wrong = '{"0": "Light limits the rate only on the rising part of the curve. In the level part, more light causes no increase, so light is not limiting.", "1": "The amount of chlorophyll stays roughly the same in an experiment. CO₂ concentration and temperature are the usual limiting factors at high light.", "2": "Oxygen is a product of photosynthesis, not a raw material, so its concentration does not limit the rate here."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6027' AND answer = 3;
UPDATE questions SET why = 'The compensation point is the light intensity at which photosynthesis and respiration run at exactly the same rate. All the CO₂ released by respiration is used by photosynthesis, and all the O₂ made is used in respiration, so there is no net gas exchange. Plants usually reach it in dim light, at dawn and dusk.', wrong = '{"0": "The saturation point is the light intensity above which more light gives no further rise in the rate of photosynthesis.", "1": "Limiting point is not the standard name for this light intensity. The correct term is compensation point.", "3": "Photoperiod is the length of the daily light period, which controls flowering in many plants. It is not a light intensity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6028' AND answer = 2;
UPDATE questions SET why = 'Air contains only about 0.04% CO₂. In bright light and at a suitable temperature, this low CO₂ level is often the factor that limits photosynthesis. Raising the CO₂ concentration in a closed greenhouse lets the plants photosynthesise faster, so they grow more and give a higher yield.', wrong = '{"0": "Adding CO₂ does not cool plants. Its purpose is to remove the limit on photosynthesis.", "2": "CO₂ enrichment is not used as a pest control method. It is used to raise the rate of photosynthesis.", "3": "Land plants take in CO₂ from the air through the stomata of their leaves, not through their roots."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6029' AND answer = 1;
UPDATE questions SET why = 'Only a very small part of the water a plant absorbs is used as a raw material in photosynthesis. During drought, the plant closes its stomata to reduce water loss by transpiration. Closed stomata also stop CO₂ entering the leaf, so the chloroplasts run short of CO₂ and the rate falls.', wrong = '{"1": "Less than about 1% of absorbed water is used directly in photosynthesis, so the shortage of water as a raw material is not the main cause.", "2": "Chlorophyll is held in the thylakoid membranes. It does not dissolve away during drought.", "3": "Drought does not block sunlight. Light still reaches the leaves normally."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6030' AND answer = 0;
UPDATE questions SET why = 'In cyclic photophosphorylation, only photosystem I is used. Electrons excited from its reaction centre P700 pass along an electron transport chain and then return to P700, and the energy released is used to make ATP. Because the electrons go round in a cycle, no NADPH is made, no water is split and no oxygen is released.', wrong = '{"0": "Photosystem II takes part only in the non-cyclic pathway. The cyclic pathway uses photosystem I alone.", "1": "Splitting of water and release of O₂ happen only in the non-cyclic pathway, where photosystem II needs replacement electrons.", "2": "This is reversed. Cyclic flow makes ATP only, and no NADPH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6031' AND answer = 3;
UPDATE questions SET why = 'In non-cyclic photophosphorylation, photosystem II loses electrons from its reaction centre P680 when light excites them. These electrons are replaced by splitting water, called photolysis: 2H₂O → 4H⁺ + 4e⁻ + O₂. The oxygen released by plants comes from this splitting of water.', wrong = '{"0": "NADPH is a final product of the light reactions. It is formed when electrons from photosystem I reduce NADP⁺, so it does not supply electrons to photosystem II.", "1": "CO₂ is used later in the Calvin cycle. It is not a source of electrons in the light reactions.", "3": "Glucose is made later from the products of the Calvin cycle. It is not used in the light reactions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6032' AND answer = 2;
UPDATE questions SET why = 'Fixing one CO₂ in the Calvin cycle needs 3 ATP and 2 NADPH. Non-cyclic flow makes ATP and NADPH in roughly equal amounts, which is not enough ATP. Cyclic flow makes ATP only, so running it alongside the non-cyclic pathway supplies the extra ATP the Calvin cycle needs.', wrong = '{"0": "Cyclic flow does not split water, so it releases no oxygen.", "2": "Glucose is made from the products of the Calvin cycle, not directly by any light reaction.", "3": "Non-cyclic flow does make ATP, along with NADPH. It simply does not make enough ATP for the Calvin cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6033' AND answer = 1;
UPDATE questions SET why = 'Carnivorous plants such as the pitcher plant have chlorophyll and make their own food by photosynthesis, so they are autotrophs. They grow in boggy, nutrient-poor soil that is low in nitrogen. They trap and digest insects to get the extra nitrogen and minerals they cannot get from the soil.', wrong = '{"1": "Carnivorous plants are green and photosynthesise, so they are not heterotrophs. Insects add nitrogen, not their main food.", "2": "A parasite takes food from a living host plant. Carnivorous plants do not attach to or feed on other plants.", "3": "Decomposers break down dead matter. Carnivorous plants actively trap and digest living insects instead."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6034' AND answer = 0;
UPDATE questions SET why = 'Globular proteins are folded into a compact, roughly spherical shape, are soluble and do functional work such as transport or catalysis. Haemoglobin is a globular protein that carries oxygen in red blood cells. Keratin, collagen and fibrin are long fibrous proteins with structural roles.', wrong = '{"0": "Keratin is a fibrous structural protein found in hair, nails, horns and the outer layer of skin.", "1": "Collagen is a fibrous structural protein that gives strength to tendons, bone, cartilage and skin.", "2": "Fibrin is a fibrous protein that forms the mesh of threads in a blood clot."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6035' AND answer = 3;
UPDATE questions SET why = 'Fibrous proteins are long fibrils with mainly primary or secondary structure. They are insoluble in water, non-crystalline and elastic, and they do not lose their structure easily when conditions change. Their main role is structural, as in collagen, keratin and silk.', wrong = '{"0": "Being soluble and acting as enzymes are features of globular proteins, not fibrous ones.", "1": "Globular proteins can be crystallised. Fibrous proteins are non-crystalline and elastic.", "3": "A spherical or ellipsoidal shape is typical of globular proteins. Fibrous proteins are long and thread-like."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6036' AND answer = 2;
UPDATE questions SET why = 'When enzymes are grouped by the substrate they act on, enzymes that break down carbohydrates are called carbohydrases. Sucrase acts on sucrose, maltase on maltose and cellulase on cellulose, so all three are carbohydrases. Amylase, which digests starch, is another member.', wrong = '{"0": "Proteases act on proteins. Examples are pepsin and trypsin.", "2": "Lipases act on lipids, splitting them into fatty acids and glycerol.", "3": "Nucleases act on nucleic acids, splitting DNA or RNA into nucleotides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6037' AND answer = 1;
UPDATE questions SET why = 'Protein digestion happens in steps. Pepsin and trypsin break large polypeptides into smaller ones, and aminopeptidases break small polypeptides into dipeptides. Erypsin finishes the process by breaking dipeptides into single amino acids, which can then be absorbed.', wrong = '{"1": "Breaking large polypeptides into smaller polypeptides is done by pepsin and trypsin, early in protein digestion.", "2": "Starch is broken into maltose by amylase, a carbohydrase, not by a protein-digesting enzyme.", "3": "Lipids are broken into fatty acids and glycerol by lipase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-6038' AND answer = 0;
UPDATE questions SET why = 'Digestive enzymes are proteins made for export. They are built on ribosomes attached to the rough ER and enter its lumen. The Golgi apparatus then modifies them, packs them into secretory vesicles and sends them to the cell surface. A cell that exports this much protein needs both organelles in large amounts.', wrong = '{"1": "Smooth ER makes lipids and steroids and detoxifies drugs, and peroxisomes break down H₂O₂. Neither makes protein for export.", "2": "Free ribosomes make proteins that stay in the cytosol, and lysosomes digest material inside the cell. Neither exports enzymes.", "3": "Mitochondria supply ATP and centrioles help organise the spindle during division. Neither makes or packages secretory protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7001' AND answer = 0;
UPDATE questions SET why = 'Labelled amino acids are first built into protein on ribosomes of the rough ER. The new protein moves in transport vesicles to the Golgi apparatus, where it is modified and packed into secretory vesicles. These vesicles fuse with the plasma membrane and release the protein outside the cell by exocytosis.', wrong = '{"0": "The Golgi receives proteins from the ER, so it cannot become labelled before the rough ER.", "1": "Secretory protein is made on rough ER, not smooth ER. Lysosomes keep their enzymes inside the cell and are not the export route.", "2": "Proteins are not made in the nucleus, and a secreted protein ends up outside the cell, not inside lysosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7002' AND answer = 3;
UPDATE questions SET why = 'Steroid hormones such as cortisol and testosterone are lipids made from cholesterol. The enzymes for lipid and steroid synthesis lie on the smooth ER. So cells of the adrenal cortex and Leydig cells of the testis, which make large amounts of steroid hormone, have a very extensive smooth ER.', wrong = '{"0": "Rough ER is abundant in cells that secrete protein, such as enzyme- or insulin-secreting cells, not in steroid-making cells.", "1": "Lysosomes contain hydrolytic enzymes that digest materials. They do not make hormones.", "2": "The nucleolus makes ribosomal RNA for protein synthesis, which is not the main activity of steroid-making cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7003' AND answer = 3;
UPDATE questions SET why = 'Each lysosomal hydrolase digests particular substances. If one enzyme is missing, lysosomes still form and take in material, but that enzyme''s substrate cannot be broken down. It builds up inside the lysosomes, which swell and damage the cell. Tay-Sachs disease, where a lipid collects in nerve cells, is an example.', wrong = '{"0": "The lysosome membrane stays intact. The problem is one missing enzyme, not bursting of lysosomes.", "2": "Ribosomes and protein synthesis are not directly affected by the lack of one lysosomal enzyme.", "3": "Mitochondria carry out aerobic respiration. They do not digest materials taken into the cell, so they cannot take over this job."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7004' AND answer = 1;
UPDATE questions SET why = 'The fluid mosaic model of Singer and Nicolson says the membrane is a fluid lipid bilayer in which proteins float. The labelled mouse and human proteins could only become evenly mixed so quickly if they drifted sideways within the plane of the membrane. This experiment strongly supports the fluid mosaic model.', wrong = '{"0": "Newly made proteins would not carry the old labels. The labels mixed because proteins already in the membrane moved.", "1": "A rigid protein-lipid-protein sandwich, as in the older Davson-Danielli model, would not let proteins move and mix.", "3": "The result concerns proteins within the membrane, not exchange of cytoplasm between cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7005' AND answer = 2;
UPDATE questions SET why = 'Unsaturated fatty acids have double bonds that put kinks in their tails. Kinked tails cannot pack tightly together, so the membrane stays fluid even at low temperatures. Fish in very cold water therefore have more unsaturated fatty acid tails in their membrane phospholipids.', wrong = '{"0": "Saturated tails are straight and pack tightly, so they would make the membrane stiffer in the cold.", "2": "Long, saturated tails pack even more closely and would make the membrane more rigid, the opposite of what cold-water fish need.", "3": "Each phospholipid has a single phosphate-containing head. The number of heads per molecule does not change."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7006' AND answer = 1;
UPDATE questions SET why = 'Mitochondria have their own small ribosomes that resemble the 70S ribosomes of bacteria, a clue that they came from engulfed bacteria. Antibiotics that block bacterial 70S ribosomes can therefore also block protein synthesis inside human mitochondria, especially at high doses.', wrong = '{"1": "Ribosomes in the cytoplasm and on the rough ER of human cells are 80S. These antibiotics are chosen because they do not target 80S ribosomes.", "2": "The nucleolus makes the subunits of 80S cytoplasmic ribosomes, not 70S ribosomes.", "3": "The Golgi apparatus has no ribosomes of its own. It modifies and packages proteins made elsewhere."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7007' AND answer = 0;
UPDATE questions SET why = 'According to the endosymbiont theory, chloroplasts and mitochondria came from prokaryotes that were engulfed by an early host cell. Like bacteria, chloroplasts have their own circular DNA with no histone proteins, have 70S ribosomes and divide by a fission-like process. These shared features support the theory.', wrong = '{"0": "Neither bacteria nor chloroplasts have a nucleus. A double-membrane nucleus is a feature of eukaryotic cells.", "1": "Bacteria and chloroplasts both have 70S ribosomes. 80S ribosomes are found in the cytoplasm of eukaryotic cells.", "3": "Bacterial cell walls are made of peptidoglycan, and chloroplasts have no wall at all. Cellulose walls belong to plant cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7008' AND answer = 2;
UPDATE questions SET why = 'Centrioles, no cell wall, many small vacuoles and glycogen as the stored carbohydrate together point to an animal cell. Plant cells have a cellulose wall, one large central vacuole and store starch. Bacteria have no membrane-bound organelles, and fungi have a chitin wall.', wrong = '{"1": "A plant mesophyll cell has a cellulose wall, a large central vacuole and chloroplasts, and stores starch, not glycogen.", "2": "A bacterial cell has a peptidoglycan wall and no centrioles or membrane-bound vacuoles.", "3": "Fungi do store glycogen, but their hyphae are surrounded by a cell wall made of chitin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7009' AND answer = 0;
UPDATE questions SET why = 'The nucleolus is the part of the nucleus that makes ribosomal RNA and assembles ribosome subunits. A cell that makes a lot of protein needs many ribosomes, so its nucleolus becomes large and prominent. Examples are actively secreting gland cells.', wrong = '{"0": "The nucleolus disappears during cell division, so a large nucleolus is not a sign that the cell is about to divide.", "1": "Lipid storage does not need extra ribosomes, so it is not linked to a large nucleolus.", "3": "Cells undergoing programmed death shut down synthesis, and their nuclei shrink and break into fragments."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7010' AND answer = 2;
UPDATE questions SET why = 'The Krebs cycle, the electron transport chain and β-oxidation all take place in mitochondria. Without mitochondria, red blood cells make ATP only by glycolysis in the cytoplasm. They turn pyruvate into lactate, which regenerates the NAD⁺ needed to keep glycolysis running.', wrong = '{"0": "The Krebs cycle takes place only in the mitochondrial matrix, so it cannot run in a cell without mitochondria.", "1": "Oxidative phosphorylation needs the inner mitochondrial membrane. Red cells carry oxygen for other tissues, not for their own respiration.", "3": "β-oxidation of fatty acids also takes place in mitochondria, so red blood cells cannot use it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7011' AND answer = 2;
UPDATE questions SET why = 'Peroxisomes are small vesicles that contain oxidase enzymes. These oxidise substances such as fatty acids and alcohol and produce hydrogen peroxide (H₂O₂), which is toxic. Peroxisomes also contain catalase, which at once breaks H₂O₂ down into water and oxygen.', wrong = '{"1": "Lysosomes contain hydrolytic enzymes for digestion inside the cell, not oxidases and catalase.", "2": "Mitochondria carry out aerobic respiration to make ATP. Breaking down H₂O₂ with catalase is the job of peroxisomes.", "3": "The Golgi apparatus modifies, sorts and packages proteins and lipids. It does not break down H₂O₂."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7012' AND answer = 0;
UPDATE questions SET why = 'Cell wall layers form from the outside inwards. The middle lamella forms first between neighbouring cells, and each cell then lays down its primary wall inside it. The thick secondary wall is added last, on the inner side of the primary wall, between the primary wall and the plasma membrane.', wrong = '{"1": "The cell lays down wall material on its inner side, next to the plasma membrane, not outside the primary wall.", "2": "The primary wall lies directly against the middle lamella, with no other layer between them.", "3": "The middle lamella is the outermost layer, shared between neighbouring cells. No cell wall layer lies outside it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7013' AND answer = 0;
UPDATE questions SET why = 'Secretory proteins are made on the rough ER and leave it in vesicles that travel to the cis face of the Golgi. If budding of these vesicles is blocked, the newly made proteins cannot leave. They pile up inside the lumen of the rough ER and never reach the Golgi.', wrong = '{"0": "Proteins cannot leave the ER, so they never reach the Golgi and cannot build up at its trans face.", "1": "Secretion would fall, not rise, because proteins cannot get past the first step of the route out.", "3": "Blocking vesicle budding does not change the signal that directs these proteins to be made on the rough ER."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7014' AND answer = 2;
UPDATE questions SET why = 'A chain of n amino acids has n − 1 peptide bonds, and each bond releases one water molecule. With two separate chains, one bond fewer forms in each chain. So bonds = 250 − 2 = 248, and 248 water molecules are released.', wrong = '{"0": "249 treats the protein as one single chain of 250 amino acids, ignoring that there are two chains.", "1": "250 counts one peptide bond for every amino acid. The last amino acid of each chain has no partner after it.", "2": "125 simply halves the total. It confuses the number of amino acids per chain with the number of bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7015' AND answer = 3;
UPDATE questions SET why = 'Sucrose is made of glucose and fructose. Glucose is an aldose, with an aldehyde group, and fructose is a ketose, with a ketone group. So hydrolysis of sucrose gives two different monosaccharides, one of them a ketose.', wrong = '{"1": "Lactose gives glucose and galactose. These are different sugars, but both are aldoses.", "2": "Maltose gives two molecules of glucose, so its products are neither different nor a ketose.", "3": "Cellobiose, a breakdown product of cellulose, gives two molecules of glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7016' AND answer = 0;
UPDATE questions SET why = 'Starch is made of α-glucose units joined by α-1,4 bonds (with α-1,6 branches), which human amylase can break. Cellulose is made of β-glucose units joined by β-1,4 bonds. Humans make no cellulase, the enzyme needed to break β-1,4 bonds, so cellulose passes through undigested as fibre.', wrong = '{"0": "α-1,4 bonds are the bonds of starch, and amylase breaks them easily. Cellulose does not have them.", "2": "Cellulose is unbranched. α-1,6 branch points occur in amylopectin and glycogen, which humans can digest.", "3": "Cellulose is made only of glucose units. It contains no fructose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7017' AND answer = 1;
UPDATE questions SET why = 'Enzymes remove glucose units one at a time from the ends of glycogen chains. Heavy branching gives a glycogen molecule many chain ends, so many enzymes can work on it at once. This lets liver and muscle release glucose quickly when energy is suddenly needed.', wrong = '{"0": "Glycogen is a polar carbohydrate. Branching does not make it soluble in lipids.", "2": "Branching speeds up enzyme action by giving more ends to attack. It does not protect glycogen from enzymes.", "3": "A good storage molecule should have little osmotic effect. Glycogen is large and insoluble for this reason, so raising osmotic pressure is not an advantage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7018' AND answer = 1;
UPDATE questions SET why = 'Specific heat capacity is the heat needed to raise the temperature of 1 g of a substance by 1 °C. In water, much of the heat is first used to break hydrogen bonds between molecules, so water absorbs a lot of heat with only a small rise in temperature. Body water therefore keeps temperature steady despite metabolic heat.', wrong = '{"1": "Water''s maximum density at 4 °C explains why ice floats and ponds freeze from the top. It does not explain absorbing metabolic heat.", "2": "Ionisation of water into H⁺ and OH⁻ affects pH. It has nothing to do with absorbing heat.", "3": "Low viscosity lets water flow easily in blood vessels. It does not keep body temperature stable."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7019' AND answer = 0;
UPDATE questions SET why = 'A triglyceride forms by condensation. Each of the three –OH groups of glycerol reacts with the –COOH group of one fatty acid, forming an ester bond and releasing one water molecule. Three fatty acids therefore give three ester bonds and three water molecules.', wrong = '{"1": "Glycosidic bonds join monosaccharides in carbohydrates. Glycerol and fatty acids are joined by ester bonds.", "2": "Three ester bonds form by three condensation reactions, and each releases one water, so three water molecules are released, not two.", "3": "Peptide bonds join amino acids in proteins. They are not found in lipids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7020' AND answer = 0;
UPDATE questions SET why = 'A phospholipid has a hydrophilic (water-loving) phosphate head and two hydrophobic (water-hating) fatty acid tails, so it is amphipathic. In water, the molecules arrange themselves in two layers with heads facing the water on both sides and tails hidden inside. This is the lipid bilayer.', wrong = '{"0": "A molecule that was hydrophilic at both ends would simply dissolve in water and would not form a bilayer.", "1": "This is reversed. The fatty acid tails are non-polar and the phosphate head is polar and charged.", "2": "Glycerol with three fatty acids is a triglyceride. It is fully hydrophobic and forms oil droplets, not bilayers."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7021' AND answer = 3;
UPDATE questions SET why = 'Heat denatures an enzyme by breaking the weak bonds that hold its 3D shape: hydrogen bonds, ionic bonds and hydrophobic interactions. The protein unfolds and the active site is lost. The strong covalent peptide bonds of the primary structure are not broken, so the amino acid sequence stays the same.', wrong = '{"0": "Hydrogen bonds hold the α-helices, β-sheets and folding of a protein. They are weak and break easily on heating.", "2": "Ionic bonds between charged side chains help hold the tertiary structure and are disrupted by heat.", "3": "Hydrophobic interactions that keep non-polar side chains inside the protein are disrupted when it unfolds on heating."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7022' AND answer = 1;
UPDATE questions SET why = 'Quaternary structure exists only when a protein is made of two or more polypeptide chains held together. Haemoglobin has four chains, two α and two β, each carrying a haem group. So it shows quaternary structure.', wrong = '{"1": "Myoglobin is a single polypeptide chain with one haem group, so its highest level is tertiary structure.", "2": "Ribonuclease is a single folded polypeptide chain, so it has tertiary but not quaternary structure.", "3": "A single α-helix is secondary structure, a coil held by hydrogen bonds within one chain."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7023' AND answer = 0;
UPDATE questions SET why = 'A sugar is reducing when it has a free carbonyl group, at C-1 of glucose or C-2 of fructose, that can reduce Benedict''s reagent. In sucrose the glycosidic bond joins C-1 of glucose to C-2 of fructose, so both reducing groups are used up in the bond. Maltose keeps one free C-1, so it is reducing.', wrong = '{"0": "Glucose joined to galactose is lactose, not sucrose. Lactose is a reducing sugar.", "2": "Sucrose still has many free –OH groups. What is blocked are the reducing carbonyl carbons of both sugars.", "3": "Sugars are joined by glycosidic bonds. Peptide bonds join amino acids in proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7024' AND answer = 1;
UPDATE questions SET why = 'Chargaff''s rule that A equals T (or U) and G equals C holds because bases pair across two strands. Most RNA is a single strand, so its bases are not all paired, and their amounts need not match. A sample with 20% A and 30% U is therefore possible.', wrong = '{"0": "A must equal U only if the RNA were fully double stranded. Single-stranded RNA has no such rule.", "1": "In a double-stranded molecule A would equal U. Here A is 20% and U is 30%, so the molecule is not fully double stranded.", "2": "RNA contains uracil in place of thymine. The four percentages already add up to 100%."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7025' AND answer = 3;
UPDATE questions SET why = 'In double-stranded DNA, A pairs with T and G pairs with C, so A = T and G = C. A = T = 18%, so A + T = 36%. The remaining 100 − 36 = 64% is G + C, and since G = C, cytosine = 64 ÷ 2 = 32%.', wrong = '{"1": "18% is the value for thymine, which equals adenine. It is not the cytosine value.", "2": "36% is A + T together. The question asks for cytosine.", "3": "64% is G + C together. It must be halved to get cytosine alone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7026' AND answer = 0;
UPDATE questions SET why = 'An A–T pair is held by 2 hydrogen bonds and a G–C pair by 3. Of the 100 pairs, 30 are A–T, so 70 are G–C. Hydrogen bonds = (30 × 2) + (70 × 3) = 60 + 210 = 270.', wrong = '{"1": "230 comes from swapping the values: 30 × 3 + 70 × 2 = 90 + 140. A–T pairs have 2 bonds and G–C pairs have 3.", "2": "250 gives every pair an average of 2.5 bonds, which ignores that G–C pairs outnumber A–T pairs here.", "3": "300 gives every pair 3 bonds. Only the 70 G–C pairs have 3; the A–T pairs have 2."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7027' AND answer = 0;
UPDATE questions SET why = 'The A and B antigens are short chains of sugars (oligosaccharides) that stick out from the red cell surface. These chains are attached to membrane lipids and proteins, forming glycolipids and glycoproteins. The A and B antigens differ only in the last sugar on the chain, and they act as recognition markers.', wrong = '{"0": "ABO antigens are defined by their sugar chains, so a phospholipid head with no sugar cannot be the antigen.", "1": "Cholesterol sits within the bilayer and helps control fluidity. It does not carry the ABO sugar chains.", "2": "Nucleic acids are found inside cells. They are not exposed on the red cell surface, and mature red cells lack a nucleus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7028' AND answer = 3;
UPDATE questions SET why = 'Malonate has a shape similar to succinate, so it binds to the active site of succinate dehydrogenase and blocks it. This is competitive inhibition, because the inhibitor and substrate compete for the same site. Raising the succinate concentration lets the substrate win the active site more often, so the rate recovers.', wrong = '{"0": "At 60 °C the enzyme starts to denature, which lowers its activity further instead of removing the inhibition.", "1": "Adding more malonate gives the inhibitor more chances to occupy the active site, so inhibition increases.", "3": "A sharp drop in pH moves the enzyme away from its optimum pH and lowers its activity even more."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7029' AND answer = 2;
UPDATE questions SET why = 'A non-competitive inhibitor binds at a site other than the active site and changes the shape of the enzyme. The substrate no longer fits well, and adding more substrate cannot push the inhibitor off because they do not compete for the same site. So the maximum rate stays low however much substrate is added.', wrong = '{"0": "Competitive inhibition can be overcome by a large excess of substrate, which restores the maximum rate. Here it is not restored.", "1": "A coenzyme helps the enzyme work by carrying groups or electrons. It does not lower the rate.", "3": "A metal ion activator increases enzyme activity, so it cannot explain a lower rate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7030' AND answer = 2;
UPDATE questions SET why = 'When substrate is in large excess, every active site is already occupied, so the enzyme is saturated. The rate is now limited by the number of enzyme molecules. Adding more enzyme provides more active sites, so more reactions happen each second and the rate rises.', wrong = '{"0": "All active sites are already busy, so more substrate cannot speed up the reaction.", "1": "A competitive inhibitor takes up active sites and lowers the rate.", "2": "Cooling lowers the kinetic energy of molecules, so they collide less often and the rate falls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7031' AND answer = 3;
UPDATE questions SET why = 'Low temperature only slows the movement of molecules, so fewer collisions occur, but the enzyme''s shape is unharmed. When warmed to 37 °C, the cold sample works again. At 70 °C the enzyme is denatured: its 3D shape and active site are permanently lost, so it does not recover on cooling.', wrong = '{"0": "This is reversed. Heat denaturation is permanent, while inactivation by cold is reversed on warming.", "1": "The sample heated to 70 °C has been denatured, and denaturation is not undone by cooling.", "3": "Cold does not destroy the active site, so the sample kept at 5 °C does recover at 37 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7032' AND answer = 2;
UPDATE questions SET why = 'Pepsin works best at an acidic pH of about 2, as in the stomach. In the duodenum, alkaline pancreatic juice and bile raise the pH. This changes the charges on groups in pepsin''s active site, so the substrate no longer binds well and pepsin stops working.', wrong = '{"0": "The stomach and duodenum are both at body temperature, about 37 °C.", "2": "Amylase is a carbohydrase that digests starch. It does not digest proteins such as pepsin.", "3": "Much protein is still undigested when chyme enters the duodenum. Trypsin continues its digestion there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7033' AND answer = 1;
UPDATE questions SET why = 'Koshland''s induced fit model says the active site is flexible. When the substrate binds, the active site changes shape slightly to fit it closely. This explains why some enzymes can act on a few related substrates. The rigid lock and key model explains only strict specificity for one substrate.', wrong = '{"0": "Action on only one substrate (absolute specificity) is what the rigid lock and key model explains well.", "1": "Denaturation at high temperature is explained equally well by both models, because both depend on the enzyme''s shape.", "2": "Binding of competitive inhibitors to the active site is explained by both models."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7034' AND answer = 3;
UPDATE questions SET why = 'Dialysis removes small molecules that are not firmly attached, while large proteins stay behind. The enzyme lost activity when these were removed and regained it when they were added back. So it needs a small, loosely bound cofactor, such as a coenzyme or a metal ion activator, to work.', wrong = '{"0": "A prosthetic group is tightly bound to the protein, so it would stay with the enzyme during dialysis.", "1": "Proteins are too large to pass through the dialysis membrane, so a second enzyme would not have been removed.", "2": "Dialysis does not change the temperature. Activity was restored by adding back the removed small molecules."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7035' AND answer = 3;
UPDATE questions SET why = 'A prosthetic group is a non-protein organic cofactor that is tightly and permanently attached to the enzyme. Haem in catalase is an example. Coenzymes such as NAD⁺, by contrast, bind loosely and separate from the enzyme after each reaction.', wrong = '{"0": "A coenzyme is an organic cofactor that binds loosely and can move between enzymes, so it is not permanently bound.", "2": "An activator is an inorganic ion, such as Mg²⁺ or Zn²⁺, not an organic group.", "3": "The apoenzyme is the protein part of the enzyme without its cofactor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7036' AND answer = 1;
UPDATE questions SET why = 'Enzymes lower the activation energy of both the forward and the reverse reaction by the same amount. So both reactions speed up equally. The enzyme helps the reaction reach equilibrium faster, but at equilibrium it does not change the amounts of reactant and product.', wrong = '{"0": "A catalyst speeds up the forward and reverse reactions equally, so it cannot shift equilibrium towards products.", "2": "A catalyst cannot shift equilibrium towards reactants either. The proportions stay the same.", "3": "Enzymes lower activation energy in both directions. They do not raise it for the reverse reaction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7037' AND answer = 1;
UPDATE questions SET why = 'In feedback inhibition, the end product of a pathway slows an earlier enzyme, usually the first one. D binds to a regulatory (allosteric) site on the first enzyme, not to its active site, because D does not resemble A. This switches the pathway off when enough D is present and prevents waste.', wrong = '{"0": "Here it is the end product D that inhibits the first enzyme, not A inhibiting the last.", "2": "Feedback inhibition is reversible. As D is used up, it leaves the enzyme and the pathway starts again.", "3": "Substrate-level phosphorylation is a way of making ATP, not a way of regulating a pathway."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7038' AND answer = 1;
UPDATE questions SET why = 'Acetylcholinesterase normally breaks down acetylcholine in the synaptic cleft soon after each impulse. Organophosphates block this enzyme permanently. Acetylcholine then builds up and keeps stimulating the muscle, so muscles go into spasm and cannot relax.', wrong = '{"0": "Release of acetylcholine from nerve endings is not affected. Its breakdown after release is what is blocked.", "2": "Nerve impulses still start and travel along axons normally. The problem is at the synapse.", "3": "Muscles are over-stimulated and keep contracting at first. They are not unable to contract."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7039' AND answer = 1;
UPDATE questions SET why = 'At high substrate concentration every active site is occupied at any moment, so the enzyme is saturated. Adding more substrate cannot make the reaction any faster, because substrate has to wait for a free active site. The curve levels off at the maximum rate.', wrong = '{"0": "Substrate is plentiful at the plateau. The level part appears at high substrate concentration.", "2": "Substrate concentration does not denature enzymes. Heat or extreme pH does.", "3": "Product keeps forming at the plateau, at the enzyme''s maximum rate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7040' AND answer = 1;
UPDATE questions SET why = 'Fatty acids are long hydrocarbon chains with many C–H bonds and very little oxygen. When they are oxidised, they give many hydrogen atoms to NAD⁺ and FAD, forming much NADH and FADH₂. These feed the electron transport chain, which makes much more ATP per gram than from carbohydrate.', wrong = '{"0": "Fats can only be respired aerobically, through β-oxidation, the Krebs cycle and the electron transport chain.", "1": "Triglycerides contain no phosphate groups. Phosphate groups are found in phospholipids.", "3": "Fatty acids are broken down by β-oxidation in mitochondria, not in glycolysis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7041' AND answer = 2;
UPDATE questions SET why = 'A triglyceride is first split into glycerol and fatty acids. Glycerol is phosphorylated and converted into the 3-carbon sugar phosphate PGAL (phosphoglyceraldehyde), which is an intermediate of glycolysis, and it continues along that pathway. Fatty acids enter separately as acetyl CoA after β-oxidation.', wrong = '{"1": "Acetyl CoA is made from fatty acids by β-oxidation. Glycerol enters earlier, at glycolysis.", "2": "Glycerol does not enter as oxaloacetate or any other Krebs cycle acid.", "3": "Glycerol is not changed into fatty acids for respiration. Fatty acids are the other product of triglyceride breakdown."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7042' AND answer = 0;
UPDATE questions SET why = 'Amino acids contain an amino group (–NH₂) that cannot be respired. In the liver, deamination removes this group as ammonia, which is converted into urea. The remaining carbon skeleton then enters respiration as pyruvate, acetyl CoA or a Krebs cycle intermediate.', wrong = '{"0": "β-oxidation is the pathway that breaks down fatty acids, not amino acids.", "2": "Phosphorylation by ATP is not the first step for amino acids. The amino group must be removed first.", "3": "Glycerol comes from the breakdown of fats, not from proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7043' AND answer = 1;
UPDATE questions SET why = 'Respiratory quotient (RQ) = CO₂ released ÷ O₂ used. Fats contain very little oxygen, so they need much more O₂ to oxidise than the CO₂ they release, giving an RQ of about 0.7. Carbohydrates give an RQ of 1.0 and proteins about 0.8 to 0.9.', wrong = '{"1": "Carbohydrate releases equal volumes of CO₂ and uses equal volumes of O₂, so its RQ is 1.0.", "2": "Protein gives an RQ of about 0.8 to 0.9, higher than the value measured here.", "3": "Anaerobic respiration uses no O₂, so its RQ cannot be 0.7. In yeast, which releases CO₂ without using O₂, the RQ is very high."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7044' AND answer = 0;
UPDATE questions SET why = 'Glucose has 6 carbon atoms, and all of them leave as CO₂ in aerobic respiration. In the link reaction each pyruvate loses one CO₂, giving 2 per glucose. In the Krebs cycle each acetyl group loses two CO₂, giving 4 per glucose. Total = 2 + 4 = 6 CO₂, matching the 6 carbons of glucose.', wrong = '{"0": "4 counts only the CO₂ from two turns of the Krebs cycle and leaves out the 2 from the link reaction.", "1": "2 counts only the link reaction and leaves out the 4 CO₂ from the Krebs cycle.", "3": "3 is the total for one pyruvate (1 + 2). One glucose gives two pyruvates."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7045' AND answer = 2;
UPDATE questions SET why = 'One turn of the Krebs cycle, for one acetyl CoA, gives 3 NADH, 1 FADH₂, 1 ATP (via GTP) and 2 CO₂. One glucose makes two acetyl CoA, so the cycle turns twice. Doubling gives 6 NADH, 2 FADH₂, 2 ATP and 4 CO₂ per glucose.', wrong = '{"0": "These are the products of one turn of the cycle, for one acetyl CoA. A glucose molecule gives two turns.", "2": "This wrongly adds the 2 NADH and 2 CO₂ of the link reaction, which the question excludes.", "3": "The Krebs cycle gives 2 ATP and 4 CO₂ per glucose, not 4 ATP and 6 CO₂."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7046' AND answer = 1;
UPDATE questions SET why = 'Cytochrome oxidase is the last carrier of the chain and passes electrons to oxygen, forming water. Cyanide blocks it, so electrons cannot reach oxygen and the whole chain stops. No protons are pumped, so ATP synthesis by mitochondria stops and oxygen is no longer used.', wrong = '{"0": "Oxygen is used only when cytochrome oxidase passes electrons to it. Once it is blocked, oxygen use falls to nearly zero.", "2": "Glycolysis takes place in the cytoplasm and can continue for a while anaerobically, so it does not stop at once.", "3": "NADH cannot be reoxidised to NAD⁺ when the chain is blocked, so the Krebs cycle slows rather than speeds up."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7047' AND answer = 1;
UPDATE questions SET why = 'ATP synthase makes ATP when H⁺ ions flow back into the matrix through it. If the inner membrane leaks H⁺, the ions return without passing through ATP synthase, and the proton gradient collapses. Electron transport and oxygen use carry on, but little ATP is made and the energy is lost as heat. This is called uncoupling.', wrong = '{"0": "Electron transport is not blocked by a leaky membrane. It continues and may even speed up.", "2": "The protons bypass ATP synthase through the leaks, so less ATP is made, not more.", "3": "Oxygen use continues because electrons still flow to oxygen. It is ATP synthesis that fails."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7048' AND answer = 1;
UPDATE questions SET why = 'Glycolysis needs a steady supply of NAD⁺ to accept hydrogen. When oxygen is short, NADH cannot pass its hydrogen to the electron transport chain. Muscle cells instead reduce pyruvate to lactate using NADH, which regenerates NAD⁺. Glycolysis can then keep making its 2 ATP per glucose.', wrong = '{"0": "The conversion of pyruvate to lactate makes no ATP. The only ATP comes from glycolysis itself.", "1": "Lactic acid fermentation releases no CO₂. CO₂ is released in alcoholic fermentation by yeast.", "3": "Lactate is a by-product that is carried to the liver for processing. It is not a way to store energy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7049' AND answer = 2;
UPDATE questions SET why = 'In yeast, pyruvate (3C) first loses CO₂ to form acetaldehyde (2C). Acetaldehyde then accepts hydrogen from NADH and is reduced to ethanol. This step regenerates NAD⁺ so that glycolysis can continue without oxygen.', wrong = '{"0": "In yeast, pyruvate is first decarboxylated to acetaldehyde. Direct reduction of pyruvate by NADH happens in lactic acid fermentation.", "2": "Ethanol is the product formed when acetaldehyde is reduced. It is not the molecule that accepts hydrogen.", "3": "CO₂ is released when pyruvate is decarboxylated. It is not reduced in fermentation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7050' AND answer = 1;
UPDATE questions SET why = 'In substrate-level phosphorylation, a phosphate group is passed directly from a substrate molecule to ADP (or GDP), with no electron transport chain involved. In the Krebs cycle this happens when succinyl CoA is converted to succinate, giving one ATP (via GTP). It also happens at two steps of glycolysis.', wrong = '{"0": "ATP synthase uses the flow of protons to make ATP. This is oxidative phosphorylation by chemiosmosis.", "1": "Passing electrons along the chain releases energy that pumps protons, but this step does not itself form ATP.", "3": "Reducing oxygen to water is the final step of the electron transport chain. It forms water, not ATP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7051' AND answer = 2;
UPDATE questions SET why = 'All the oxygen gas released in photosynthesis comes from splitting water (photolysis). The oxygen atoms of CO₂ are fixed in the Calvin cycle and end up in the carbohydrate made, and in some water formed. So ¹⁸O from labelled CO₂ appears in the carbohydrate, not in the oxygen released.', wrong = '{"0": "The O₂ released comes from water, so it would carry the label only if the water, not the CO₂, were labelled.", "2": "The O₂ released is not labelled, because it comes only from water, which was ordinary here.", "3": "The oxygen of CO₂ is not lost as water vapour. It is fixed into the sugars made in the Calvin cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7052' AND answer = 1;
UPDATE questions SET why = 'Fixing one CO₂ in the Calvin cycle uses 3 ATP and 2 NADPH. A glucose molecule has 6 carbons, so 6 CO₂ must be fixed. ATP = 6 × 3 = 18 and NADPH = 6 × 2 = 12.', wrong = '{"0": "The numbers are swapped. The cycle uses more ATP (18) than NADPH (12).", "2": "6 ATP and 6 NADPH is far too little. Each of the 6 CO₂ fixed needs 3 ATP and 2 NADPH.", "3": "3 ATP and 2 NADPH is the cost of fixing one CO₂, not of making a whole glucose molecule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7053' AND answer = 1;
UPDATE questions SET why = 'By Blackman''s law of limiting factors, the rate of photosynthesis is controlled by the factor in shortest supply. Extra light made no difference, but extra CO₂ raised the rate. So CO₂ concentration was the limiting factor at this point.', wrong = '{"0": "More light had no effect on the rate, which shows light was already in excess and not limiting.", "1": "Chlorophyll concentration was not changed in the experiment, so there is no evidence it was limiting.", "3": "Water supply was not changed. Only raising CO₂ increased the rate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7054' AND answer = 2;
UPDATE questions SET why = 'RuBP combines with CO₂ to form PGA, and PGA is reduced using ATP and NADPH from the light reactions to regenerate RuBP. In the dark, ATP and NADPH quickly run out, so PGA cannot be reduced and RuBP is not regenerated. Fixation of CO₂ continues briefly, using up RuBP, so RuBP falls and PGA rises.', wrong = '{"1": "RuBP rising and PGA falling is what happens when CO₂, not light, is cut off.", "2": "RuBP is used up in fixing CO₂ and is not replaced in the dark, so it cannot rise.", "3": "PGA does not fall. It builds up because it cannot be reduced without ATP and NADPH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7055' AND answer = 0;
UPDATE questions SET why = 'Cyclic photophosphorylation needs only photosystem I. Electrons excited from P700 pass along the electron transport chain and return to photosystem I, making ATP on the way. Since it does not need photosystem II, water splitting or NADP⁺, it can still run when photosystem II is blocked.', wrong = '{"0": "Non-cyclic photophosphorylation needs photosystem II to pass electrons from water, so it stops when photosystem II is blocked.", "1": "Splitting of water and release of oxygen happen at photosystem II, so they stop.", "2": "Electrons from water reach NADP⁺ only by passing through photosystem II first, so this transfer stops."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7056' AND answer = 3;
UPDATE questions SET why = 'HIV is a retrovirus. Its enzyme reverse transcriptase copies the viral RNA into DNA, which then joins the host chromosome. AZT looks like a normal nucleotide, so it is built into the growing DNA chain, but no more nucleotides can be added after it. The DNA copy is never finished, and the virus cannot multiply.', wrong = '{"0": "Blocking the binding of gp120 to CD4 is how entry inhibitors work, a different class of drug.", "1": "Uncoating of the capsid is not the target of nucleotide analogues such as AZT.", "2": "Blocking the host''s ribosomes would stop protein synthesis in all the patient''s cells and be very toxic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7057' AND answer = 3;
UPDATE questions SET why = 'Helper T cells, which carry the CD4 receptor, coordinate specific immunity. They release chemical signals (cytokines) that activate B cells to make antibodies and activate cytotoxic T cells to kill infected cells. When HIV destroys helper T cells, both antibody-mediated and cell-mediated immunity fail.', wrong = '{"0": "Antibodies are made by plasma cells, which develop from B lymphocytes, not by helper T cells.", "1": "The main phagocytes in blood are neutrophils and monocytes (which become macrophages). Helper T cells are not phagocytes.", "2": "Bone marrow contains many types of cells. Helper T cells form there but mature in the thymus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7058' AND answer = 3;
UPDATE questions SET why = 'In the lysogenic cycle, phage DNA joins the bacterial chromosome as a prophage and is copied along with it. Stress such as UV damage to DNA can trigger the prophage to cut itself out. It then enters the lytic cycle, directing the cell to make new phages, and the cell bursts to release them.', wrong = '{"0": "Stress such as UV light releases the prophage from the chromosome. It does not fix it in place.", "1": "A lysogenic bacterium resists only the same kind of phage, and UV induction ends lysogeny anyway.", "3": "The phage DNA is copied many times during the lytic cycle. It is not broken down by the host."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7059' AND answer = 2;
UPDATE questions SET why = 'An enveloped virus such as influenza gets its envelope when new virus particles bud out through the host cell''s plasma membrane. So the envelope is a lipid bilayer from the host. Virus-coded glycoproteins, such as haemagglutinin and neuraminidase in influenza, are inserted into it as spikes.', wrong = '{"0": "Viruses do not code for making lipids. The lipid of the envelope comes from the host cell membrane.", "1": "Peptidoglycan is found only in bacterial cell walls. No virus has a peptidoglycan wall.", "2": "The envelope is a lipid membrane lying outside the capsid. It is not a second protein capsid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7060' AND answer = 3;
UPDATE questions SET why = 'Viruses are obligate intracellular parasites. They contain only nucleic acid inside a protein coat and lack ribosomes and the enzymes needed for their own metabolism. They can multiply only by taking over a living host cell''s machinery, so sterile nutrient agar cannot support them.', wrong = '{"0": "Size is not the reason. Viruses cannot multiply anywhere outside living cells.", "1": "Glucose in agar does not kill viruses. They simply cannot use it, because they have no metabolism of their own.", "2": "Viruses multiply at the normal temperature of their host. A temperature above 60 °C would destroy most of them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7061' AND answer = 3;
UPDATE questions SET why = 'Herpes simplex virus is an enveloped virus whose genome is double-stranded DNA. HIV, influenza virus and poliovirus all have single-stranded RNA genomes. So herpes simplex is the only dsDNA virus in the list.', wrong = '{"1": "HIV is a retrovirus with single-stranded RNA, which it copies into DNA using reverse transcriptase.", "2": "Influenza virus has a single-stranded RNA genome split into several segments.", "3": "Poliovirus has a single strand of RNA as its genome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7062' AND answer = 0;
UPDATE questions SET why = 'Complex viruses combine more than one shape. Bacteriophage T4 has a polyhedral (icosahedral) head holding its DNA, attached to a helical tail with tail fibres used to attach to a bacterium. This combination makes it a complex virus.', wrong = '{"0": "Tobacco mosaic virus is a rod-shaped helical virus with RNA, and it has no head or tail.", "1": "Influenza virus is an enveloped virus with spikes on its surface. It has no head and tail.", "2": "Poliovirus is a small naked icosahedral virus with RNA, without a tail."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7063' AND answer = 3;
UPDATE questions SET why = 'Prions are infectious agents made only of misfolded protein, with no nucleic acid. Enzymes that digest nucleic acids cannot harm them, but enzymes that digest protein can inactivate them. They cause fatal brain diseases such as Creutzfeldt-Jakob disease.', wrong = '{"0": "A viroid is a small naked RNA molecule, so nucleic acid-digesting enzymes would destroy it.", "1": "A DNA virus would be inactivated when nucleases break down its DNA genome.", "3": "A bacteriophage infects bacteria, not the brain, and contains nucleic acid that nucleases could attack."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7064' AND answer = 2;
UPDATE questions SET why = 'When the ventricles begin to contract, their pressure rises above atrial pressure and the AV valves close. For a short time the pressure is still below that in the aorta and pulmonary artery, so the semilunar valves also stay shut. The ventricles contract with no change in blood volume: isovolumetric contraction.', wrong = '{"0": "During atrial systole the atria push blood into the ventricles through open AV valves.", "1": "During ventricular ejection the semilunar valves are open and blood leaves the ventricles.", "3": "During ventricular filling the AV valves are open and blood flows in from the atria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7065' AND answer = 2;
UPDATE questions SET why = 'The first heart sound, lub, is heard when the ventricles start to contract. The rising ventricular pressure snaps the atrioventricular valves (tricuspid and bicuspid) shut, and this produces the longer, lower sound. The second sound, dub, comes from closure of the semilunar valves.', wrong = '{"0": "Closure of the semilunar valves at the end of ventricular systole produces the second sound, dub.", "2": "Opening of heart valves is silent in a normal heart. Heart sounds come from valves closing.", "3": "Atrial contraction is normally not heard. It does not produce the first heart sound."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7066' AND answer = 1;
UPDATE questions SET why = 'Cardiac output is the volume of blood pumped by one ventricle per minute. Cardiac output = heart rate × stroke volume = 75 × 80 = 6000 cm³ per minute. Since 1 dm³ = 1000 cm³, this is 6.0 dm³ per minute.', wrong = '{"0": "155 comes from adding 75 + 80. The two values must be multiplied, not added.", "2": "0.94 comes from dividing heart rate by stroke volume, 75 ÷ 80. The correct step is to multiply.", "3": "60 dm³ is ten times too large. 6000 cm³ equals 6.0 dm³, not 60 dm³."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7067' AND answer = 1;
UPDATE questions SET why = 'Blood picks up oxygen in the lungs. The pulmonary veins carry this freshly oxygenated blood from the lungs to the left atrium, so they carry blood with the highest oxygen content. They are the only veins in the adult body that carry oxygenated blood.', wrong = '{"0": "The pulmonary artery carries deoxygenated blood from the right ventricle to the lungs, the only artery that does so.", "1": "The inferior vena cava returns deoxygenated blood from the lower body to the right atrium.", "3": "The coronary sinus drains deoxygenated blood from the heart muscle into the right atrium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7068' AND answer = 2;
UPDATE questions SET why = 'At the arterial end of a capillary, blood pressure pushes fluid out into the tissues. At the venous end, the osmotic pull of plasma proteins draws most of it back. With very low plasma protein, this pull is weak, so less fluid returns and more stays in the tissues than the lymph vessels can drain. The tissues swell.', wrong = '{"0": "Low plasma protein does not stop the heart from producing blood pressure at the arterial end of capillaries.", "1": "Lymph vessels drain excess tissue fluid back to the blood. They do not secrete fluid.", "2": "Red blood cells stay inside the vessels. Oedema is a build-up of fluid, not of cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7069' AND answer = 3;
UPDATE questions SET why = 'Each capillary is very narrow, but there are billions of them, so their combined cross-sectional area is far larger than that of the arteries. The same volume of blood per minute spread over a much larger total area must move more slowly. Slow flow gives time for exchange of materials with the tissues.', wrong = '{"0": "Capillary walls are only one cell thick, with no muscle layer, which is what allows exchange.", "1": "Distance from the heart is not the reason. Blood speeds up again in veins, which are even farther along the circuit.", "3": "The viscosity of blood is about the same throughout the circulation, so it does not explain the slow flow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7070' AND answer = 2;
UPDATE questions SET why = 'The SA node starts each heartbeat, and the impulse spreads over the atria, making them contract. At the AV node the impulse is held back for about 0.1 s. This delay lets the atria finish contracting and fill the ventricles before the impulse passes down the bundle of His and Purkinje fibres to make the ventricles contract.', wrong = '{"0": "The semilunar valves open later, during ventricular ejection. The AV delay is not for them.", "1": "The SA node fires on its own regular rhythm. The AV delay is not a recovery period for it.", "2": "After the delay both ventricles do contract together. The delay only sets the timing after the atria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7071' AND answer = 3;
UPDATE questions SET why = 'Some fluid leaves blood capillaries and stays in the tissues. Lymph vessels normally collect this extra tissue fluid and return it to the blood in the veins. In filariasis the worms block the lymph vessels, so fluid builds up in the legs and they swell greatly, a condition called lymphoedema.', wrong = '{"0": "A burst artery causes bleeding, not the slow, long-term swelling of filariasis.", "1": "Red blood cells are made in red bone marrow, not in the tissues of the legs.", "2": "A rise in plasma protein would pull more fluid back into the blood, which would reduce swelling."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7072' AND answer = 3;
UPDATE questions SET why = 'The alveoli are lined by a thin film of water whose surface tension tends to make them collapse. Surfactant lowers this surface tension and keeps the alveoli open. The lungs make enough surfactant only late in fetal life, so very premature babies often lack it and their alveoli collapse, a condition called respiratory distress syndrome.', wrong = '{"0": "Fetal haemoglobin carries oxygen very well, even better than adult haemoglobin, so it is not the problem.", "1": "The diaphragm forms early in fetal development, long before birth.", "2": "The cartilage rings of the trachea are already present in premature babies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7073' AND answer = 3;
UPDATE questions SET why = 'Smoking causes long-term inflammation, and enzymes released by white blood cells destroy the thin walls between alveoli. Many small alveoli merge into fewer, larger air spaces, so the surface area for gas exchange falls sharply. The lungs also lose their elasticity, making it hard to breathe out.', wrong = '{"0": "Thick mucus blocking the airways is the main feature of chronic bronchitis, not emphysema.", "1": "Emphysema does not involve making too much surfactant. The problem is loss of alveolar walls.", "3": "The diaphragm is not paralysed in emphysema. It works, but the damaged lungs exchange gases poorly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7074' AND answer = 2;
UPDATE questions SET why = 'Quiet expiration is mostly passive. The diaphragm relaxes and returns to its dome shape, and the external intercostal muscles relax so the ribs move down and in. The stretched, elastic lungs recoil, the volume of the chest falls, pressure in the lungs rises above atmospheric pressure and air flows out.', wrong = '{"0": "The internal intercostal muscles contract strongly only in forced expiration, as during exercise or coughing.", "1": "Contraction and flattening of the diaphragm enlarges the chest during inspiration, not expiration.", "3": "The external intercostal muscles contract to raise the ribs during inspiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7075' AND answer = 2;
UPDATE questions SET why = 'Working muscles release more CO₂, which forms carbonic acid in the blood and raises the H⁺ concentration (lowers pH). Chemoreceptors in the medulla and in the carotid and aortic bodies detect this rise. They signal the breathing centre, which increases the rate and depth of breathing to remove the extra CO₂.', wrong = '{"0": "Blood oxygen does not rise during exercise. If anything it falls slightly as muscles use more O₂.", "2": "Blood pressure usually rises during exercise, and it is not the main signal for faster breathing.", "3": "Body temperature rises during exercise, not falls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7076' AND answer = 1;
UPDATE questions SET why = 'Active muscle respires fast, so it releases more CO₂, and the blood there becomes more acidic. Higher CO₂ and lower pH change the shape of haemoglobin and lower its affinity for oxygen, so it unloads more O₂. This is the Bohr effect, and it delivers more oxygen where it is most needed.', wrong = '{"0": "Haemoglobin is carried in red blood cells, and its iron content is the same in all tissues.", "1": "Active muscle is warmer, not cooler. Higher temperature also helps haemoglobin release oxygen.", "3": "Muscles do not produce carbon monoxide. Carbon monoxide comes from incomplete burning, as in smoking."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7077' AND answer = 2;
UPDATE questions SET why = 'About 70% of CO₂ is carried as hydrogen carbonate ions. In red blood cells, the enzyme carbonic anhydrase quickly combines CO₂ with water to form carbonic acid, which splits into H⁺ and HCO₃⁻. The HCO₃⁻ ions move out into the plasma and are carried to the lungs.', wrong = '{"0": "Carbaminohaemoglobin, CO₂ bound to haemoglobin, carries only about 20 to 23% of the CO₂.", "2": "Only a small part, about 7%, travels as CO₂ dissolved in plasma.", "3": "Carbonic acid splits into H⁺ and HCO₃⁻ almost at once, so it is not the main form in which CO₂ is carried."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7078' AND answer = 1;
UPDATE questions SET why = 'Bile salts emulsify fats into small droplets so lipase can digest them, and bile pigments give faeces their brown colour. If a gallstone blocks the common bile duct, no bile reaches the intestine. Fat is poorly digested and absorbed and passes out in the faeces, which are also pale.', wrong = '{"1": "Starch is digested by amylase from saliva and the pancreas, not by bile, so starch would not appear in the faeces.", "2": "Bile pigments darken faeces, so without bile the faeces become pale, not dark. Protein digestion does not depend on bile.", "3": "Bile has no digestive enzymes, but it is essential for emulsifying fats, so the faeces would change."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7079' AND answer = 0;
UPDATE questions SET why = 'When acidic chyme enters the duodenum, the duodenal wall releases the hormone secretin into the blood. Secretin makes the pancreas release a juice rich in hydrogen carbonate (HCO₃⁻). This alkaline juice neutralises stomach acid and gives pancreatic enzymes their optimum pH.', wrong = '{"1": "Secretin reduces acid secretion by the stomach rather than increasing it.", "2": "Contraction of the gall bladder is caused mainly by another duodenal hormone, cholecystokinin (CCK).", "3": "Secretion of saliva is controlled by nerves, not by secretin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7080' AND answer = 0;
UPDATE questions SET why = 'Trypsinogen is the inactive form of trypsin made by the pancreas. In the duodenum, the enzyme enterokinase (enteropeptidase), made by the intestinal lining, converts the first trypsinogen into active trypsin. Trypsin then activates more trypsinogen and other inactive pancreatic enzymes.', wrong = '{"0": "Pepsin becomes inactive at the alkaline pH of the duodenum and does not activate trypsinogen.", "2": "Hydrochloric acid activates pepsinogen to pepsin in the stomach, not trypsinogen.", "3": "Bile salts emulsify fats. They do not activate enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7081' AND answer = 1;
UPDATE questions SET why = 'Fatty acids and monoglycerides enter the epithelial cells of the villi and are rebuilt into triglycerides. These are coated with protein to form tiny droplets called chylomicrons, which pass into the lacteals, the lymph vessels of the villi. The lymph later carries them into the blood through the thoracic duct.', wrong = '{"0": "Glucose and amino acids go into the hepatic portal vein. Most fat enters the lymph first.", "2": "Most fat is carried as chylomicrons in the lymph, not as glycerol in blood capillaries.", "3": "Very little absorption happens in the stomach, and fats are absorbed in the small intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7082' AND answer = 1;
UPDATE questions SET why = 'Parietal (oxyntic) cells of the stomach secrete hydrochloric acid and intrinsic factor. Intrinsic factor binds vitamin B₁₂ and allows it to be absorbed in the ileum. Without most of the stomach, there is no intrinsic factor, B₁₂ is not absorbed, and pernicious anaemia develops unless B₁₂ is injected.', wrong = '{"0": "Pepsin digests proteins. It is not needed for absorbing vitamin B₁₂.", "1": "Mucus protects the stomach lining from acid and pepsin. It does not store vitamin B₁₂.", "3": "Gastrin is a hormone that stimulates acid secretion. It does not make red blood cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7083' AND answer = 2;
UPDATE questions SET why = 'The lipase that reaches the duodenum is made by the pancreas, not the liver, so this is NOT a liver function. The liver produces bile, which contains no enzymes. It also forms urea, stores glycogen and makes plasma proteins such as fibrinogen.', wrong = '{"1": "This is a liver function. The liver deaminates excess amino acids and turns the ammonia into urea through the ornithine cycle.", "2": "This is a liver function. Under the influence of insulin, the liver stores excess glucose as glycogen.", "3": "This is a liver function. Fibrinogen and most other plasma proteins are made in the liver."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7084' AND answer = 0;
UPDATE questions SET why = 'The A band is the region containing the thick myosin filaments, so its length equals the length of these filaments. During contraction, thin actin filaments slide over myosin towards the centre, and neither type of filament shortens. So the I band and H zone narrow and the sarcomere shortens, but the A band stays the same.', wrong = '{"1": "The I band contains only thin filaments and becomes shorter as they slide inward over myosin.", "2": "The H zone contains only thick filaments and becomes narrower, or disappears, as thin filaments slide in.", "3": "The whole sarcomere shortens during contraction as its Z lines are pulled closer together."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7085' AND answer = 0;
UPDATE questions SET why = 'At rest, tropomyosin covers the myosin-binding sites on actin. When a nerve impulse arrives, Ca²⁺ ions are released from the sarcoplasmic reticulum and bind to troponin. Troponin changes shape and moves tropomyosin aside, so the binding sites are exposed and myosin heads can attach to form cross-bridges.', wrong = '{"0": "Myosin heads split ATP themselves using their own ATPase activity. Ca²⁺ does not bind to them for this.", "1": "Cross-bridges are broken when a new ATP binds to the myosin head, not by calcium.", "3": "Acetylcholine, not Ca²⁺, binds to receptors on the sarcolemma at the neuromuscular junction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7086' AND answer = 2;
UPDATE questions SET why = 'A myosin head can only detach from actin when a new ATP molecule binds to it. After death, cells stop making ATP. The cross-bridges cannot break, so actin and myosin stay locked together and the muscles become stiff. This is rigor mortis.', wrong = '{"0": "After death calcium leaks out of the sarcoplasmic reticulum. Pumping it back needs ATP, which is no longer made.", "1": "Breakdown of the filaments by enzymes happens later and ends rigor mortis. It does not cause it.", "2": "Nerve activity stops at death, so acetylcholine is not released to keep stimulating the muscle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7087' AND answer = 3;
UPDATE questions SET why = 'Rheumatoid arthritis is an autoimmune disease. The immune system attacks the synovial membrane lining the joint, causing inflammation, and it often affects many small joints on both sides of the body. Osteoarthritis is instead the wearing down of articular cartilage with age and use.', wrong = '{"0": "Wear and tear of articular cartilage with age describes osteoarthritis, not rheumatoid arthritis.", "1": "Rheumatoid arthritis usually affects many small joints, such as those of the hands, on both sides of the body.", "2": "Uric acid crystals deposited in joints cause gout, a different form of arthritis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7088' AND answer = 3;
UPDATE questions SET why = 'Glucose is always filtered at the glomerulus, and normally carrier proteins in the proximal convoluted tubule reabsorb all of it. The number of carriers is limited. In untreated diabetes mellitus, blood glucose is so high that the filtered glucose saturates these carriers, and the excess stays in the filtrate and appears in urine.', wrong = '{"0": "Glucose is freely filtered at the glomerulus in healthy people too. The problem is reabsorption, not filtration.", "1": "The loop of Henle handles salt and water. It does not secrete glucose into the filtrate.", "2": "ADH controls water reabsorption in the collecting ducts. It has no role in reabsorbing glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7089' AND answer = 3;
UPDATE questions SET why = 'Plasma proteins are too large to pass through the healthy glomerular filter, so normal urine has almost no protein. If protein appears in urine on repeated tests, the filtration membrane of the glomerulus, its capillary walls and basement membrane, is most likely damaged.', wrong = '{"1": "The loop of Henle reabsorbs salt and water. Proteins enter the filtrate only at the glomerulus.", "2": "The collecting duct adjusts how much water is reabsorbed. It does not let proteins into the urine.", "3": "The distal convoluted tubule adjusts ion balance. Protein entry into the filtrate happens at the glomerular filter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7090' AND answer = 0;
UPDATE questions SET why = 'Blood enters the glomerulus through a wide afferent arteriole but leaves through a narrower efferent arteriole. More blood comes in than can easily get out, so pressure builds up inside the glomerular capillaries. This high pressure forces fluid and small solutes out into Bowman''s capsule, which is ultrafiltration.', wrong = '{"0": "The glomerulus is supplied by afferent arterioles that branch from the renal artery, not directly by the aorta.", "2": "Glomerular capillaries have thin walls with pores and no muscle, which suits filtration.", "3": "The width of the renal vein does not create the pressure inside the glomerulus. The arteriole sizes do."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7091' AND answer = 1;
UPDATE questions SET why = 'The thick ascending limb actively pumps Na⁺ and Cl⁻ out of the filtrate into the medulla, but its wall is impermeable to water, so water cannot follow. This makes the medulla salty (hypertonic) and the filtrate more dilute. The salty medulla later lets water leave the collecting duct by osmosis. This is the counter-current multiplier.', wrong = '{"0": "Being freely permeable to water but not to salts describes the descending limb, not the ascending limb.", "1": "The thick ascending limb does not secrete urea. Its job is to pump out salt.", "3": "All the filtered glucose is normally reabsorbed in the proximal convoluted tubule, not the loop of Henle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7092' AND answer = 2;
UPDATE questions SET why = 'ADH makes the collecting ducts permeable to water so that water is reabsorbed. Without ADH they stay almost waterproof, so little water is reabsorbed and large volumes of dilute urine are passed. This condition is diabetes insipidus, and unlike diabetes mellitus the urine has no glucose.', wrong = '{"0": "Small volumes of concentrated urine are produced when ADH is present and acting on the collecting ducts.", "1": "Glucose in urine is a sign of diabetes mellitus, caused by insulin problems, not lack of ADH.", "3": "Plasma proteins in urine point to damage of the glomerular filter, not lack of ADH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7093' AND answer = 2;
UPDATE questions SET why = 'Aldosterone is a hormone of the adrenal cortex. When blood sodium or blood volume is low, the renin-angiotensin system triggers its release. It makes the distal convoluted tubule and collecting duct reabsorb more Na⁺ and secrete K⁺ in exchange, and water follows the Na⁺ back into the blood.', wrong = '{"0": "ADH controls how permeable the collecting ducts are to water. It does not exchange Na⁺ for K⁺.", "1": "Atrial natriuretic peptide, from the heart, has the opposite effect. It increases the loss of Na⁺ in urine.", "3": "Calcitonin, from the thyroid, lowers blood calcium. It does not act on Na⁺ and K⁺."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7094' AND answer = 2;
UPDATE questions SET why = 'Tubular secretion actively moves certain substances from the blood in the peritubular capillaries into the tubule. Examples are H⁺, K⁺ and drugs such as penicillin. This adds to the amount already filtered at the glomerulus, so penicillin is removed faster than by filtration alone.', wrong = '{"0": "Reabsorption returns a substance to the blood, which would slow its removal, not speed it up.", "1": "All small solutes are filtered at the same glomerular pressure. There is no special higher pressure for penicillin.", "2": "The loop of Henle helps concentrate urine. It does not break down drugs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7095' AND answer = 3;
UPDATE questions SET why = 'Lithotripsy is a treatment for kidney stones that needs no surgery. Shock waves produced outside the body are focused on the stone and break it into small pieces. These fragments are then flushed out of the body with the urine.', wrong = '{"0": "Strong acid is not used inside the body to dissolve kidney stones. It would damage tissues.", "1": "Lithotripsy is used to avoid surgery. It does not involve removing the kidney.", "2": "Eating more calcium does not break up a stone. Lithotripsy works by physically shattering it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7096' AND answer = 3;
UPDATE questions SET why = 'In dialysis, each substance diffuses across the partially permeable membrane down its own concentration gradient. Glucose in the dialysis fluid is at the same concentration as in plasma, so there is no gradient and glucose is not lost from the blood. Urea is absent from the fluid, so it diffuses out of the blood.', wrong = '{"0": "With equal glucose concentrations on both sides, there is no net movement of glucose into the blood.", "1": "Each substance moves down its own gradient. Glucose does not push urea out.", "3": "Glucose has no effect on keeping the dialysis membrane open."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7097' AND answer = 2;
UPDATE questions SET why = 'Uric acid is nearly insoluble in water and much less toxic than ammonia. It can be stored safely and passed out as a paste with very little water. This saves water for animals that live in dry places and for those that develop inside shelled eggs, such as birds and insects.', wrong = '{"0": "Ammonia, not uric acid, is the most toxic nitrogenous waste. Uric acid is the least toxic of the three.", "1": "Making uric acid uses more energy than making ammonia or urea. Its advantage is saving water.", "3": "Uric acid is nearly insoluble. Its advantage is that it needs very little water to excrete."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7098' AND answer = 2;
UPDATE questions SET why = 'Deamination of amino acids, mainly in the liver, produces ammonia, and more ammonia is absorbed from gut bacteria. The liver normally converts this toxic ammonia into much less toxic urea by the ornithine cycle. In severe liver failure this conversion stops, so ammonia builds up in the blood.', wrong = '{"0": "The kidneys excrete nitrogenous waste. They do not add ammonia to the blood.", "1": "Breakdown of amino acids continues in liver failure and keeps producing ammonia.", "2": "Ammonia from the gut is still absorbed. The problem is that the liver cannot detoxify it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7099' AND answer = 3;
UPDATE questions SET why = 'When the body is cold, the arterioles that supply skin capillaries constrict (vasoconstriction). Less blood flows through the capillaries near the skin surface, so less heat is carried to the skin and lost to the cold air. More warm blood stays deep in the body.', wrong = '{"0": "Sweating cools the body by evaporation. It is reduced, not increased, on a cold day.", "1": "Less blood near the surface means less heat lost by radiation, not more.", "2": "Vasoconstriction only changes blood flow. It does not raise the metabolic rate of skin cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7100' AND answer = 3;
UPDATE questions SET why = 'During an infection, substances called pyrogens act on the hypothalamus and raise its set point for body temperature. Until the body reaches this new, higher set point, the normal temperature is sensed as too cold. So heat-gaining responses such as shivering and vasoconstriction switch on, and the person feels cold.', wrong = '{"0": "The skin temperature receptors still work. What has changed is the set point in the hypothalamus.", "2": "A destroyed hypothalamus could not trigger shivering. Here it is working but with a raised set point.", "3": "Sweating happens when the fever breaks and the set point falls back, not at the start."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7101' AND answer = 1;
UPDATE questions SET why = 'A freshwater fish''s body fluids are more concentrated than the water around it, so water keeps entering by osmosis and salts are lost. The fish removes the extra water as large volumes of dilute urine and replaces lost salts by actively absorbing them through its gills. Marine bony fish do the opposite.', wrong = '{"0": "Drinking seawater and excreting salt through the gills is how marine bony fish cope with losing water.", "1": "Small volumes of concentrated urine save water, which is needed in a hypertonic environment such as the sea.", "3": "The gills must stay thin and permeable to exchange gases, so they cannot keep all water out."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7102' AND answer = 2;
UPDATE questions SET why = 'The Na⁺/K⁺ pump uses ATP to move 3 Na⁺ out and 2 K⁺ into the neuron. This keeps the ion gradients on which the resting potential depends. When ouabain blocks the pump, ions keep leaking down their gradients, so the gradients and the resting potential gradually run down.', wrong = '{"0": "The potential falls gradually as ions leak. It does not jump at once to +40 mV, the peak of an action potential.", "1": "As the gradients are lost, the neuron eventually cannot fire action potentials at all.", "2": "Leak channels remain open, so ions keep moving. That is why the gradients run down."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7103' AND answer = 3;
UPDATE questions SET why = 'An action potential begins when voltage-gated Na⁺ channels open and Na⁺ rushes in, depolarising the membrane. Lidocaine blocks these channels in sensory nerves. Without Na⁺ entry, action potentials cannot be generated or conducted, so pain signals do not reach the brain.', wrong = '{"0": "The resting potential depends mainly on K⁺ leak channels and the Na⁺/K⁺ pump, which lidocaine does not reverse.", "2": "With no impulses arriving at the nerve endings, neurotransmitter release falls rather than becoming continuous.", "3": "Lidocaine targets Na⁺ channels. K⁺ channels used in repolarisation are not its target."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7104' AND answer = 1;
UPDATE questions SET why = 'Myelin insulates the axon, so ions can cross the membrane only at the gaps between myelin, the nodes of Ranvier. The impulse jumps from node to node, which is saltatory conduction and is very fast. When myelin is destroyed in multiple sclerosis, impulses can no longer jump, so conduction slows or fails.', wrong = '{"0": "Loss of myelin does not make axons thicker. The axon loses its insulating layer.", "2": "Transmitter release at synapses is not what slows conduction along the axon.", "3": "The main problem is loss of insulation between nodes, not removal of sodium channels from the nodes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7105' AND answer = 1;
UPDATE questions SET why = 'After an action potential passes, the voltage-gated Na⁺ channels in that part of the membrane are inactivated for a short time. This is the refractory period, when that region cannot fire again. So the impulse can only spread forward into membrane that is still at rest.', wrong = '{"0": "Release of transmitter only from axon terminals explains one-way transmission across a synapse, not along an axon.", "2": "Myelin speeds up conduction by making the impulse jump between nodes. It does not set the direction.", "3": "The Na⁺/K⁺ pump restores ion gradients after impulses. It does not push the impulse along."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7106' AND answer = 1;
UPDATE questions SET why = 'When an impulse reaches the axon terminal, voltage-gated Ca²⁺ channels open and Ca²⁺ flows in from the surrounding fluid. This Ca²⁺ makes vesicles fuse with the membrane and release neurotransmitter into the cleft by exocytosis. Without Ca²⁺ outside the cell, no transmitter is released and transmission stops.', wrong = '{"0": "Ca²⁺ is not the neurotransmitter. Neurotransmitters are substances such as acetylcholine and noradrenaline.", "2": "The action potential in the axon depends on movements of Na⁺ and K⁺, not Ca²⁺.", "3": "Acetylcholine in the cleft is broken down by the enzyme acetylcholinesterase, not by Ca²⁺."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7107' AND answer = 1;
UPDATE questions SET why = 'At an electrical synapse, the membranes of two cells are very close and joined by protein channels called gap junctions. Ions flow directly from one cell to the next, so the signal passes almost without delay. These synapses can often transmit in both directions and use no chemical transmitter.', wrong = '{"0": "Acetylcholine is used at chemical synapses. Electrical synapses need no chemical transmitter.", "2": "Electrical synapses can usually pass signals in both directions. One-way transmission is a feature of chemical synapses.", "3": "At electrical synapses the cells are almost touching. A wider synaptic cleft is found at chemical synapses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7108' AND answer = 1;
UPDATE questions SET why = 'Action potentials obey the all-or-none law: once threshold is reached, every action potential in a neuron has the same size. So a stronger stimulus cannot make bigger impulses. Instead it is signalled by a higher frequency of action potentials, and often by more neurons firing.', wrong = '{"0": "Under the all-or-none law, the size of each action potential is fixed and does not grow with stimulus strength.", "1": "Conduction speed depends on the axon, such as its diameter and myelin, not on how strong the stimulus is.", "2": "Each action potential lasts about the same short time, whatever the stimulus strength."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7109' AND answer = 3;
UPDATE questions SET why = 'The knee-jerk is a monosynaptic stretch reflex. The sensory neuron from the stretch receptor enters the spinal cord and synapses directly with the motor neuron to the thigh muscle. There is no relay neuron, so there is only one synapse, which makes the reflex very fast.', wrong = '{"0": "Two synapses would need one relay neuron between sensory and motor neurons, as in the withdrawal reflex.", "1": "Three synapses would need two relay neurons in the pathway, which the knee-jerk does not have.", "2": "A reflex arc always has at least one synapse in the central nervous system, between sensory and motor neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7110' AND answer = 3;
UPDATE questions SET why = 'A spinal nerve joins the cord by two roots. The dorsal root carries sensory fibres into the cord, and the ventral root carries motor fibres out to the muscles. Cutting the ventral root stops commands reaching the muscles, so the area is paralysed, but sensory signals still travel in, so sensation remains.', wrong = '{"0": "Losing sensation but keeping movement is what happens when the dorsal (sensory) root is cut.", "2": "Both sensation and movement would be lost only if the whole spinal nerve, carrying both kinds of fibre, were cut.", "3": "The motor supply to the area is lost, so its muscles are paralysed. The area is clearly affected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7111' AND answer = 1;
UPDATE questions SET why = 'The cerebellum coordinates muscle activity and keeps posture and balance, using information from the ears, eyes and muscles. Damage to it makes movements clumsy and unsteady, with a staggering walk. Muscle strength and sensation stay normal because these are handled by other parts of the nervous system.', wrong = '{"0": "The medulla oblongata controls breathing, heart rate and blood pressure. Damage there threatens life rather than balance.", "2": "The hypothalamus controls body temperature, thirst, hunger and the pituitary gland, not balance.", "3": "The thalamus relays sensory information to the cerebrum, so damage would affect sensation, which is normal here."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7112' AND answer = 1;
UPDATE questions SET why = 'The medulla oblongata contains the vital centres that control breathing, heart rate and blood pressure. Damage to it can stop breathing or the heartbeat, so it is the most immediately life-threatening. Damage to the other listed parts affects coordination, vision or communication between the hemispheres.', wrong = '{"0": "Damage to the cerebellum causes poor coordination and balance, but does not stop vital functions.", "1": "The occipital lobe holds the visual area, so damage affects vision, not breathing or heartbeat.", "3": "The corpus callosum links the two cerebral hemispheres. Damage affects communication between them, not survival."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7113' AND answer = 2;
UPDATE questions SET why = 'Nerves to the arms, and the phrenic nerves to the diaphragm, leave the spinal cord in the neck region. A cervical injury cuts off all signals below it, so both arms and legs can be paralysed and breathing may fail. A lumbar injury lies lower and affects mainly the legs.', wrong = '{"1": "Paralysis of the legs only is typical of injuries lower down, such as in the lumbar region.", "2": "Bladder control can be lost in both kinds of injury, but a cervical injury affects far more than the bladder.", "3": "Sensation is also lost below the level of a spinal cord injury."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7114' AND answer = 0;
UPDATE questions SET why = 'A transducer changes energy from one form into another. Sensory receptors change the energy of a stimulus, such as light, sound, pressure, heat or chemicals, into a generator potential. This then triggers electrical nerve impulses in a sensory neuron that travel to the central nervous system.', wrong = '{"1": "Each type of receptor is specialised for one kind of stimulus. For example, rods and cones respond to light.", "2": "Carrying impulses from the brain to effectors is the job of motor neurons, not receptors.", "3": "Hormones are released into the blood by endocrine glands, not by sensory receptors."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7115' AND answer = 0;
UPDATE questions SET why = 'The thyroid needs iodine to make thyroxine. In iodine deficiency, thyroxine falls and no longer inhibits the hypothalamus and anterior pituitary, so negative feedback is lost. The pituitary releases more TSH, which keeps stimulating the thyroid, and the gland grows larger, forming a goitre.', wrong = '{"1": "Thyroxine is low, not high, in iodine deficiency, because iodine is needed to make it.", "2": "Iodine does not directly make thyroid cells divide. It is the lack of iodine, acting through raised TSH, that enlarges the gland.", "3": "TSH secretion rises because negative feedback from thyroxine is removed. It does not stop."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7116' AND answer = 0;
UPDATE questions SET why = 'In positive feedback, a response makes the original stimulus stronger. During childbirth, the baby''s head stretches the cervix, which triggers oxytocin release. Oxytocin strengthens contractions of the uterus, which stretch the cervix more and release still more oxytocin, until the baby is born.', wrong = '{"1": "Insulin lowers blood glucose, which removes the stimulus for its own release. This is negative feedback.", "2": "Thyroxine inhibiting TSH release is a classic example of negative feedback.", "3": "ADH makes the kidneys keep water, which dilutes the blood and removes the stimulus. This is negative feedback."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7117' AND answer = 0;
UPDATE questions SET why = 'In type 1 diabetes the β cells of the pancreas make no insulin. Muscle and fat cells need insulin to take up glucose, because insulin makes them place glucose carrier proteins in their membranes. Without it, glucose stays in the blood while these cells are starved and break down fat and protein for energy.', wrong = '{"0": "Glucose leaves capillaries easily. The block is at the plasma membrane of the muscle and fat cells.", "1": "Without insulin the liver releases glucose instead of storing it as glycogen, which raises blood glucose further.", "3": "Glucagon is not absent. Its level stays high and raises blood glucose even more."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7118' AND answer = 2;
UPDATE questions SET why = 'Steroid hormones are lipid-soluble, so they pass straight through the plasma membrane. They bind to receptor proteins inside the cell, and the hormone-receptor complex attaches to DNA to switch particular genes on or off. Peptide hormones cannot cross the membrane and act through surface receptors and second messengers.', wrong = '{"0": "Binding to surface receptors and acting through cAMP is typical of peptide hormones such as adrenaline and glucagon.", "1": "Steroid hormones are made on smooth ER. Peptide hormones are made on rough ER.", "3": "Steroid hormones such as testosterone and cortisol act on many tissues, not only nerve cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7119' AND answer = 2;
UPDATE questions SET why = 'Growth hormone makes long bones grow at their growth plates. After puberty these plates close, so excess growth hormone in an adult cannot make the person taller. Instead, bones of the hands, feet and face thicken and enlarge. This condition is called acromegaly.', wrong = '{"0": "Excess growth hormone before puberty, when the growth plates are open, causes gigantism with very tall stature.", "1": "Lack of thyroxine in childhood causes cretinism, with stunted growth and poor mental development.", "3": "A lack of growth hormone in adulthood would not enlarge the bones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7120' AND answer = 2;
UPDATE questions SET why = 'Early in the cycle, low oestrogen inhibits LH release by negative feedback. As the Graafian follicle matures, it secretes much more oestrogen. When oestrogen stays high, it switches to stimulating the hypothalamus and anterior pituitary, a positive feedback. This causes the mid-cycle surge of LH that triggers ovulation.', wrong = '{"1": "A fall in progesterone at the end of the cycle leads to menstruation, not ovulation.", "2": "Inhibin lowers FSH release. It does not cause an LH surge.", "3": "hCG is made by the embryo after implantation, long after ovulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7121' AND answer = 0;
UPDATE questions SET why = 'After ovulation, the corpus luteum makes progesterone and oestrogen, which keep the endometrium thick. If no fertilisation occurs, there is no hCG from an embryo, and the corpus luteum breaks down near the end of the cycle. Progesterone and oestrogen fall, and the endometrium is shed as menstruation.', wrong = '{"0": "FSH begins to rise after progesterone falls, to start a new cycle. It does not cause the lining to shed.", "1": "The LH surge causes ovulation in the middle of the cycle. It does not destroy the endometrium.", "3": "Oestrogen from a new follicle rebuilds the endometrium after menstruation. It does not break it down."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7122' AND answer = 2;
UPDATE questions SET why = 'Soon after implantation, the outer layer of the embryo (the trophoblast, which later forms part of the placenta) secretes human chorionic gonadotrophin (hCG). hCG keeps the corpus luteum alive, so progesterone stays high and the endometrium is not shed. Some hCG passes into the urine, where pregnancy tests detect it.', wrong = '{"1": "LH comes from the mother''s anterior pituitary, not the embryo, and its level falls after ovulation.", "2": "FSH comes from the mother''s anterior pituitary and is kept low during pregnancy.", "3": "Oxytocin comes from the posterior pituitary and acts during birth and milk ejection."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7123' AND answer = 0;
UPDATE questions SET why = 'The pill gives steady levels of synthetic oestrogen and progestogen. These inhibit the hypothalamus and anterior pituitary by negative feedback, so FSH and LH stay low. No follicle matures and there is no mid-cycle LH surge, so ovulation does not occur.', wrong = '{"0": "The combined pill is not a spermicide. It acts on hormones, not directly on sperms.", "2": "hCG is made by an embryo after implantation, not by the corpus luteum, and the pill does not cause its release.", "3": "The pill''s effect is hormonal and reversible. Blocking the oviducts is a surgical method (tubal ligation)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7124' AND answer = 1;
UPDATE questions SET why = 'LH from the anterior pituitary stimulates the interstitial (Leydig) cells, which lie between the seminiferous tubules and make testosterone. If these cells are destroyed, testosterone falls first. LH would then rise, because low testosterone removes its negative feedback on the pituitary.', wrong = '{"1": "FSH is made by the anterior pituitary and acts on Sertoli cells. It would not fall first.", "2": "LH would rise, not fall, because low testosterone removes negative feedback on the pituitary.", "3": "Inhibin is made by Sertoli cells, which are not destroyed by this drug."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7125' AND answer = 0;
UPDATE questions SET why = 'In spermatogenesis, each primary spermatocyte completes meiosis to give four spermatids, which all become sperms: 100 × 4 = 400 sperms. In oogenesis, the cytoplasm divides unequally, so each primary oocyte gives only one ovum and the other cells are small polar bodies: 100 × 1 = 100 ova.', wrong = '{"1": "400 ova would mean each oocyte gives four ova. Three of the four products are polar bodies, which are not functional gametes.", "2": "100 sperms would mean one sperm per spermatocyte. Each spermatocyte actually gives four sperms.", "3": "200 sperms would mean two per spermatocyte, as if only the first meiotic division were counted. Each gives four."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7126' AND answer = 0;
UPDATE questions SET why = 'Spermatogenesis needs a temperature about 2 to 3 °C below core body temperature. The scrotum hangs outside the abdomen to keep the testes at this lower temperature. Testes that stay in the abdomen are too warm, so sperm production fails, although testosterone can still be made.', wrong = '{"0": "The interstitial cells can still make testosterone at body temperature. It is sperm production that fails.", "1": "The problem is not the route sperm take. At abdominal temperature, sperm are hardly produced at all.", "2": "FSH travels in the blood and reaches all tissues, including testes inside the abdomen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7127' AND answer = 3;
UPDATE questions SET why = 'Sperms are formed in the seminiferous tubules of the testis. They pass to the epididymis, where they mature and are stored. From there they travel along the vas deferens to the ejaculatory duct, where the seminal vesicle duct joins, and leave the body through the urethra.', wrong = '{"1": "Sperms are made in the seminiferous tubules first, so the path cannot start in the epididymis.", "2": "The epididymis comes before the vas deferens, because sperms mature there before moving on.", "3": "The vas deferens comes before the urethra. The urethra is the final tube leading outside."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7128' AND answer = 0;
UPDATE questions SET why = 'A vasectomy cuts and ties the vasa deferentia, so sperms cannot travel from the epididymis to the urethra. The seminal vesicles and prostate still add their fluid, so semen is ejaculated but contains no sperms. Testosterone is released into the blood, not the vas deferens, so its level stays normal.', wrong = '{"1": "Testosterone made by the interstitial cells enters the blood directly, so cutting the vas deferens does not affect it.", "2": "The seminal vesicles and prostate gland still secrete fluid, so semen is still produced.", "3": "Sperms are still produced in the testes, but they cannot leave and are broken down and reabsorbed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7129' AND answer = 0;
UPDATE questions SET why = 'Syphilis is caused by the spiral bacterium Treponema pallidum. Its first stage is a painless, firm ulcer called a chancre at the site of infection, which heals on its own. Weeks to months later, the bacterium spreads through the body and the secondary stage brings a skin rash.', wrong = '{"0": "Gonorrhoea, caused by Neisseria gonorrhoeae, mainly causes painful urination and a discharge, not a painless ulcer.", "2": "Genital herpes causes painful blisters, not a single painless, firm ulcer.", "3": "HIV infection does not begin with a genital ulcer. It slowly destroys helper T cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7130' AND answer = 1;
UPDATE questions SET why = 'Genital herpes is caused by herpes simplex virus, usually HSV-2. After the first infection, the virus hides in a latent state in sensory nerve ganglia. From time to time it reactivates and travels down the nerves, causing repeated outbreaks of painful blisters. Antibiotics cannot cure it.', wrong = '{"0": "Syphilis is caused by a bacterium, Treponema pallidum, not a virus, and it does not hide in nerve ganglia.", "2": "Gonorrhoea is caused by the bacterium Neisseria gonorrhoeae, not a virus.", "3": "Chlamydia infection is caused by a bacterium, Chlamydia trachomatis, not a virus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7131' AND answer = 1;
UPDATE questions SET why = 'In the follicular phase, oestrogen rebuilds the endometrium after menstruation. After ovulation, in the luteal phase, progesterone from the corpus luteum makes the lining thick, glandular and rich in blood vessels. This is when the uterus is best prepared for an embryo to implant, about a week after ovulation.', wrong = '{"1": "In the follicular phase the lining is still being rebuilt by oestrogen, and FSH acts on the follicles, not the endometrium.", "2": "In the menstrual phase the endometrium is being shed, so it is at its thinnest.", "3": "The lining keeps thickening for about a week after ovulation, so the day after the LH surge is too early."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7132' AND answer = 0;
UPDATE questions SET why = 'Passive immunity means receiving antibodies made by another organism, and it is artificial when they are given by injection. Anti-tetanus serum contains ready-made antibodies, so protection starts at once. The person''s own lymphocytes are not activated and no memory cells form, so protection fades as the antibodies are broken down.', wrong = '{"0": "Active immunity needs the person''s own immune response, as after a vaccine. Ready-made antibodies do not cause this.", "1": "Naturally acquired active immunity follows an actual infection, when the body makes its own antibodies and memory cells.", "2": "Naturally acquired passive immunity is when antibodies pass from mother to baby through the placenta or breast milk."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7133' AND answer = 3;
UPDATE questions SET why = 'The first dose of a vaccine produces a primary response and leaves behind memory B and T cells. When the booster brings the same antigen again, these memory cells are activated quickly and multiply into many plasma cells. This secondary response is faster, larger and longer-lasting than the first.', wrong = '{"0": "The bigger response comes from memory cells, not from a larger amount of antigen in the booster.", "1": "By the time a booster is given, antibodies from the first dose have usually fallen to low levels.", "3": "Vaccines contain antigens that trigger the body''s own response. They do not contain ready-made antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7134' AND answer = 2;
UPDATE questions SET why = 'Antibodies can only act on viruses outside cells, in body fluids. A virus-infected cell shows pieces of viral antigen on its surface. Cytotoxic (killer) T cells recognise these antigens and destroy the infected cell, for example by releasing perforin that makes holes in its membrane.', wrong = '{"0": "Antibodies are large proteins that cannot cross the plasma membrane, so they cannot reach viruses inside cells.", "2": "Plasma cells secrete antibodies. They do not engulf cells; phagocytes do that.", "3": "Helper T cells activate B cells and cytotoxic T cells. They do not make antibodies themselves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7135' AND answer = 1;
UPDATE questions SET why = 'An antibody is a Y-shaped molecule made of two heavy and two light chains. At the tip of each arm, the variable regions of one heavy and one light chain form an antigen-binding site. Their amino acid sequence differs between antibodies and gives a shape complementary to one specific antigen.', wrong = '{"1": "The constant region is the same within an antibody class. It decides the class and how the antibody acts, not which antigen it binds.", "2": "Disulphide bonds hold the four chains together, but they are the same in all antibodies and do not give specificity.", "3": "The hinge region gives the arms flexibility to reach antigens. It does not decide which antigen is bound."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7136' AND answer = 0;
UPDATE questions SET why = 'IgM is the first antibody class made in a primary immune response. It is a large pentamer made of five Y-shaped units, so it has ten binding sites and is good at clumping antigens. Later in the response, and in secondary responses, IgG becomes the main antibody.', wrong = '{"0": "IgG is a single Y-shaped unit. It is the main antibody later in the primary response and in secondary responses.", "1": "IgA is found mainly in secretions such as tears, saliva and breast milk.", "2": "IgE is involved in allergies and in defence against parasitic worms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7137' AND answer = 3;
UPDATE questions SET why = 'According to clonal selection, each lymphocyte already has receptors for one particular antigen before it ever meets that antigen. When an antigen enters, it binds only to the few lymphocytes with matching receptors. These selected cells multiply into a clone of effector cells and memory cells.', wrong = '{"1": "Lymphocyte receptors are fixed before contact with any antigen. They do not change shape to fit it.", "2": "Only the lymphocytes that match the antigen are selected and divide. The others are not stimulated.", "3": "The idea that antibodies mould around the antigen was rejected. Antibody shape is coded by genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7138' AND answer = 0;
UPDATE questions SET why = 'T lymphocytes are made in the bone marrow but must travel to the thymus to mature. A child born without a thymus therefore lacks mature T cells, so cell-mediated immunity is very weak. Antibody responses also suffer, because B cells need help from helper T cells.', wrong = '{"1": "B lymphocytes are made and mature in the bone marrow, so they would still be present.", "2": "Neutrophils are made in the bone marrow and do not need the thymus.", "3": "Red blood cells are made in the bone marrow and do not need the thymus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7139' AND answer = 0;
UPDATE questions SET why = 'Antibodies are glycoproteins that plasma cells make in large amounts and secrete into the blood. Proteins for export are made on ribosomes of the rough ER and then packaged by the Golgi apparatus. So plasma cells are packed with rough ER to produce so much antibody.', wrong = '{"0": "Engulfing and digesting bacteria is done by phagocytes such as neutrophils and macrophages, which are rich in lysosomes.", "2": "Storing lipid is not the role of plasma cells, and lipid synthesis takes place on smooth ER.", "3": "Plasma cells are final, specialised cells that rarely divide. Their job is to secrete antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7140' AND answer = 1;
UPDATE questions SET why = 'At birth, some of the baby''s Rh-positive red cells enter the Rh-negative mother''s blood and could make her produce her own anti-D and memory cells. Injected anti-D quickly destroys these fetal cells before her immune system responds. So she never becomes sensitised, and in the next pregnancy no anti-D attacks the fetus.', wrong = '{"1": "The aim is the opposite: to stop her immune system from making its own anti-D antibodies.", "2": "A person''s blood group is set by genes and cannot be changed by injecting antibodies.", "3": "The injected antibodies are broken down within weeks, long before the next pregnancy, so they do not protect the next baby directly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7141' AND answer = 0;
UPDATE questions SET why = 'Every person''s cells carry surface tissue-type proteins called MHC proteins. A kidney from an unrelated donor has MHC proteins different from the recipient''s. The recipient''s T lymphocytes recognise these as foreign and attack the kidney, so patients take immunosuppressant drugs to prevent rejection.', wrong = '{"0": "Red blood cells carry oxygen and take no part in attacking transplanted organs.", "2": "Rejection is directed against foreign proteins on donor cells. Glucose is the same in everyone and is not an antigen.", "3": "Platelets help in blood clotting. They are not the main cause of graft rejection."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7142' AND answer = 1;
UPDATE questions SET why = 'In a test cross, the two large classes (42% each) are parental types and the two small classes (8% each) are recombinants. Recombination frequency = 8% + 8% = 16%. Since 1% recombination equals 1 map unit, the genes are 16 map units apart.', wrong = '{"0": "8 counts only one of the two recombinant classes. Both small classes, Aabb and aaBb, are recombinants.", "1": "42% is the size of one parental class, not a recombinant frequency.", "2": "84% is the total of the parental types, 42% + 42%. Map distance is based on recombinants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7143' AND answer = 3;
UPDATE questions SET why = 'When genes assort independently, their probabilities are multiplied. For one gene, Aa × Aa gives aa with probability 1/4. For three genes: 1/4 × 1/4 × 1/4 = 1/64 of the offspring are aabbcc.', wrong = '{"0": "1/8 comes from multiplying 1/2 three times. The chance of aa from Aa × Aa is 1/4, not 1/2.", "1": "1/16 is the answer for only two genes, 1/4 × 1/4. There are three genes here.", "3": "1/32 comes from 1/2 × 1/4 × 1/4, wrongly using 1/2 for one of the genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7144' AND answer = 2;
UPDATE questions SET why = 'Treat each gene separately and multiply. Aa × Aa gives Aa in 1/2 of offspring, and Bb × Bb gives Bb in 1/2. So the chance of AaBb = 1/2 × 1/2 = 1/4, which is 4 of the 16 boxes in the Punnett square.', wrong = '{"0": "9/16 is the fraction showing both dominant traits (A_B_), which includes homozygous as well as heterozygous offspring.", "1": "1/16 is the fraction of any one fully homozygous genotype, such as AABB or aabb.", "3": "1/2 is the chance of being heterozygous for one gene. Both genes must be heterozygous, so 1/2 × 1/2."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7145' AND answer = 2;
UPDATE questions SET why = 'The carrier mother is XᴴXʰ and the normal father is XᴴY. Their children are XᴴXᴴ, XᴴXʰ, XᴴY and XʰY in equal proportions. Only XʰY is a son with haemophilia, so the probability is 1/4 of all children (half of the sons).', wrong = '{"0": "1/2 is the chance among sons only. The question asks about the next child, who may be a son or a daughter.", "1": "1/8 halves the correct answer a second time. The 1/2 chance of a son is already included in the 1/4.", "3": "Sons get their X chromosome from the carrier mother, so half of them can receive Xʰ and be affected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7146' AND answer = 2;
UPDATE questions SET why = 'The father is XʰY and the non-carrier mother is XᴴXᴴ. Every daughter gets Xʰ from her father and Xᴴ from her mother, so all daughters are carriers (XᴴXʰ). Every son gets Y from his father and Xᴴ from his mother, so no son has haemophilia.', wrong = '{"0": "Sons get their X chromosome from the mother, who has only normal Xᴴ, so no son is affected.", "2": "Daughters also receive a normal Xᴴ from their mother, so they are carriers, not affected, and sons are normal.", "3": "Males have only one X chromosome, so they are either affected or normal. They cannot be carriers."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7147' AND answer = 1;
UPDATE questions SET why = 'A colour-blind woman is XᶜXᶜ, so every child gets Xᶜ from her. Sons get Y from the father, so they are XᶜY and colour-blind. Daughters also get the father''s normal X, so they are XᴺXᶜ: carriers with normal vision.', wrong = '{"1": "Daughters receive a normal X from the father, so they are carriers, not colour-blind. Sons are affected.", "2": "Every son receives Xᶜ from his mother, so all sons are colour-blind, not half.", "3": "Every son receives the recessive allele from the mother and, with no second X, shows colour blindness."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7148' AND answer = 0;
UPDATE questions SET why = 'An O child is ii, so each parent must carry an i allele. The parents are therefore Iᴬi and Iᴮi. Their children are IᴬIᴮ, Iᴬi, Iᴮi and ii in equal proportions, so the chance of an AB child (IᴬIᴮ) is 1/4.', wrong = '{"0": "1/2 would need one parent to be homozygous, for example IᴬIᴬ. The O child shows both parents are heterozygous.", "2": "AB is possible: the child can get Iᴬ from one parent and Iᴮ from the other.", "3": "3/4 is the chance that the next child is NOT group AB."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7149' AND answer = 1;
UPDATE questions SET why = 'In four o''clock plants, red (RR) and white (WW) show incomplete dominance, so the heterozygote RW has a blended pink colour. Crossing two pink plants, RW × RW, gives RR : RW : WW in a 1 : 2 : 1 ratio. Each genotype has its own colour, so the ratio is 1 red : 2 pink : 1 white.', wrong = '{"0": "3 : 1 is the phenotypic ratio when one allele is completely dominant. Here the heterozygote looks different.", "2": "All pink offspring come only from crossing pure red with pure white plants.", "3": "Pink × pink gives red, pink and white offspring in a 1 : 2 : 1 ratio, not 3 pink : 1 white."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7150' AND answer = 1;
UPDATE questions SET why = 'In recessive epistasis, being homozygous recessive at one gene hides the effect of another gene. For example, in mouse coat colour, cc gives an albino whatever the other gene is. Two of the usual 9 : 3 : 3 : 1 classes (3 + 1) then look the same, giving 9 : 3 : 4.', wrong = '{"1": "Dominant epistasis, where one dominant allele hides another gene, gives a 12 : 3 : 1 ratio.", "2": "Complementary gene action, where both dominant alleles are needed for the trait, gives 9 : 7.", "3": "Incomplete dominance at one gene changes 3 : 1 into 1 : 2 : 1. It does not give 9 : 3 : 4."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7151' AND answer = 0;
UPDATE questions SET why = 'Each offspring can receive 0, 1, 2, 3, 4, 5 or 6 dominant (adding) alleles from the six alleles of three genes. With equal, additive effects, each number gives a different phenotype. So there are 6 + 1 = 7 phenotypic classes, as in human skin colour.', wrong = '{"0": "6 forgets the class with no dominant alleles. Counting from 0 to 6 gives seven classes.", "2": "8 is the number of different gamete types made by AaBbCc (2³), not phenotypic classes.", "3": "27 is the number of different genotypes (3³). Many genotypes with the same number of dominant alleles look alike."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7152' AND answer = 1;
UPDATE questions SET why = 'The eye colour gene is on the X chromosome. P: XᴿXᴿ × XʳY gives F₁ females XᴿXʳ and males XᴿY, all red-eyed. In the F₂, every female gets Xᴿ from her F₁ father, so all are red-eyed. Males get X from the XᴿXʳ mother, so half are XʳY with white eyes.', wrong = '{"0": "Every F₂ female receives Xᴿ from her red-eyed father, so no female is white-eyed.", "1": "White eyes do not appear in any F₂ females in this cross, because they all get Xᴿ from the father.", "2": "Half the F₂ males receive Xᴿ from their mother and are red-eyed, so not all males are white-eyed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7153' AND answer = 3;
UPDATE questions SET why = 'During prophase I of meiosis, homologous chromosomes pair up (synapsis). Non-sister chromatids of each pair then exchange matching segments at points called chiasmata. This crossing over produces new combinations of alleles of linked genes on the same chromosome.', wrong = '{"0": "Sister chromatids are identical copies, so an exchange between them would not create new combinations, and crossing over is a meiotic event.", "1": "Crossing over takes place between homologous chromosomes in prophase I, not between non-homologous ones in anaphase II.", "3": "Crossing over happens after DNA replication, during prophase I of meiosis, not during replication itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7154' AND answer = 2;
UPDATE questions SET why = 'An organism with 2n = 8 has 4 pairs of homologous chromosomes. At metaphase I, each pair lines up independently of the others, and either member can go to a given pole. So the number of different gamete combinations is 2ⁿ, where n is the number of pairs: 2⁴ = 16.', wrong = '{"0": "8 is the diploid number of chromosomes, not the number of chromosome combinations in gametes.", "1": "4 is the number of homologous pairs (n). The number of combinations is 2 raised to that power.", "2": "256 is 2⁸, which wrongly uses the diploid number 8 in place of the 4 pairs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7155' AND answer = 3;
UPDATE questions SET why = 'Crossing an unknown dominant plant with a homozygous recessive (tt) plant is a test cross. If the tall parent were TT, all offspring would be Tt and tall. A 1 tall : 1 dwarf ratio appears only when the tall parent is Tt, because it gives T and t gametes in equal numbers.', wrong = '{"0": "A homozygous TT parent crossed with tt would give only tall (Tt) offspring, with no dwarfs.", "1": "A tt plant shows the recessive trait and would be dwarf, but this parent is tall.", "2": "Polyploidy, having extra sets of chromosomes, is not what a 1 : 1 test cross ratio shows."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7156' AND answer = 3;
UPDATE questions SET why = 'Aa × Aa gives AA, Aa, Aa and aa, so each child has a 3/4 chance of normal pigmentation. The children''s genotypes are independent events, so their probabilities are multiplied. For three children: 3/4 × 3/4 × 3/4 = 27/64.', wrong = '{"0": "3/4 is the chance for one child only. All three children must be normal.", "1": "9/16 is (3/4)², the chance that two children are normal, not three.", "3": "1/64 is (1/4)³, the chance that all three children are albino."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7157' AND answer = 2;
UPDATE questions SET why = 'When two unaffected parents have an affected child, the trait must be recessive and both parents must be carriers. It cannot be X-linked recessive here, because an affected daughter would need an affected X from her father, who is unaffected. So the trait is autosomal recessive.', wrong = '{"0": "For an X-linked recessive daughter to be affected, her father must be affected. Here the father is unaffected.", "1": "An autosomal dominant trait in a child would show in at least one parent, but both are unaffected.", "3": "An X-linked dominant trait in a child would also show in at least one parent, but both are unaffected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7158' AND answer = 2;
UPDATE questions SET why = 'A father passes his only X chromosome to every daughter and his Y chromosome to every son. If all his daughters show the trait and none of his sons do, the gene must be on the X chromosome. Since one copy from the father is enough to show it, the trait is X-linked dominant.', wrong = '{"1": "In X-linked recessive inheritance, daughters of an affected father and a normal mother are carriers, not affected.", "2": "An autosomal recessive trait would not split so cleanly by sex, with every daughter affected and every son normal.", "3": "A Y-linked trait passes from father to every son and never to daughters, the opposite of this pattern."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7159' AND answer = 0;
UPDATE questions SET why = 'The AB father (IᴬIᴮ) passes either Iᴬ or Iᴮ, and the O mother (ii) always passes i. So the children are either Iᴬi, group A, or Iᴮi, group B, in equal numbers. No child can be AB or O.', wrong = '{"0": "AB needs both Iᴬ and Iᴮ, but the mother gives only i. O needs i from the father too, and he has none.", "1": "Only two genotypes, Iᴬi and Iᴮi, are possible from this cross, so groups AB and O cannot occur.", "3": "Every child gets i from the mother, so no child can be IᴬIᴮ (group AB)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7160' AND answer = 2;
UPDATE questions SET why = 'DNA replication is semi-conservative: each new molecule keeps one old strand and gains one new strand. After the first round in ¹⁴N, every molecule is hybrid (¹⁵N/¹⁴N). In the second round, each hybrid molecule gives one hybrid and one fully light molecule, so the DNA is half hybrid and half light.', wrong = '{"0": "All hybrid DNA is the result after only one round of replication.", "1": "No fully heavy DNA remains after the first round, because every heavy strand is paired with a new light strand.", "2": "The original heavy strands are kept in hybrid molecules in every later generation, so not all DNA becomes light."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7161' AND answer = 3;
UPDATE questions SET why = 'Sulphur (³⁵S) is found in protein but not in DNA, so it labels only the phage coat. During infection only phage DNA enters the bacterium, and the empty coat stays outside. Blending shakes the coats off, and centrifuging leaves them in the liquid (supernatant), so most ³⁵S stays there. This showed that DNA is the genetic material.', wrong = '{"1": "³²P, which labels DNA, was found inside the bacteria in the pellet. ³⁵S-labelled protein stayed outside.", "2": "The protein coat of the parent phage does not enter the cell, so its ³⁵S is not passed to new phages.", "3": "The protein coats separate clearly from the heavier bacterial cells, so the label is not shared equally."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7162' AND answer = 0;
UPDATE questions SET why = 'Avery, MacLeod and McCarty treated the extract from heat-killed S-strain bacteria with different enzymes. Protease and RNase did not stop transformation, but DNase, the enzyme that digests DNA, did. This showed that the transforming principle is DNA.', wrong = '{"0": "Protease digested the proteins, yet transformation still occurred, so protein was not the transforming factor.", "1": "RNase digested the RNA, yet transformation still occurred, so RNA was not the transforming factor.", "2": "The capsule is the trait passed on to R cells. It is not the agent that carries the genetic information."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7163' AND answer = 3;
UPDATE questions SET why = 'On the lagging strand, DNA is made in short Okazaki fragments. After the RNA primers are replaced with DNA, small gaps remain in the sugar-phosphate backbone between fragments. DNA ligase seals these gaps. Without ligase, the lagging strand would stay in separate pieces.', wrong = '{"0": "Unwinding of the double helix is done by helicase, not by DNA ligase.", "1": "RNA primers are made by the enzyme primase, not by DNA ligase.", "2": "DNA polymerase adds nucleotides continuously to the leading strand, without needing ligase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7164' AND answer = 3;
UPDATE questions SET why = 'DNA polymerase can add nucleotides only to the 3′ end of a growing strand, so it builds DNA in the 5′ → 3′ direction. The two template strands are antiparallel. On one template, building runs towards the fork and is continuous; on the other it runs away from the fork, so it must restart again and again in short pieces as the fork opens.', wrong = '{"0": "Both template strands are the same length. The problem is their opposite direction.", "1": "Helicase unwinds the double helix at the fork, separating both strands together.", "3": "The leading strand also needs an RNA primer, though only one at the start. The lagging strand needs many."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7165' AND answer = 2;
UPDATE questions SET why = 'mRNA is complementary and antiparallel to the DNA template. Pair each base: T→A, A→U, C→G, G→C. The template 3′–TAC CGA TTC–5′ therefore gives mRNA 5′–AUG GCU AAG–3′, running in the opposite direction to the template.', wrong = '{"0": "This has the right pairing, but it contains thymine. RNA uses uracil in place of thymine.", "1": "This simply copies the template with U for T, instead of pairing complementary bases.", "2": "The bases are correct, but the direction is reversed. The mRNA must run 5′ to 3′, opposite the template''s 3′ to 5′."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7166' AND answer = 3;
UPDATE questions SET why = 'A codon and anticodon pair by complementary bases and run antiparallel. G pairs with C, C with G and U with A. So the codon 5′–GCU–3′ pairs with an anticodon that reads 3′–CGA–5′.', wrong = '{"0": "The bases are correct, but written 5′ to 3′ they would pair in the same direction. Pairing must be antiparallel.", "1": "tRNA is RNA, so it contains uracil (U), not thymine (T).", "2": "This repeats the codon instead of using its complementary bases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7167' AND answer = 3;
UPDATE questions SET why = 'The genetic code is degenerate, meaning most amino acids are coded by more than one codon. These codons usually differ only in the third base. So a change in the third base often still codes for the same amino acid, giving a silent mutation with no effect on the protein.', wrong = '{"0": "Ribosomes read all three bases of each codon. The third base is read but often does not change the amino acid.", "1": "Most third-base changes are silent. Only a few create one of the three stop codons.", "3": "tRNA anticodons pair with all bases of the codon. They do not ignore it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7168' AND answer = 2;
UPDATE questions SET why = 'Deleting one base shifts the reading frame, so every codon after the deletion is read wrongly. This is a frameshift mutation. Near the start of the gene it changes almost every amino acid and usually creates an early stop codon, so the protein is likely to lose its function completely.', wrong = '{"1": "A change in the third base of a codon is often silent because the code is degenerate.", "2": "Deleting three bases removes one amino acid without shifting the frame, and near the end it affects only a small part of the protein.", "3": "Replacing an amino acid with a very similar one often leaves the protein''s shape and function nearly unchanged."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7169' AND answer = 0;
UPDATE questions SET why = 'The change from GAG to GTG replaces one base (A with T) with no bases added or lost. This is a point (substitution) mutation. The codon now codes for valine in place of glutamic acid, and this single change makes haemoglobin S form fibres at low oxygen, sickling the red cells.', wrong = '{"0": "No base is added or removed, so the reading frame does not shift. It is not a frameshift.", "1": "The codon is still present, with one base changed. No codon is deleted.", "2": "A translocation moves a large segment between chromosomes. Here only one base pair changes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7170' AND answer = 3;
UPDATE questions SET why = 'Histones contain many lysine and arginine amino acids, which carry positive charges. DNA''s sugar-phosphate backbone carries negative charges on its phosphate groups. The attraction between opposite charges lets DNA wrap tightly around groups of eight histones, forming nucleosomes.', wrong = '{"0": "Negatively charged amino acids would repel the negatively charged DNA backbone instead of attracting it.", "1": "Histones bind DNA mainly by attraction between charges, not by covalent bonds to the bases.", "2": "Histones are proteins made of amino acids, not of nucleotides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7171' AND answer = 3;
UPDATE questions SET why = 'In meiosis I of a man, the X and Y chromosomes normally separate into different cells. If they fail to separate (non-disjunction), one secondary spermatocyte gets both X and Y and the other gets neither. The sperms formed carry XY or no sex chromosome (O), which can give XXY (Klinefelter) or XO (Turner) zygotes.', wrong = '{"0": "XX or YY sperms arise when sister chromatids fail to separate in meiosis II, not meiosis I.", "1": "Sperms carrying one X or one Y are the normal result when meiosis goes correctly.", "2": "A single error in meiosis I can give at most two sex chromosomes in a sperm, not three."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7172' AND answer = 3;
UPDATE questions SET why = 'In the lac operon, a repressor protein normally binds to the operator and blocks RNA polymerase. When lactose is present, it is converted into allolactose, which acts as the inducer. Allolactose binds the repressor and changes its shape, so it falls off the operator and the structural genes are transcribed.', wrong = '{"0": "Lactose (as allolactose) binds the repressor, not the operator itself.", "1": "The repressor gene stays present and keeps making repressor. Lactose only inactivates the repressor protein.", "3": "The lac operon is controlled at transcription. Lactose does not act directly on ribosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7173' AND answer = 2;
UPDATE questions SET why = 'DNA polymerase can only add nucleotides to an existing chain, so it needs a primer to start. RNA polymerase binds to a promoter and can begin a new RNA chain on its own, without any primer. Both enzymes build their chains in the 5′ → 3′ direction.', wrong = '{"1": "Both RNA and DNA polymerases build chains in the 5′ → 3′ direction, not 3′ → 5′.", "2": "RNA polymerase uses ribonucleotides to make RNA. Deoxyribonucleotides are used by DNA polymerase.", "3": "An RNA transcript is made as one continuous piece, so DNA ligase is not needed to join it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7174' AND answer = 0;
UPDATE questions SET why = 'A restriction enzyme cuts DNA at one specific recognition sequence, often leaving short single-stranded overhangs called sticky ends. Cutting both the human DNA and the plasmid with the same enzyme gives matching sticky ends. These base-pair with each other, and DNA ligase then seals the sugar-phosphate backbones.', wrong = '{"0": "Cost is not the reason. The same enzyme is needed to produce sticky ends that match.", "1": "Restriction enzymes only cut DNA. Joining the pieces is done by a separate enzyme, DNA ligase.", "3": "Many different restriction enzymes can cut circular plasmid DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7175' AND answer = 2;
UPDATE questions SET why = 'If the four bases are equally common and random, each position has a 1/4 chance of matching the site. A particular 6-base sequence therefore occurs with probability (1/4)⁶ = 1/4096. So the enzyme cuts on average once every 4⁶ = 4096 base pairs.', wrong = '{"0": "24 comes from multiplying 6 × 4. The chances at each position must be multiplied together, giving 4⁶.", "2": "256 is 4⁴, which is the answer for a 4-base recognition site, not a 6-base site.", "3": "1296 is 6⁴, which swaps the base and the power. The correct value is 4⁶."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7176' AND answer = 1;
UPDATE questions SET why = 'In PCR, each cycle of heating, primer binding and extension ideally doubles the amount of target DNA. After n cycles, one molecule gives 2ⁿ copies. After 10 cycles: 2¹⁰ = 1024 copies.', wrong = '{"1": "20 comes from adding two copies per cycle (10 × 2). PCR doubles the DNA each cycle, so the growth is exponential.", "2": "100 comes from multiplying 10 × 10, which has no link to the doubling in PCR.", "3": "512 is 2⁹, the number of copies after 9 cycles. One more cycle doubles it to 1024."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7177' AND answer = 0;
UPDATE questions SET why = 'Each PCR cycle heats the mixture to about 95 °C to separate the two DNA strands. Most enzymes are destroyed at this temperature. Taq polymerase comes from a bacterium that lives in hot springs, so it is heat-stable and survives, and new enzyme does not have to be added after every cycle.', wrong = '{"0": "Taq polymerase works best at about 72 °C, the extension temperature of PCR, not at low temperature.", "1": "Copying RNA into DNA is done by reverse transcriptase, not by Taq polymerase.", "2": "Like other DNA polymerases, Taq polymerase needs primers to start making a new strand."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7178' AND answer = 3;
UPDATE questions SET why = 'Each phosphate group in DNA carries a negative charge, so DNA fragments move through the gel towards the positive electrode (anode). The gel acts like a sieve. Smaller fragments slip through its pores more easily, so they travel faster and farther than larger ones.', wrong = '{"0": "DNA is negatively charged, so it moves to the positive electrode, and larger fragments travel less far.", "2": "The direction is correct, but larger fragments are slowed more by the gel, so they travel less far.", "3": "DNA carries a negative charge on every phosphate group, so it does move in an electric field."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7179' AND answer = 1;
UPDATE questions SET why = 'A B cell can make one specific antibody but does not divide for long in culture. A myeloma (cancer) cell divides endlessly. Fusing them forms a hybridoma that makes the one chosen antibody and also keeps dividing in culture, so large amounts of a single (monoclonal) antibody can be produced.', wrong = '{"1": "Each hybridoma comes from one B cell, so its clone makes one specific antibody, not many.", "2": "Making cells resistant to antigens is not the aim. The aim is to produce one antibody in large amounts.", "3": "Hybridoma cells are living cells and still need a nutrient culture medium to grow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7180' AND answer = 0;
UPDATE questions SET why = 'A DNA probe is a short, single-stranded piece of DNA whose base sequence is complementary to part of the gene being tested. It carries a radioactive or fluorescent label. If the patient''s DNA contains the matching sequence, the probe base-pairs with it, and the label shows that the sequence is present.', wrong = '{"0": "A probe must be single-stranded so that it can base-pair with the target. A double-stranded plasmid cannot do this.", "1": "Antibodies detect proteins. A probe detects a DNA sequence by base-pairing.", "2": "A probe finds a sequence by pairing with it. Cutting DNA is the job of a restriction enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7181' AND answer = 3;
UPDATE questions SET why = 'The gene for the hepatitis B surface protein is put into yeast, which produces large amounts of this protein. The vaccine contains only this purified protein, with no viral genome, so it cannot cause infection. It still triggers the body to make antibodies and memory cells.', wrong = '{"0": "The recombinant vaccine contains no virus at all, whether live or weakened.", "1": "Ready-made antibodies give passive immunity. A vaccine contains antigen so the body makes its own antibodies.", "2": "Hepatitis B is caused by a virus, and the vaccine is made using yeast, not killed bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7182' AND answer = 3;
UPDATE questions SET why = 'Human genes contain introns, non-coding regions that human cells cut out of the mRNA before translation. Bacteria cannot remove introns. Mature insulin mRNA has already had its introns removed, so a cDNA copy made from it by reverse transcriptase can be expressed correctly by bacteria.', wrong = '{"0": "Human chromosomal DNA can be cut by restriction enzymes in the same way as any other DNA.", "1": "cDNA is copied from mature mRNA, so it contains no introns at all.", "3": "Plasmids are DNA, so mRNA cannot be inserted directly. It must first be copied into DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7183' AND answer = 2;
UPDATE questions SET why = 'Gametes come only from germ-line cells in the testes or ovaries. Somatic gene therapy changes only body cells, such as blood cells, and does not change the germ line. So the corrected gene is not present in sperms or eggs and cannot be passed on to children.', wrong = '{"0": "Inserted genes can stay in long-lived cells for months or years. They are not always lost within a week.", "2": "The vectors used in gene therapy do not destroy the gonads.", "3": "Whether an allele is dominant or recessive does not decide whether it is inherited."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7184' AND answer = 1;
UPDATE questions SET why = 'Lamarck proposed that characteristics an organism acquires during its life are passed on to its offspring. Weismann cut off the tails of mice for many generations, yet every new generation was born with normal tails. This showed that changes to body cells do not reach the germ cells, so acquired characteristics are not inherited.', wrong = '{"0": "Natural selection does not predict that cut tails would be inherited, so the experiment did not test it.", "1": "The cell theory, that living things are made of cells, has nothing to do with this experiment.", "2": "The experiment did not test whether genes exist. It tested whether body changes are inherited."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7185' AND answer = 3;
UPDATE questions SET why = 'Darwin argued that individuals in a population vary naturally. Giraffes that happened to have longer necks could reach more leaves on high branches, so they survived better and left more offspring. Over many generations, natural selection made long necks common.', wrong = '{"0": "Stretching the neck during life and passing on the change is Lamarck''s explanation, the inheritance of acquired characters.", "2": "Darwin stressed gradual change through many small variations, not one sudden mutation in all giraffes.", "3": "In Darwin''s view the environment selects existing variations. It does not change genes to order."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7186' AND answer = 1;
UPDATE questions SET why = 'Before the antibiotic is used, a few bacteria in the population already carry resistance, arising by random mutation or gene transfer. The antibiotic kills the susceptible bacteria, but the resistant ones survive and multiply. Soon the population is made mostly of resistant bacteria. This is natural selection.', wrong = '{"0": "The antibiotic does not cause resistance. It selects bacteria that were already resistant.", "1": "Bacteria have no nervous system and cannot learn. Resistance is a genetic trait.", "3": "Resistance spreads because resistant variants are selected, not because each bacterium slowly gains resistance by use."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7187' AND answer = 2;
UPDATE questions SET why = 'Analogous organs do the same job but have different structures and origins. Bird wings are modified forelimbs with bones and feathers, while insect wings are outgrowths of the cuticle with no bones. Both are used for flight, so they are analogous and result from convergent evolution.', wrong = '{"0": "Homologous organs share the same basic structure and origin, such as vertebrate forelimbs. Bird and insect wings do not.", "1": "Vestigial organs are reduced and have little or no function. Both kinds of wing are fully used for flight.", "2": "These wings are not homologous, and homologous organs reflect divergent evolution, not convergent."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7188' AND answer = 3;
UPDATE questions SET why = 'The whale''s flipper, the bat''s wing and the human arm all share the same basic five-fingered (pentadactyl) bone plan. They are homologous organs that have been modified for swimming, flying and grasping. This shows that these mammals came from a common ancestor and then diverged: divergent evolution.', wrong = '{"0": "Convergent evolution gives a similar function from different structures. Here the structure is the same and functions differ.", "1": "Acquired characteristics are not inherited, and shared bone structure is not evidence for it.", "3": "Shared bone structure in different animals points to common descent, not separate creation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7189' AND answer = 2;
UPDATE questions SET why = 'Darwin could not explain where variation came from or how it was inherited. Neo-Darwinism, the modern synthesis, combined natural selection with Mendelian genetics. It explained that new variation arises from mutation, and is reshuffled by genetic recombination during sexual reproduction.', wrong = '{"1": "Neo-Darwinism keeps natural selection as the central mechanism of evolution. It does not reject it.", "2": "Inheritance of acquired characteristics was Lamarck''s idea and is not accepted by neo-Darwinism.", "3": "Neo-Darwinism explains how species change over time. It does not say that species never change."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7190' AND answer = 0;
UPDATE questions SET why = 'Scientists believed that the early Earth''s atmosphere was reducing, with gases such as methane, ammonia and hydrogen and no free oxygen. Oxygen would also oxidise and break down organic molecules before they could build up. So Miller and Urey left oxygen out to imitate early conditions.', wrong = '{"0": "Electric sparks can pass through oxygen. That was not the reason it was left out.", "1": "Oxygen had been known since the 1770s, long before the experiment in 1953.", "2": "Amino acids do contain oxygen, in their carboxyl (–COOH) groups. It came from the water vapour."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7191' AND answer = 3;
UPDATE questions SET why = 'Under Hardy-Weinberg equilibrium, the recessive phenotype frequency is q². So q² = 0.16, q = 0.4 and p = 1 − 0.4 = 0.6. Heterozygotes = 2pq = 2 × 0.6 × 0.4 = 0.48, which is 48%.', wrong = '{"0": "24% is pq = 0.6 × 0.4, which forgets to multiply by 2.", "2": "36% is p² = 0.6², the homozygous dominant frequency.", "3": "84% is 100 − 16, all individuals showing the dominant phenotype, both homozygous and heterozygous."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7192' AND answer = 1;
UPDATE questions SET why = 'Transpiration from the leaves pulls water up the xylem under tension. Water molecules stick to each other by hydrogen bonds (cohesion) and stick to the walls of the narrow xylem vessels (adhesion). These forces keep the water column unbroken from root to leaf. This is the cohesion-tension theory.', wrong = '{"1": "Root pressure is far too small to raise water to the top of tall trees. It plays only a minor role.", "2": "Mature xylem vessels are dead, hollow tubes with no cytoplasm, so they cannot pump water.", "3": "Phloem carries sugars in solution. It does not drive water up the xylem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7193' AND answer = 0;
UPDATE questions SET why = 'At a source such as a leaf, companion cells actively load sucrose into the sieve tubes. This lowers the water potential inside, so water enters by osmosis from the nearby xylem. The resulting high pressure pushes the sap along the sieve tubes towards sinks, where sucrose is removed.', wrong = '{"1": "Sucrose is removed at the sink, such as a root, not at the source. Water then leaves the phloem there.", "2": "Sieve tubes are living cells, though they lack a nucleus. They are not dead and empty.", "3": "Transpiration pulls water up the xylem. It does not pull water directly into the phloem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7194' AND answer = 0;
UPDATE questions SET why = 'In light, guard cells pump out H⁺ ions and take up K⁺ ions. The extra K⁺ lowers their water potential, so water enters by osmosis and the guard cells become turgid. Their inner walls are thicker than their outer walls, so they bend apart and the pore opens.', wrong = '{"1": "K⁺ moving out of the guard cells makes them lose water and become flaccid, which closes the stomata.", "2": "Turning sugar into insoluble starch would raise the water potential, so water would leave and the stomata would close.", "3": "Guard cells that lose water and shrink close the pore instead of opening it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7195' AND answer = 0;
UPDATE questions SET why = 'The Casparian strip is a band of waterproof suberin in the walls of endodermal cells. It blocks the pathway through cell walls, so water and minerals must pass through the selectively permeable membranes of endodermal cells. This lets the root control which substances enter the xylem.', wrong = '{"1": "The Casparian strip blocks the cell wall pathway, so it slows rather than speeds up water flow.", "2": "Storing starch is not its job. It is a waterproof band in the cell walls.", "3": "It helps prevent water and ions from leaking back out of the xylem, which also helps build root pressure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7196' AND answer = 0;
UPDATE questions SET why = 'A population in a new habitat first grows slowly, then rapidly, giving an S-shaped (logistic) curve. As numbers rise, food and space run short and predation and disease increase. This environmental resistance slows growth until births equal deaths, and the population levels off at the carrying capacity.', wrong = '{"1": "Reproduction does not stop. Births continue but are balanced by deaths.", "2": "If all individuals died at once, the population would crash, not level off at a stable size.", "3": "Unlimited resources would give J-shaped exponential growth with no levelling off."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7197' AND answer = 0;
UPDATE questions SET why = 'At each feeding level, much energy is lost as heat in respiration, so less energy passes to the next level. Each higher level therefore always has less energy than the one below, and the pyramid of energy can never be inverted. Pyramids of numbers and biomass can be inverted in some ecosystems.', wrong = '{"0": "A pyramid of biomass can be inverted, for example in some aquatic ecosystems.", "2": "A pyramid of numbers can be inverted, for example when one tree supports many insects.", "3": "In a pond, the biomass of phytoplankton at one time can be smaller than that of zooplankton, so the pyramid is inverted."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7198' AND answer = 1;
UPDATE questions SET why = 'Penicillin stops bacteria from building the cross-links of peptidoglycan, so the wall weakens and the cell bursts. Gram-positive bacteria have a thick peptidoglycan wall that is exposed on the outside, so penicillin reaches it easily. Gram-negative bacteria have a thin peptidoglycan layer covered by an outer membrane that keeps much of the penicillin out.', wrong = '{"0": "The outer lipid membrane belongs to Gram-negative bacteria, and it blocks penicillin rather than absorbing it.", "1": "Gram-negative bacteria do have peptidoglycan, but only a thin layer hidden beneath their outer membrane.", "3": "Gram-positive bacteria have a cell wall with a thick peptidoglycan layer, which is why penicillin works well on them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7199' AND answer = 2;
UPDATE questions SET why = 'Some bacteria form endospores, which have a tough coat and very little water inside. These spores can survive boiling at 100 °C. An autoclave uses steam under pressure at about 121 °C for around 15 minutes, which kills even endospores, so instruments are fully sterilised.', wrong = '{"1": "Viruses cannot grow outside living cells at all, so they do not grow in boiling water.", "2": "Boiling water does not dissolve surgical steel instruments.", "3": "Autoclaving does not sharpen instruments. Its purpose is to kill all microbes, including spores."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7200' AND answer = 0;
UPDATE questions SET why = 'DNA is copied during the S phase of interphase, so after S the cell holds twice the diploid amount of DNA. The next stage is G₂, when the cell grows and prepares for mitosis but has not started dividing. A cell with doubled DNA and no sign of mitosis is therefore in G₂.', wrong = '{"1": "In G₁ the DNA has not yet been copied, so the cell has the normal diploid amount.", "2": "In early S phase replication has only just begun, so the DNA is not yet fully doubled.", "3": "In telophase the cell is clearly dividing, with chromosomes at the poles and nuclei re-forming."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7201' AND answer = 0;
UPDATE questions SET why = 'The spindle fibres that move chromosomes are made of microtubules, built from tubulin. Colchicine stops microtubules forming, so no spindle develops. Chromosomes condense and gather, but the chromatids cannot be pulled apart, so cells are held at metaphase. This is used to prepare karyotypes.', wrong = '{"0": "DNA replication does not need microtubules, so cells can pass through interphase normally.", "2": "Without a spindle the chromatids never separate, so the cells do not reach telophase.", "3": "Chromosome condensation in prophase does not depend on microtubules, so cells pass prophase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7202' AND answer = 1;
UPDATE questions SET why = 'In anaphase I of meiosis, whole homologous chromosomes move to opposite poles. Each daughter cell then gets only one chromosome of each pair, so the number is halved from 2n to n. In anaphase II, as in mitosis, sister chromatids separate, which does not change the chromosome number.', wrong = '{"1": "Separating sister chromatids in anaphase II keeps the number the same, because each chromatid becomes a chromosome.", "2": "DNA replication in S phase doubles the DNA, but the chromosome number stays the same.", "3": "Mitosis keeps the chromosome number constant, giving two cells identical to the parent."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7203' AND answer = 0;
UPDATE questions SET why = 'Meiosis I separates homologous chromosomes, so each daughter cell gets one chromosome of each pair: 46 ÷ 2 = 23. The sister chromatids of each chromosome are still joined at the centromere. They separate only in meiosis II, so each chromosome still has two chromatids.', wrong = '{"1": "46 chromosomes of one chromatid each is the state of a cell after mitosis, not meiosis I.", "2": "Chromosomes made of single chromatids appear only after meiosis II, when sister chromatids separate.", "3": "46 chromosomes of two chromatids each is the state of the primary spermatocyte before meiosis I."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7204' AND answer = 0;
UPDATE questions SET why = 'Before mitosis, all 46 chromosomes are copied during S phase. At metaphase each chromosome is still made of two sister chromatids joined at the centromere. So the cell has 46 chromosomes and 46 × 2 = 92 chromatids.', wrong = '{"0": "Each chromosome at metaphase has two chromatids, so there are 92 chromatids, not 46.", "2": "Mitosis does not halve the chromosome number, so a human cell has 46 chromosomes at metaphase, not 23.", "3": "The chromatids separate and count as 92 chromosomes only in anaphase, not metaphase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7205' AND answer = 1;
UPDATE questions SET why = 'Normal cells pass checkpoints in the cell cycle that stop division when cells are crowded, damaged or not signalled to divide. In cancer, mutations in genes that control these checks, such as proto-oncogenes and tumour-suppressor genes, switch the controls off. The cells divide by mitosis without control and form a tumour.', wrong = '{"0": "Cancer cells replicate their DNA again and again as they keep dividing.", "2": "Cancer cells have a nucleus, which often looks enlarged and abnormal.", "3": "Cancer cells divide by mitosis, not meiosis, which happens only in making gametes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7206' AND answer = 1;
UPDATE questions SET why = 'In differential centrifugation, the largest and densest particles settle at the lowest speed. Nuclei are the largest, so they form the first pellet. Mitochondria come next, then small fragments of ER called microsomes, and ribosomes, the smallest, need the highest speed.', wrong = '{"0": "This is the reverse order. Ribosomes are the smallest and settle last, not first.", "1": "Nuclei are larger than mitochondria, so they settle first at low speed.", "2": "Ribosomes are the smallest particles, so they settle last, after mitochondria and microsomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7207' AND answer = 3;
UPDATE questions SET why = 'An isotonic solution has the same water potential as the organelles, so there is no net movement of water by osmosis. Organelles therefore neither swell and burst nor shrink. The solution is also ice-cold to slow enzymes that could damage organelles, and buffered to keep the pH steady.', wrong = '{"1": "The solution is kept cold to slow enzymes down, not to make them work faster.", "2": "A buffer is used to prevent pH changes, not to cause them.", "3": "The aim is to separate organelles cleanly, not to make them clump together."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7208' AND answer = 0;
UPDATE questions SET why = 'Primary succession starts on bare rock or newly formed land where there is no soil. Pioneer species such as lichens and mosses break down rock and add organic matter, slowly building soil for other plants. Secondary succession starts where soil remains after a disturbance, so it is faster.', wrong = '{"0": "Succession after a forest fire, where soil remains, is secondary succession.", "1": "Primary succession is slower than secondary succession because soil must form first.", "2": "Both primary and secondary succession can eventually reach a stable climax community."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7209' AND answer = 3;
UPDATE questions SET why = 'An abandoned field already has soil and seeds in it. Annual weeds colonise first, then grasses and shrubs, and finally trees, as the community passes through stages towards a climax. Succession that starts on existing soil after a disturbance is called secondary succession.', wrong = '{"0": "Primary succession begins on bare surfaces with no soil, such as bare rock. A farm field already has soil.", "1": "An ecological pyramid shows feeding levels at one time. It does not describe change in a community over time.", "3": "Exponential growth describes the rise of one population. Here whole communities replace each other."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7210' AND answer = 2;
UPDATE questions SET why = 'Many plant cells are totipotent: they keep all the genes needed to form a complete plant and can still divide and specialise. A leaf cell placed on a nutrient medium with suitable hormones divides to form a callus, which can then develop shoots and roots and grow into a whole plant.', wrong = '{"0": "Leaf cells are diploid, not haploid. Haploid cells are found in pollen and ovules.", "1": "Mature plant cells in culture can start dividing again. This is what makes tissue culture possible.", "3": "Plant cells have cell walls. Wall-free cells, called protoplasts, are made only by removing them with enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7211' AND answer = 2;
UPDATE questions SET why = 'Skoog and Miller showed that the balance of two plant hormones decides what a callus forms. A high ratio of cytokinin to auxin promotes shoots. A high ratio of auxin to cytokinin promotes roots. Roughly equal amounts keep the callus growing without forming organs.', wrong = '{"0": "Shoots form when cytokinin is high relative to auxin, the opposite of the condition here.", "1": "Flowering is not what the auxin to cytokinin ratio controls in a callus.", "2": "The callus does not die. With high auxin it develops roots."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7212' AND answer = 3;
UPDATE questions SET why = 'Algae contain chlorophyll and make their own food by photosynthesis, usually have cell walls of cellulose and store starch. Fungi have no chlorophyll, absorb food from their surroundings as heterotrophs, have cell walls of chitin and store glycogen. So photosynthesis with cellulose walls versus heterotrophy with chitin walls separates them.', wrong = '{"0": "The wall materials are swapped. Algae usually have cellulose walls, and fungi have chitin walls.", "1": "The storage products are swapped. Algae store starch, and fungi store glycogen.", "3": "Algae are eukaryotes. Cyanobacteria are the photosynthetic prokaryotes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7213' AND answer = 2;
UPDATE questions SET why = 'A lichen is a close partnership in which both partners benefit (mutualism). The alga or cyanobacterium photosynthesises and supplies carbohydrates. The fungus absorbs and holds water and minerals and shelters its partner. Together they can live on bare rock as pioneer organisms.', wrong = '{"0": "Fungi have no chlorophyll and cannot photosynthesise. In a lichen the alga makes the food.", "2": "A fungus attacking a plant root is parasitism, not mutualism, and a lichen does not involve plant roots.", "3": "Nitrogen-fixing bacteria in legume root nodules are a different association, between a bacterium and a plant."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7214' AND answer = 1;
UPDATE questions SET why = 'HIV stands for Human Immunodeficiency Virus. It infects and destroys helper T lymphocytes, which coordinate the immune response. As their numbers fall, the immune system becomes very weak, and the person develops AIDS (acquired immunodeficiency syndrome).', wrong = '{"1": "There is no virus with this name. The I in HIV stands for immunodeficiency.", "2": "This is not what HIV stands for. The H stands for human and the I for immunodeficiency.", "3": "HIV is a virus that causes disease, not a vaccine. The V stands for virus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9001' AND answer = 0;
UPDATE questions SET why = 'The oesophagus is a muscular tube that carries swallowed food from the pharynx to the stomach by peristalsis. Its wall secretes mucus to help the food slide down, but it makes no digestive enzymes. Salivary amylase swallowed with the food may keep working there, but the oesophagus itself does not digest food.', wrong = '{"0": "Digestion begins in the mouth: chewing breaks food up, and salivary amylase starts digesting starch.", "2": "The stomach digests proteins with pepsin in acid conditions produced by HCl.", "3": "Most chemical digestion and nearly all absorption of food take place in the small intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9002' AND answer = 1;
UPDATE questions SET why = 'Pacinian corpuscles are nerve endings wrapped in a layered capsule. They lie deep in the dermis of the skin and respond to deep pressure and vibration. Other skin receptors, such as Merkel cells, detect light touch nearer the surface.', wrong = '{"0": "The retina of the eye contains photoreceptors, rods and cones, which respond to light.", "1": "The lungs have stretch receptors that help control breathing, not Pacinian corpuscles as a sense organ for pressure.", "2": "The liver is a metabolic organ. It is not where pressure receptors of the body are known to lie."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9003' AND answer = 3;
UPDATE questions SET why = 'The inner ear contains hair cells in the cochlea, which detect sound, and in the vestibular apparatus, which detect balance. These hair cells respond when movement of fluid bends their hair-like projections. Because they respond to mechanical movement, they are mechanoreceptors.', wrong = '{"1": "Thermoreceptors respond to changes in temperature, such as those in the skin.", "2": "Nociceptors respond to painful or damaging stimuli.", "3": "Photoreceptors respond to light. They are the rods and cones of the retina."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9004' AND answer = 0;
UPDATE questions SET why = 'Smell is detected when odour molecules from food dissolve in the mucus of the nose and bind to olfactory receptors. Receptors that respond to chemicals are called chemoreceptors. Taste receptors on the tongue are also chemoreceptors.', wrong = '{"1": "Mechanoreceptors respond to touch, pressure, sound and stretch, not to odour chemicals.", "2": "Nociceptors respond to pain caused by damaging stimuli.", "3": "Photoreceptors respond to light. They are found in the retina."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9005' AND answer = 0;
UPDATE questions SET why = 'Skeletal muscle is attached to bones and is under conscious (voluntary) control. It is the only voluntary type of muscle, and it also makes up most of the body''s muscle mass. Cardiac and smooth muscle are involuntary.', wrong = '{"0": "Cardiac muscle is involuntary and is found only in the wall of the heart.", "2": "Smooth muscle is involuntary and is found in the walls of organs such as the gut and blood vessels.", "3": "Both smooth and cardiac muscle are involuntary, so neither is a voluntary muscle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9006' AND answer = 1;
UPDATE questions SET why = 'A cell has three main types of RNA. Ribosomal RNA (rRNA) makes up about 80% and transfer RNA (tRNA) about 10 to 15%. Messenger RNA is made and broken down quickly, so at any time it is only about 3 to 4% of the total RNA, even though it carries the genetic message to the ribosomes.', wrong = '{"1": "4 to 5% is higher than the standard figure. mRNA makes up only about 3 to 4% of cellular RNA.", "2": "5 to 6% is too high. mRNA is short-lived, so it forms only about 3 to 4% of total RNA.", "3": "6 to 7% is too high. Most RNA is rRNA (about 80%) and tRNA (10 to 15%), leaving about 3 to 4% for mRNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9007' AND answer = 0;
UPDATE questions SET why = 'The stomach wall has four layers. The innermost layer, lining the lumen, is the mucosa. It contains the gastric glands, whose cells secrete pepsinogen (chief cells), HCl (parietal cells) and mucus (mucous cells).', wrong = '{"0": "The submucosa lies under the mucosa. It is connective tissue carrying blood vessels and nerves, not gastric glands.", "2": "The muscularis is the muscle layer that contracts to churn and mix food with gastric juice.", "3": "The serosa is the thin outer covering of the stomach, not the inner lining."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9008' AND answer = 1;
UPDATE questions SET why = 'Lamarck proposed that organs used often become stronger and organs not used become weaker during an organism''s life. He called the features gained in this way acquired characters and claimed they are passed to offspring. This idea is known as the inheritance of acquired characters.', wrong = '{"0": "Prominent characters is not a term from Lamarck''s theory.", "1": "Biological characters is too general and is not the term Lamarck used for traits gained by use and disuse.", "3": "Physical characters is too general and is not Lamarck''s term for traits gained during life."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9009' AND answer = 2;
UPDATE questions SET why = 'Bone matrix contains collagen fibres, which give flexibility and strength. Crystals of calcium phosphate, in the form called hydroxyapatite, are laid down on these fibres and make the bone hard. If the minerals are removed, bone becomes rubbery; if the collagen is removed, it becomes brittle.', wrong = '{"0": "Calcium oxalate is the usual material of many kidney stones. It is not the mineral that hardens bone.", "2": "Magnesium and nitrate are not the main minerals of bone.", "3": "Iron is found in haemoglobin and glycogen is a stored carbohydrate. Neither hardens bone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9010' AND answer = 1;
UPDATE questions SET why = 'The wall of the intestine contains two layers of smooth muscle, one circular and one longitudinal. These involuntary muscles contract in waves, squeezing the food along the gut. These waves are called peristalsis.', wrong = '{"1": "Cardiac muscle is found only in the wall of the heart.", "2": "Skeletal muscle is found only at the two ends of the gut, around the mouth, upper oesophagus and anus, not in the intestine.", "3": "Neither skeletal nor cardiac muscle forms the intestinal wall, which is made of smooth muscle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9011' AND answer = 0;
UPDATE questions SET why = 'In the Watson-Crick model, one complete turn of the double helix is 3.4 nm long, and neighbouring base pairs are 0.34 nm apart. So one turn contains 3.4 ÷ 0.34 = 10 base pairs.', wrong = '{"0": "6 base pairs is too few. A full turn of 3.4 nm with base pairs 0.34 nm apart holds 10.", "1": "8 base pairs is too few. 3.4 nm ÷ 0.34 nm = 10 base pairs per turn.", "3": "12 base pairs is too many. 3.4 nm ÷ 0.34 nm gives 10 base pairs per turn."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9012' AND answer = 2;
UPDATE questions SET why = 'Chewing (mastication) breaks food into many small pieces. This greatly increases the surface area on which digestive enzymes, such as salivary amylase, can act, so digestion is faster. It also makes food easier to swallow.', wrong = '{"0": "Chewing does soften food, but its main purpose is to increase the surface area for enzymes.", "1": "Food is moistened mainly by saliva. Chewing mixes it in but this is not its main purpose.", "3": "Improving taste is not the purpose of chewing. Its main role is to help digestion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9013' AND answer = 2;
UPDATE questions SET why = 'Follicle stimulating hormone (FSH) is released by the anterior pituitary. As its name says, it stimulates primary follicles in the ovary to grow and mature. The growing follicle then secretes oestrogen.', wrong = '{"0": "Oestrogen is made by the growing follicle after FSH has started its development.", "1": "Progesterone is made by the corpus luteum after ovulation. It prepares the uterus lining for implantation.", "2": "LH triggers ovulation and the formation of the corpus luteum. It does not start follicle development."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9014' AND answer = 3;
UPDATE questions SET why = 'A sensory neuron carries impulses from a receptor towards the central nervous system. It has one long dendron that brings impulses from the receptor to the cell body, which lies in the dorsal root ganglion. A short axon then carries impulses into the spinal cord.', wrong = '{"0": "Every neuron has an axon, so a single axon does not distinguish sensory neurons.", "2": "Many short dendrites around the cell body are typical of motor neurons, not sensory neurons.", "3": "Nodes of Ranvier occur on myelinated fibres of many neurons, and sensory neurons do have a dendron."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9015' AND answer = 1;
UPDATE questions SET why = 'Nissl''s granules are groups of ribosomes and rough endoplasmic reticulum in the cytoplasm of the neuron''s cell body (soma). They make the proteins the neuron needs, including those used to make neurotransmitters. They are absent from the axon.', wrong = '{"0": "The axoplasm, the cytoplasm of the axon, does not contain Nissl''s granules.", "1": "The myelin sheath is formed by Schwann cells wrapping around the axon. It is not part of the neuron''s cytoplasm.", "2": "Nissl''s granules are concentrated in the cell body, not in the tips of the dendrites."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9016' AND answer = 3;
UPDATE questions SET why = 'The cerebellum lies at the back of the brain below the cerebrum. It receives information from muscles, joints, eyes and ears and uses it to coordinate muscle activity. This makes movements smooth and accurate and keeps balance and posture.', wrong = '{"0": "The thalamus acts as the relay station that passes sensory impulses to the cerebrum.", "1": "The hippocampus, part of the limbic system, turns short-term memories into long-term memories.", "3": "The hypothalamus links the nervous and endocrine systems by controlling the pituitary gland."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9017' AND answer = 2;
UPDATE questions SET why = 'Specific immunity targets particular antigens and forms memory cells. It is carried out by lymphocytes. B lymphocytes produce antibodies against specific antigens, and T lymphocytes kill infected cells or help activate other immune cells.', wrong = '{"0": "Erythrocytes (red blood cells) carry oxygen and have no role in immunity.", "1": "Thrombocytes (platelets) help blood to clot at a wound. They play no part in specific immunity.", "2": "Neutrophils are phagocytes that engulf any microbe, so they are part of non-specific defence."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9018' AND answer = 3;
UPDATE questions SET why = 'A competitive inhibitor has a shape similar to the substrate and competes with it for the active site. Raising the substrate concentration means substrate molecules occupy the active site more often than the inhibitor. So competitive inhibition can be overcome and the rate is restored.', wrong = '{"0": "A non-competitive inhibitor binds at another site and changes the enzyme''s shape, so extra substrate cannot reverse it.", "2": "An irreversible inhibitor binds permanently to the enzyme, so adding substrate cannot remove it.", "3": "An allosteric inhibitor binds at a site away from the active site, so extra substrate does not reverse it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9019' AND answer = 1;
UPDATE questions SET why = 'Sperms are gametes, so they are haploid and carry one set of chromosomes: n = 8. Body cells are diploid and carry two sets, one from each parent. So body cells have 2n = 2 × 8 = 16 chromosomes.', wrong = '{"0": "4 is half of the haploid number. Body cells have twice, not half, the number in a sperm.", "2": "24 would be 3 × 8, a triploid number. Normal body cells are diploid.", "3": "32 would be 4 × 8, a tetraploid number. Normal body cells are diploid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9020' AND answer = 1;
UPDATE questions SET why = 'The Golgi apparatus is a stack of flattened sacs. It receives proteins and lipids from the ER, modifies them, for example by adding carbohydrate, then sorts and packs them into vesicles. These vesicles are sent for secretion or for use inside the cell.', wrong = '{"0": "Energy production as ATP is the job of mitochondria, through aerobic respiration.", "2": "Genetic material (DNA) is stored in the nucleus, not in the Golgi apparatus.", "3": "Proteins are made on ribosomes. The Golgi modifies them afterwards."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9021' AND answer = 1;
UPDATE questions SET why = 'In natural selection, individuals vary, and those with heritable traits that suit the environment survive and reproduce more. Their offspring therefore make up a larger share of each new generation. Over time the favourable traits become more common in the population.', wrong = '{"0": "Mutation creates new variation, but it does not by itself make better-adapted individuals leave more offspring.", "1": "Inheritance of acquired characters is Lamarck''s idea and is not supported by evidence.", "3": "Genetic drift is a random change in allele frequencies, especially in small populations. It is not linked to adaptation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9022' AND answer = 2;
UPDATE questions SET why = 'Temperature receptors and the hypothalamus detect a fall in body temperature. The hypothalamus then sends nerve impulses to skeletal muscles, which contract rapidly and repeatedly. This shivering produces heat. Because it is started by nerve signals, the nervous system directly controls it.', wrong = '{"0": "The respiratory system exchanges gases. It does not start shivering.", "1": "The circulatory system carries heat around the body, but it does not send commands to the muscles.", "3": "The digestive system is not involved in starting shivering."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9023' AND answer = 2;
UPDATE questions SET why = 'Trypsinogen is the inactive form of trypsin secreted by the pancreas. In the small intestine, the enzyme enterokinase, made by the intestinal wall, converts trypsinogen into active trypsin. Without enterokinase, trypsinogen stays inactive.', wrong = '{"0": "Pepsinogen is activated by hydrochloric acid in the stomach, not by enterokinase.", "2": "Pancreatic amylase is secreted in its active form and does not need enterokinase.", "3": "Pancreatic lipase is secreted in its active form. Bile helps it by emulsifying fats, but enterokinase is not needed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9024' AND answer = 1;
UPDATE questions SET why = 'Acetylcholine is the neurotransmitter released at neuromuscular junctions, where motor neurons stimulate skeletal muscle. It is also used widely in the autonomic nervous system and in the brain. So it works widely both inside and outside the brain.', wrong = '{"0": "Dopamine acts mainly within the brain, for example in control of movement and reward.", "1": "As a neurotransmitter, serotonin acts mainly in the brain, affecting mood and sleep.", "3": "Melatonin is a hormone of the pineal gland that helps control sleep. It is not a neurotransmitter at synapses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9025' AND answer = 2;
UPDATE questions SET why = 'Deamination of amino acids in the liver produces ammonia, which is very toxic. Liver cells combine ammonia with CO₂ in the ornithine cycle, also called the urea cycle, to form urea. Urea is much less toxic and is carried in the blood to the kidneys to be excreted.', wrong = '{"0": "The carbon cycle is an ecological cycle of carbon between organisms and the environment, not a liver pathway.", "1": "Glycolysis breaks glucose down into pyruvate. It does not make urea.", "3": "The Krebs cycle oxidises acetyl CoA to release energy. It does not convert ammonia into urea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9026' AND answer = 2;
UPDATE questions SET why = 'Each villus of the small intestine has a network of blood capillaries and a central lymph capillary called a lacteal. Fats are absorbed into the lacteal as chylomicrons and carried away in the lymph. Glucose and amino acids enter the blood capillaries instead.', wrong = '{"0": "Microvilli are tiny finger-like folds of the membrane of the epithelial cells that cover each villus.", "1": "The brush border is the surface formed by the microvilli of the epithelial cells.", "3": "Lymph nodes lie along lymph vessels in places such as the neck and armpits, not inside villi."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9027' AND answer = 2;
UPDATE questions SET why = 'During transcription, mRNA is made from DNA in the nucleus. It then leaves through nuclear pores and attaches to ribosomes in the cytoplasm. There, tRNAs bring amino acids that match each codon, and the protein is built. This step is translation.', wrong = '{"0": "The nucleolus makes ribosomal RNA. Translation happens on ribosomes in the cytoplasm.", "2": "The Golgi apparatus modifies and packages proteins after translation. It does not read mRNA.", "3": "Lysosomes contain enzymes that digest materials. They do not take part in protein synthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9028' AND answer = 1;
UPDATE questions SET why = 'Animals excrete nitrogen as ammonia, urea or uric acid. Uric acid is the least toxic of the three and is nearly insoluble in water. It can therefore be stored safely and passed out as a paste or solid with very little water, as in birds, reptiles and insects.', wrong = '{"0": "Ammonia is very toxic and very soluble, so it needs a large amount of water to dilute and flush it out.", "1": "Urea is less toxic than ammonia but is soluble, so it needs a moderate amount of water to excrete.", "3": "Creatinine is a minor nitrogenous waste from muscle. It is not the main water-saving form of excretion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9029' AND answer = 2;
UPDATE questions SET why = 'About 70% of kidney stones are made of calcium oxalate, and others contain calcium phosphate. These stones form mainly when there is too much calcium in the urine (hypercalciuria), which often follows a high blood calcium level. The calcium salts then crystallise in the kidney. Too much oxalate and dehydration also add to the risk.', wrong = '{"0": "A low rate of filtration in Bowman''s capsule is not the main cause of kidney stones.", "1": "Protein digestion in the stomach does not produce the crystals that form kidney stones.", "2": "High blood glucose is a sign of diabetes mellitus. It is not the main cause of kidney stones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9030' AND answer = 3;
UPDATE questions SET why = 'A virus has a protein coat called the capsid that surrounds its nucleic acid. The capsid is built from many identical protein subunits called capsomeres, arranged in a regular pattern. Their arrangement gives the virus its helical or polyhedral shape.', wrong = '{"0": "Nucleic acid, DNA or RNA, is the genome inside the capsid. It is not a protein unit of the coat.", "2": "The core is the nucleic acid in the centre of the virus, not the repeating units of the coat.", "3": "The envelope is a lipid membrane that surrounds the capsid of some viruses. It is not made of capsomeres."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9031' AND answer = 1;
UPDATE questions SET why = 'Haemophilia is caused by a recessive gene on the X chromosome. A father passes his X chromosome to every daughter and his Y chromosome to every son. So a man with haemophilia passes the gene to all his daughters and to none of his sons.', wrong = '{"0": "Sons receive their father''s Y chromosome, not his X, so they cannot get the haemophilia gene from him.", "2": "Sons never receive their father''s X chromosome, so the gene cannot reach sons and daughters equally.", "3": "Sons never receive their father''s X chromosome, so no sons receive the gene and there is no 2:1 ratio."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9032' AND answer = 1;
UPDATE questions SET why = 'Reverse transcriptase is an enzyme first found in retroviruses such as HIV. It builds a DNA strand using RNA as the template, the reverse of normal transcription. In genetic engineering it is used to make complementary DNA (cDNA) from mRNA.', wrong = '{"0": "Restriction endonucleases cut DNA at specific base sequences. They do not make DNA from RNA.", "2": "DNA ligase joins pieces of DNA by sealing their sugar-phosphate backbones.", "3": "Helicase unwinds the DNA double helix during replication."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9033' AND answer = 1;
UPDATE questions SET why = 'Prokaryotic cells, such as bacteria, have no membrane-bound organelles, so they have no mitochondria. They carry out respiration using enzymes on their cell membrane. They do have circular DNA, 70S ribosomes and a cell membrane.', wrong = '{"1": "Prokaryotes do have DNA, as a single circular molecule lying in the cytoplasm.", "2": "Prokaryotes have ribosomes of the smaller 70S type, which they use to make proteins.", "3": "Every cell, prokaryotic or eukaryotic, is surrounded by a cell membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9034' AND answer = 0;
UPDATE questions SET why = 'When a neuron is not carrying an impulse, the inside of its membrane is negative compared with the outside. This resting membrane potential is about −70 mV. It is maintained by the Na⁺/K⁺ pump and by K⁺ leaking out through membrane channels.', wrong = '{"0": "About −50 to −55 mV is near the threshold that must be reached to fire an action potential, not the resting value.", "1": "At rest the inside of the neuron is negative, not positive, compared with the outside.", "3": "The inside is negative at rest. Positive values are reached only briefly during an action potential."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9035' AND answer = 2;
UPDATE questions SET why = 'Synovial fluid is secreted by the synovial membrane and lubricates freely movable joints. In arthritis, especially osteoarthritis, the joint has less synovial fluid and the articular cartilage wears away. Bones rub together with more friction, causing pain and stiffness.', wrong = '{"0": "Gout is a form of arthritis caused by uric acid crystals deposited in a joint, often the big toe, not by loss of synovial fluid.", "2": "Rickets is softening of bones in children due to lack of vitamin D. It is not a joint disease.", "3": "Sciatica is pain along the sciatic nerve caused by pressure on it, often from a slipped disc."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9036' AND answer = 1;
UPDATE questions SET why = 'Many axons are wrapped in a myelin sheath formed by Schwann cells. Between neighbouring Schwann cells there are short gaps where the axon is bare. These gaps are the nodes of Ranvier, and impulses jump from one node to the next in saltatory conduction.', wrong = '{"1": "Schwann cells are the cells that form the myelin sheath, not the gaps in it.", "2": "Neuroglia are supporting cells of the nervous system, not gaps along an axon.", "3": "A dendron is a long fibre that carries impulses towards the cell body."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9037' AND answer = 0;
UPDATE questions SET why = 'High temperature makes the atoms in an enzyme vibrate so strongly that the weak bonds holding its 3D shape break. The active site loses its shape, so the substrate no longer fits. This is denaturation, and it slows or stops catalysis permanently.', wrong = '{"0": "Low temperature slows enzyme activity because molecules move more slowly, but it does not denature the enzyme.", "2": "Enzymes work in water, so a high water content does not denature them.", "3": "Low water content can lower enzyme activity, but it does not denature the enzyme in the way heat does."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9038' AND answer = 1;
UPDATE questions SET why = 'Gastric glands contain several kinds of cells. The parietal, or oxyntic, cells secrete hydrochloric acid, which kills microbes and activates pepsinogen. They also secrete intrinsic factor, needed to absorb vitamin B₁₂.', wrong = '{"1": "Pepsinogen is secreted by the chief (peptic) cells of the gastric glands.", "2": "Mucus is secreted by mucous cells, and it protects the stomach lining from acid.", "3": "Gastrin is a hormone secreted by endocrine G cells of the stomach, not parietal cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9039' AND answer = 0;
UPDATE questions SET why = 'Pepsinogen is secreted by chief cells in an inactive form so that it does not digest the cells that make it. In the stomach, hydrochloric acid gives a low pH of about 2. This acid converts pepsinogen into active pepsin, which then digests proteins.', wrong = '{"1": "A high, alkaline pH would inactivate pepsin. That is why pepsin stops working in the duodenum.", "2": "Body temperature is suitable for enzyme action, but it does not by itself turn pepsinogen into pepsin.", "3": "Freezing temperature stops enzyme activity. It does not activate enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9040' AND answer = 0;
UPDATE questions SET why = 'Pumping substances against their concentration gradient is active transport, and it uses energy from ATP. Most of a cell''s ATP is made by aerobic respiration in the mitochondria. So the mitochondrion supplies the energy for this process.', wrong = '{"0": "The nucleus contains DNA and controls the cell''s activities, but it does not make ATP.", "2": "The Golgi apparatus modifies and packages proteins and lipids. It does not produce ATP.", "3": "The endoplasmic reticulum makes and transports proteins and lipids. It is not the main source of ATP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9041' AND answer = 1;
UPDATE questions SET why = 'Viruses are classified mainly by their structure and by their nucleic acid. Structure includes the shape of the capsid and whether an envelope is present. The nucleic acid may be DNA or RNA and single- or double-stranded. The type of host is also used.', wrong = '{"0": "Viruses have no colour of their own, and size alone is not the basis of their classification.", "2": "Viruses live only inside host cells, so habitat is not used as the main basis for classifying them.", "3": "Temperature tolerance is not a basis for classifying viruses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9042' AND answer = 1;
UPDATE questions SET why = 'Linked genes are different genes that lie on the same chromosome. Because they are on one chromosome, they tend to be inherited together. They are separated only when crossing over occurs between them during meiosis.', wrong = '{"0": "Two different genes cannot occupy the same locus. Only alleles of one gene share a locus.", "2": "Alleles are different forms of one gene. Linkage refers to two different genes on one chromosome.", "3": "Traits that depend on sex describe sex-linked or sex-limited inheritance, not linkage in general."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9043' AND answer = 1;
UPDATE questions SET why = 'Ribosome size is measured in Svedberg units (S), based on how fast they settle in a centrifuge. Prokaryotes have smaller 70S ribosomes, while the ribosomes in the cytoplasm of eukaryotes are larger, 80S. Mitochondria and chloroplasts also have 70S ribosomes.', wrong = '{"0": "Prokaryotes have the smaller 70S ribosomes, not 80S.", "1": "This reverses the two. Prokaryotes have 70S ribosomes and eukaryotes have 80S.", "3": "Both prokaryotic and eukaryotic cells make their proteins on ribosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9044' AND answer = 2;
UPDATE questions SET why = 'The peritubular capillaries are formed from the efferent arteriole and wrap closely around the renal tubules. Useful substances reabsorbed from the filtrate, such as glucose, amino acids, salts and water, pass into these capillaries and return to the circulation. They also carry substances to be secreted into the tubule.', wrong = '{"0": "Capillaries deliver oxygen to kidney cells. They do not take oxygen away from them.", "1": "Capillaries carry carbon dioxide away from kidney cells. They do not supply it.", "2": "Most urea is left in the filtrate to be excreted. Reabsorbing urea is not their main role."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9045' AND answer = 3;
UPDATE questions SET why = 'Linked genes lie on the same chromosome and tend to be inherited together. As a result, offspring mostly show the parental combinations of these genes, and fewer new combinations (recombinants) appear. So gene linkage reduces variation among offspring.', wrong = '{"0": "Meiosis increases variation through independent assortment and crossing over.", "1": "Epistasis changes the phenotype ratios produced by two genes, but it does not reduce genetic variation.", "2": "Crossing over increases variation by separating linked genes and forming new combinations."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9046' AND answer = 3;
UPDATE questions SET why = 'In a reflex arc, a receptor detects the stimulus and sends impulses along a sensory neuron into the CNS. In the spinal cord, a relay neuron passes the signal to a motor neuron. The motor neuron carries impulses from the CNS to an effector, such as a muscle, which responds.', wrong = '{"0": "Impulses never travel from the CNS to receptors. Receptors send impulses into the CNS.", "1": "This reverses the direction of the arc. Impulses go from receptors to the CNS, then out to effectors.", "3": "This also reverses the arc. Effectors receive impulses from the CNS; they do not send them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9047' AND answer = 2;
UPDATE questions SET why = 'Blood enters the glomerulus through the afferent arteriole and is filtered. The remaining blood leaves through the efferent arteriole, which is narrower and helps keep pressure high in the glomerulus. The efferent arteriole then branches to form the peritubular capillaries.', wrong = '{"0": "The renal artery brings blood from the aorta to the kidney, before it reaches any glomerulus.", "1": "The renal vein drains blood from the whole kidney later, after it has passed through the peritubular capillaries.", "2": "The afferent arteriole carries blood into the glomerulus, not away from it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9048' AND answer = 3;
UPDATE questions SET why = 'A ganglion is a cluster of neuron cell bodies lying outside the central nervous system. The dorsal root ganglion of a spinal nerve, for example, contains the cell bodies of sensory neurons. Bundles of axons, by contrast, form nerves.', wrong = '{"0": "Ganglia contain the cell bodies of neurons. Their long fibres extend away from the ganglion.", "2": "Bundles of axon fibres form nerves or tracts, not ganglia.", "3": "Bundles of nerve fibres make up nerves. Ganglia are clusters of cell bodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9049' AND answer = 1;
UPDATE questions SET why = 'The sarcoplasmic reticulum is a network of membranes around each myofibril that stores Ca²⁺ ions. When an impulse arrives, it spreads along the sarcolemma and down the T-tubules, making the sarcoplasmic reticulum release Ca²⁺ into the cytosol. The Ca²⁺ binds troponin and starts contraction.', wrong = '{"0": "The sarcolemma is the cell membrane of the muscle fibre. It carries the impulse but does not store calcium.", "1": "The sarcomere is the contractile unit between two Z lines. It is not a calcium store.", "3": "Myofilaments of actin and myosin slide to cause contraction. They respond to Ca²⁺ but do not release it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9050' AND answer = 2;
UPDATE questions SET why = 'After ovulation, the empty follicle turns into the corpus luteum. It secretes mainly progesterone, along with some oestrogen. Progesterone keeps the uterine lining thick and ready for a pregnancy.', wrong = '{"0": "Luteinising hormone is made by the anterior pituitary. It causes the corpus luteum to form but is not made by it.", "2": "Testosterone is the male sex hormone made by the interstitial cells of the testes.", "3": "Secretin is a hormone made by the duodenum. It stimulates the pancreas to release alkaline juice."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9051' AND answer = 1;
UPDATE questions SET why = 'In the glomerulus, blood is filtered under pressure through a membrane with tiny pores. Small molecules such as glucose, salts, urea and water pass into Bowman''s capsule. Plasma proteins and blood cells are too large and stay in the blood.', wrong = '{"0": "Plasma proteins are too large to pass the glomerular filter, so they are not part of the filtrate.", "1": "Plasma proteins are too large to be filtered, so this group cannot all enter Bowman''s capsule.", "3": "Plasma proteins are too large to be filtered, so this group cannot all enter Bowman''s capsule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9052' AND answer = 2;
UPDATE questions SET why = 'B lymphocytes are responsible for antibody-mediated immunity. When a B cell meets its matching antigen, it multiplies and becomes plasma cells. These plasma cells secrete large amounts of antibodies into the blood.', wrong = '{"0": "T lymphocytes give cell-mediated immunity by killing infected cells or helping other cells. They do not make antibodies.", "2": "Macrophages engulf pathogens and present antigens to lymphocytes, but they do not make antibodies.", "3": "Platelets help blood to clot. They have no role in making antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9053' AND answer = 1;
UPDATE questions SET why = 'Lymph nodes lie along lymph vessels and filter the lymph passing through them. Macrophages remove pathogens, and lymphocytes that meet their antigen multiply rapidly. During infection this makes the nodes swell, which people call swollen glands.', wrong = '{"0": "The spleen filters blood, not lymph, and it lies in the abdomen rather than forming local swellings.", "2": "Lymphatic ducts only carry lymph back into the veins. They do not filter it.", "3": "Lymph capillaries collect tissue fluid as lymph. They do not filter it or house dividing lymphocytes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9054' AND answer = 1;
UPDATE questions SET why = 'The left ventricle pumps blood into the aorta and around the whole body, the systemic circulation. This needs a high pressure to push blood a long way, so the left ventricle has the thickest, most muscular wall. The right ventricle only pumps blood the short distance to the lungs.', wrong = '{"0": "The right atrium only pushes blood a short way into the right ventricle, so its wall is thin.", "1": "The right ventricle pumps blood only to the nearby lungs, so its wall is thinner than the left ventricle''s.", "2": "The left atrium only pushes blood into the left ventricle, so its wall is thin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9055' AND answer = 3;
UPDATE questions SET why = 'By the time food reaches the colon, most nutrients have already been absorbed in the small intestine. The main job of the colon is to absorb water, along with some salts, from the remaining material, turning it into semi-solid faeces. A diseased colon therefore mainly affects water absorption, which can cause diarrhoea.', wrong = '{"0": "Glucose is absorbed in the small intestine, before food reaches the colon.", "2": "Fats are absorbed into the lacteals of the small intestine, not in the colon.", "3": "Amino acids are absorbed in the small intestine, before material reaches the colon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9056' AND answer = 1;
UPDATE questions SET why = 'The interstitial (Leydig) cells lie in the spaces between the seminiferous tubules of the testis. When stimulated by LH from the anterior pituitary, they secrete testosterone. Testosterone controls male secondary sexual characteristics and supports sperm production.', wrong = '{"1": "Sertoli cells line the seminiferous tubules and nourish developing sperm. They do not make testosterone.", "2": "Spermatogonia are the stem cells that divide to produce cells that become sperm.", "3": "Primary spermatocytes divide by meiosis to form sperm. They do not secrete hormones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9057' AND answer = 0;
UPDATE questions SET why = 'Lymph passes through lymph nodes on its way back to the blood. In the nodes, macrophages and lymphocytes filter out and destroy germs and toxins. The lymphatic system also returns excess tissue fluid to the blood and absorbs fats from the intestine.', wrong = '{"0": "Glucose is absorbed into the blood capillaries of the villi, not into the lymph.", "1": "Blood clotting is carried out by platelets and clotting factors in the blood.", "3": "Body temperature is controlled by the hypothalamus, using the skin, sweating and blood flow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9058' AND answer = 2;
UPDATE questions SET why = 'As the follicle matures, high oestrogen triggers a sudden surge of LH from the anterior pituitary in the middle of the cycle. This LH surge makes the mature Graafian follicle burst and release its egg. This release is ovulation.', wrong = '{"0": "Menstruation follows a fall in progesterone and oestrogen when the corpus luteum breaks down, not an LH surge.", "2": "Fertilisation needs a sperm to meet the egg. It is not caused by a hormone surge.", "3": "Implantation happens about a week after fertilisation and is supported by progesterone, not caused by LH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9059' AND answer = 1;
UPDATE questions SET why = 'Each turn of the Krebs cycle oxidises one acetyl group. It releases 2 CO₂ and produces reduced coenzymes, 3 NADH and 1 FADH₂, plus 1 ATP (via GTP). The NADH and FADH₂ carry hydrogen to the electron transport chain, where most ATP is made, so they are the main products.', wrong = '{"0": "Glucose and oxygen are products of photosynthesis, not of the Krebs cycle.", "2": "G3P is made in glycolysis and in the Calvin cycle, not in the Krebs cycle.", "3": "Pyruvate is made in glycolysis and acetyl CoA in the link reaction, before the Krebs cycle begins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9060' AND answer = 1;
UPDATE questions SET why = 'Blood leaves the right ventricle through the pulmonary artery to go to the lungs. At the base of the pulmonary artery is the pulmonary semilunar valve. When the ventricle relaxes, this valve closes and stops blood flowing back into the right ventricle.', wrong = '{"0": "The mitral (bicuspid) valve lies between the left atrium and left ventricle, on the other side of the heart.", "1": "The aortic semilunar valve stops blood flowing back from the aorta into the left ventricle.", "2": "The tricuspid valve stops blood flowing back from the right ventricle into the right atrium, not into the ventricle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9061' AND answer = 3;
UPDATE questions SET why = 'Bile salts are made in the liver and act as emulsifiers. They break large fat globules into tiny droplets, which greatly increases the surface area for lipase to act on. Lipase can then digest the fats into fatty acids and glycerol faster.', wrong = '{"0": "Proteins are digested by proteases such as pepsin and trypsin, without help from bile salts.", "2": "Nucleic acids are digested by nucleases. Bile salts do not act on them.", "3": "Carbohydrates are digested by amylase and other carbohydrases, not with help from bile salts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9062' AND answer = 1;
UPDATE questions SET why = 'The exocrine part of the pancreas releases pancreatic juice into the duodenum. Its carbohydrate-digesting enzyme is pancreatic amylase, which breaks starch down into the disaccharide maltose.', wrong = '{"0": "Pancreatic lipase digests fats into fatty acids and glycerol, not carbohydrates.", "1": "Trypsin is a protease that digests proteins into smaller polypeptides.", "2": "Enterokinase is made by the intestinal wall, not the pancreas, and it activates trypsinogen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9063' AND answer = 3;
UPDATE questions SET why = 'When acidic chyme from the stomach enters the duodenum, the acid stimulates endocrine cells in the duodenal wall to release secretin into the blood. Secretin makes the pancreas secrete juice rich in hydrogen carbonate, which neutralises the acid.', wrong = '{"0": "Acetylcholine is a neurotransmitter used by nerves. It is not the stimulus for secretin release.", "2": "Bile salts emulsify fats. They are not the trigger for secretin release.", "3": "Sodium bicarbonate is part of the response to secretin, not the stimulus that releases it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9064' AND answer = 1;
UPDATE questions SET why = 'The chordae tendineae are tough fibrous cords of connective tissue. They connect the flaps of the atrioventricular valves to the papillary muscles of the ventricle wall. When the ventricles contract, they stop the valve flaps from turning inside out into the atria.', wrong = '{"0": "Chordae tendineae carry no blood, so they are not blood vessels.", "2": "They attach to papillary muscles, which are cardiac muscle, but the cords themselves are fibrous tissue.", "3": "They are made of fibrous connective tissue, not epithelial tissue."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9065' AND answer = 1;
UPDATE questions SET why = 'Each Rr parent makes R and r gametes in equal numbers. Rr × Rr gives RR : Rr : rr in a 1 : 2 : 1 ratio. Since R (round) is dominant, RR and Rr are round, so 3/4 (75%) are round and 1/4 (25%) are wrinkled.', wrong = '{"0": "All round offspring would need at least one parent to be RR.", "1": "50% round and 50% wrinkled is the result of a test cross, Rr × rr.", "3": "All wrinkled offspring would need both parents to be rr."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9066' AND answer = 2;
UPDATE questions SET why = 'The endoplasmic reticulum is a network of membrane-bound channels that is continuous with the outer membrane of the nucleus. It spreads through the cytoplasm and carries proteins made on its ribosomes towards the Golgi apparatus and other parts of the cell.', wrong = '{"1": "Mitochondria produce ATP by aerobic respiration. They do not form transport channels.", "2": "The Golgi complex receives proteins from the ER and packages them, but it does not form the channels from the nucleus.", "3": "The nuclear membrane encloses the nucleus. The transport channels that extend from it are the ER."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9067' AND answer = 0;
UPDATE questions SET why = 'During the first exposure to an antigen, the immune system makes memory B and T cells. If the same antigen enters again, these memory cells respond quickly, giving a faster and larger secondary response. This ability is called immunological memory, and it is the basis of vaccination.', wrong = '{"0": "The primary immune response is the first, slower response to a new antigen, not the faster later one.", "2": "Short-term memory is a term for a brain function, not for the immune system.", "3": "Long-term memory is a term for a brain function, not the immunology term for this response."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9068' AND answer = 1;
UPDATE questions SET why = 'The coding (sense) strand of DNA has the same sequence as the mRNA, read 5′ to 3′, except it has T in place of U. The mRNA for Y-X-Y-Y-X-Z-Z-X-Z-Y is ACU UCA ACU ACU UCA GUC GUC UCA GUC ACU. So the coding strand is 5′-ACTTCAACTACTTCAGTCGTCTCAGTCACT-3′.', wrong = '{"0": "This is the mRNA sequence itself. DNA contains thymine (T), not uracil (U).", "2": "This is the template (antisense) strand, which is complementary to the mRNA, not the coding strand.", "3": "DNA never contains uracil, so a strand with U cannot be a DNA strand."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9069' AND answer = 1;
UPDATE questions SET why = 'Lamarck''s theory had three main ideas: use and disuse of organs, unused organs becoming reduced or vestigial, and inheritance of these acquired characters. Overproduction of offspring, leading to a struggle for existence, was part of Darwin''s theory of natural selection, not Lamarck''s. So this is the idea NOT proposed by Lamarck.', wrong = '{"0": "Use and disuse is one of Lamarck''s main ideas: organs used often grow stronger.", "1": "Inheritance of acquired characters is Lamarck''s central idea.", "2": "Lamarck did propose that organs not used become weaker and may become vestigial."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9070' AND answer = 3;
UPDATE questions SET why = 'At the plateau, every active site is occupied, so the enzyme is saturated and the amount of enzyme limits the rate. Adding more enzyme provides more active sites, so more substrate is converted each second and the rate rises further.', wrong = '{"0": "The enzyme is already saturated, so adding more substrate has no further effect.", "1": "Lowering the temperature slows the movement of molecules and lowers the rate.", "3": "A non-competitive inhibitor reduces enzyme activity, so it lowers the rate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9071' AND answer = 2;
UPDATE questions SET why = 'Quaternary structure is formed when two or more polypeptide chains join into one protein, as in haemoglobin. The chains are held together by the same kinds of bonds as tertiary structure: hydrophobic interactions, hydrogen bonds, ionic bonds and sometimes disulphide bridges. Hydrophobic interaction is the only one of these listed.', wrong = '{"0": "1,4-glycosidic bonds join sugar units in carbohydrates such as starch, not polypeptide chains.", "2": "Ester bonds join glycerol and fatty acids in lipids, not polypeptide chains.", "3": "1,6-glycosidic bonds form the branch points of glycogen and amylopectin, not links between polypeptides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9072' AND answer = 1;
UPDATE questions SET why = 'The medulla oblongata, at the base of the brain, contains the vital centres. The cardiac centre controls heart rate, the respiratory centre controls breathing and the vasomotor centre controls blood pressure. These work automatically, without conscious thought.', wrong = '{"0": "The cerebellum coordinates movement and maintains balance and posture.", "1": "The hypothalamus controls body temperature, thirst, hunger and the pituitary gland.", "3": "The cerebrum is responsible for thought, memory, senses and voluntary actions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9073' AND answer = 2;
UPDATE questions SET why = 'A thin filament is made of actin, with tropomyosin and troponin attached. In resting muscle, tropomyosin lies over the binding sites on the actin filament, so the heads of myosin cannot attach. When Ca²⁺ binds troponin, tropomyosin shifts and the myosin heads can bind.', wrong = '{"1": "Myosin heads are what attach to the binding sites. Myosin does not cover them.", "2": "Actin carries the binding sites. It is tropomyosin that covers them.", "3": "Myosin is the filament whose heads attach. The binding sites are on actin, covered by tropomyosin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9074' AND answer = 0;
UPDATE questions SET why = 'Crossing true-breeding green (GG) and yellow (gg) parents gives an F1 that is all Gg. Selfing Gg × Gg gives GG 25%, Gg 50% and gg 25%. The homozygotes are GG + gg = 25% + 25% = 50%.', wrong = '{"0": "Both kinds of homozygote, GG and gg, appear in the F2, so the answer cannot be 0%.", "1": "25% counts only one kind of homozygote, either GG or gg, but not both.", "3": "75% is the proportion showing the dominant green phenotype (GG + Gg), not the homozygotes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9075' AND answer = 2;
UPDATE questions SET why = 'The walls of the trachea and bronchi are supported by cartilage, but bronchioles have no cartilage. Their walls are mainly smooth muscle arranged in a circular way around the tube. When this muscle contracts or relaxes, the bronchioles narrow or widen and control air flow.', wrong = '{"0": "C-shaped cartilage rings support the trachea and primary bronchi, not the bronchioles.", "1": "Cartilage plates are found in the secondary bronchi. Bronchioles have no cartilage.", "3": "The smooth muscle of bronchioles runs around the tube in a circular way, which lets it change their width."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9076' AND answer = 2;
UPDATE questions SET why = 'Hyaline cartilage is the most common type of cartilage. It is smooth and firm and forms the costal cartilages joining the ribs to the sternum, the nose, the C-shaped rings of the trachea and the coverings at the ends of long bones.', wrong = '{"1": "Elastic cartilage is flexible and is found in the outer ear (pinna) and the epiglottis.", "2": "Fibrocartilage is very tough and is found in the intervertebral discs and the pubic symphysis.", "3": "An osteoblast is a bone-forming cell, not a type of cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9077' AND answer = 0;
UPDATE questions SET why = 'In early pregnancy, the corpus luteum secretes progesterone, which keeps the uterine lining thick and holds the embryo in place. If the corpus luteum breaks down too early, progesterone falls and the lining starts to break down. The embryo cannot stay implanted, so the pregnancy is lost.', wrong = '{"0": "The hormones of pregnancy suppress ovulation, and losing the corpus luteum does not cause more fertilisation.", "1": "Breakdown of the corpus luteum does not trigger extra LH release or the release of another egg.", "2": "Oestrogen falls along with progesterone when the corpus luteum breaks down, so it does not rise."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9078' AND answer = 3;
UPDATE questions SET why = 'The hepatic portal vein collects blood from the small intestine and carries it to the liver. This blood is rich in absorbed nutrients such as glucose and amino acids. The liver can then process and store them before they reach the rest of the body.', wrong = '{"0": "The renal vein carries blood away from the kidney to the inferior vena cava.", "2": "The iliac veins drain blood from the legs and pelvis.", "3": "The hepatic vein carries blood away from the liver to the inferior vena cava, not from the intestine to the liver."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9079' AND answer = 1;
UPDATE questions SET why = 'The two alleles of a gene lie on a pair of homologous chromosomes. In anaphase I of meiosis, the homologues separate and move to different cells. So each gamete receives only one allele of each gene. This is Mendel''s law of segregation.', wrong = '{"0": "In mitosis, sister chromatids separate, so each daughter cell gets both alleles, not just one.", "1": "Binary fission is the division method of prokaryotes. It does not separate alleles of homologous chromosomes.", "3": "DNA replication copies each allele. It does not separate the two alleles from each other."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9080' AND answer = 2;
UPDATE questions SET why = 'Linked genes lie on the same chromosome and are usually inherited together, so most offspring show parental phenotypes. During prophase I of meiosis, crossing over between non-sister chromatids can separate them. This forms a small number of recombinant gametes, which give non-parental phenotypes.', wrong = '{"1": "The same results have been repeated by many scientists, so contamination does not explain them.", "2": "Linked genes on the same chromosome do not assort independently.", "3": "Sweet pea plants have flowers with both male and female parts, so there are no separate sexes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9081' AND answer = 0;
